import { useFetcher } from "@remix-run/react";
import { useCallback, useRef, useState } from "react";

import { resizeImage } from "~/features/upload/image-resize";
import {
  uploadFile,
  uploadMultipleFiles,
} from "~/features/upload/upload.client";

import type { Asset } from "./types";

interface UseAssetUploadOptions {
  onSuccess: (message: string) => void;
  onError: (message: string) => void;
}

export function useAssetUpload({ onSuccess, onError }: UseAssetUploadOptions) {
  const assetFetcher = useFetcher<{
    success?: boolean;
    asset?: Asset;
    assets?: Asset[];
    error?: string;
  }>();
  const [bulkUploadFiles, setBulkUploadFiles] = useState<File[]>([]);
  const [isProcessingImages, setIsProcessingImages] = useState(false);
  const [singleFileUploading, setSingleFileUploading] = useState(false);
  const [bulkFileUploading, setBulkFileUploading] = useState(false);
  const textAssetFormRef = useRef<HTMLFormElement>(null);
  const imageAssetFormRef = useRef<HTMLFormElement>(null);

  const handleSingleFileUpload = useCallback(
    async (e: React.FormEvent, form: HTMLFormElement) => {
      e.preventDefault();
      setSingleFileUploading(true);

      try {
        const formData = new FormData(form);
        const fileInput = form.querySelector(
          'input[type="file"]',
        ) as HTMLInputElement;
        const file = fileInput?.files?.[0];

        if (!file) {
          throw new Error("No file selected");
        }

        // Process file if it's an image
        const processedFile = file.type.startsWith("image/")
          ? await resizeImage(file)
          : file;

        // Upload file using new upload system
        const uploadResult = await uploadFile(processedFile);

        if (!uploadResult.success) {
          throw new Error(uploadResult.error ?? "Upload failed");
        }

        // Submit to server with upload result
        const serverFormData = new FormData();
        serverFormData.append("_action", formData.get("_action") as string);
        serverFormData.append("title", formData.get("title") as string);
        serverFormData.append("tags", formData.get("tags") as string);
        serverFormData.append("uploadResult", JSON.stringify(uploadResult));

        assetFetcher.submit(serverFormData, { method: "post" });
      } catch (error: unknown) {
        const { handleAsyncErrorWithMessage, getErrorMessage } = await import(
          "~/lib/error-handler.client"
        );
        const errorMessage = `Upload failed: ${getErrorMessage(error)}`;
        handleAsyncErrorWithMessage(
          error,
          errorMessage,
          {
            component: "useAssetUpload",
            action: "handleSingleFileUpload",
          },
          false, // Don't show toast, we call onError instead
        );
        onError(errorMessage);
      } finally {
        setSingleFileUploading(false);
      }
    },
    [assetFetcher, onError],
  );

  const handleBulkFileUpload = useCallback(async () => {
    if (bulkUploadFiles.length === 0) return;

    setBulkFileUploading(true);

    try {
      // Upload all files using new upload system
      const uploadResults = await uploadMultipleFiles(bulkUploadFiles);

      // Check for failed uploads
      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        throw new Error(`Upload failed: ${errorMessages}`);
      }

      // Get form data for titles and tags
      const bulkForm = document.querySelector(
        "form[data-bulk-form]",
      ) as HTMLFormElement;
      if (!bulkForm) throw new Error("Bulk form not found");

      const formData = new FormData(bulkForm);
      const serverFormData = new FormData();
      serverFormData.append("_action", "bulk_create_media_assets");
      serverFormData.append("uploadResults", JSON.stringify(uploadResults));

      // Add titles and tags
      const titles = formData.getAll("titles");
      const tags = formData.getAll("tags");
      titles.forEach((title) =>
        serverFormData.append("titles", title as string),
      );
      tags.forEach((tag) => serverFormData.append("tags", tag as string));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage, getErrorMessage } = await import(
        "~/lib/error-handler.client"
      );
      const errorMessage = `Bulk upload failed: ${getErrorMessage(error)}`;
      handleAsyncErrorWithMessage(
        error,
        errorMessage,
        {
          component: "useAssetUpload",
          action: "handleBulkFileUpload",
        },
        false, // Don't show toast, we call onError instead
      );
      onError(errorMessage);
    } finally {
      setBulkFileUploading(false);
    }
  }, [bulkUploadFiles, assetFetcher, onError]);

  const handleBulkFileChange = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files) {
        const selectedFiles = Array.from(e.target.files);

        setIsProcessingImages(true);
        try {
          // Process files to remove metadata for privacy (images only)
          const processedFiles = await Promise.all(
            selectedFiles.map(async (file) => {
              if (file.type.startsWith("image/")) {
                return await resizeImage(file);
              }
              // Videos are uploaded as-is (no processing needed for privacy)
              return file;
            }),
          );
          setBulkUploadFiles(processedFiles);
        } catch (error) {
          const { handleErrorSafely } = await import(
            "~/lib/error-handler.client"
          );
          handleErrorSafely(
            error,
            {
              component: "useAssetUpload",
              action: "handleBulkFileChange",
            },
            () => {
              // Fallback to original files if processing fails
              setBulkUploadFiles(selectedFiles);
            },
          );
        } finally {
          setIsProcessingImages(false);
        }
      }
    },
    [],
  );

  // Handle fetcher responses
  const handleFetcherResponse = useCallback(() => {
    if (assetFetcher.data?.success) {
      // Show toast message
      if (
        assetFetcher.data &&
        typeof assetFetcher.data === "object" &&
        "asset" in assetFetcher.data &&
        assetFetcher.data.asset &&
        typeof assetFetcher.data.asset === "object" &&
        "assetType" in assetFetcher.data.asset
      ) {
        const assetType = assetFetcher.data.asset.assetType;
        onSuccess(
          `${typeof assetType === "string" ? assetType.toLowerCase() : String(assetType).toLowerCase()} asset created successfully!`,
        );
      } else if (assetFetcher.data.assets) {
        onSuccess(
          `${assetFetcher.data.assets.length} image assets uploaded successfully!`,
        );
      } else {
        onSuccess("Asset created successfully!");
      }

      // Clear forms
      if (textAssetFormRef.current) {
        textAssetFormRef.current.reset();
      }
      if (imageAssetFormRef.current) {
        imageAssetFormRef.current.reset();
      }

      // Clear bulk upload state
      setBulkUploadFiles([]);

      // Rehydrate page by reloading data
      window.location.reload();
    }
  }, [assetFetcher.data, onSuccess]);

  return {
    assetFetcher,
    bulkUploadFiles,
    isProcessingImages,
    singleFileUploading,
    bulkFileUploading,
    textAssetFormRef,
    imageAssetFormRef,
    handleSingleFileUpload,
    handleBulkFileUpload,
    handleBulkFileChange,
    handleFetcherResponse,
  };
}

import { Link, useFetcher, useLocation } from "@remix-run/react";
import { useCallback } from "react";

import { Avatar, AvatarFallback, AvatarImage } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import { handleAsyncError } from "~/lib/error-handler.client";
import { useOptionalUser } from "~/lib/remix-utils";
export default function NostrAuthButton() {
  const user = useOptionalUser() ?? null;
  const fetcher = useFetcher();
  const location = useLocation();

  const handleNostrLogin = useCallback(() => {
    void (async () => {
      try {
        // Load and initialize nostr-login when button is clicked
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { init } = await import("nostr-login");

        await init({
          methods: ["connect", "extension"],
          noBanner: true,
          onAuth: () => {
            void (async () => {
              try {
                // @ts-ignore - window.nostr is injected by browser extensions at runtime
                if (!window.nostr) {
                  throw new Error(
                    "Nostr extension not found. Please install a Nostr extension like Alby or nos2x.",
                  );
                }

                const randomKeys = () => {
                  const chars =
                    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
                  let result = "";
                  for (let i = 0; i < 10; i++) {
                    result += chars.charAt(
                      Math.floor(Math.random() * chars.length),
                    );
                  }
                  return result;
                };
                const contentSign = `Login request ${randomKeys()}`;
                const event = {
                  kind: 27235,
                  created_at: Math.floor(Date.now() / 1000),
                  tags: [],
                  content: contentSign,
                };

                // @ts-ignore - window.nostr is injected by browser extensions at runtime
                const signedEvent = await window.nostr.signEvent(event);

                const formData = new FormData();
                formData.append("pubkey", signedEvent.pubkey);
                formData.append("signature", signedEvent.sig);
                formData.append("event", JSON.stringify(signedEvent));
                formData.append("contentSign", contentSign);

                // Submit auth request
                fetcher.submit(formData, {
                  method: "post",
                  action: "/nostr-auth",
                });
              } catch (authError) {
                handleAsyncError(
                  authError,
                  {
                    component: "NostrAuthButton",
                    action: "onAuth",
                  },
                  true,
                );
              }
            })();
          },
        });

        // Trigger the login modal
        document.dispatchEvent(
          new CustomEvent("nlLaunch", { detail: "welcome" }),
        );
      } catch (error) {
        // Log and handle error
        handleAsyncError(
          error,
          {
            component: "NostrAuthButton",
            action: "handleNostrLogin",
          },
          true,
        );
      }
    })();
  }, [fetcher]);

  const handleLogout = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      // Dispatch nostr logout event
      document.dispatchEvent(new Event("nlLogout"));

      // Submit the logout form after a small delay to ensure nostr logout completes
      setTimeout(() => {
        if (event.target instanceof HTMLFormElement) {
          event.target.submit();
        }
      }, 100);
    },
    [],
  );

  return (
    <>
      {user ? (
        <>
          <div className="flex items-center gap-3">
            <Avatar>
              <AvatarImage
                src={
                  user &&
                  typeof user === "object" &&
                  "nostrProfile" in user &&
                  typeof user.nostrProfile === "object" &&
                  user.nostrProfile !== null &&
                  "picture" in user.nostrProfile
                    ? String(user.nostrProfile["picture"])
                    : undefined
                }
                alt="Profile"
              />
              <AvatarFallback>
                {user &&
                typeof user === "object" &&
                "nostrProfile" in user &&
                typeof user.nostrProfile === "object" &&
                user.nostrProfile !== null
                  ? (("name" in user.nostrProfile && user.nostrProfile["name"]
                      ? String(user.nostrProfile["name"])[0]
                      : null) ??
                    ("display_name" in user.nostrProfile &&
                    user.nostrProfile["display_name"]
                      ? String(user.nostrProfile["display_name"])[0]
                      : null) ??
                    "U")
                  : "U"}
              </AvatarFallback>
            </Avatar>
            <span className="hidden sm:inline">
              {user &&
              typeof user === "object" &&
              "nostrProfile" in user &&
              typeof user.nostrProfile === "object" &&
              user.nostrProfile !== null
                ? (("name" in user.nostrProfile && user.nostrProfile["name"]
                    ? String(user.nostrProfile["name"])
                    : null) ??
                  ("display_name" in user.nostrProfile &&
                  user.nostrProfile["display_name"]
                    ? String(user.nostrProfile["display_name"])
                    : null) ??
                  ("npub" in user && user.npub
                    ? `${String(user.npub).slice(0, 12)}...${String(user.npub).slice(-8)}`
                    : ""))
                : user &&
                    typeof user === "object" &&
                    "npub" in user &&
                    user.npub
                  ? `${String(user.npub).slice(0, 12)}...${String(user.npub).slice(-8)}`
                  : ""}
            </span>
            {location.pathname === "/" ? (
              <Button variant="outline" size="sm" asChild>
                <Link to="/dashboard">Dashboard</Link>
              </Button>
            ) : null}
            <form action="/logout" method="post" onSubmit={handleLogout}>
              <Button variant="outline" size="sm" type="submit">
                Logout
              </Button>
            </form>
          </div>
        </>
      ) : (
        <Button
          onClick={handleNostrLogin}
          disabled={fetcher.state === "submitting"}
          className="bg-gradient-to-r from-purple-500 to-indigo-600 font-bold text-white hover:from-purple-600 hover:to-indigo-700"
          size="lg"
          type="button"
        >
          {fetcher.state === "submitting"
            ? "Logging in..."
            : "Login with Nostr 🪿"}
        </Button>
      )}
    </>
  );
}

import { nip19 } from "nostr-tools";

import type {
  CompleteProfileResult,
  GetCompleteProfileParams,
  MediaData,
  PrimalEvent,
  ProcessedProfile,
  ProfileData,
  StatsData,
} from "~/features/nostr/types";
import { nostrAdapter } from "~/lib/nostr-adapter.server";
import { connectToPrimalCache } from "~/lib/nostrwebsocket.server";

/**
 * Validates an npub string
 */
export function validateNpub(npub: string): boolean {
  try {
    const { type } = nip19.decode(npub);
    return type === "npub";
  } catch (_e) {
    return false;
  }
}

/**
 * Fetches profile data from Primal API using WebSocket
 */
export async function fetchPrimalProfileData(
  npub: string,
): Promise<PrimalEvent[]> {
  try {
    const pubkey = nostrAdapter.decodeNpub(npub);
    const responses = await connectToPrimalCache("user_profile", {
      pubkey,
    });
    return responses as PrimalEvent[];
  } catch (error) {
    console.error("Failed to fetch profile data from Primal cache:", error);
    // Return empty array to allow login to proceed without profile data
    return [];
  }
}

/**
 * Processes Primal API response to extract profile information
 */
export function processPrimalData(data: PrimalEvent[]): {
  profile: ProcessedProfile;
} {
  // Find the profile event (kind 0)
  const profileEvent = data.find(
    (event) =>
      Array.isArray(event) && event[0] === "EVENT" && event[2].kind === 0,
  );

  // Find the stats event (kind 10000105)
  const statsEvent = data.find(
    (event) =>
      Array.isArray(event) &&
      event[0] === "EVENT" &&
      event[2].kind === 10000105,
  );

  // Find the media resources event (kind 10000119)
  const mediaEvent = data.find(
    (event) =>
      Array.isArray(event) &&
      event[0] === "EVENT" &&
      event[2].kind === 10000119,
  );

  // Parse profile content
  const profile: ProfileData = profileEvent
    ? (JSON.parse(profileEvent[2].content) as ProfileData)
    : {};

  // Parse stats content
  const stats: StatsData = statsEvent
    ? (JSON.parse(statsEvent[2].content) as StatsData)
    : {};

  // Parse media content
  const media: MediaData = mediaEvent
    ? (JSON.parse(mediaEvent[2].content) as MediaData)
    : {};

  return {
    profile: {
      ...profile,
      followers_count: stats.followers_count ?? 0,
      following_count: stats.follows_count ?? 0,
      posts_count: stats.note_count ?? 0,
      zaps_count: stats.total_zap_count ?? 0,
      total_satszapped: stats.total_satszapped ?? 0,
      media,
    },
  };
}

export async function getCompleteProfile({
  npub,
}: GetCompleteProfileParams): Promise<CompleteProfileResult> {
  const primalData = await fetchPrimalProfileData(npub);

  // If no data returned, return empty profile
  if (!primalData || primalData.length === 0) {
    const emptyProfile: ProcessedProfile = {
      followers_count: 0,
      following_count: 0,
      posts_count: 0,
      zaps_count: 0,
      total_satszapped: 0,
      media: {},
    };
    return {
      nostrProfile: emptyProfile,
      lud16: undefined,
    };
  }

  const { profile } = processPrimalData(primalData);

  return {
    nostrProfile: profile,
    lud16: profile.lud16,
  };
}

import { env } from "~/lib/env.server";
import { logError } from "~/lib/error-logger.server";
import { fetchJsonWithRetry } from "~/lib/fetch.server";

type CacheParams = Record<string, unknown>;
type CacheResponse = unknown[];

/**
 * Fetches data from the Primal cache REST API
 * Uses hardened fetch wrapper with retries and timeouts
 */
export async function fetchFromCache(
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  // Read directly from process.env to support test environment changes
  const primalUrl = process.env["PRIMAL_CACHING_URL"] ?? env.PRIMAL_CACHING_URL;
  if (!primalUrl) {
    throw new Error("PRIMAL_CACHING_URL environment variable is not set");
  }

  try {
    return await fetchJsonWithRetry<CacheResponse>(primalUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        requestType,
        params,
      }),
      timeout: 5000, // 5 seconds for cache requests
      maxRetries: 2,
      retryOn5xx: true,
    });
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      requestType,
      params,
      message: "[REST Cache] Failed to fetch",
    });
    throw error;
  }
}

/**
 * Connects to the Primal cache REST API and fetches data.
 * Supports request types: thread_view, feed, user_profile, user_infos, events, net_stats, reposts, likes, replies, zaps
 *
 * @param requestType - The type of request (e.g., "thread_view", "feed", etc.)
 * @param params - Parameters for the request (e.g., { event_id: "..." })
 * @returns Array of response events from the cache
 *
 * @example
 * const responses = await connectToPrimalCache("thread_view", {
 *   event_id: "d17048466d168d49a0af46ce7fc054f59a797ad0d05e0f95a0241192cd220bff"
 * });
 */
export async function connectToPrimalCache(
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  try {
    const responses = await fetchFromCache(requestType, params);

    // Check if we got valid responses (at least one non-EOSE event)
    const nonEose = responses?.filter(
      (res): res is unknown[] => Array.isArray(res) && res[0] !== "EOSE",
    );

    if (nonEose && nonEose.length > 0) {
      return responses;
    }

    logError(new Error("[REST Cache] Empty response"), {
      requestType,
      params,
    });
    throw new Error("Primal cache gave empty response.");
  } catch (err) {
    logError(err instanceof Error ? err : new Error(String(err)), {
      requestType,
      params,
      message: "[REST Cache] Failed",
    });
    throw err;
  }
}

import { formatDate } from "~/lib/helpers";

import type { ChildReply } from "../hooks/useNotificationActions";
interface ChildRepliesPanelProps {
  isLoading: boolean;
  replies: ChildReply[];
  metadata: Record<string, unknown>;
}

export function ChildRepliesPanel({
  isLoading,
  replies,
  metadata,
}: ChildRepliesPanelProps) {
  if (isLoading) {
    return (
      <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
        <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
          <svg className="h-4 w-4 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            ></circle>
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            ></path>
          </svg>
          Loading replies...
        </div>
      </div>
    );
  }

  if (replies.length === 0) {
    return (
      <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
        <div className="text-xs text-gray-500 dark:text-gray-400">
          No replies yet
        </div>
      </div>
    );
  }

  return (
    <div className="mt-3 space-y-2 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
      {replies.map((reply) => {
        const replyMetadata = metadata[reply.pubkey];
        let replyAuthorName =
          reply.pubkey.substring(0, 8) + "..." + reply.pubkey.slice(-4);
        let replyAuthorPicture = null;

        if (replyMetadata) {
          try {
            const metadataContent =
              replyMetadata &&
              typeof replyMetadata === "object" &&
              !Array.isArray(replyMetadata) &&
              "content" in replyMetadata
                ? (replyMetadata as { content?: unknown }).content
                : null;
            const profile =
              typeof metadataContent === "string"
                ? (JSON.parse(metadataContent) as Record<string, unknown>)
                : metadataContent &&
                    typeof metadataContent === "object" &&
                    !Array.isArray(metadataContent)
                  ? (metadataContent as Record<string, unknown>)
                  : null;
            if (profile && typeof profile === "object") {
              replyAuthorName =
                (profile as { display_name?: string; name?: string })
                  ?.display_name ??
                (profile as { name?: string })?.name ??
                replyAuthorName;
              replyAuthorPicture =
                (profile as { picture?: string | null })?.picture ?? null;
            }
          } catch (_e) {
            // Ignore parsing errors
          }
        }

        return (
          <div
            key={reply.id}
            className="rounded-lg border border-gray-200 bg-gray-50 p-2 dark:border-gray-700 dark:bg-gray-800/50"
          >
            <div className="mb-1 flex items-center gap-2">
              {replyAuthorPicture ? (
                <img
                  src={replyAuthorPicture}
                  alt={replyAuthorName}
                  className="h-6 w-6 rounded-full"
                />
              ) : (
                <div className="h-6 w-6 rounded-full bg-gray-300 dark:bg-gray-600" />
              )}
              <span className="text-xs font-semibold text-gray-900 dark:text-gray-100">
                {replyAuthorName}
              </span>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {formatDate(new Date(reply.created_at * 1000).toISOString())}
              </span>
            </div>
            <p className="whitespace-pre-wrap break-words text-xs text-gray-700 dark:text-gray-300">
              {reply.content}
            </p>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Engagement feed content component
 */

import type { GroupedNotification } from "../types";

import GroupedNotificationList from "./GroupedNotificationList";
interface EngagementContentProps {
  activeTab: "all" | "replies" | "quotes";
  groupedNotifications: {
    replies: GroupedNotification[];
    quotes: GroupedNotification[];
  };
  userTimezone?: string | null;
  userRelays?: string[];
  trustScores: Record<string, number>;
  postsCount: number;
}

export function EngagementContent({
  activeTab,
  groupedNotifications,
  userTimezone,
  userRelays,
  trustScores,
  postsCount,
}: EngagementContentProps) {
  const defaultRelays = ["wss://relay.primal.net"];

  // All Tab Content
  if (activeTab === "all") {
    return (
      <div className="space-y-6">
        {/* Replies Section */}
        {groupedNotifications.replies.length > 0 ? (
          <div>
            <h4 className="mb-3 font-medium text-gray-900 dark:text-gray-100">
              Replies
            </h4>
            <GroupedNotificationList
              groupedNotifications={groupedNotifications.replies}
              userTimezone={userTimezone ?? undefined}
              userRelays={userRelays ?? defaultRelays}
              trustScores={trustScores}
            />
          </div>
        ) : null}

        {/* Quote Reposts Section */}
        {groupedNotifications.quotes &&
        groupedNotifications.quotes.length > 0 ? (
          <div>
            <h4 className="mb-3 font-medium text-gray-900 dark:text-gray-100">
              Repost with Quote
            </h4>
            <GroupedNotificationList
              groupedNotifications={groupedNotifications.quotes}
              userTimezone={userTimezone ?? undefined}
              userRelays={userRelays ?? defaultRelays}
              trustScores={trustScores}
            />
          </div>
        ) : null}

        {groupedNotifications.replies.length === 0 &&
        (!groupedNotifications.quotes ||
          groupedNotifications.quotes.length === 0) ? (
          <div className="rounded-lg border border-gray-200 bg-white p-8 text-center dark:border-gray-700 dark:bg-gray-800">
            <p className="text-gray-500 dark:text-gray-400">
              No engagement found for your posts yet.
            </p>
          </div>
        ) : null}
      </div>
    );
  }

  // Replies Tab Content
  if (activeTab === "replies") {
    return (
      <>
        {groupedNotifications.replies.length > 0 ? (
          <GroupedNotificationList
            groupedNotifications={groupedNotifications.replies}
            userTimezone={userTimezone ?? undefined}
            userRelays={userRelays ?? defaultRelays}
            trustScores={trustScores}
          />
        ) : (
          <div className="rounded-lg border border-gray-200 bg-white p-8 text-center dark:border-gray-700 dark:bg-gray-800">
            <p className="text-gray-500 dark:text-gray-400">
              No replies found for your posts.
            </p>
            <p className="mt-2 text-sm text-gray-400">
              Posts fetched: {postsCount}
            </p>
          </div>
        )}
      </>
    );
  }

  // Quote Reposts Tab Content
  if (activeTab === "quotes") {
    return (
      <>
        {groupedNotifications.quotes &&
        groupedNotifications.quotes.length > 0 ? (
          <GroupedNotificationList
            groupedNotifications={groupedNotifications.quotes}
            userTimezone={userTimezone ?? undefined}
            userRelays={userRelays ?? defaultRelays}
            trustScores={trustScores}
          />
        ) : (
          <div className="rounded-lg border border-gray-200 bg-white p-8 text-center dark:border-gray-700 dark:bg-gray-800">
            <p className="text-gray-500 dark:text-gray-400">
              No quote reposts found for your posts.
            </p>
          </div>
        )}
      </>
    );
  }

  return null;
}

