/**
 * Engagement feed loader data preparation
 * Centralized data fetching for engagement feed page
 */

import { connectToPrimalCache } from "~/features/cache/primalCache.server";
import type { SignedEvent } from "~/features/nostr/types";
import type { PostData, QueueType } from "~/features/posts/types";
import { convertJsonValueToScheduleConfig } from "~/features/posts/types";
import type { UserWithHashTagPresets } from "~/features/user";
import { getUserById } from "~/features/user";
import { getPostedPosts } from "~/models/post.queries.server";

import {
  groupNotificationsByParent,
  groupNotificationsByType,
  parseThreadViewNotifications,
  processQuoteReposts,
  type Notification,
} from "../engagement.server";
import { calculateTrustScore, type User } from "../trustScore";
import type {
  EngagementProfile,
  EngagementStats,
  EventStats,
  GroupedNotification,
  NostrTag,
  NotificationEvent,
  PrimalEvent,
} from "../types";

/**
 * Fetches user profile data from Primal API and converts to User type for trust scoring
 */
async function fetchUserProfile(pubkey: string): Promise<User | null> {
  try {
    const profileData = await connectToPrimalCache("user_profile", { pubkey });

    if (!Array.isArray(profileData)) {
      return null;
    }

    // Find kind 0 (profile) and kind 10000105 (stats) events
    let profileEvent = null;
    let statsEvent = null;

    for (const item of profileData) {
      if (!Array.isArray(item) || item[0] !== "EVENT" || !item[2]) continue;
      const rawEventData: unknown = item[2] as unknown;
      if (
        !rawEventData ||
        typeof rawEventData !== "object" ||
        Array.isArray(rawEventData)
      )
        continue;
      const event: { kind?: number; content?: string } = rawEventData as {
        kind?: number;
        content?: string;
      };

      if (event.kind === 0) {
        profileEvent = event;
      } else if (event.kind === 10000105) {
        statsEvent = event;
      }
    }

    // Parse profile data
    let profile: EngagementProfile = {};
    if (profileEvent?.content) {
      try {
        profile = JSON.parse(profileEvent.content) as EngagementProfile;
      } catch (e) {
        console.error("Failed to parse profile content:", e);
      }
    }

    // Parse stats data
    let stats: EngagementStats = {};
    if (statsEvent?.content) {
      try {
        stats = JSON.parse(statsEvent.content) as EngagementStats;
      } catch (e) {
        console.error("Failed to parse stats content:", e);
      }
    }

    // Convert to User type
    const profileTyped = profile;
    const statsTyped = stats;
    const user: User = {
      pubkey,
      name: profileTyped.name ?? undefined,
      displayName: profileTyped.display_name ?? undefined,
      about: (profileTyped["about"] as string | undefined) ?? undefined,
      picture: profileTyped.picture ?? undefined,
      nip05: (profileTyped["nip05"] as string | undefined) ?? undefined,
      lud16: (profileTyped["lud16"] as string | undefined) ?? undefined,
      followsCount: statsTyped.follows_count ?? 0,
      followersCount: statsTyped.followers_count ?? 0,
      noteCount: statsTyped.note_count ?? 0,
      replyCount: (statsTyped["reply_count"] as number | undefined) ?? 0,
      timeJoined: (statsTyped["time_joined"] as number | undefined) ?? 0,
      zapCount: statsTyped.total_zap_count ?? 0,
      totalSatsZapped: statsTyped.total_satszapped ?? 0,
      mediaCount: (statsTyped["media_count"] as number | undefined) ?? 0,
    };

    return user;
  } catch (error) {
    console.error(`Failed to fetch user profile for ${pubkey}:`, error);
    return null;
  }
}

/**
 * Fetch thread view with timeout
 */
async function fetchThreadViewWithTimeout(eventId: string, timeout = 5000) {
  const timeoutPromise = new Promise((_, reject) =>
    setTimeout(() => reject(new Error("Request timeout")), timeout),
  );

  const fetchPromise = connectToPrimalCache("thread_view", {
    event_id: eventId,
  });

  return Promise.race([fetchPromise, timeoutPromise]);
}

/**
 * Process batch of event IDs to get stats and notifications
 */
async function processEventBatch(batchIds: string[], userNpub: string) {
  const notificationPromises = batchIds.map(async (eventId) => {
    try {
      const threadViewData = await fetchThreadViewWithTimeout(eventId);
      const notifications = parseThreadViewNotifications(
        Array.isArray(threadViewData) ? threadViewData : [],
        eventId,
        userNpub,
      );

      const statsEvent = (threadViewData as PrimalEvent[]).find(
        (event: PrimalEvent) => {
          if (!Array.isArray(event) || event[0] !== "EVENT" || !event[2])
            return false;
          const eventData = event[2];
          if (typeof eventData !== "object" || Array.isArray(eventData))
            return false;
          const eventTyped = eventData as { kind?: number; content?: string };
          return (
            eventTyped.kind === 10000100 &&
            eventTyped.content &&
            typeof eventTyped.content === "string" &&
            eventTyped.content.includes(eventId)
          );
        },
      );

      let eventStats = {
        likes: 0,
        replies: 0,
        mentions: 0,
        reposts: 0,
        zaps: 0,
        satszapped: 0,
      };

      if (statsEvent && Array.isArray(statsEvent) && statsEvent[2]) {
        const eventData = statsEvent[2] as { kind?: number; content?: string };
        if (eventData.content) {
          try {
            const content = JSON.parse(eventData.content) as {
              likes?: number;
              replies?: number;
              mentions?: number;
              reposts?: number;
              zaps?: number;
              satszapped?: number;
            };
            eventStats = {
              likes: content.likes ?? 0,
              replies: content.replies ?? 0,
              mentions: content.mentions ?? 0,
              reposts: content.reposts ?? 0,
              zaps: content.zaps ?? 0,
              satszapped: content.satszapped ?? 0,
            };
          } catch {
            // Ignore parse errors
          }
        }
      }

      return {
        eventId,
        stats: eventStats,
        notifications,
      };
    } catch (_error) {
      return {
        eventId,
        stats: {
          likes: 0,
          replies: 0,
          mentions: 0,
          reposts: 0,
          zaps: 0,
          satszapped: 0,
        },
        notifications: [],
      };
    }
  });

  return Promise.all(notificationPromises);
}

/**
 * Filter notifications by muted users
 */
function filterMutedNotifications(
  notifications: Notification[],
  mutedPubkeys: string[],
): Notification[] {
  return notifications.filter((notification) => {
    const pubkeyToCheck =
      notification.type === "zap"
        ? notification.senderPubkey
        : notification.pubkey;
    return !mutedPubkeys.includes(pubkeyToCheck);
  });
}

/**
 * Filter notifications by trust score
 */
function filterLowTrustNotifications(
  notifications: Notification[],
  trustScoresMap: Map<string, number>,
): Notification[] {
  return notifications.filter((notification) => {
    const pubkeyToCheck =
      notification.type === "zap"
        ? notification.senderPubkey
        : notification.pubkey;
    const trustScore = trustScoresMap.get(pubkeyToCheck);
    return trustScore === undefined || trustScore >= 40;
  });
}

/**
 * Load engagement feed data
 */
export async function loadEngagementFeedData(
  userId: string,
  page = 1,
  limit = 50,
) {
  const [{ posts }, userResult] = await Promise.all([
    getPostedPosts({
      userId,
      page,
      limit,
      queueType: "all",
    }),
    getUserById(userId),
  ]);

  // Validate user data
  if (!userResult) {
    throw new Error("User not found");
  }

  const user: UserWithHashTagPresets = userResult;

  // Ensure user has required properties with safe defaults
  const userNpub = user.npub ?? "";
  const userFilterMuted = user.filterMuted ?? false;
  const userHidePostsFromLowTrustUsers =
    user.hidePostsFromLowTrustUsers ?? false;

  // Type guard for mutedList
  const mutedListData =
    user.mutedList &&
    typeof user.mutedList === "object" &&
    !Array.isArray(user.mutedList) &&
    "npubs" in user.mutedList
      ? (user.mutedList as { npubs?: unknown; lastSynced?: unknown })
      : null;
  const mutedNpubs =
    mutedListData && Array.isArray(mutedListData.npubs)
      ? (mutedListData.npubs as string[])
      : [];

  // Get event IDs from signedEvent.id
  const eventIds = posts
    .filter((post) => {
      const se = post.signedEvent;
      return (
        se &&
        typeof se === "object" &&
        !Array.isArray(se) &&
        "id" in se &&
        typeof (se as { id: unknown }).id === "string"
      );
    })
    .map((post) => {
      const se = post.signedEvent as { id: string };
      return se.id;
    });

  let stats: Record<string, EventStats> = {};
  let allNotifications: Notification[] = [];
  const userProfilesMap = new Map<string, User>();
  const trustScoresMap = new Map<string, number>();

  // Early return if no posts - skip expensive API calls
  if (eventIds.length === 0) {
    return {
      posts: [],
      stats: {},
      user,
      notifications: {
        all: [],
        replies: [],
        mentions: [],
        zaps: [],
        quotes: [],
      },
      groupedNotifications: {
        replies: [],
        quotes: [],
      },
      trustScores: {},
    };
  }

  try {
    // Batch fetch notifications and stats
    const BATCH_SIZE = 10;
    const batches: string[][] = [];
    for (let i = 0; i < eventIds.length; i += BATCH_SIZE) {
      batches.push(eventIds.slice(i, i + BATCH_SIZE));
    }

    // Process batches in parallel
    const batchPromises = batches.map((batchIds) =>
      processEventBatch(batchIds, userNpub),
    );

    const allBatchResults = await Promise.all(batchPromises);
    const results = allBatchResults.flat();

    // Combine stats and notifications
    const initialStats: Record<string, EventStats> = {};
    stats = results.reduce((acc, result) => {
      if (result.eventId && result.stats) {
        acc[result.eventId] = result.stats;
      }
      return acc;
    }, initialStats);

    allNotifications = results.flatMap((result) =>
      result && Array.isArray(result.notifications) ? result.notifications : [],
    );

    // Filter out muted users if enabled
    if (userFilterMuted && mutedNpubs.length > 0) {
      allNotifications = filterMutedNotifications(allNotifications, mutedNpubs);
    }

    // Fetch user profiles and calculate trust scores
    const uniquePubkeys = Array.from(
      new Set(
        allNotifications.map((notification) =>
          notification.type === "zap"
            ? notification.senderPubkey
            : notification.pubkey,
        ),
      ),
    );

    const profilePromises = uniquePubkeys.map(async (pubkey) => {
      const userProfile = await fetchUserProfile(pubkey);
      if (userProfile) {
        userProfilesMap.set(pubkey, userProfile);
        const trustScore = calculateTrustScore(userProfile);
        trustScoresMap.set(pubkey, trustScore);
      }
    });

    await Promise.all(profilePromises);

    // Filter out low trust users if enabled
    if (userHidePostsFromLowTrustUsers) {
      allNotifications = filterLowTrustNotifications(
        allNotifications,
        trustScoresMap,
      );
    }
  } catch (error) {
    console.error("📊 [SERVER] Error fetching stats:", error);
    // Gracefully handle errors
    stats = posts
      .filter((post) => {
        const se = post.signedEvent;
        return (
          se &&
          typeof se === "object" &&
          !Array.isArray(se) &&
          "id" in se &&
          typeof (se as { id: unknown }).id === "string"
        );
      })
      .reduce(
        (acc, post) => {
          const se = post.signedEvent;
          if (
            se &&
            typeof se === "object" &&
            !Array.isArray(se) &&
            "id" in se &&
            typeof se["id"] === "string"
          ) {
            const result: Record<string, EventStats> = acc;
            const eventStats: EventStats = {
              likes: 0,
              replies: 0,
              mentions: 0,
              reposts: 0,
              zaps: 0,
              satszapped: 0,
            };
            result[se["id"]] = eventStats;
            return result;
          }
          return acc;
        },
        ((): Record<string, EventStats> => ({}))(),
      );
  }

  // Group notifications by type
  const groupedNotifications = groupNotificationsByType(allNotifications);

  // Group notifications by parent event - focus on replies only
  // Convert PostWithQueueType[] to PostData[] for compatibility
  const postsAsPostData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    const convertedQueueType: QueueType | null = queueType
      ? {
          id: queueType.id,
          name: queueType.name,
          color: queueType.color,
          description: queueType.description,
          scheduleType: queueType.scheduleType as
            | "INTERVAL"
            | "FIXED_SLOTS"
            | undefined,
          scheduleConfig: convertJsonValueToScheduleConfig(
            queueType.scheduleConfig,
          ),
          isEnabled: queueType.isEnabled,
          userId: queueType.userId,
        }
      : null;
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- Type assertion needed for Prisma query result compatibility
    return {
      ...rest,
      signedEvent: post.signedEvent as SignedEvent | null | undefined,
      queueType: convertedQueueType,
    } as PostData;
  });

  const groupedByParent = {
    replies: groupNotificationsByParent(
      groupedNotifications.replies,
      postsAsPostData,
      [], // No longform posts in this feed
      stats,
    ),
  };

  // Filter posts to only show those with replies
  const postsWithReplies = posts.filter((post) => {
    const se = post.signedEvent;
    if (
      !se ||
      typeof se !== "object" ||
      Array.isArray(se) ||
      !("id" in se) ||
      typeof (se as { id: unknown }).id !== "string"
    ) {
      return false;
    }
    const eventId = (se as { id: string }).id;
    const postStats = stats[eventId];
    return postStats && postStats.replies > 0;
  });

  // Fetch quote reposts using get_notifications
  let quoteRepostNotifications: Notification[] = [];
  let groupedQuoteReposts: GroupedNotification[] = [];
  try {
    const notificationsData = await connectToPrimalCache("get_notifications", {
      pubkey: userNpub,
      limit: 100,
    });

    // Extract quote reposts (kind 1 events with mention tags)
    if (Array.isArray(notificationsData)) {
      const rawQuoteReposts = (notificationsData as PrimalEvent[])
        .filter((item: PrimalEvent) => {
          if (
            Array.isArray(item) &&
            item[0] === "EVENT" &&
            item[2] &&
            typeof item[2] === "object" &&
            !Array.isArray(item[2]) &&
            "kind" in item[2] &&
            (item[2] as { kind?: unknown }).kind === 1
          ) {
            const event = item[2] as {
              id?: unknown;
              pubkey?: unknown;
              content?: unknown;
              kind?: unknown;
              tags?: unknown;
            };

            if (!event || typeof event !== "object" || Array.isArray(event)) {
              return false;
            }

            const eventTyped = event;
            if (
              !eventTyped.id ||
              typeof eventTyped.id !== "string" ||
              !eventTyped.pubkey ||
              typeof eventTyped.pubkey !== "string" ||
              typeof eventTyped.content !== "string"
            ) {
              return false;
            }

            const tags =
              ((eventTyped as { tags?: unknown }).tags as NostrTag[]) || [];

            // Skip if it's the user's own post
            if (eventTyped.pubkey === userNpub) {
              return false;
            }

            // Check if it has both "e" and "p" tags with mention marker
            const eMentionTags = tags.filter(
              (tag: NostrTag) => tag[0] === "e" && tag[3] === "mention",
            );
            const hasEMention = eMentionTags.length > 0;

            const pMentionTags = tags.filter(
              (tag: NostrTag) =>
                tag[0] === "p" && (tag[3] === "mention" || tag[3] === ""),
            );
            const hasPMention = pMentionTags.length > 0;

            if (!hasEMention || !hasPMention) {
              return false;
            }

            // Check if the mentioned user (p tag) is the current user
            const mentionedUserPubkey = tags.find(
              (tag: NostrTag) =>
                tag[0] === "p" && (tag[3] === "mention" || tag[3] === ""),
            )?.[1];
            return mentionedUserPubkey === userNpub;
          }
          return false;
        })
        .map((item: PrimalEvent) => {
          if (Array.isArray(item) && item[2]) {
            return item[2] as NotificationEvent;
          }
          throw new Error("Invalid PrimalEvent structure");
        }); // Extract the event object

      // Process quote reposts
      if (rawQuoteReposts.length > 0) {
        quoteRepostNotifications = await processQuoteReposts(
          rawQuoteReposts,
          connectToPrimalCache,
        );

        // Filter out muted users if enabled
        if (userFilterMuted && mutedNpubs.length > 0) {
          quoteRepostNotifications = filterMutedNotifications(
            quoteRepostNotifications,
            mutedNpubs,
          );
        }

        // Fetch user profiles and calculate trust scores for quote reposts
        const quoteUniquePubkeys = Array.from(
          new Set(
            quoteRepostNotifications.map((notification) => notification.pubkey),
          ),
        );

        const quoteProfilePromises = quoteUniquePubkeys.map(async (pubkey) => {
          if (!userProfilesMap.has(pubkey)) {
            const userProfile = await fetchUserProfile(pubkey);
            if (userProfile) {
              userProfilesMap.set(pubkey, userProfile);
              const trustScore = calculateTrustScore(userProfile);
              trustScoresMap.set(pubkey, trustScore);
            }
          }
        });

        await Promise.all(quoteProfilePromises);

        // Filter out low trust users from quote reposts if enabled
        if (userHidePostsFromLowTrustUsers) {
          quoteRepostNotifications = filterLowTrustNotifications(
            quoteRepostNotifications,
            trustScoresMap,
          );
        }

        // Group quote reposts by parent post
        groupedQuoteReposts = groupNotificationsByParent(
          quoteRepostNotifications,
          postsAsPostData,
          [], // No longform posts in this feed
          stats,
        );
      }
    }
  } catch (error) {
    console.error(
      "🔍 [QUOTE REPOST DEBUG] Error fetching quote reposts:",
      error,
    );
  }

  // Convert trust scores map to object for JSON serialization
  const trustScores: Record<string, number> = {};
  trustScoresMap.forEach((score, pubkey) => {
    trustScores[pubkey] = score;
  });

  return {
    posts: postsWithReplies ?? [],
    stats: stats ?? {},
    user,
    notifications: groupedNotifications ?? {
      all: [],
      replies: [],
      mentions: [],
      zaps: [],
      quotes: [],
    },
    groupedNotifications: {
      replies: groupedByParent.replies ?? [],
      quotes: groupedQuoteReposts ?? [],
    },
    trustScores: trustScores ?? {},
  };
}

/**
 * Load engagement data (alias for loadEngagementFeedData)
 */
export const loadEngagementData = loadEngagementFeedData;

import type { TrustScoreUser as User } from "./types";
// Re-export the User type
export type { TrustScoreUser as User } from "~/features/engagement/types";

/**
 * Calculates a trust score from 0-100 based on user data
 * Higher scores indicate more trustworthy/established profiles
 */
export function calculateTrustScore(user: User): number {
  let score = 0;
  let maxScore = 0;

  // 1. Profile Completeness (25 points max)
  // Having basic profile information shows investment in the account
  maxScore += 25;

  if (user.name) score += 5;
  if (user.displayName) score += 5;
  if (user.about && user.about.length > 20) score += 8; // Meaningful about section
  if (user.picture) score += 4;
  if (user.nip05) score += 3; // NIP-05 verification shows legitimacy

  // 2. Account Age (15 points max)
  // Older accounts are generally more trustworthy
  maxScore += 15;

  const accountAge = getAccountAgeInDays(user.timeJoined);
  if (accountAge > 365)
    score += 15; // 1+ years
  else if (accountAge > 180)
    score += 12; // 6+ months
  else if (accountAge > 90)
    score += 8; // 3+ months
  else if (accountAge > 30)
    score += 5; // 1+ month
  else if (accountAge > 7) score += 2; // 1+ week

  // 3. Social Engagement (30 points max)
  // Active participation indicates legitimate use
  maxScore += 30;

  // Followers (weighted logarithmically to prevent gaming)
  const followerScore = Math.min(
    12,
    Math.log10(Math.max(1, user.followersCount)) * 3,
  );
  score += followerScore;

  // Notes/Content creation
  const noteScore = Math.min(8, Math.log10(Math.max(1, user.noteCount)) * 2);
  score += noteScore;

  // Replies (shows engagement)
  const replyScore = Math.min(
    5,
    Math.log10(Math.max(1, user.replyCount)) * 1.5,
  );
  score += replyScore;

  // Balanced following ratio (not following too many or too few)
  const followRatio =
    user.followersCount > 0 ? user.followsCount / user.followersCount : 0;
  if (followRatio > 0.1 && followRatio < 10) score += 5; // Healthy follow ratio

  // 4. Economic Activity (20 points max)
  // Lightning and zap activity indicates real economic participation
  maxScore += 20;

  if (user.lud16) score += 5; // Lightning address shows economic participation

  // Zap activity (both sent and received)
  const zapScore = Math.min(10, Math.log10(Math.max(1, user.zapCount)) * 2.5);
  score += zapScore;

  // Total sats zapped (economic value)
  const satsScore = Math.min(
    5,
    Math.log10(Math.max(1, user.totalSatsZapped)) * 1,
  );
  score += satsScore;

  // 5. Content Diversity (10 points max)
  // Varied content types suggest authentic usage
  maxScore += 10;

  if (user.mediaCount > 0) score += 3; // Media posts
  if (user.replyCount > user.noteCount * 0.1) score += 3; // Engages with others
  if (user.noteCount > 10) score += 2; // Regular posting
  if (user.followersCount > user.noteCount * 0.5) score += 2; // Good content quality

  // Normalize to 0-100 scale
  const normalizedScore = Math.round((score / maxScore) * 100);

  // Cap at 100 and ensure minimum of 0
  return Math.min(100, Math.max(0, normalizedScore));
}

/**
 * Gets account age in days from timeJoined timestamp
 */
export function getAccountAgeInDays(timeJoined: number): number {
  if (timeJoined === 0) return 0;

  const joinedDate = new Date(timeJoined * 1000);
  const now = new Date();
  const diffInMs = now.getTime() - joinedDate.getTime();
  const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

  return Math.max(0, diffInDays);
}

/**
 * Gets a trust level description based on score
 */
export function getTrustLevel(score: number): {
  level: string;
  color: string;
  description: string;
} {
  if (score >= 80) {
    return {
      level: "Highly Trusted",
      color: "text-green-600 dark:text-green-400",
      description: "Well-established profile with strong community engagement",
    };
  } else if (score >= 60) {
    return {
      level: "Trusted",
      color: "text-blue-600 dark:text-blue-400",
      description: "Active profile with good community standing",
    };
  } else if (score >= 40) {
    return {
      level: "Developing",
      color: "text-yellow-600 dark:text-yellow-400",
      description: "Growing profile building community presence",
    };
  } else if (score >= 20) {
    return {
      level: "New",
      color: "text-orange-600 dark:text-orange-400",
      description: "Recently created or limited activity profile",
    };
  } else {
    return {
      level: "Unverified",
      color: "text-gray-600 dark:text-gray-400",
      description: "Minimal profile information or activity",
    };
  }
}

/**
 * Gets trust score badge color classes
 */
export function getTrustScoreBadgeColor(score: number): string {
  if (score >= 80) {
    return "bg-green-100 dark:bg-green-900/20 text-green-800 dark:text-green-200 border-green-200 dark:border-green-800";
  } else if (score >= 60) {
    return "bg-blue-100 dark:bg-blue-900/20 text-blue-800 dark:text-blue-200 border-blue-200 dark:border-blue-800";
  } else if (score >= 40) {
    return "bg-yellow-100 dark:bg-yellow-900/20 text-yellow-800 dark:text-yellow-200 border-yellow-200 dark:border-yellow-800";
  } else if (score >= 20) {
    return "bg-orange-100 dark:bg-orange-900/20 text-orange-800 dark:text-orange-200 border-orange-200 dark:border-orange-800";
  } else {
    return "bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 border-gray-200 dark:border-gray-700";
  }
}

import { useFetcher } from "@remix-run/react";
import { Plus, X } from "lucide-react";
import type { UseFormReturn } from "react-hook-form";
import type { z } from "zod";

import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import { Input } from "~/components/ui/input";
import { updateBlacklistClientSchema } from "~/lib/validation";
import { useZodFieldArray } from "~/lib/validation/hooks/useZodFieldArray";
import { useZodForm, formDataToFormData } from "~/lib/validation/utils.client-safe";

interface GiveawayBlacklistSettingsProps {
  giveawayBlacklist: string[];
}

interface FetcherData {
  success?: boolean;
  error?: string;
}

export function GiveawayBlacklistSettings({
  giveawayBlacklist,
}: GiveawayBlacklistSettingsProps) {
  const fetcher = useFetcher<FetcherData>();
  const form = useZodForm(updateBlacklistClientSchema, {
    defaultValues: {
      blacklist: giveawayBlacklist.length > 0 ? giveawayBlacklist : [""],
    },
  });

  const { fields, append, remove } = useZodFieldArray<
    z.infer<typeof updateBlacklistClientSchema>,
    "blacklist"
  >(form as unknown as UseFormReturn<z.infer<typeof updateBlacklistClientSchema>>, "blacklist");

  const isSubmitting = fetcher.state === "submitting";
  const watchedBlacklist = form.watch("blacklist");
  const hasChanged =
    JSON.stringify(watchedBlacklist) !== JSON.stringify(giveawayBlacklist);

  const onSubmit = form.handleSubmit((data) => {
    // Filter out empty strings and validate
    const filteredBlacklist = data.blacklist.filter((item: string) =>
      item.trim(),
    );

    // Validate all non-empty items start with npub
    const invalidItems = filteredBlacklist.filter(
      (item: string) => !item.trim().startsWith("npub"),
    );

    if (invalidItems.length > 0) {
      form.setError("blacklist", {
        type: "manual",
        message: "All blacklist items must start with npub",
      });
      return;
    }

    const formData = formDataToFormData(
      { blacklist: filteredBlacklist.join("\n") },
      "update_blacklist",
    );

    fetcher.submit(formData, { method: "post" });
  });

  return (
    <Card>
      <CardHeader>
        <CardTitle>Giveaway Blacklist</CardTitle>
        <CardDescription>
          Manage blocked npub addresses for giveaways and contests
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={(e) => { e.preventDefault(); void onSubmit(e); }} className="space-y-4">
          <div className="space-y-2">
            <p className="text-sm text-muted-foreground">
              Add npub addresses one by one
            </p>
            {fields.map((field, index) => (
              <div key={field.id} className="flex items-start space-x-2">
                <div className="flex-1">
                  <Input
                    {...form.register(`blacklist.${index}`)}
                    placeholder="npub1xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                    disabled={isSubmitting}
                    className={
                      form.formState.errors.blacklist?.[index]
                        ? "border-destructive"
                        : ""
                    }
                  />
                  {form.formState.errors.blacklist?.[index] ? <p className="mt-1 text-sm text-destructive">
                      {String(form.formState.errors.blacklist[index]?.message)}
                    </p> : null}
                </div>
                <Button
                  type="button"
                  variant="destructive"
                  size="icon"
                  onClick={() => remove(index)}
                  disabled={isSubmitting}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            ))}
            <Button
              type="button"
              variant="outline"
              onClick={() => append("")}
              disabled={isSubmitting}
              className="w-full"
            >
              <Plus className="mr-2 h-4 w-4" />
              Add npub
            </Button>
          </div>

          {form.formState.errors.blacklist ? <p className="text-sm text-destructive">
              {form.formState.errors.blacklist.message}
            </p> : null}

          <Button
            type="submit"
            disabled={isSubmitting || !hasChanged || !form.formState.isValid}
            className="w-full"
          >
            {isSubmitting ? "Saving..." : "Save Blacklist"}
          </Button>

          {fetcher.data?.success ? (
            <p className="text-sm text-green-600">
              Blacklist updated successfully!
            </p>
          ) : null}
          {fetcher.data?.error ? (
            <p className="text-sm text-destructive">{fetcher.data.error}</p>
          ) : null}
        </form>
      </CardContent>
    </Card>
  );
}

import { nip19 } from "nostr-tools";
import { useState } from "react";

import { handleErrorSafely } from "~/lib/error-handler.client";
interface RandomUser {
  pubkey: string;
}

interface RandomUsers {
  reposters: RandomUser[];
  likers: RandomUser[];
  commenters: RandomUser[];
}

interface GiveawayPostProps {
  randomUsers: RandomUsers;
}

const GiveawayPost = ({ randomUsers }: GiveawayPostProps) => {
  const [message, setMessage] = useState("");
  const [copied, setCopied] = useState(false);

  // Generate the giveaway message based on random users
  const generateMessage = () => {
    if (
      !randomUsers?.reposters ||
      !randomUsers.likers ||
      !randomUsers.commenters
    ) {
      return "No user data available to generate message.";
    }

    const formatNpub = (pubkey: string): string => {
      if (!pubkey) return "unknown";
      try {
        const npub = nip19.npubEncode(pubkey);
        return `nostr:${npub}`;
      } catch (error) {
        handleErrorSafely(error, {
          component: "GiveawayPost",
          action: "formatNpub",
        });
        return "unknown";
      }
    };

    const reposters = randomUsers.reposters
      .map((user: RandomUser) => formatNpub(user.pubkey))
      .join(", ");
    const likers = randomUsers.likers
      .map((user: RandomUser) => formatNpub(user.pubkey))
      .join(", ");
    const commenters = randomUsers.commenters
      .map((user: RandomUser) => formatNpub(user.pubkey))
      .join(", ");

    return `Thanks to everyone who shared, zapped, liked and commented on our memes lately 🫡

✅ 3 random reposts from last week each got 2,000 sats - congrats to ${reposters} 🎉

✅ 3 random reactions from last week each got 1,000 sats - congrats to ${likers} 🎉

✅ 3 random comments from last week each got 1,000 sats - congrats to ${commenters} 🎉

