import { useFetcher } from "@remix-run/react";
import { useState } from "react";

import type {
  CombinedContent,
  LongFormPostData,
  PostData,
  PostFetcher,
} from "../types";

import { ContentBulkActions } from "./ContentBulkActions";
import { ContentSearchBar } from "./ContentSearchBar";
import { ContentTableHeader } from "./ContentTableHeader";
import { ContentTableRow } from "./ContentTableRow";

interface AllContentListingProps {
  content: CombinedContent[];
  type: "scheduled" | "draft" | "posted";
  searchTerm: string;
  onSearchChange: (term: string) => void;
  userTimezone?: string;
  onPostSelect?: (content: CombinedContent) => void;
  selectedItems?: Set<string>;
  onToggleSelection?: (id: string) => void;
  onToggleSelectAll?: () => void;
  showBulkActions?: boolean;
  onBulkDelete?: () => void;
  bulkDeleteState?: string;
  // Advanced actions for posted content
  individualRepostFetcher?: PostFetcher;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
  onBulkRepost?: () => void;
  onBulkScheduledRepost?: () => void;
  onBulkQuote?: () => void;
  repostFetcher?: PostFetcher;
  // Edit and reschedule actions for scheduled content
  onEditPost?: (post: PostData | LongFormPostData) => void;
  onReschedulePost?: (post: PostData | LongFormPostData) => void;
}

export default function AllContentListing({
  content,
  type,
  searchTerm,
  onSearchChange,
  userTimezone,
  onPostSelect,
  selectedItems = new Set(),
  onToggleSelection,
  onToggleSelectAll,
  showBulkActions = false,
  onBulkDelete,
  bulkDeleteState = "idle",
  // Advanced actions
  individualRepostFetcher,
  longformRepostFetcher,
  longformQuoteFetcher,
  onBulkRepost,
  onBulkScheduledRepost,
  onBulkQuote,
  repostFetcher,
  // Edit and reschedule actions
  onEditPost,
  onReschedulePost,
}: AllContentListingProps) {
  const deleteFetcher = useFetcher<{
    success?: boolean;
    error?: string;
    needsSigning?: boolean;
    post?: PostData | LongFormPostData;
  }>();
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: "asc" | "desc";
  }>({
    key:
      type === "posted"
        ? "postedAt"
        : type === "scheduled"
          ? "scheduledFor"
          : "createdAt",
    direction: "desc",
  });

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const sortedContent = [...content].sort((a, b) => {
    let aValue: number | string;
    let bValue: number | string;

    if (sortConfig.key === "scheduledFor") {
      const aScheduled = a.scheduledFor;
      const bScheduled = b.scheduledFor;
      aValue =
        aScheduled && typeof aScheduled === "string"
          ? parseInt(aScheduled, 10) * 1000
          : 0;
      bValue =
        bScheduled && typeof bScheduled === "string"
          ? parseInt(bScheduled, 10) * 1000
          : 0;
    } else if (sortConfig.key === "postedAt") {
      const aPosted = a.postedAt;
      const bPosted = b.postedAt;
      aValue = aPosted ? new Date(aPosted).getTime() : 0;
      bValue = bPosted ? new Date(bPosted).getTime() : 0;
    } else if (
      sortConfig.key === "createdAt" ||
      sortConfig.key === "updatedAt"
    ) {
      const aKey = a[sortConfig.key];
      const bKey = b[sortConfig.key];
      aValue = aKey ? new Date(aKey).getTime() : 0;
      bValue = bKey ? new Date(bKey).getTime() : 0;
    } else {
      const aKey = a[sortConfig.key as keyof CombinedContent];
      const bKey = b[sortConfig.key as keyof CombinedContent];
      aValue = aKey ? (typeof aKey === "string" ? aKey : String(aKey)) : "";
      bValue = bKey ? (typeof bKey === "string" ? bKey : String(bKey)) : "";
    }

    if (aValue < bValue) {
      return sortConfig.direction === "asc" ? -1 : 1;
    }
    if (aValue > bValue) {
      return sortConfig.direction === "asc" ? 1 : -1;
    }
    return 0;
  });

  const filteredContent = sortedContent.filter(
    (item) =>
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR for filter logic
      item.caption?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR for filter logic
      item.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR for filter logic
      item.content?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.summary?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  return (
    <div>
      <ContentSearchBar
        searchTerm={searchTerm}
        onSearchChange={onSearchChange}
      />

      {showBulkActions ? (
        <ContentBulkActions
          type={type}
          selectedCount={selectedItems.size}
          onBulkDelete={onBulkDelete ?? (() => {})}
          onBulkRepost={onBulkRepost}
          onBulkScheduledRepost={onBulkScheduledRepost}
          onBulkQuote={onBulkQuote}
          bulkDeleteState={bulkDeleteState}
          repostFetcher={repostFetcher}
        />
      ) : null}

      {/* Content Table */}
      <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
        <table className="min-w-full whitespace-nowrap align-middle text-sm">
          <ContentTableHeader
            type={type}
            showBulkActions={showBulkActions}
            sortConfig={sortConfig}
            filteredContentLength={filteredContent.length}
            selectedItemsSize={selectedItems.size}
            onToggleSelectAll={onToggleSelectAll}
            onRequestSort={requestSort}
          />
          <tbody>
            {filteredContent.map((item) => (
              <ContentTableRow
                key={`${item.type}-${item.id}`}
                item={item}
                type={type}
                userTimezone={userTimezone}
                showBulkActions={showBulkActions}
                selectedItems={selectedItems}
                onToggleSelection={onToggleSelection}
                onPostSelect={onPostSelect}
                onEditPost={onEditPost}
                onReschedulePost={onReschedulePost}
                deleteFetcher={deleteFetcher as unknown as PostFetcher}
                individualRepostFetcher={individualRepostFetcher}
                longformRepostFetcher={longformRepostFetcher}
                longformQuoteFetcher={longformQuoteFetcher}
              />
            ))}
          </tbody>
        </table>
      </div>

      {filteredContent.length === 0 ? (
        <div className="mt-8 text-center">
          <p className="text-gray-500 dark:text-gray-400">No content found.</p>
        </div>
      ) : null}
    </div>
  );
}

/**
 * BulkPostCard Component
 * Individual post card for bulk scheduling view
 * Extracted from dashboard.bulkposts.tsx
 */
import MediaThumbnail from "~/components/ui/MediaThumbnail";

import { getDynamicQueueStyle } from "../queueColors";
import type { BulkPostCardProps, BulkPost, QueueType } from "../types";
// Re-export types for consumers
export type { BulkPost, QueueType };

/**
 * Get the image URL to display for a post
 */
function getDisplayImageUrl(post: BulkPost): string | null {
  if (post.isKind6Repost) {
    if (
      post.originalFileUrl &&
      (Array.isArray(post.originalFileUrl)
        ? post.originalFileUrl.length > 0
        : post.originalFileUrl)
    ) {
      let originalImageUrl = Array.isArray(post.originalFileUrl)
        ? post.originalFileUrl[0]
        : post.originalFileUrl;

      // Handle case where fileUrl might be a JSON string array
      if (
        typeof originalImageUrl === "string" &&
        originalImageUrl.startsWith("[")
      ) {
        try {
          const parsed = JSON.parse(originalImageUrl) as string[];
          if (Array.isArray(parsed) && parsed.length > 0) {
            originalImageUrl = parsed[0];
          }
        } catch {
          // If parsing fails, use as is
        }
      }
      return originalImageUrl ?? null;
    }
    return null;
  }

  if (post.isQuotePost && post.fileUrl && post.fileUrl.trim() !== "") {
    return post.fileUrl;
  }

  if (post.isRepost && post.fileUrl) {
    return post.fileUrl;
  }

  return null;
}

export function BulkPostCard({
  post,
  index,
  queueTypes,
  previewData,
  onCaptionChange,
  onDateChange,
  onQueueTypeChange,
  onIsRecyclableChange,
  onRemove,
  onMediaClick,
}: BulkPostCardProps) {
  const renderMediaPreview = () => {
    // Handle kind 6 reposts
    if (post.isKind6Repost) {
      const imageUrl = getDisplayImageUrl(post);
      if (imageUrl) {
        return (
          <div className="relative">
            <MediaThumbnail
              src={imageUrl}
              alt="Original post preview"
              className="h-24 w-24 rounded object-cover"
              onClick={() => onMediaClick(imageUrl)}
            />
            <div className="absolute -right-1 -top-1 rounded-full bg-purple-500 p-1">
              <svg
                className="h-3 w-3 text-white"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"
                />
              </svg>
            </div>
          </div>
        );
      }
      return (
        <div className="flex h-24 w-24 items-center justify-center rounded bg-purple-200 text-xs font-medium text-purple-800 dark:bg-purple-800 dark:text-purple-200">
          REPOST
        </div>
      );
    }

    // Handle quote posts
    if (post.isQuotePost) {
      const imageUrl = getDisplayImageUrl(post);
      if (imageUrl) {
        return (
          <div className="relative">
            <MediaThumbnail
              src={imageUrl}
              alt="Quote post preview"
              className="h-24 w-24 rounded object-cover"
              onClick={() => onMediaClick(imageUrl)}
            />
            <div className="absolute -right-1 -top-1 rounded-full bg-green-500 p-1">
              <svg
                className="h-3 w-3 text-white"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z"
                />
              </svg>
            </div>
          </div>
        );
      }
      return (
        <div className="flex h-24 w-24 items-center justify-center rounded bg-green-200 text-xs font-medium text-green-800 dark:bg-green-800 dark:text-green-200">
          QUOTE
        </div>
      );
    }

    // Handle regular reposts with file URL
    if (post.isRepost && post.fileUrl) {
      return (
        <MediaThumbnail
          src={post.fileUrl}
          alt="Preview"
          className="h-24 w-24 rounded object-cover"
          onClick={() => onMediaClick(post.fileUrl!)}
        />
      );
    }

    // Handle regular file uploads with preview data
    if (post.file) {
      const previewInfo = previewData.get(index);
      if (previewInfo) {
        return (
          <MediaThumbnail
            src={previewInfo.url}
            alt="Preview"
            className="h-24 w-24 rounded object-cover"
            onClick={() => onMediaClick(previewInfo.url)}
            forceType={previewInfo.isVideo ? "video" : "image"}
          />
        );
      }
    }

    // Fallback: TEXT placeholder
    return (
      <div className="flex h-24 w-24 items-center justify-center rounded bg-gray-200 text-xs font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300">
        TEXT
      </div>
    );
  };

  return (
    <tr className="border-b">
      <td className="p-4">
        {renderMediaPreview()}
        <input type="file" name="files" hidden />
      </td>
      <td className="p-4">
        <div className="space-y-2">
          <textarea
            name="captions"
            value={post.caption}
            onChange={(e) => onCaptionChange(index, e.target.value)}
            disabled={post.isKind6Repost}
            className={`w-full rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100 ${post.isKind6Repost ? "cursor-not-allowed bg-gray-100 dark:bg-gray-700" : ""}`}
            rows={3}
            placeholder={
              post.isKind6Repost
                ? "Kind 6 reposts have no content..."
                : post.isQuotePost
                  ? "Add your comment to this quote post..."
                  : "Write your caption..."
            }
          />
          {(post.isKind6Repost ?? post.isQuotePost) && post.originalCaption ? (
            <div className="rounded border bg-gray-50 p-2 text-xs text-gray-500 dark:bg-gray-800 dark:text-gray-400">
              <strong>Original:</strong>{" "}
              {post.originalCaption.length > 100
                ? post.originalCaption.substring(0, 100) + "..."
                : post.originalCaption}
            </div>
          ) : null}
        </div>
      </td>
      <td className="p-4">
        <div className="flex flex-wrap gap-1">
          {queueTypes.map((queue: QueueType | string) => {
            const queueName =
              typeof queue === "string" ? queue : (queue.name ?? "");
            const queueColor = typeof queue === "object" ? queue.color : null;
            return (
              <button
                key={queueName}
                type="button"
                onClick={() => onQueueTypeChange(index, queueName ?? "")}
                className={`rounded-full px-3 py-1 text-xs ${getDynamicQueueStyle(queueColor ?? null, (post.queueType ?? null) === queueName)}`}
                style={{
                  backgroundColor: queueColor ?? undefined,
                  borderColor: queueColor ?? undefined,
                }}
              >
                {queueName}
              </button>
            );
          })}
        </div>
      </td>
      <td className="p-4">
        <input
          type="datetime-local"
          name="scheduledDates"
          value={post.scheduledFor}
          onChange={(e) => onDateChange(index, e.target.value)}
          className="rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
        />
      </td>
      <td className="p-4">
        <div className="flex items-center">
          <input
            id={`recyclable-${index}`}
            type="checkbox"
            checked={post.isRecyclable ?? false}
            onChange={(e) => onIsRecyclableChange(index, e.target.checked)}
            className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
          />
          <label
            htmlFor={`recyclable-${index}`}
            className="ml-2 text-sm text-gray-700 dark:text-gray-300"
          >
            Recyclable
          </label>
        </div>
      </td>
      <td className="p-4">
        <button
          type="button"
          onClick={() => onRemove(index)}
          className="rounded bg-red-500 px-3 py-1 text-white hover:bg-red-600"
        >
          Remove
        </button>
      </td>
    </tr>
  );
}

export default BulkPostCard;

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";

import { getDynamicQueueStyle } from "../queueColors";

import type { BulkPost, QueueType } from "./BulkPostCard";

interface BulkPostsActionButtonsProps {
  posts: BulkPost[];
  isProcessing: boolean;
  scheduleIntervals: number[] | undefined;
  queueTypes: QueueType[];
  hashTagPresets: Array<{ id: string; name: string; hashtags: string }>;
  selectedHashtagPresetId: string | null;
  useHashtagPresets: boolean;
  handleScheduleIntervalClick: (interval: number) => void;
  handleBulkQueueUpdate: (queueName: string) => void;
  handleHashtagPresetSelect: (
    presetId: string | null,
    hashtags: string,
  ) => void;
  setUseHashtagPresets: (use: boolean) => void;
  handleBulkRecyclableToggle: () => void;
}

export default function BulkPostsActionButtons({
  posts,
  isProcessing,
  scheduleIntervals,
  queueTypes,
  hashTagPresets,
  selectedHashtagPresetId,
  useHashtagPresets,
  handleScheduleIntervalClick,
  handleBulkQueueUpdate,
  handleHashtagPresetSelect,
  setUseHashtagPresets,
  handleBulkRecyclableToggle,
}: BulkPostsActionButtonsProps) {
  if (posts.length === 0) return null;

  return (
    <>
      <div className="mb-4 mt-4 flex flex-col items-center gap-3">
        <div className="flex justify-center">
          {scheduleIntervals
            ? scheduleIntervals.map((interval) => (
                <button
                  key={interval}
                  type="button"
                  onClick={() => handleScheduleIntervalClick(interval)}
                  disabled={isProcessing}
                  className="mx-2 rounded-md bg-gray-100 px-4 py-2 text-sm font-medium text-gray-700 shadow-md transition-all hover:scale-105 hover:bg-gray-200 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                >
                  +{interval}h
                </button>
              ))
            : null}
        </div>
      </div>

      <div className="mb-6">
        <div className="flex flex-wrap justify-center gap-2">
          {queueTypes.map((queue) => {
            const queueName =
              typeof queue === "string" ? queue : (queue.name ?? "");
            const queueColor = typeof queue === "object" ? queue.color : null;
            // Check if this queue is selected for all posts
            const isAllSelected =
              posts.length > 0 && posts.every((p) => p.queueType === queueName);
            return (
              <button
                key={queueName}
                type="button"
                onClick={() => {
                  handleBulkQueueUpdate(queueName ?? "");
                }}
                disabled={isProcessing}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, isAllSelected)} disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100`}
                style={{
                  backgroundColor: queueColor ?? undefined,
                  borderColor: queueColor ?? undefined,
                }}
              >
                {queueName}
              </button>
            );
          })}
        </div>
        <p className="mt-2 text-center text-xs text-gray-500 dark:text-gray-400">
          Click a queue to update all posts
        </p>
      </div>

      <div className="mx-auto mb-6 max-w-md">
        <HashtagPresetToggle
          presets={hashTagPresets.map((p) => ({
            id: p.id,
            name: p.name,
            tags: p.hashtags,
          }))}
          selectedPresetId={selectedHashtagPresetId}
          onSelect={handleHashtagPresetSelect}
          disabled={isProcessing}
          useHashtagPresets={useHashtagPresets}
          onUseHashtagPresetsChange={setUseHashtagPresets}
          showQueuePreset={false}
        />
      </div>

      <div className="mb-6">
        <div className="flex justify-center">
          <button
            type="button"
            onClick={handleBulkRecyclableToggle}
            disabled={isProcessing}
            className="rounded-md bg-purple-100 px-4 py-2 text-sm font-medium text-purple-700 shadow-md transition-all hover:scale-105 hover:bg-purple-200 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 dark:bg-purple-800 dark:text-purple-300 dark:hover:bg-purple-700"
          >
            {posts.every((post) => post.isRecyclable)
              ? "Mark All Non-Recyclable"
              : "Mark All Recyclable"}
          </button>
        </div>
        <p className="mt-2 text-center text-xs text-gray-500 dark:text-gray-400">
          Toggle recyclable status for all posts
        </p>
      </div>
    </>
  );
}

import MediaThumbnail from "~/components/ui/MediaThumbnail";

import { getDynamicQueueStyle } from "../queueColors";

import type { BulkPost, QueueType } from "./BulkPostCard";

interface BulkPostsTableProps {
  posts: BulkPost[];
  queueTypes: QueueType[];
  previewData: Map<number, { url: string; isVideo: boolean; file: File }>;
  handleCaptionChange: (index: number, value: string) => void;
  handleDateChange: (index: number, value: string) => void;
  handleIsRecyclableChange: (index: number, checked: boolean) => void;
  handleRemovePost: (index: number) => void;
  handleQueueTypeChange: (index: number, value: string) => void;
  handleMediaClick: (mediaSrc: string) => void;
}

export default function BulkPostsTable({
  posts,
  queueTypes,
  previewData,
  handleCaptionChange,
  handleDateChange,
  handleIsRecyclableChange,
  handleRemovePost,
  handleQueueTypeChange,
  handleMediaClick,
}: BulkPostsTableProps) {
  if (posts.length === 0) return null;

  return (
    <div className="overflow-x-auto">
      <table className="w-full border-collapse">
        <thead>
          <tr className="border-b">
            <th className="p-4 text-left">Media</th>
            <th className="p-4 text-left">Caption</th>
            <th className="p-4 text-left">Queue</th>
            <th className="p-4 text-left">Schedule</th>
            <th className="p-4 text-left">Recyclable</th>
            <th className="p-4 text-left">Actions</th>
          </tr>
        </thead>
        <tbody>
          {posts.map((post, index) => (
            <tr key={index} className="border-b">
              <td className="p-4">
                {(() => {
                  let imageUrl = "";

                  if (post.isKind6Repost) {
                    // For kind 6 reposts, check if original post has images
                    if (
                      post.originalFileUrl &&
                      post.originalFileUrl.length > 0
                    ) {
                      // Try to get the first image URL from the original post
                      let originalImageUrl = "";

                      if (Array.isArray(post.originalFileUrl)) {
                        originalImageUrl = post.originalFileUrl[0] ?? "";
                      } else {
                        originalImageUrl = post.originalFileUrl ?? "";
                      }

                      // Handle case where fileUrl might be a JSON string array
                      if (
                        typeof originalImageUrl === "string" &&
                        originalImageUrl.startsWith("[")
                      ) {
                        try {
                          const parsed = JSON.parse(
                            originalImageUrl,
                          ) as string[];
                          if (Array.isArray(parsed) && parsed.length > 0) {
                            originalImageUrl = parsed[0] ?? "";
                          }
                        } catch (_e) {
                          // If parsing fails, use as is
                        }
                      }

                      return (
                        <div className="relative">
                          <MediaThumbnail
                            src={originalImageUrl}
                            alt="Original post preview"
                            className="h-24 w-24 rounded object-cover"
                            onClick={() => handleMediaClick(originalImageUrl)}
                          />
                          <div className="absolute -right-1 -top-1 rounded-full bg-purple-500 p-1">
                            <svg
                              className="h-3 w-3 text-white"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"
                              />
                            </svg>
                          </div>
                        </div>
                      );
                    } else {
                      // Show REPOST placeholder for text-only reposts
                      return (
                        <div className="flex h-24 w-24 items-center justify-center rounded bg-purple-200 text-xs font-medium text-purple-800 dark:bg-purple-800 dark:text-purple-200">
                          REPOST
                        </div>
                      );
                    }
                  } else if (post.isQuotePost) {
                    // Handle quote posts - always show image if available
                    if (post.fileUrl && post.fileUrl.trim() !== "") {
                      let fileUrl = "";
                      if (Array.isArray(post.fileUrl)) {
                        fileUrl =
                          typeof post.fileUrl[0] === "string"
                            ? post.fileUrl[0]
                            : "";
                      } else {
                        fileUrl =
                          typeof post.fileUrl === "string" ? post.fileUrl : "";
                      }

                      return (
                        <div className="relative">
                          <MediaThumbnail
                            src={fileUrl}
                            alt="Quote post preview"
                            className="h-24 w-24 rounded object-cover"
                            onClick={() => handleMediaClick(fileUrl)}
                          />
                          <div className="absolute -right-1 -top-1 rounded-full bg-green-500 p-1">
                            <svg
                              className="h-3 w-3 text-white"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z"
                              />
                            </svg>
                          </div>
                        </div>
                      );
                    } else {
                      // Show QUOTE placeholder for text-only quote posts
                      return (
                        <div className="flex h-24 w-24 items-center justify-center rounded bg-green-200 text-xs font-medium text-green-800 dark:bg-green-800 dark:text-green-200">
                          QUOTE
                        </div>
                      );
                    }
                  } else if (post.isRepost && post.fileUrl) {
                    // Handle repost fileUrl which should now be a single URL string
                    if (Array.isArray(post.fileUrl)) {
                      imageUrl =
                        typeof post.fileUrl[0] === "string"
                          ? post.fileUrl[0]
                          : "";
                    } else {
                      imageUrl =
                        typeof post.fileUrl === "string" ? post.fileUrl : "";
                    }
                  } else if (post.file) {
                    // Handle regular file uploads - use previewData which includes type info
                    const previewInfo = previewData.get(index);
                    if (previewInfo) {
                      return (
                        <MediaThumbnail
                          src={previewInfo.url}
                          alt="Preview"
                          className="h-24 w-24 rounded object-cover"
                          onClick={() => handleMediaClick(previewInfo.url)}
                          forceType={previewInfo.isVideo ? "video" : "image"}
                        />
                      );
                    }
                  }

                  // Fallback for repost with fileUrl
                  if (imageUrl && imageUrl.trim() !== "") {
                    return (
                      <MediaThumbnail
                        src={imageUrl}
                        alt="Preview"
                        className="h-24 w-24 rounded object-cover"
                        onClick={() => handleMediaClick(imageUrl)}
                      />
                    );
                  } else {
                    // Show TEXT placeholder for text-only posts
                    return (
                      <div className="flex h-24 w-24 items-center justify-center rounded bg-gray-200 text-xs font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300">
                        TEXT
                      </div>
                    );
                  }
                })()}
                <input type="file" name="files" hidden />
              </td>
              <td className="p-4">
                <div className="space-y-2">
                  <textarea
                    name="captions"
                    value={post.caption}
                    onChange={(e) => handleCaptionChange(index, e.target.value)}
                    disabled={post.isKind6Repost}
                    className={`w-full rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100 ${post.isKind6Repost ? "cursor-not-allowed bg-gray-100 dark:bg-gray-700" : ""}`}
                    rows={3}
                    placeholder={
                      post.isKind6Repost
                        ? "Kind 6 reposts have no content..."
                        : post.isQuotePost
                          ? "Add your comment to this quote post..."
                          : "Write your caption..."
                    }
                  />
                  {(post.isKind6Repost || post.isQuotePost) &&
                  post.originalCaption ? (
                    <div className="rounded border bg-gray-50 p-2 text-xs text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                      <strong>Original:</strong>{" "}
                      {post.originalCaption.length > 100
                        ? post.originalCaption.substring(0, 100) + "..."
                        : post.originalCaption}
                    </div>
                  ) : null}
                </div>
              </td>
              <td className="p-4">
                <div className="flex flex-wrap gap-1">
                  {queueTypes.map((queue) => {
                    const queueName =
                      typeof queue === "string" ? queue : (queue.name ?? "");
                    const queueColor =
                      typeof queue === "object" ? queue.color : null;
                    return (
                      <button
                        key={queueName}
                        type="button"
                        onClick={() => {
                          handleQueueTypeChange(index, queueName ?? "");
                        }}
                        className={`rounded-full px-3 py-1 text-xs ${getDynamicQueueStyle(queueColor ?? null, post.queueType === queueName)}`}
                        style={{
                          backgroundColor: queueColor ?? undefined,
                          borderColor: queueColor ?? undefined,
                        }}
                      >
                        {queueName}
                      </button>
                    );
                  })}
                </div>
              </td>
              <td className="p-4">
                <input
                  type="datetime-local"
                  name="scheduledDates"
                  value={post.scheduledFor}
                  onChange={(e) => handleDateChange(index, e.target.value)}
                  className="rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
                />
              </td>
              <td className="p-4">
                <div className="flex items-center">
                  <input
                    id={`bulk-recyclable-${index}`}
                    type="checkbox"
                    checked={post.isRecyclable ?? false}
                    onChange={(e) =>
                      handleIsRecyclableChange(index, e.target.checked)
                    }
                    className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <label
                    htmlFor={`bulk-recyclable-${index}`}
                    className="ml-2 text-sm text-gray-700 dark:text-gray-300"
                  >
                    Recyclable
                  </label>
                </div>
              </td>
              <td className="p-4">
                <button
                  type="button"
                  onClick={() => handleRemovePost(index)}
                  className="rounded bg-red-500 px-3 py-1 text-white hover:bg-red-600"
                >
                  Remove
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { isVideoFile } from "~/lib/helpers";

import { PostBadges } from "./PostBadges";
import type { PostBlockBaseProps, QueueColorStyle } from "./PostBlock.types";
import {
  getPostPreview,
  getFirstImage,
  getStatusColor,
  getDisplayTime,
} from "./PostBlock.utils";
import { PostIcon } from "./PostIcon";
import { PostStatusIcons } from "./PostStatusIcons";

interface CompactPostBlockProps extends PostBlockBaseProps {
  queueColorStyle: QueueColorStyle | null;
  userTimezone: string;
  timeString: string;
}

export function CompactPostBlock({
  post,
  user: _user,
  isLongform,
  isPast,
  isDragging,
  onDragStart,
  onDragEnd,
  onClick,
  onKeyDown,
  queueColorStyle,
  userTimezone,
  timeString,
}: CompactPostBlockProps) {
  const firstImage = getFirstImage(post, isLongform ?? false);
  const postPreview = getPostPreview(post, isLongform ?? false);
  const displayTime = getDisplayTime(
    post,
    isLongform ?? false,
    isPast ?? false,
  );

  return (
    <div
      draggable={!isPast}
      onDragStart={onDragStart}
      onDragEnd={onDragEnd}
      onClick={onClick}
      onKeyDown={onKeyDown}
      tabIndex={0}
      role="button"
      aria-label={`${isPast ? "View" : "Edit"} ${isLongform ? "longform post" : "post"}: ${postPreview}, ${isPast ? "posted" : isLongform ? "published" : "scheduled"} for ${displayTime.toLocaleString("en-US", { timeZone: userTimezone })}`}
      className={`rounded-md border p-2 text-xs transition-all focus:outline-none focus:ring-2 focus:ring-blue-500 ${
        isPast ? "cursor-default" : "cursor-pointer"
      } ${
        isDragging ? "rotate-2 opacity-50" : isPast ? "" : "hover:shadow-md"
      } ${queueColorStyle ? "" : getStatusColor(post, isLongform ?? false, isPast ?? false)} ${queueColorStyle ? "" : "border-current border-opacity-20"}`}
      style={queueColorStyle ?? {}}
      title={`${postPreview}\n${isPast ? "Posted" : isLongform ? "Published" : "Scheduled"} for ${displayTime.toLocaleString("en-US", { timeZone: userTimezone })}\n${isPast ? "Past post (view only)" : "Click to edit"}`}
    >
      <div className="mb-1 flex items-start justify-between">
        <div className="flex items-center space-x-1">
          {firstImage ? (
            <div className="relative">
              <MediaThumbnail
                src={firstImage}
                alt="Post thumbnail"
                className="h-4 w-4 flex-shrink-0 rounded"
                forceType={isVideoFile(firstImage) ? "video" : "image"}
                hidePlayButton={true}
                fallback={
                  <div className="h-4 w-4 flex-shrink-0 rounded bg-gray-200 dark:bg-gray-600" />
                }
              />
              <PostBadges post={post} size="sm" />
            </div>
          ) : (
            <div className="relative">
              <PostIcon post={post} isLongform={isLongform ?? false} />
              <PostBadges post={post} size="sm" />
            </div>
          )}
          <span className="font-medium">{timeString}</span>
        </div>

        <PostStatusIcons post={post} isLongform={isLongform ?? false} />
      </div>

      {/* Show image thumbnail if available, otherwise show text preview */}
      {firstImage ? (
        <div className="space-y-1">
