import { handleErrorSafely } from "~/lib/error-handler.client";
import { isVideoFile } from "~/lib/helpers";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { QueueType, UserData } from "../../types";

import type { CalendarPost } from "./PostBlock.types";
interface RescheduleData {
  post: CalendarPost;
  newDateTime: Date;
  wasAutoScheduled: boolean;
  queueName: string | null;
  isEdit: boolean;
  isLongform: boolean;
}

interface RescheduleModalProps {
  data: RescheduleData | null;
  onClose: () => void;
  onConfirm: (success?: boolean) => void;
  user?: UserData | null;
  queueTypes?: QueueType[];
}

export function RescheduleModal({
  data,
  onClose,
  onConfirm,
  user: userProp,
  queueTypes,
}: RescheduleModalProps) {
  interface FetcherData {
    success?: boolean;
    needsSigning?: boolean;
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const loaderData = useLoaderData<{ user?: UserData }>();
  const user = userProp ?? loaderData?.user;
  const [isSigningEvent, setIsSigningEvent] = useState(false);
  const [signingError, setSigningError] = useState<string | null>(null);
  const [editableDateTime, setEditableDateTime] = useState<Date | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [selectedQueueType, setSelectedQueueType] = useState<string | null>(
    null,
  );

  useEffect(() => {
    if (fetcher.data?.success) {
      if (fetcher.data.needsSigning) {
        // Event was rescheduled but needs re-signing, keep modal open
        return;
      }
      toast.success("Post rescheduled and re-signed successfully!");
      onConfirm(true);
    }
    if (fetcher.data?.error) {
      toast.error(`Reschedule failed: ${fetcher.data.error}`);
    }
  }, [fetcher.data, onConfirm]);

  // Initialize editable datetime and queue type when data changes
  useEffect(() => {
    if (data) {
      setEditableDateTime(data.newDateTime);
      setValidationError(null);
      setSelectedQueueType(data.post.queueType?.id ?? null);
    }
  }, [data]);

  if (!data) return null;

  const { post, wasAutoScheduled, isEdit } = data;

  const getFirstMedia = (): string | null => {
    if (data.isLongform && post.image) {
      return post.image;
    }

    if (post.fileUrl && post.fileUrl.length > 0) {
      try {
        const firstFileUrl = post.fileUrl[0];
        if (typeof firstFileUrl === "string") {
          try {
            const parsed = JSON.parse(firstFileUrl) as string[] | string;
            return Array.isArray(parsed) ? (parsed[0] ?? null) : firstFileUrl;
          } catch {
            return firstFileUrl;
          }
        }
        return (firstFileUrl as string | undefined) ?? null;
      } catch (error) {
        handleErrorSafely(error, {
          component: "RescheduleModal",
          action: "getFirstMedia",
        });
        return null;
      }
    }
    return null;
  };

  const formatDateTime = (date: Date): string => {
    const userTimezone = user?.timezone ?? "Etc/UTC";
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: userTimezone,
    });
  };

  const validateDateTime = (dateTime: Date | null): boolean => {
    if (!dateTime) return false;
    const now = new Date();
    const userTimezone = user?.timezone ?? "Etc/UTC";
    const nowInUserTz = new Date(
      now.toLocaleString("en-US", { timeZone: userTimezone }),
    );

    if (dateTime <= nowInUserTz) {
      setValidationError("Cannot schedule posts in the past");
      return false;
    }

    setValidationError(null);
    return true;
  };

  const handleDateTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = new Date(e.target.value);
    setEditableDateTime(newValue);
    validateDateTime(newValue);
  };

  const formatDateTimeForInput = (date: Date): string => {
    const userTimezone = user?.timezone ?? "Etc/UTC";
    // Create date string in format needed for datetime-local input
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone }),
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleConfirm = async (shouldOverride = false) => {
    // Validate the selected time
    if (!validateDateTime(editableDateTime)) {
      return;
    }

    if (!editableDateTime) return;

    const newTimeUnix = Math.floor(editableDateTime.getTime() / 1000);

    try {
      setIsSigningEvent(true);

      // Use the exact same content and tags from the original signed event
      const originalSignedEvent = post.signedEvent as
        | { content: string; kind?: number; tags?: string[][] }
        | undefined;
      const originalNostrEvent = post.nostrEvent;

      if (!originalSignedEvent || !originalNostrEvent) {
        throw new Error(
          "Original event not found. Cannot reschedule unsigned posts.",
        );
      }

      // Re-sign with the same content but new timestamp
      const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
        content: originalSignedEvent.content, // Use exact same content
        created_at: newTimeUnix, // Only change the timestamp
        kind: originalSignedEvent.kind ?? 1,
        tags: originalSignedEvent.tags ?? [], // Use exact same tags
      });

      // Submit the reschedule action with signed event
      const formData = new FormData();
      formData.append("action", "reschedule");
      formData.append("postId", post.id);
      formData.append("newTime", newTimeUnix.toString());
      formData.append("overrideQueue", shouldOverride.toString());
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      if (selectedQueueType) {
        formData.append("queueTypeId", selectedQueueType);
      }

      fetcher.submit(formData, { method: "post" });
    } catch (error) {
      console.error("Error re-signing event:", error);
      setIsSigningEvent(false);
      const errorMessage =
        error instanceof Error
          ? error.message
          : "Failed to sign event. Please try again.";
      setSigningError(errorMessage);
      toast.error(errorMessage);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-md rounded-lg bg-white shadow-xl dark:bg-gray-800">
        <div className="p-6">
          {/* Header */}
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              {isEdit
                ? "Edit Post Schedule"
                : wasAutoScheduled
                  ? "Override Queue Logic?"
                  : "Update Post Time?"}
            </h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
            >
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>

          {/* Content */}
          <div className="space-y-4">
            {/* Post preview */}
            <div className="rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
              <div className="mb-2 text-sm font-medium text-gray-900 dark:text-white">
                Post Preview:
              </div>

              {/* Show media thumbnail if available */}
              {getFirstMedia() ? (
                <div className="mb-2">
                  <div className="post-thumbnail h-20 w-full overflow-hidden rounded-md">
                    <MediaThumbnail
                      src={getFirstMedia()}
                      alt="Post preview"
                      className="h-full w-full rounded-md"
                      forceType={
                        isVideoFile(getFirstMedia()!) ? "video" : "image"
                      }
                      hidePlayButton={false}
                      fallback={
                        <div className="flex h-full w-full items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                          {post.postType === "VIDEO" ||
                          isVideoFile(getFirstMedia()!)
                            ? "VIDEO"
                            : "MEDIA"}
                        </div>
                      }
                    />
                  </div>
                </div>
              ) : null}

              <div className="text-sm text-gray-600 dark:text-gray-300">
                {post.caption ? (
                  <span
                    style={{
                      display: "inline-block",
                      maxWidth: "100%",
                      wordBreak: "break-word",
                      whiteSpace: "pre-line",
                      overflowWrap: "anywhere",
                    }}
                  >
                    {post.caption}
                  </span>
                ) : (
                  "No caption"
                )}
                {post.fileUrl && post.fileUrl.length > 0 ? (
                  <span className="ml-2 text-xs text-gray-500">
                    ({post.fileUrl.length} file
                    {post.fileUrl.length > 1 ? "s" : ""})
                  </span>
                ) : null}
              </div>
            </div>

            {/* New time */}
            <div className="space-y-2">
              <label
                htmlFor="reschedule-datetime"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                {isEdit ? "Edit scheduled time:" : "New time:"}
              </label>
              <div className="flex items-center space-x-2">
                <svg
                  className="h-4 w-4 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                <input
                  id="reschedule-datetime"
                  type="datetime-local"
                  value={
                    editableDateTime
                      ? formatDateTimeForInput(editableDateTime)
                      : ""
                  }
                  onChange={handleDateTimeChange}
                  className="flex-1 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>
              {editableDateTime ? (
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {formatDateTime(editableDateTime)}
                </div>
              ) : null}
            </div>

            {/* Queue Type Selection */}
            <div className="space-y-2">
              <label
                htmlFor="reschedule-queue-type"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                Queue Type:
              </label>
              <select
                id="reschedule-queue-type"
                value={selectedQueueType ?? ""}
                onChange={(e) => setSelectedQueueType(e.target.value || null)}
                className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                <option value="">Manual (No Queue)</option>
                {queueTypes
                  ? queueTypes.map((queueType) => (
                      <option key={queueType.id} value={queueType.id}>
                        {queueType.name}
                      </option>
                    ))
                  : null}
              </select>
              <div className="text-xs text-gray-500 dark:text-gray-400">
                {selectedQueueType
                  ? "Post will be managed by the selected queue type"
                  : "Post will be manually scheduled"}
              </div>
            </div>

            {/* Re-signing warning */}
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 dark:border-blue-800 dark:bg-blue-900/20">
              <div className="flex items-start space-x-2">
                <svg
                  className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                  fill="currentColor"
                  viewBox="0 0 20 20"
                >
                  <path
                    fillRule="evenodd"
                    d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                    clipRule="evenodd"
                  />
                </svg>
                <div>
                  <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                    {isEdit ? "Editing this post" : "Rescheduling this post"}{" "}
                    requires re-signing the Nostr event
                  </div>
                  <div className="mt-1 text-xs text-blue-700 dark:text-blue-300">
                    Your Nostr client will prompt you to sign the updated event
                    with the new timestamp.
                  </div>
                </div>
              </div>
            </div>

            {/* Validation error */}
            {validationError ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {validationError}
                </div>
              </div>
            ) : null}

            {/* Error display */}
            {(fetcher.data?.error ?? signingError) ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {fetcher.data?.error ?? signingError}
                </div>
              </div>
            ) : null}
          </div>

          {/* Actions */}
          <div className="mt-6 flex items-center justify-end space-x-3">
            <button
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
            >
              Cancel
            </button>

            {wasAutoScheduled && Boolean(wasAutoScheduled) ? (
              <button
                onClick={() => void handleConfirm(false)}
                className="rounded-lg border border-blue-300 px-4 py-2 text-sm font-medium text-blue-600 hover:bg-blue-50 hover:text-blue-700 dark:border-blue-600 dark:text-blue-400 dark:hover:bg-blue-900/20 dark:hover:text-blue-300"
              >
                Keep Queue Rule
              </button>
            ) : null}

            <button
              onClick={() => void handleConfirm(wasAutoScheduled)}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
              disabled={
                fetcher.state === "submitting" ||
                isSigningEvent ||
                !!validationError
              }
            >
              {isSigningEvent
                ? "Signing Event..."
                : fetcher.state === "submitting"
                  ? "Updating..."
                  : isEdit
                    ? "Save Changes"
                    : wasAutoScheduled
                      ? "Convert to Manual"
                      : "Confirm"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";

import { handleErrorSafely } from "~/lib/error-handler.client";

import type { QueueType, UserData } from "../../types";

import { PostBlock } from "./PostBlock";
import type { CalendarPost } from "./PostBlock.types";

interface WeeklyViewProps {
  scheduledPosts: CalendarPost[];
  pastPosts?: CalendarPost[];
  currentDate: Date;
  onPostDrop: (post: CalendarPost, newDateTime: Date) => void;
  onPostEdit: (post: CalendarPost) => void;
  user?: UserData | null;
  queueTypes?: QueueType[];
  isLongform?: boolean;
  isAll?: boolean;
}

type PostsGrid = Record<string, Record<string, CalendarPost[]>>;

interface CurrentTimeIndicatorProps {
  user?: UserData | null;
  weekDays: Date[];
}

export function WeeklyView({
  scheduledPosts,
  pastPosts = [],
  currentDate,
  onPostDrop,
  onPostEdit,
  user,
  queueTypes,
  isLongform = false,
  isAll = false,
}: WeeklyViewProps) {
  const [dragOverSlot, setDragOverSlot] = useState<string | null>(null);

  // Generate week days starting from Monday
  const weekDays = useMemo(() => {
    const days: Date[] = [];
    const startOfWeek = new Date(currentDate);
    const day = startOfWeek.getDay();
    const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1); // Adjust for Monday start
    startOfWeek.setDate(diff);

    for (let i = 0; i < 7; i++) {
      const date = new Date(startOfWeek);
      date.setDate(startOfWeek.getDate() + i);
      days.push(date);
    }
    return days;
  }, [currentDate]);

  // Generate hours (00:00 to 23:30)
  const hours = useMemo(() => {
    const hoursList: string[] = [];
    for (let h = 0; h < 24; h++) {
      hoursList.push(`${h.toString().padStart(2, "0")}:00`);
      hoursList.push(`${h.toString().padStart(2, "0")}:30`);
    }
    return hoursList;
  }, []);

  // Group posts by date and time
  const postsGrid = useMemo(() => {
    const grid: PostsGrid = {};
    const userTimezone = user?.timezone ?? "Etc/UTC";

    // Initialize grid with user timezone date keys
    weekDays.forEach((day) => {
      const year = day.getFullYear();
      const month = String(day.getMonth() + 1).padStart(2, "0");
      const dayStr = String(day.getDate()).padStart(2, "0");
      const dateKey = `${year}-${month}-${dayStr}`;
      grid[dateKey] = {};
    });

    // Process scheduled posts
    scheduledPosts.forEach((post) => {
      // Determine if this specific post is longform when in All tab
      const postIsLongform = isAll
        ? !!post.title && post.publishedAt
        : isLongform;
      // For longform posts, use publishedAt, for regular posts use scheduledFor
      const timestamp = postIsLongform ? post.publishedAt : post.scheduledFor;
      if (timestamp) {
        const postDate = postIsLongform
          ? new Date(timestamp as string)
          : new Date(Number(timestamp) * 1000);
        // Convert to user's timezone for display
        const timeInUserTz = new Date(
          postDate.toLocaleString("en-US", { timeZone: userTimezone }),
        );
        const year = timeInUserTz.getFullYear();
        const month = String(timeInUserTz.getMonth() + 1).padStart(2, "0");
        const dayStr = String(timeInUserTz.getDate()).padStart(2, "0");
        const dateKey = `${year}-${month}-${dayStr}`;
        const hour = timeInUserTz.getHours();
        const minutes = timeInUserTz.getMinutes();
        const timeSlot = `${hour.toString().padStart(2, "0")}:${minutes >= 30 ? "30" : "00"}`;

        if (grid[dateKey]) {
          grid[dateKey][timeSlot] ??= [];
          grid[dateKey][timeSlot].push({ ...post, isPast: false });
        }
      }
    });

    // Process past posts
    pastPosts.forEach((post) => {
      // Use postedAt for past posts
      const timestamp = post.postedAt;
      if (timestamp) {
        const postDate = new Date(timestamp as string);
        // Convert to user's timezone for display
        const timeInUserTz = new Date(
          postDate.toLocaleString("en-US", { timeZone: userTimezone }),
        );
        const year = timeInUserTz.getFullYear();
        const month = String(timeInUserTz.getMonth() + 1).padStart(2, "0");
        const dayStr = String(timeInUserTz.getDate()).padStart(2, "0");
        const dateKey = `${year}-${month}-${dayStr}`;
        const hour = timeInUserTz.getHours();
        const minutes = timeInUserTz.getMinutes();
        const timeSlot = `${hour.toString().padStart(2, "0")}:${minutes >= 30 ? "30" : "00"}`;

        if (grid[dateKey]) {
          grid[dateKey][timeSlot] ??= [];
          grid[dateKey][timeSlot].push({ ...post, isPast: true });
        }
      }
    });

    return grid;
  }, [scheduledPosts, pastPosts, weekDays, user?.timezone, isLongform, isAll]);

  const handleDragOver = (
    e: React.DragEvent<HTMLDivElement>,
    date: string,
    time: string,
  ) => {
    e.preventDefault();
    setDragOverSlot(`${date}-${time}`);
  };

  const handleDrop = (
    e: React.DragEvent<HTMLDivElement>,
    date: string,
    time: string,
  ) => {
    e.preventDefault();
    setDragOverSlot(null);

    const postData = JSON.parse(
      e.dataTransfer.getData("text/plain"),
    ) as CalendarPost;
    const [hours, minutes] = time.split(":").map(Number);
    const safeHours = hours ?? 0;
    const safeMinutes = minutes ?? 0;

    // Create the datetime that represents the intended time in the user's timezone
    const userTimezone = user?.timezone ?? "Etc/UTC";

    // Create an ISO string that represents the local time in the user's timezone
    const isoString = `${date}T${safeHours.toString().padStart(2, "0")}:${safeMinutes.toString().padStart(2, "0")}:00`;

    // Use a library approach - create the date as if it's in user's timezone
    // This is the reverse of how we display dates - we convert from user timezone to UTC
    try {
      // Create a temporary date in browser's local timezone
      const tempDate = new Date(isoString);

      // Convert to user's timezone and back to get the right UTC offset
      const userTzDate = new Date(
        tempDate.toLocaleString("sv-SE", { timeZone: userTimezone }),
      );
      const localTzDate = new Date(tempDate.toLocaleString("sv-SE"));

      // Calculate the difference and apply it
      const diff = localTzDate.getTime() - userTzDate.getTime();
      const newDateTime = new Date(tempDate.getTime() + diff);

      onPostDrop(postData, newDateTime);
    } catch (error) {
      handleErrorSafely(
        error,
        {
          component: "WeeklyView",
          action: "handleDrop",
        },
        () => {
          // Fallback to simple date creation
          const newDateTime = new Date(isoString);
          onPostDrop(postData, newDateTime);
        },
      );
    }
  };

  const handleDragLeave = () => {
    setDragOverSlot(null);
  };

  return (
    <div className="flex h-[70vh] flex-col overflow-hidden">
      {/* Days header */}
      <div className="flex border-b border-gray-200 dark:border-gray-700">
        <div className="w-16 flex-shrink-0"></div>
        {weekDays.map((day, index) => {
          const isToday = day.toDateString() === new Date().toDateString();
          return (
            <div
              key={index}
              className={`min-w-0 flex-1 border-r border-gray-200 p-3 text-center last:border-r-0 dark:border-gray-700 ${
                isToday ? "bg-blue-50 dark:bg-blue-900/20" : ""
              }`}
            >
              <div className="text-sm font-medium text-gray-900 dark:text-white">
                {day.toLocaleDateString("en-US", {
                  weekday: "short",
                  timeZone: user?.timezone ?? "Etc/UTC",
                })}
              </div>
              <div
                className={`mt-1 text-lg font-semibold ${
                  isToday
                    ? "text-blue-600 dark:text-blue-400"
                    : "text-gray-900 dark:text-white"
                }`}
              >
                {day.getDate()}
              </div>
            </div>
          );
        })}
      </div>

      {/* Time grid */}
      <div className="flex-1 overflow-y-auto">
        <div className="relative">
          {hours.map((time) => (
            <div
              key={time}
              className="flex h-12 border-b border-gray-100 dark:border-gray-800"
            >
              {/* Time label */}
              <div className="w-16 flex-shrink-0 p-2 text-right text-xs text-gray-500 dark:text-gray-400">
                {time}
              </div>

              {/* Day columns */}
              {weekDays.map((day) => {
                // Use local date to match the posts grouping
                const year = day.getFullYear();
                const month = String(day.getMonth() + 1).padStart(2, "0");
                const dayStr = String(day.getDate()).padStart(2, "0");
                const dateKey = `${year}-${month}-${dayStr}`;
                const posts = postsGrid[dateKey]?.[time] ?? [];
                const slotKey = `${dateKey}-${time}`;
                const isDragOver = dragOverSlot === slotKey;

                return (
                  <div
                    key={`${dateKey}-${time}`}
                    role="gridcell"
                    tabIndex={-1}
                    className={`relative min-w-0 flex-1 overflow-visible border-r border-gray-100 p-1 last:border-r-0 dark:border-gray-800 ${
                      isDragOver
                        ? "bg-blue-100 dark:bg-blue-900/30"
                        : "hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    }`}
                    onDragOver={(e) => handleDragOver(e, dateKey, time)}
                    onDrop={(e) => handleDrop(e, dateKey, time)}
                    onDragLeave={handleDragLeave}
                  >
                    {posts.length === 1 ? (
                      // Single post - full width
                      posts[0] ? (
                        <PostBlock
                          post={posts[0]}
                          compact={true}
                          user={user}
                          queueTypes={queueTypes}
                          onEdit={onPostEdit}
                          isLongform={
                            isAll
                              ? Boolean(posts[0].title && posts[0].publishedAt)
                              : isLongform
                          }
                          isPast={
                            typeof posts[0]?.isPast === "boolean"
                              ? posts[0].isPast
                              : false
                          }
                        />
                      ) : null
                    ) : posts.length <= 6 ? (
                      // 2-6 posts - dynamic equal width distribution with smaller labels
                      <div className="flex h-full space-x-0.5">
                        {posts.map((post, postIndex) => (
                          <div
                            key={`${post.id}-${postIndex}`}
                            className="min-w-0 flex-1"
                          >
                            <PostBlock
                              post={post}
                              compact={true}
                              minimal={true}
                              user={user}
                              queueTypes={queueTypes}
                              onEdit={onPostEdit}
                              isLongform={
                                isAll
                                  ? Boolean(post.title && post.publishedAt)
                                  : isLongform
                              }
                              isPast={
                                typeof post.isPast === "boolean"
                                  ? post.isPast
                                  : false
                              }
                              multipleInCell={true}
                            />
                          </div>
                        ))}
                      </div>
                    ) : (
                      // More than 6 posts - show first 5 with overflow indicator
                      <div className="flex h-full space-x-0.5">
                        {posts.slice(0, 5).map((post, postIndex) => (
                          <div
                            key={`${post.id}-${postIndex}`}
                            className="min-w-0 flex-1"
                          >
                            <PostBlock
                              post={post}
                              compact={true}
                              minimal={true}
                              user={user}
                              queueTypes={queueTypes}
                              onEdit={onPostEdit}
                              isLongform={
                                isAll
                                  ? Boolean(post.title && post.publishedAt)
                                  : isLongform
                              }
                              isPast={
                                typeof post.isPast === "boolean"
                                  ? post.isPast
                                  : false
                              }
                              multipleInCell={true}
                            />
                          </div>
                        ))}
                        <div className="flex flex-1 items-center justify-center rounded bg-gray-100 text-xs text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                          +{posts.length - 5}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ))}

          {/* Current time indicator - only show if today is in this week */}
          <CurrentTimeIndicator user={user} weekDays={weekDays} />
        </div>
      </div>
    </div>
  );
}

function CurrentTimeIndicator({ user, weekDays }: CurrentTimeIndicatorProps) {
  const userTimezone = user?.timezone ?? "Etc/UTC";
  const now = new Date();
  const nowInUserTz = new Date(
    now.toLocaleString("en-US", { timeZone: userTimezone }),
  );
  const currentHour = nowInUserTz.getHours();
  const currentMinutes = nowInUserTz.getMinutes();

  // Check if today is in the current week view
  const today = new Date();
  const todayString = today.toDateString();
  const isTodayInWeek = weekDays.some(
    (day) => day.toDateString() === todayString,
  );

  if (!isTodayInWeek) return null;

  // Find the exact position for current time
  // Each hour has 2 slots (30-minute intervals), each 48px tall (h-12 = 48px)
  const hourIndex = currentHour;
  const minuteProgress = currentMinutes / 60; // 0-1 progress through the hour

  // Calculate position:
  // - Each hour has 2 slots (00 and 30), so multiply by 2
  // - Add progress within the current hour
  const topOffset = hourIndex * 2 * 48 + minuteProgress * 48 * 2;

  return (
    <div
      className="pointer-events-none absolute left-16 right-0 z-20 h-0.5 bg-red-500"
      style={{ top: `${topOffset}px` }}
    >
      <div className="absolute -left-2 -top-1 h-3 w-3 rounded-full bg-red-500"></div>
    </div>
  );
}

