  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "~/components/ui/dialog";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import {
  createHashtagPresetClientSchema,
  updateHashtagPresetClientSchema,
} from "~/lib/validation";
import { useZodForm, formDataToFormData } from "~/lib/validation/utils.client-safe";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
  createdAt: string;
  updatedAt: string;
}

interface HashtagPresetsSettingsProps {
  presets: HashTagPreset[];
}

interface FetcherData {
  success?: boolean;
  error?: string;
}

export function HashtagPresetsSettings({
  presets,
}: HashtagPresetsSettingsProps) {
  const fetcher = useFetcher<FetcherData>();
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [editingPreset, setEditingPreset] = useState<HashTagPreset | null>(
    null,
  );

  const createForm = useZodForm(createHashtagPresetClientSchema, {
    defaultValues: {
      name: "",
      tags: "",
      description: "",
    },
  });

  const editForm = useZodForm(updateHashtagPresetClientSchema, {
    defaultValues: {
      id: "",
      name: "",
      tags: "",
      description: "",
    },
  });

  const isSubmitting = fetcher.state === "submitting";

  // Reset create form when dialog closes
  useEffect(() => {
    if (!isCreateDialogOpen) {
      createForm.reset({
        name: "",
        tags: "",
        description: "",
      });
    }
  }, [isCreateDialogOpen, createForm]);

  // Update edit form when editing preset changes
  useEffect(() => {
    if (editingPreset) {
      editForm.reset({
        id: editingPreset.id,
        name: editingPreset.name,
        tags: editingPreset.tags,
        description: editingPreset.description ?? "",
      });
    }
  }, [editingPreset, editForm]);

  const handleCreateSubmit = createForm.handleSubmit((data) => {
    const formData = formDataToFormData(data, "create_hashtag_preset");
    fetcher.submit(formData, { method: "post" });
    setIsCreateDialogOpen(false);
  });

  const handleEditSubmit = editForm.handleSubmit((data) => {
    if (!editingPreset) return;
    const formData = formDataToFormData(data, "update_hashtag_preset");
    fetcher.submit(formData, { method: "post" });
    setEditingPreset(null);
    setIsEditDialogOpen(false);
  });

  const handleDelete = (id: string) => {
    if (
      window.confirm("Are you sure you want to delete this hashtag preset?")
    ) {
      const formData = new FormData();
      formData.set("_action", "delete_hashtag_preset");
      formData.set("id", id);
      fetcher.submit(formData, { method: "post" });
    }
  };

  const openEditDialog = (preset: HashTagPreset) => {
    setEditingPreset(preset);
    setIsEditDialogOpen(true);
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Hash className="h-5 w-5" />
              Hashtag Presets
            </CardTitle>
            <CardDescription>
              Create and manage reusable hashtag collections for your posts
            </CardDescription>
          </div>

          <Dialog
            open={isCreateDialogOpen}
            onOpenChange={setIsCreateDialogOpen}
          >
            <DialogTrigger asChild>
              <Button size="sm">
                <Plus className="mr-2 h-4 w-4" />
                New Preset
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create Hashtag Preset</DialogTitle>
                <DialogDescription>
                  Create a new hashtag preset to reuse across your posts
                </DialogDescription>
              </DialogHeader>

              <form onSubmit={(e) => { e.preventDefault(); void handleCreateSubmit(e); }} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="create-name">Preset Name</Label>
                  <Input
                    id="create-name"
                    {...createForm.register("name")}
                    placeholder="e.g., Tech Posts, Travel Content"
                    disabled={isSubmitting}
                  />
                  {createForm.formState.errors.name ? <p className="text-sm text-destructive">
                      {createForm.formState.errors.name.message}
                    </p> : null}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="create-tags">Hashtags</Label>
                  <Textarea
                    id="create-tags"
                    {...createForm.register("tags")}
                    placeholder="#bitcoin #nostr #technology #coding"
                    disabled={isSubmitting}
                    rows={3}
                  />
                  {createForm.formState.errors.tags ? <p className="text-sm text-destructive">
                      {createForm.formState.errors.tags.message}
                    </p> : null}
                  <p className="text-xs text-muted-foreground">
                    Separate hashtags with spaces. Each hashtag should start
                    with #
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="create-description">
                    Description (optional)
                  </Label>
                  <Input
                    id="create-description"
                    {...createForm.register("description")}
                    placeholder="Brief description of when to use this preset"
                    disabled={isSubmitting}
                  />
                  {createForm.formState.errors.description ? <p className="text-sm text-destructive">
                      {createForm.formState.errors.description?.message}
                    </p> : null}
                </div>

                <div className="flex justify-end gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setIsCreateDialogOpen(false)}
                    disabled={isSubmitting}
                  >
                    Cancel
                  </Button>
                  <Button type="submit" disabled={isSubmitting}>
                    {isSubmitting ? "Creating..." : "Create Preset"}
                  </Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>

      <CardContent>
        {presets.length === 0 ? (
          <div className="py-8 text-center text-muted-foreground">
            <Hash className="mx-auto mb-4 h-12 w-12 opacity-50" />
            <p className="mb-2 text-lg font-medium">No hashtag presets yet</p>
            <p className="mb-4 text-sm">
              Create your first hashtag preset to organize and reuse hashtags
              across your posts
            </p>
            <Button onClick={() => setIsCreateDialogOpen(true)}>
              <Plus className="mr-2 h-4 w-4" />
              Create First Preset
            </Button>
          </div>
        ) : (
          <div className="space-y-4">
            {presets.map((preset) => (
              <div
                key={preset.id}
                className="flex items-start justify-between rounded-lg border p-4 transition-colors hover:bg-accent/50"
              >
                <div className="min-w-0 flex-1">
                  <div className="mb-2 flex items-center gap-2">
                    <h3 className="text-sm font-medium">{preset.name}</h3>
                    <Badge variant="secondary" className="text-xs">
                      {countHashtags(preset.tags)} tags
                    </Badge>
                  </div>

                  {preset.description ? (
                    <p className="mb-2 text-xs text-muted-foreground">
                      {preset.description}
                    </p>
                  ) : null}

                  <div className="flex flex-wrap gap-1">
                    {preset.tags
                      .split(/\s+/)
                      .filter((tag) => tag.startsWith("#") && tag.length > 1)
                      .map((tag, index) => (
                        <Badge
                          key={index}
                          variant="outline"
                          className="px-2 py-0 text-xs"
                        >
                          {tag}
                        </Badge>
                      ))}
                  </div>
                </div>

                <div className="ml-4 flex items-center gap-1">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => openEditDialog(preset)}
                    disabled={isSubmitting}
                  >
                    <Edit2 className="h-4 w-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleDelete(preset.id)}
                    disabled={isSubmitting}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}

        {fetcher.data?.success ? (
          <p className="mt-4 text-sm text-green-600">
            Hashtag preset updated successfully!
          </p>
        ) : null}
        {fetcher.data?.error ? (
          <p className="mt-4 text-sm text-destructive">{fetcher.data.error}</p>
        ) : null}
      </CardContent>

      {/* Edit Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Hashtag Preset</DialogTitle>
            <DialogDescription>Update your hashtag preset</DialogDescription>
          </DialogHeader>

          <form onSubmit={(e) => { e.preventDefault(); void handleEditSubmit(e); }} className="space-y-4">
            <input
              type="hidden"
              {...editForm.register("id")}
            />
            <div className="space-y-2">
              <Label htmlFor="edit-name">Preset Name</Label>
              <Input
                id="edit-name"
                {...editForm.register("name")}
                placeholder="e.g., Tech Posts, Travel Content"
                disabled={isSubmitting}
              />
              {editForm.formState.errors.name ? <p className="text-sm text-destructive">
                  {editForm.formState.errors.name.message}
                </p> : null}
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit-tags">Hashtags</Label>
              <Textarea
                id="edit-tags"
                {...editForm.register("tags")}
                placeholder="#bitcoin #nostr #technology #coding"
                disabled={isSubmitting}
                rows={3}
              />
              {editForm.formState.errors.tags ? <p className="text-sm text-destructive">
                  {editForm.formState.errors.tags.message}
                </p> : null}
              <p className="text-xs text-muted-foreground">
                Separate hashtags with spaces. Each hashtag should start with #
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="edit-description">Description (optional)</Label>
              <Input
                id="edit-description"
                {...editForm.register("description")}
                placeholder="Brief description of when to use this preset"
                disabled={isSubmitting}
              />
              {editForm.formState.errors.description ? <p className="text-sm text-destructive">
                  {editForm.formState.errors.description?.message}
                </p> : null}
            </div>

            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsEditDialogOpen(false)}
                disabled={isSubmitting}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? "Saving..." : "Save Changes"}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";
import { toast } from "react-hot-toast";

import { resizeImage } from "~/features/upload/image-resize";
import { useOptionalUser } from "~/lib/remix-utils";

import { getDynamicQueueStyle } from "../queueColors";
import type { QueueType } from "../types";

interface PreparedEventData {
  content: string;
  type: "image";
  queueType: string;
}

interface ImagePostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: Array<string | QueueType>;
  onQueueTypeChange?: (queueType: string) => void;
}

export default function ImagePost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  onQueueTypeChange,
}: ImagePostProps) {
  interface FetcherData {
    success?: boolean;
    fileUrls?: Array<{ fileUrl: string; scheduledFor: string; queueType: string }>;
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const user = useOptionalUser();

  const scheduleIntervals =
    user && typeof user === "object" && "scheduleInterval" in user
      ? user.scheduleInterval
      : null;
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);

  // Determine initial queue selection - default to "unassigned"
  const getInitialQueue = () => {
    return "unassigned";
  };

  const [selectedQueue, setSelectedQueue] = useState(getInitialQueue());

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Process files to remove metadata for privacy
    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        }),
      );
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage } = await import(
        "~/lib/error-handler.client"
      );
      handleAsyncErrorWithMessage(
        error,
        "Error processing images. Using original files.",
        {
          component: "ImagePost",
          action: "handleFileChange",
        },
        false, // Don't show toast, we call toast.error instead
      );
      toast.error("Error processing images. Using original files.");
      setFiles((prev: File[]) => [...prev, ...selectedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    if (droppedFiles.length > 0) {
      // Check if files are images
      const imageFiles = droppedFiles.filter((file) =>
        file.type.startsWith("image/"),
      );
      if (imageFiles.length === 0) {
        toast.error("Please drop only image files");
        return;
      }

      // Process files to remove metadata for privacy
      try {
        const processedFiles = await Promise.all(
          imageFiles.map(async (file) => await resizeImage(file)),
        );
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      } catch (error: unknown) {
        const { handleAsyncErrorWithMessage } = await import(
          "~/lib/error-handler.client"
        );
        handleAsyncErrorWithMessage(
          error,
          "Error processing images. Using original files.",
          {
            component: "ImagePost",
            action: "handleDrop",
          },
          false, // Don't show toast, we call toast.error instead
        );
        toast.error("Error processing images. Using original files.");
        setFiles((prev: File[]) => [...prev, ...imageFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleImagePreview = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    setTimeError("");
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    formData.set("_action", "upload-images-preview");
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }

    // Remove any existing files from formData
    formData.delete("files");

    // Append each file individually to formData
    files.forEach((file) => {
      formData.append("files", file);
    });

    fetcher.submit(formData, {
      method: "post",
      encType: "multipart/form-data",
    });
  };

  const calculateQueueScheduleTime = useCallback(
    async (queueTypeName: string) => {
      if (queueTypeName === "unassigned") {
        setScheduledFor("");
        return;
      }

      // Find the queue type object to get its ID
      const selectedQueueType = queueTypes.find((qt) => {
        if (typeof qt === "string") {
          return qt === queueTypeName;
        }
        if (
          qt &&
          typeof qt === "object" &&
          "name" in qt &&
          typeof qt.name === "string"
        ) {
          return qt.name === queueTypeName;
        }
        return false;
      });
      const queueTypeId =
        selectedQueueType &&
        typeof selectedQueueType === "object" &&
        "id" in selectedQueueType &&
        typeof selectedQueueType.id === "string"
          ? selectedQueueType.id
          : null;

      try {
        const response = await fetch("/api/queue-schedule", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            queueTypeId,
            queueTypeName, // Keep for backward compatibility
            userId:
              user &&
              typeof user === "object" &&
              "id" in user &&
              typeof user.id === "string"
                ? user.id
                : undefined,
          }),
        });

        if (response.ok) {
          const dataRaw: unknown = await response.json();
          const data =
            dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
              ? (dataRaw as { scheduledTime?: unknown })
              : {};
          const scheduledTime =
            typeof data.scheduledTime === "string"
              ? data.scheduledTime
              : undefined;
          if (scheduledTime) {
            setScheduledFor(scheduledTime);
          }
          setTimeError("");
        }
      } catch (error: unknown) {
        console.error("Error calculating schedule time:", error);
      }
    },
    [queueTypes, user],
  );

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find((qt) => {
      if (typeof qt === "string") {
        return qt === selectedQueue;
      }
      if (
        qt &&
        typeof qt === "object" &&
        "name" in qt &&
        typeof qt.name === "string"
      ) {
        return qt.name === selectedQueue;
      }
      return false;
    });

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (
      selectedQueueType &&
      typeof selectedQueueType === "object" &&
      "scheduleType" in selectedQueueType &&
      selectedQueueType.scheduleType === "FIXED_SLOTS"
    ) {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      void calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const intervalHoursNum =
      typeof intervalHours === "string"
        ? parseInt(intervalHours, 10)
        : intervalHours;
    const hoursLater = new Date(
      now.getTime() + intervalHoursNum * 60 * 60 * 1000,
    );

    // Format the date in the user's timezone
    const userTimezone =
      user &&
      typeof user === "object" &&
      "timezone" in user &&
      typeof user.timezone === "string"
        ? user.timezone
        : "UTC";
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: userTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart?.split("/") ?? ["", "", ""];
    const [hours, minutes] = timePart?.split(":") ?? ["", ""];

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    if (!year || !month || !day || !hours || !minutes) {
      return "";
    }
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
  };

  // Handle fetcher success data
  const fetcherDataRaw = fetcher.data;
  const fetcherData =
    fetcherDataRaw &&
    typeof fetcherDataRaw === "object" &&
    !Array.isArray(fetcherDataRaw)
      ? (fetcherDataRaw as {
          success?: unknown;
          fileUrls?: unknown;
          error?: unknown;
        })
      : null;
  const isSuccess =
    fetcherData &&
    typeof fetcherData.success === "boolean" &&
    fetcherData.success;
  const fileUrls =
    fetcherData &&
    "fileUrls" in fetcherData &&
    Array.isArray(fetcherData.fileUrls)
      ? fetcherData.fileUrls
      : null;
  const error =
    fetcherData && typeof fetcherData.error === "string"
      ? fetcherData.error
      : null;

  if (isSuccess && fileUrls) {
    toast.success("Images uploaded successfully!");

    const preparedData: PreparedEventData[] = fileUrls.map((url: unknown) => {
      const urlObj =
        url && typeof url === "object" && !Array.isArray(url)
          ? (url as {
              fileUrl?: unknown;
              scheduledFor?: unknown;
              queueType?: unknown;
            })
          : {};
      const fileUrl = typeof urlObj.fileUrl === "string" ? urlObj.fileUrl : "";
      const queueType =
        typeof urlObj.queueType === "string" ? urlObj.queueType : selectedQueue;
      return {
        content: fileUrl,
        type: "image",
        queueType, // Include queue type information
      };
    });

    setShowImagePreview(true);
    setPreparedImageEvent(preparedData);
    setFiles([]);
  }

  // Add error handling
  if (
    fetcherData &&
    typeof fetcherData.success === "boolean" &&
    !fetcherData.success &&
    error
  ) {
    toast.error(error);
  }

  const isUploaded = Boolean(isSuccess && fileUrls);

  return (
    <fetcher.Form
      method="post"
      className="w-full"
      encType="multipart/form-data"
      onSubmit={(e) => {
        handleImagePreview(e);
      }}
    >
      <input type="hidden" name="_action" value="upload-images-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*"
          multiple
          onChange={(e) => {
            void handleFileChange(e);
          }}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={
            !isUploaded
              ? (e) => {
                  void handleDrop(e);
                }
              : undefined
          }
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => (
                <div key={index} className="relative">
                  <img
                    src={URL.createObjectURL(file)}
                    alt="Preview"
                    className="h-32 w-32 object-cover"
                  />
                  <button
                    type="button"
                    onClick={() =>
                      setFiles(files.filter((_, i) => i !== index))
                    }
                    className="absolute -right-2 -top-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                    disabled={fetcher.state !== "idle"}
                  >
                    ×
                  </button>
                </div>
              ))}
              <div className="flex h-32 w-32 items-center justify-center border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Multiple images (max 100MB total)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your image(s)..."
          rows={3}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <div className="mb-2">
            <label
              htmlFor="queue-type-selector"
              className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
            >
              Queue Type
            </label>
            <div className="flex flex-wrap gap-2">
              {/* Unassigned option */}
              <button
                type="button"
                onClick={() => setSelectedQueue("unassigned")}
                disabled={fetcher.state !== "idle" || isUploaded}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(null, selectedQueue === "unassigned")} disabled:cursor-not-allowed disabled:opacity-50`}
              >
                Unassigned
              </button>

              {/* Queue types */}
              {queueTypes
                .filter((queue) => {
                  return typeof queue === "object"
                      ? queue.isEnabled !== false
                      : true;
                })
                .map((queue) => {
                  const queueName =
                    typeof queue === "string" ? queue : queue.name;
                  const queueColor =
                    typeof queue === "object" ? queue.color : null;
                  return (
                    <button
                      key={queueName}
                      type="button"
                      onClick={() => setSelectedQueue(queueName ?? "")}
                      disabled={fetcher.state !== "idle" || isUploaded}
                      className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueue === queueName)} disabled:cursor-not-allowed disabled:opacity-50`}
                      style={{
                        backgroundColor: queueColor ?? undefined,
                        borderColor: queueColor ?? undefined,
                      }}
                    >
                      {queueName}
                    </button>
                  );
                })}
            </div>
            <input type="hidden" name="queueType" value={selectedQueue} />
          </div>
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={fetcher.state !== "idle" || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <div className="flex items-center gap-4">
            <input
              type="datetime-local"
              name="scheduledFor"
              value={scheduledFor}
              onChange={(e) => {
                setScheduledFor(e.target.value);
                setTimeError("");
              }}
              className={`rounded-md border ${timeError ? "border-red-500" : "border-gray-300"} p-2 text-gray-900`}
              disabled={fetcher.state !== "idle" || isUploaded}
            />
          </div>
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
          <div className="flex flex-wrap gap-2">
            {(() => {
              // Find the currently selected queue type
              const selectedQueueType = queueTypes.find((qt) => {
                if (typeof qt === "string") {
                  return qt === selectedQueue;
                }
                if (
                  qt &&
                  typeof qt === "object" &&
                  "name" in qt &&
                  typeof qt.name === "string"
                ) {
                  return qt.name === selectedQueue;
                }
                return false;
              });

              // For fixed slot queues, show a different UI
              if (
                selectedQueueType &&
                typeof selectedQueueType === "object" &&
                "scheduleType" in selectedQueueType &&
                selectedQueueType.scheduleType === "FIXED_SLOTS"
              ) {
                return (
                  <button
                    type="button"
                    onClick={() => {
                      void calculateQueueScheduleTime(selectedQueue);
                    }}
                    className="rounded-md bg-blue-100 px-2.5 py-1.5 text-xs font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-800 dark:text-blue-300 dark:hover:bg-blue-700"
                    disabled={fetcher.state !== "idle" || isUploaded}
                  >
                    Next Slot
                  </button>
                );
              }

              // For interval-based queues, show the hour buttons
              if (scheduleIntervals && Array.isArray(scheduleIntervals)) {
                return scheduleIntervals
                  .map((interval: unknown) => {
                    const intervalValue =
                      typeof interval === "string"
                        ? interval
                        : typeof interval === "number"
                          ? String(interval)
                          : "";
                    if (!intervalValue) return null;
                    return (
                      <button
                        key={intervalValue}
                        type="button"
                        onClick={() =>
                          handleScheduleIntervalClick(intervalValue)
                        }
                        className="rounded-md bg-gray-100 px-2.5 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                        disabled={fetcher.state !== "idle" || isUploaded}
                      >
                        +{intervalValue}h
                      </button>
                    );
                  })
                  .filter((button): button is JSX.Element => button !== null);
              }
              return null;
            })()}
          </div>
        </div>
        <button
          type="submit"
          className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
          disabled={
            fetcher.state !== "idle" || isUploaded || files.length === 0
          }
        >
          {fetcher.state !== "idle" ? "Uploading..." : "Upload Images →"}
        </button>
      </div>
    </fetcher.Form>
  );
}

