                ) : null}
                <td className="p-3 text-center">{getStatusBadge(post)}</td>
                <td className="p-3 text-center">
                  <div className="flex justify-center gap-2">
                    {type === "draft" ? (
                      <Link
                        to={`/dashboard/drafts/longform/edit/${post.id}`}
                        onClick={(e) => e.stopPropagation()}
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
                      >
                        Edit
                      </Link>
                    ) : null}
                    {type === "scheduled" && onEditPost ? (
                      <>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onEditPost(post);
                          }}
                          className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
                        >
                          Edit
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            if (onReschedulePost) {
                              onReschedulePost(post);
                            }
                          }}
                          className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                        >
                          Reschedule
                        </button>
                      </>
                    ) : null}
                    {type === "posted" &&
                    (post.nostrEventId ??
                      (post.signedEvent &&
                      typeof post.signedEvent === "object" &&
                      "id" in post.signedEvent
                        ? (post.signedEvent as { id?: string }).id
                        : undefined)) ? (
                      <>
                        <Link
                          to={`https://primal.net/a/${String(post.nostrEventId ?? (post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : "") ?? "")}`}
                          target="_blank"
                          rel="noreferrer"
                          onClick={(e) => e.stopPropagation()}
                          className="font-montserrat inline-block rounded-full bg-black/50 px-4 py-1 text-sm text-white transition-colors duration-200 hover:bg-black/70"
                        >
                          View Article
                        </Link>
                        {longformRepostFetcher
                          ? (() => {
                              const fetcher = longformRepostFetcher;
                              const formData = getFetcherFormData(fetcher);
                              return (
                                <fetcher.Form
                                  method="post"
                                  onClick={(e) => e.stopPropagation()}
                                >
                                  <input
                                    type="hidden"
                                    name="postId"
                                    value={post.id}
                                  />
                                  <input
                                    type="hidden"
                                    name="_action"
                                    value="longformRepost"
                                  />
                                  <button
                                    type="submit"
                                    disabled={
                                      fetcher.state !== "idle" ||
                                      (formData
                                        ? (formData.get("postId") as
                                            | string
                                            | null) === post.id
                                        : false)
                                    }
                                    className="inline-flex items-center justify-center gap-2 rounded-lg border border-purple-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-purple-800 hover:border-purple-300 hover:text-purple-900 hover:shadow-sm focus:ring focus:ring-purple-300/25 active:border-purple-200 active:shadow-none disabled:opacity-50 dark:border-purple-700 dark:bg-gray-800 dark:text-purple-300 dark:hover:border-purple-600 dark:hover:text-purple-200 dark:focus:ring-purple-600/40 dark:active:border-purple-700"
                                  >
                                    {fetcher.state !== "idle" &&
                                    (formData
                                      ? (formData.get("postId") as
                                          | string
                                          | null) === post.id
                                      : false)
                                      ? "Reposting..."
                                      : "Repost"}
                                  </button>
                                </fetcher.Form>
                              );
                            })()
                          : null}
                        {longformQuoteFetcher
                          ? (() => {
                              const fetcher = longformQuoteFetcher;
                              const formData = getFetcherFormData(fetcher);
                              return (
                                <fetcher.Form
                                  method="post"
                                  onClick={(e) => e.stopPropagation()}
                                >
                                  <input
                                    type="hidden"
                                    name="postId"
                                    value={post.id}
                                  />
                                  <input
                                    type="hidden"
                                    name="_action"
                                    value="longformQuote"
                                  />
                                  <button
                                    type="submit"
                                    disabled={
                                      fetcher.state !== "idle" ||
                                      (formData
                                        ? (formData.get("postId") as
                                            | string
                                            | null) === post.id
                                        : false)
                                    }
                                    className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none disabled:opacity-50 dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                                  >
                                    {fetcher.state !== "idle" &&
                                    (fetcher.formData
                                      ? (fetcher.formData.get("postId") as
                                          | string
                                          | null) === post.id
                                      : false)
                                      ? "Quoting..."
                                      : "Quote Post"}
                                  </button>
                                </fetcher.Form>
                              );
                            })()
                          : null}
                      </>
                    ) : null}
                    <deleteFetcher.Form
                      method="post"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input type="hidden" name="postId" value={post.id} />
                      <input
                        type="hidden"
                        name="_action"
                        value="deleteLongForm"
                      />
                      <button
                        type="submit"
                        disabled={
                          deleteFetcher.state !== "idle" ||
                          bulkDeleteFetcher.state !== "idle"
                        }
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-2 py-1 text-sm font-semibold leading-5 text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
                      >
                        {deleteFetcher.state !== "idle" &&
                        deleteFetcher.formData?.get("postId") === post.id
                          ? "Deleting..."
                          : "Delete"}
                      </button>
                    </deleteFetcher.Form>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { Badge } from "~/components/ui/badge";
import { AssetBrowser, type Asset } from "~/features/assets";
import { longformPostClientSchema } from "~/lib/validation";
import { useZodForm } from "~/lib/validation/utils.client-safe";

import { useLongFormSubmission } from "../hooks/useLongFormSubmission";
import { useCoverImageUpload } from "../useCoverImageUpload";
import { useLongFormEditor } from "../useLongFormEditor";
import { useLongFormScheduling } from "../useLongFormScheduling";

import { LongFormActionButtons } from "./LongFormActionButtons";
import { LongFormContentEditor } from "./LongFormContentEditor";
import { LongFormCoverImage } from "./LongFormCoverImage";
import { LongFormEditorStyles } from "./LongFormEditorStyles";
import { LongFormPostFields } from "./LongFormPostFields";
import { LongFormPublishingOptions } from "./LongFormPublishingOptions";

interface QueueType {
  id?: string;
  name: string;
  color?: string | null;
  hashtags?: string | null;
  scheduleType?: string;
  isEnabled?: boolean;
}

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface InitialData {
  title?: string;
  summary?: string;
  content?: string;
  image?: string;
  tags?: string[];
  queueType?: { name: string };
}

interface LongFormPostProps {
  queueTypes?: Array<string | QueueType>;
  scheduleIntervals?: number[];
  userTags?: string;
  assets?: Asset[];
  uploadProvider?: string | null;
  userTimezone?: string;
  onQueueTypeChange?: (name: string) => void;
  onPreview?: (data: {
    title: string;
    summary: string;
    content: string;
    image: string;
  }) => void;
  initialData?: InitialData | null;
  isEditing?: boolean;
  hashTagPresets?: HashTagPreset[];
  useHashtagPresets?: boolean;
  selectedHashtagPresetId?: string | null;
  selectedHashtags?: string;
  onUseHashtagPresetsChange?: (value: boolean) => void;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function LongFormPost({
  queueTypes = [],
  scheduleIntervals = [],
  userTags = "",
  assets = [],
  uploadProvider = null,
  userTimezone = "UTC",
  onQueueTypeChange,
  onPreview,
  initialData = null,
  isEditing: _isEditing = false,
  hashTagPresets = [],
  useHashtagPresets = false,
  selectedHashtagPresetId = null,
  selectedHashtags = "",
  onUseHashtagPresetsChange,
  onHashtagPresetChange,
}: LongFormPostProps) {
  const fetcher = useFetcher();
  const [showAssetBrowser, setShowAssetBrowser] = useState("");

  // Initialize form with React Hook Form
  const form = useZodForm(longformPostClientSchema, {
    defaultValues: {
      title: initialData?.title ?? "",
      summary: initialData?.summary ?? "",
      content: initialData?.content ?? "",
      customTags: initialData?.tags?.join(", ") ?? "",
      scheduledFor: "",
      queueType: initialData?.queueType?.name ?? "Unassigned",
      useHashtagPresets: useHashtagPresets ?? false,
      hashTagPresetId: selectedHashtagPresetId ?? undefined,
    },
  });

  // Watch form values
  const title = form.watch("title") ?? "";
  const summary = form.watch("summary") ?? "";
  const content = form.watch("content") ?? "";
  const customTags = form.watch("customTags") ?? "";

  // Use extracted hooks
  const {
    editorReady,
    loadInitialData,
    insertAssetIntoEditor,
    generateSummaryFromContent,
  } = useLongFormEditor({
    uploadProvider,
    onContentChange: (newContent) => form.setValue("content", newContent),
  });

  const {
    image: coverImage,
    setImage: setCoverImage,
    uploadError,
    uploadFetcherState,
    handleImageUpload,
    handleCoverImageAssets,
    handleFetcherData,
    handleFetcherStateChange,
  } = useCoverImageUpload({
    uploadProvider,
    initialImage: initialData?.image ?? "",
  });

  // Sync cover image with form (image field is not in schema, but we'll manage it separately)
  // Note: The schema doesn't include image, but we need it for validation
  // We'll handle it separately since it's managed by useCoverImageUpload
  const image = coverImage;

  const {
    selectedQueueType: schedulingQueueType,
    scheduledFor: schedulingScheduledFor,
    setScheduledFor: setSchedulingScheduledFor,
    displayedHashtags,
    updateDisplayedHashtags,
    handleScheduleIntervalClick,
    calculateQueueScheduleTime,
  } = useLongFormScheduling({
    queueTypes,
    scheduleIntervals,
    userTags,
    userTimezone,
    initialQueueType: initialData?.queueType?.name ?? "Unassigned",
    onQueueTypeChange,
  });

  // Sync scheduling hook with form
  useEffect(() => {
    form.setValue("queueType", schedulingQueueType);
  }, [schedulingQueueType, form]);

  useEffect(() => {
    if (schedulingScheduledFor) {
      form.setValue("scheduledFor", schedulingScheduledFor);
    }
  }, [schedulingScheduledFor, form]);

  // Sync form with scheduling hook
  const formScheduledFor = form.watch("scheduledFor");
  const formQueueType = form.watch("queueType");
  useEffect(() => {
    if (formScheduledFor && formScheduledFor !== schedulingScheduledFor) {
      setSchedulingScheduledFor(formScheduledFor);
    }
  }, [formScheduledFor, schedulingScheduledFor, setSchedulingScheduledFor]);

  useEffect(() => {
    if (formQueueType && formQueueType !== schedulingQueueType) {
      void updateDisplayedHashtags(formQueueType);
    }
  }, [formQueueType, schedulingQueueType, updateDisplayedHashtags]);

  const selectedQueueType = schedulingQueueType;
  const scheduledFor = schedulingScheduledFor ?? null;
  const setScheduledFor = (value: string | null) => {
    if (value) {
      form.setValue("scheduledFor", value);
      setSchedulingScheduledFor(value);
    } else {
      form.setValue("scheduledFor", "");
      setSchedulingScheduledFor(null);
    }
  };

  // Handle upload fetcher responses
  useEffect(() => {
    handleFetcherData();
  }, [handleFetcherData]);

  // Clear upload errors when fetcher state changes
  useEffect(() => {
    handleFetcherStateChange();
  }, [handleFetcherStateChange]);

  // Handle initial data loading - wait for both editor ready and initial data
  useEffect(() => {
    if (editorReady && initialData?.content) {
      const timeoutId = setTimeout(() => {
        void loadInitialData(initialData.content!);
      }, 100);
      return () => clearTimeout(timeoutId);
    }
  }, [editorReady, initialData?.content, loadInitialData]);

  const handleAssetBrowserSelect = (selectedAssets: Asset[]) => {
    if (showAssetBrowser === "cover") {
      handleCoverImageAssets(
        selectedAssets.map((asset) => ({
          assetType: asset.assetType,
          fileUrl: asset.fileUrl ?? undefined,
        })),
      );
    } else {
      void insertAssetIntoEditor(
        selectedAssets.map((asset) => ({
          assetType: asset.assetType,
          fileUrl: asset.fileUrl ?? undefined,
          content: asset.content ?? undefined,
          title: asset.title ?? undefined,
        })),
      );
    }
    setShowAssetBrowser("");
  };

  const handleGenerateSummary = () => {
    const generatedSummary = generateSummaryFromContent(content);
    if (generatedSummary) {
      form.setValue("summary", generatedSummary);
    }
  };

  const { handleSchedule } = useLongFormSubmission({
    title,
    summary,
    content,
    image,
    customTags,
    selectedQueueType,
    scheduledFor,
    displayedHashtags,
    useHashtagPresets,
    selectedHashtags,
  });

  // Form validation using Zod
  const isFormValid = form.formState.isValid && !!image;

  return (
    <>
      <LongFormEditorStyles />

      <div className="space-y-6">
        <LongFormPostFields
          title={title}
          summary={summary}
          customTags={customTags}
          content={content}
          onTitleChange={(value) => form.setValue("title", value)}
          onSummaryChange={(value) => form.setValue("summary", value)}
          onCustomTagsChange={(value) => form.setValue("customTags", value)}
          onGenerateSummary={handleGenerateSummary}
        />

        <LongFormCoverImage
          image={image}
          uploadError={uploadError}
          uploadProvider={uploadProvider}
          uploadFetcherState={uploadFetcherState}
          onImageUpload={(file) => void handleImageUpload(file)}
          onRemove={() => {
            setCoverImage("");
          }}
          onOpenAssetBrowser={() => setShowAssetBrowser("cover")}
        />

        <LongFormContentEditor
          uploadProvider={uploadProvider}
          onOpenAssetBrowser={() => setShowAssetBrowser("content")}
        />

        {/* Hashtags Display */}
        {displayedHashtags ? (
          <div className="flex items-center gap-2">
            <Badge variant="secondary" className="text-xs">
              <svg
                className="hi-solid hi-hashtag mr-1 inline-block size-3 opacity-75"
                fill="currentColor"
                viewBox="0 0 20 20"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  fillRule="evenodd"
                  d="M9.243 3.03a1 1 0 01.727 1.213L9.53 6h2.94l.56-2.243a1 1 0 111.94.486L14.53 6H17a1 1 0 110 2h-2.97l-1 4H15a1 1 0 110 2h-2.47l-.56 2.242a1 1 0 11-1.94-.485L10.47 14H7.53l-.56 2.242a1 1 0 11-1.94-.485L5.47 14H3a1 1 0 110-2h2.97l1-4H5a1 1 0 110-2h2.47l.56-2.243a1 1 0 011.213-.727zM9.03 8l-1 4h2.938l1-4H9.031z"
                  clipRule="evenodd"
                />
              </svg>
              {displayedHashtags}
            </Badge>
          </div>
        ) : null}

        <LongFormPublishingOptions
          queueTypes={queueTypes}
          selectedQueueType={selectedQueueType}
          onQueueTypeChange={(name) => void updateDisplayedHashtags(name)}
          scheduledFor={scheduledFor}
          onScheduledForChange={setScheduledFor}
          scheduleIntervals={scheduleIntervals}
          onScheduleIntervalClick={(intervalHours) =>
            void handleScheduleIntervalClick(intervalHours)
          }
          onNextSlotClick={() => {
            void calculateQueueScheduleTime(selectedQueueType);
          }}
          hashTagPresets={hashTagPresets}
          useHashtagPresets={useHashtagPresets}
          selectedHashtagPresetId={selectedHashtagPresetId}
          selectedHashtags={selectedHashtags}
          onHashtagPresetChange={
            onHashtagPresetChange ??
            ((_id, _tags) => {
              void _id;
              void _tags;
            })
          }
          onUseHashtagPresetsChange={
            onUseHashtagPresetsChange ??
            (() => {
              void 0;
            })
          }
        />

        <LongFormActionButtons
          fetcherState={fetcher.state}
          isFormValid={isFormValid}
          hasScheduledFor={!!scheduledFor}
          onPreview={() => {
            if (onPreview) {
              onPreview({
                title,
                summary: summary || generateSummaryFromContent(content),
                content,
                image,
              });
            }
          }}
          onSchedule={() => void handleSchedule("schedule")}
          onPublish={() => void handleSchedule("publish")}
        />

        {/* Asset Browser Modal */}
        {showAssetBrowser ? (
          <AssetBrowser
            assets={assets}
            onAssetsSelected={handleAssetBrowserSelect}
            onClose={() => setShowAssetBrowser("")}
          />
        ) : null}
      </div>
    </>
  );
}

import { Button } from "~/components/ui/button";
import { handleErrorSafely } from "~/lib/error-handler.client";

import type { EditorJSBlock } from "../types/editorjs.types";

interface LongFormPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  summary: string;
  content: string;
  image: string;
  displayedHashtags: string;
  author?: string;
}

export default function LongFormPreviewModal({
  isOpen,
  onClose,
  title,
  summary,
  content,
  image,
  displayedHashtags,
  author = "You",
}: LongFormPreviewModalProps) {
  if (!isOpen) return null;

  const convertEditorJSToHTML = (content: string) => {
    if (!content || content.trim() === "") {
      return '<p class="text-gray-500 italic">No content available</p>';
    }

    try {
      const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };

      if (!editorData.blocks || !Array.isArray(editorData.blocks)) {
        return '<p class="text-gray-500 italic">No content blocks found</p>';
      }

      let html = "";

      editorData.blocks.forEach((block: EditorJSBlock) => {
        switch (block.type) {
          case "header": {
            const levelValue = block.data["level"];
            const level = typeof levelValue === "number" ? levelValue : 3;
            const levelStr = String(level);
            const textValue = block.data["text"];
            const text = typeof textValue === "string" ? textValue : "";
            html += `<h${levelStr} class="text-${level === 2 ? "2xl" : level === 3 ? "xl" : "lg"} font-bold mb-4 text-gray-900 dark:text-white">${text}</h${levelStr}>`;
            break;
          }
          case "paragraph": {
            const textValue = block.data["text"];
            const text = typeof textValue === "string" ? textValue : "";
            html += `<p class="mb-4 text-gray-700 dark:text-gray-300 leading-relaxed">${text}</p>`;
            break;
          }
          case "list": {
            const listType = block.data["style"] === "ordered" ? "ol" : "ul";
            const listClass =
              block.data["style"] === "ordered" ? "list-decimal" : "list-disc";
            html += `<${listType} class="${listClass} ml-6 mb-4 text-gray-700 dark:text-gray-300">`;
            if (Array.isArray(block.data["items"])) {
              const items = block.data["items"];
              if (Array.isArray(items)) {
                items.forEach((item: unknown) => {
                  const itemStr = typeof item === "string" ? item : "";
                  html += `<li class="mb-1">${itemStr}</li>`;
                });
              }
            }
            html += `</${listType}>`;
            break;
          }
          case "quote": {
            const text =
              typeof block.data["text"] === "string" ? block.data["text"] : "";
            const caption =
              typeof block.data["caption"] === "string" ? block.data["caption"] : "";
            html += `<blockquote class="border-l-4 border-blue-500 pl-4 py-2 mb-4 italic text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 rounded-r">
              <p>${text}</p>
              ${caption ? `<footer class="text-sm mt-2">— ${caption}</footer>` : ""}
            </blockquote>`;
            break;
          }
          case "code": {
            const code =
              typeof block.data["code"] === "string" ? block.data["code"] : "";
            html += `<pre class="bg-gray-900 dark:bg-gray-800 text-green-400 p-4 rounded-lg mb-4 overflow-x-auto"><code>${code}</code></pre>`;
            break;
          }
          case "linkTool": {
            const link =
              typeof block.data["link"] === "string" ? block.data["link"] : "";
            const meta =
              block.data["meta"] && typeof block.data["meta"] === "object"
                ? (block.data["meta"] as { title?: string; description?: string })
                : null;
            html += `<div class="border border-gray-200 dark:border-gray-700 rounded-lg p-4 mb-4">
              <a href="${link}" target="_blank" rel="noopener noreferrer" class="text-blue-600 dark:text-blue-400 hover:underline">
                <div class="font-semibold">${meta?.title ?? link}</div>
                ${meta?.description ? `<div class="text-gray-600 dark:text-gray-400 text-sm mt-1">${meta.description}</div>` : ""}
              </a>
            </div>`;
            break;
          }
          case "embed": {
            const embed =
              typeof block.data["embed"] === "string" ? block.data["embed"] : "";
            html += `<div class="mb-4">
              <iframe src="${embed}" class="w-full aspect-video rounded-lg" frameborder="0" allowfullscreen></iframe>
            </div>`;
            break;
          }
          case "image": {
            const file =
              block.data["file"] && typeof block.data["file"] === "object"
                ? (block.data["file"] as { url?: string })
                : null;
            const url =
              typeof block.data["url"] === "string" ? block.data["url"] : "";
            const imageUrl = file?.url ?? url;
            const caption =
              typeof block.data["caption"] === "string" ? block.data["caption"] : "";
            if (imageUrl) {
              html += `<figure class="mb-6">
                <img src="${imageUrl}" alt="${caption}" class="w-full rounded-lg shadow-sm" style="max-height: 500px; object-fit: contain;" />
                ${caption ? `<figcaption class="text-center text-sm text-gray-600 dark:text-gray-400 mt-2 italic">${caption}</figcaption>` : ""}
              </figure>`;
            }
            break;
          }
          default:
            if (typeof block.data["text"] === "string") {
              html += `<p class="mb-4 text-gray-700 dark:text-gray-300">${block.data["text"]}</p>`;
            } else {
              const file =
                block.data["file"] && typeof block.data["file"] === "object"
                  ? (block.data["file"] as { url?: string })
                  : null;
              if (file?.url) {
                // Handle any other block types that might have images
                html += `<div class="mb-4">
                  <img src="${file.url}" alt="" class="w-full rounded-lg" style="max-height: 400px; object-fit: contain;" />
                </div>`;
              }
            }
        }
      });

      return (
        html ??
        '<p class="text-gray-500 italic">Content could not be rendered</p>'
      );
    } catch (error) {
      handleErrorSafely(error, {
        component: "LongFormPreviewModal",
        action: "parseEditorJSContent",
      });
      // Try to display as plain text if JSON parsing fails
      const plainTextContent = content.replace(/<[^>]*>/g, "");
      return `<p class="text-gray-700 dark:text-gray-300">${plainTextContent ?? "Content parsing failed"}</p>`;
    }
  };

  const formatDate = () => {
    return new Date().toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const handleBackdropKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") {
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black bg-opacity-50"
        onClick={onClose}
        onKeyDown={handleBackdropKeyDown}
        role="button"
        tabIndex={0}
        aria-label="Close modal"
      />

      {/* Modal */}
      <div className="relative mx-4 max-h-[90vh] w-full max-w-4xl overflow-hidden rounded-lg bg-white shadow-xl dark:bg-gray-900">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-gray-200 p-6 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            Preview: How your post will look
          </h2>
          <Button
            variant="outline"
            size="sm"
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300"
          >
            ✕ Close
          </Button>
        </div>

        {/* Content */}
        <div className="max-h-[calc(90vh-120px)] overflow-y-auto bg-white dark:bg-gray-900">
          {/* Article Card Preview - matches the Primal/Nostr style */}
          <div className="mx-auto max-w-2xl p-6">
            {/* Author Header */}
            <div className="mb-4 flex items-center gap-3">
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-purple-600 text-lg font-semibold text-white">
                {author.charAt(0).toUpperCase()}
              </div>
              <div>
                <div className="font-semibold text-gray-900 dark:text-white">
                  {author}
                </div>
              </div>
              <div className="ml-auto">
                <svg
                  className="h-6 w-6 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"
                  />
                </svg>
              </div>
            </div>

            {/* Date and Source */}
            <div className="mb-4 flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
              <span>{formatDate()}</span>
              <span>•</span>
              <span>via SmartFlow</span>
              <div className="ml-auto">
                <svg
                  className="h-5 w-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z"
                  />
                </svg>
              </div>
            </div>

            {/* Title */}
            <h1 className="mb-4 text-2xl font-bold leading-tight text-gray-900 dark:text-white">
              {title ?? "Untitled Post"}
            </h1>

            {/* Cover Image */}
            {image ? (
              <div className="mb-4 overflow-hidden rounded-2xl">
                <img
                  src={image}
                  alt="Cover"
                  className="h-80 w-full object-cover"
                />
              </div>
            ) : null}

            {/* Summary */}
            {summary ? (
              <div className="mb-6 rounded-xl bg-gray-50 p-6 dark:bg-gray-800">
                <p className="text-lg font-medium leading-relaxed text-gray-700 dark:text-gray-300">
                  {summary}
                </p>
              </div>
            ) : null}

            {/* Full Content */}
            <div
              className="prose prose-lg dark:prose-invert mb-6 max-w-none text-gray-900 dark:text-white"
              style={{
                fontSize: "1.1rem",
                lineHeight: "1.7",
                color: "inherit",
              }}
              dangerouslySetInnerHTML={{
                __html: convertEditorJSToHTML(content ?? ""),
              }}
            />

            {/* Zap Button */}
            <div className="flex items-center gap-3">
              {/* Hashtags */}
              {displayedHashtags ? (
                <div className="ml-auto flex items-center gap-2">
                  <span className="text-xs text-gray-500 dark:text-gray-400">
                    {displayedHashtags}
                  </span>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";

import { getDynamicQueueStyle } from "../queueColors";
interface QueueType {
  id?: string;
  name: string;
  color?: string | null;
  hashtags?: string | null;
  scheduleType?: string;
  isEnabled?: boolean;
}

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface LongFormPublishingOptionsProps {
  queueTypes: Array<string | QueueType>;
  selectedQueueType: string;
  onQueueTypeChange: (queueTypeName: string) => void;
  scheduledFor: string | null;
  onScheduledForChange: (value: string | null) => void;
  scheduleIntervals: number[];
  onScheduleIntervalClick: (interval: number) => void;
  onNextSlotClick: () => void;
  hashTagPresets: HashTagPreset[];
  useHashtagPresets: boolean;
  selectedHashtagPresetId?: string | null;
  selectedHashtags: string;
  onHashtagPresetChange: (presetId: string | null, hashtags: string) => void;
  onUseHashtagPresetsChange: (value: boolean) => void;
}

export function LongFormPublishingOptions({
  queueTypes,
  selectedQueueType,
  onQueueTypeChange,
  scheduledFor,
  onScheduledForChange,
  scheduleIntervals,
  onScheduleIntervalClick,
  onNextSlotClick,
  hashTagPresets,
  useHashtagPresets,
  selectedHashtagPresetId,
  selectedHashtags: _selectedHashtags,
  onHashtagPresetChange,
  onUseHashtagPresetsChange,
}: LongFormPublishingOptionsProps) {
  // Find the currently selected queue type
  const currentQueueType = queueTypes?.find(
    (qt) => (typeof qt === "string" ? qt : qt.name) === selectedQueueType,
  );

  const isFixedSlotQueue =
    currentQueueType &&
    typeof currentQueueType === "object" &&
    currentQueueType.scheduleType === "FIXED_SLOTS";

  return (
    <div className="space-y-6 rounded-lg bg-gray-50 p-6 dark:bg-gray-800/50">
      <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
        Publishing Options
      </h3>

      {/* Queue Type Selection */}
      <div className="space-y-3">
        <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
          Queue Type
        </Label>
        <div className="flex flex-wrap gap-2">
          {queueTypes
            ?.filter((queue) => {
              return typeof queue === "object" ? queue.isEnabled !== false : true;
            })
            .map((queue) => {
              const queueName = typeof queue === "string" ? queue : queue.name;
              const queueColor = typeof queue === "object" ? queue.color : null;
              return (
                <button
                  key={queueName}
                  type="button"
                  onClick={() => onQueueTypeChange(queueName)}
                  className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueueType === queueName)} transition-all disabled:cursor-not-allowed disabled:opacity-50`}
                  style={
                    queueColor
                      ? {
                          backgroundColor:
                            selectedQueueType === queueName
                              ? queueColor
                              : `${queueColor}33`,
                          borderColor: queueColor,
                          color:
                            selectedQueueType === queueName
                              ? "white"
                              : queueColor,
                        }
                      : {}
                  }
                >
                  {queueName}
                </button>
              );
            })}
        </div>
        <input type="hidden" name="queueType" value={selectedQueueType} />
      </div>

      {/* Hashtag Preset Toggle */}
      <HashtagPresetToggle
        presets={hashTagPresets}
        selectedPresetId={selectedHashtagPresetId}
        onSelect={onHashtagPresetChange}
        useHashtagPresets={useHashtagPresets}
        onUseHashtagPresetsChange={onUseHashtagPresetsChange}
        showQueuePreset={true}
        queueType={(() => {
          const qt = queueTypes?.find(
            (q) => (typeof q === "string" ? q : q.name) === selectedQueueType,
          );
          // Only pass QueueType objects with the necessary properties
          if (qt && typeof qt === "object" && qt.id) {
            return qt as {
              id: string;
              name: string;
              hashTagPreset?: HashTagPreset | null;
            };
          }
          return null;
        })()}
      />

      {/* Hidden hashtag preset inputs */}
      <input
        type="hidden"
        name="useHashtagPresets"
        value={useHashtagPresets.toString()}
      />
      <input
        type="hidden"
        name="hashTagPresetId"
        value={selectedHashtagPresetId ?? ""}
      />

      {/* Schedule Controls */}
      <div className="space-y-3">
        <Label
          htmlFor="scheduledFor"
          className="text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Schedule for later
        </Label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <Input
            type="datetime-local"
            id="scheduledFor"
            name="scheduledFor"
            value={scheduledFor ?? ""}
            onChange={(e) => onScheduledForChange(e.target.value || null)}
            className="flex-1 bg-white dark:bg-gray-900"
            placeholder="Select date and time"
          />
        </div>
        <div className="flex flex-wrap gap-2">
          {isFixedSlotQueue ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onNextSlotClick}
              className="border-blue-500 text-blue-700 hover:bg-blue-50"
            >
              Next Slot
            </Button>
          ) : (
            scheduleIntervals?.map((interval) => (
              <Button
                key={interval}
                type="button"
                variant="secondary"
                size="sm"
                onClick={() => onScheduleIntervalClick(interval)}
                className="transition-transform hover:scale-105"
              >
                +{interval}h
              </Button>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { useOptionalUser } from "~/lib/remix-utils";

import { usePostScheduling } from "../hooks/usePostScheduling";
import type { QueueType, HashTagPreset } from "../types";
import { validateAndProcessFiles } from "../utils/file-processing.client";

import { QueueSelector } from "./QueueSelector";
import { SchedulingSection } from "./SchedulingSection";

interface PreparedEventData {
  content: {
    fileUrl: string;
    scheduledFor: string;
    caption: string;
    queueType: string;
  };
  type: "media";
  queueType: string;
}

interface MediaPostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: Array<string | QueueType>;
  hashTagPresets?: HashTagPreset[];
  selectedQueueType?: string;
  onQueueTypeChange?: (queueType: string) => void;
  selectedHashTagPresetId?: string | null;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

// Helper function to determine media type (kept for backward compatibility)
const getMediaType = (file: File) => {
  if (file.type.startsWith("image/")) return "image";
  if (file.type.startsWith("video/")) return "video";
  return "unknown";
};

// isAcceptableFile is now imported from file-processing.client.ts

export default function MediaPost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  hashTagPresets = [],
  onQueueTypeChange,
  selectedHashTagPresetId,
  onHashtagPresetChange,
}: MediaPostProps) {
  const user = useOptionalUser();

  const [isRecyclable, setIsRecyclable] = useState(false);
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState(
    selectedHashTagPresetId ?? null,
  );
  const [_selectedHashtags, setSelectedHashtags] = useState("");
  const [timeError, setTimeError] = useState<string | null>(null);

  // Use the shared scheduling hook
  const {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals,
  } = usePostScheduling({
    queueTypes,
    scheduleIntervals: user?.scheduleInterval as number[] | undefined,
    userTimezone: user?.timezone ?? undefined,
    initialQueue: "unassigned",
    onQueueTypeChange,
    onTimeError: setTimeError,
  });

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Use extracted utility for validation and processing
    const processedFiles = await validateAndProcessFiles(selectedFiles);

    if (processedFiles) {
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);

    if (droppedFiles.length > 0) {
      // Use extracted utility for validation and processing
      const processedFiles = await validateAndProcessFiles(droppedFiles);

      if (processedFiles) {
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const [isUploading, setIsUploading] = useState(false);
  const [uploadProvider, setUploadProvider] = useState<string | null>(null);

  // Fetch upload provider on component mount
  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch("/api/user-upload-provider");
        const data: unknown = await res.json();
        const provider =
          data &&
          typeof data === "object" &&
          !Array.isArray(data) &&
          "provider" in data &&
          typeof data.provider === "string"
            ? data.provider
            : null;
        setUploadProvider(provider);
      } catch (err) {
        const { handleErrorSafely } =
          require("~/lib/error-handler.client") as unknown as {
            handleErrorSafely: (
              error: unknown,
              context: { component: string; action: string },
            ) => void;
          };
        handleErrorSafely(err, {
          component: "MediaPost",
          action: "fetchUploadProvider",
        });
      }
    })();
  }, []);

  const handleImagePreview = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    if (files.length === 0) {
      toast.error("Please select files to upload");
      return;
    }

    setTimeError("");
    setIsUploading(true);

    // Get form data
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const caption = formData.get("caption") ?? "";

    try {
      // Use the new upload utility that handles both S3 and Blossom
      const uploadResults = await uploadMultipleFiles(files);

      // Check if all uploads were successful
      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        toast.error(`Upload failed: ${errorMessages}`);
        setIsUploading(false);
        return;
      }

      // Extract URLs from successful uploads
      const fileUrls = uploadResults
        .filter((result) => result.success && result.file)
        .map((result) => ({
          fileUrl: result.file!.url,
          scheduledFor,
          caption: caption,
          queueType: selectedQueue,
        }));

      if (fileUrls.length === 0) {
        toast.error("No files were successfully uploaded");
        setIsUploading(false);
        return;
      }

      toast.success("Media uploaded successfully!");

      const preparedData: PreparedEventData[] = fileUrls.map((url) => {
        return {
          content: {
            fileUrl: url.fileUrl,
            scheduledFor: url.scheduledFor,
            caption:
              typeof url.caption === "string"
                ? url.caption
                : String(url.caption ?? ""),
            queueType: url.queueType ?? selectedQueue,
          },
          type: "media",
          queueType: url.queueType ?? selectedQueue,
        };
      });

      setShowImagePreview(true);
      setPreparedImageEvent(preparedData);
      setFiles([]);
      setIsUploading(false);
    } catch (error) {
      const { handleAsyncError, getErrorMessage } = await import(
        "~/lib/error-handler.client"
      );
      const errorMessage = getErrorMessage(error) ?? "Unknown error";
      handleAsyncError(
        error,
        {
          component: "MediaPost",
          action: "handleImagePreview",
        },
        false,
      ); // Don't show toast, we call toast.error instead
      toast.error(`Upload failed: ${errorMessage}`);
      setIsUploading(false);
    }
  };

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtags(hashtags);
    if (onHashtagPresetChange) {
      onHashtagPresetChange(presetId, hashtags);
    }
  };

  const isUploaded = false; // Removed old fetcher logic

  return (
    <form className="w-full" onSubmit={(e) => void handleImagePreview(e)}>
      <input type="hidden" name="_action" value="upload-media-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*,video/*"
          multiple
          onChange={(e) => void handleFileChange(e)}
          disabled={isUploading || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={!isUploaded ? (e) => void handleDrop(e) : undefined}
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => {
                const mediaType = getMediaType(file);
                const objectURL = URL.createObjectURL(file);

                return (
                  <div key={index} className="relative">
                    {mediaType === "image" ? (
                      <img
                        src={objectURL}
                        alt="Preview"
                        className="h-32 w-32 rounded object-cover"
                      />
                    ) : mediaType === "video" ? (
                      <video
                        src={objectURL}
                        className="h-32 w-32 rounded object-cover"
                        muted
                        preload="metadata"
                      />
                    ) : (
                      <div className="flex h-32 w-32 items-center justify-center rounded bg-gray-200">
                        <span className="text-xs text-gray-500">
                          Unsupported
                        </span>
                      </div>
                    )}
                    <button
                      type="button"
                      onClick={() =>
                        setFiles(files.filter((_, i) => i !== index))
                      }
                      className="absolute -right-2 -top-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                      disabled={isUploading}
                    >
                      ×
                    </button>
                    {/* Media type indicator */}
                    <div className="absolute bottom-1 left-1 rounded bg-black bg-opacity-70 px-2 py-1 text-xs text-white">
                      {mediaType === "video" ? "🎥" : "🖼️"}
                    </div>
                  </div>
                );
              })}
              <div className="flex h-32 w-32 items-center justify-center rounded border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Images (10MB max) and Videos (100MB max)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your media..."
          rows={3}
          disabled={isUploading || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <QueueSelector
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onQueueChange={setSelectedQueue}
            disabled={isUploading || isUploaded}
            className="mb-2"
          />

          {/* Hashtag Preset Toggle */}
          <HashtagPresetToggle
            presets={hashTagPresets}
            selectedPresetId={selectedHashtagPresetId}
            onSelect={handleHashtagPresetSelect}
            disabled={isUploading || isUploaded}
            useHashtagPresets={useHashtagPresets}
            onUseHashtagPresetsChange={setUseHashtagPresets}
            showQueuePreset={selectedQueue !== "unassigned"}
            queueType={
              (queueTypes.find(
                (q) => (typeof q === "string" ? q : q.name) === selectedQueue,
              ) ?? null) as QueueType | null | undefined
            }
          />
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={isUploading || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <SchedulingSection
            scheduledFor={scheduledFor}
            onScheduledForChange={setScheduledFor}
            scheduleIntervals={scheduleIntervals}
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onScheduleIntervalClick={(intervalHours) =>
              void handleScheduleIntervalClick(intervalHours)
            }
            onCalculateNextSlot={() => {
              void calculateQueueScheduleTime(selectedQueue);
            }}
            disabled={isUploading || isUploaded}
            showTimeInput={true}
          />
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
        </div>
        <div className="flex flex-col items-end gap-2">
          {uploadProvider ? (
            <div className="flex items-center gap-1 text-xs text-gray-500">
              <span>Upload via:</span>
              <span
                className={`rounded px-2 py-1 text-xs font-medium ${
                  uploadProvider.includes("BLOSSOM")
                    ? "bg-purple-100 text-purple-800"
                    : "bg-blue-100 text-blue-800"
                }`}
              >
                {uploadProvider.includes("BLOSSOM")
                  ? `🌸 ${uploadProvider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr"}`
                  : "☁️ S3"}
              </span>
            </div>
          ) : null}
          <button
            type="submit"
            className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
            disabled={isUploading || isUploaded || files.length === 0}
          >
            {isUploading ? "Uploading..." : "Upload Media →"}
          </button>
        </div>
      </div>
    </form>
  );
}

import { useFetcher } from "@remix-run/react";

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { nostrAdapter } from "~/lib/nostr-adapter.client";
import { useOptionalUser } from "~/lib/remix-utils";
interface PreparedEventData {
  content: {
    fileUrl: string;
    scheduledFor: string;
    caption: string;
    queueType: string;
  };
  type: "media";
  queueType: string;
}

interface NewPostImagesConfirmationProps {
  preparedEvents: PreparedEventData[];
  onCancel: () => void;
  postsCount: number;
  tags: string;
}

export default function NewPostImagesConfirmation({
  preparedEvents,
  onCancel,
  postsCount,
  tags,
}: NewPostImagesConfirmationProps) {
  const fetcher = useFetcher();
  const isSubmitting = fetcher.state !== "idle";
  const user = useOptionalUser();

  // Calculate addTags for display
  const addTags = user?.showHashTagsinPosts ? `\n${tags ?? ""}` : "";

  // Flatten the array structure if needed
  const events: PreparedEventData[] = Array.isArray(preparedEvents[0])
    ? (preparedEvents[0] as PreparedEventData[])
    : preparedEvents;

  const handleSignAndSubmit = async (isImmediate: boolean) => {
    try {
      // Get effective hashtags based on queue type
      const firstEvent = events[0];
      const queueType =
        firstEvent &&
        typeof firstEvent === "object" &&
        "queueType" in firstEvent &&
        typeof firstEvent.queueType === "string"
          ? firstEvent.queueType
          : "unassigned";
      let effectiveHashtags = "";

      try {
        const response = await fetch("/api/effective-hashtags", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: user?.id,
            queueTypeName: queueType,
          }),
        });

        if (response.ok) {
          const data = (await response.json()) as { hashtags?: string };
          effectiveHashtags = data.hashtags ?? "";
        } else {
          // Fallback to user's default hashtags
          effectiveHashtags = Array.isArray(tags)
            ? tags.join(" ")
            : (tags ?? "");
        }
      } catch (error) {
        const { handleErrorSafely } = await import(
          "~/lib/error-handler.client"
        );
        handleErrorSafely(error, {
          component: "NewPostImagesConfirmation",
          action: "fetchEffectiveHashtags",
        });
        // Fallback to user's default hashtags
        effectiveHashtags = Array.isArray(tags) ? tags.join(" ") : (tags ?? "");
      }

      const addTags = user?.showHashTagsinPosts ? `\n${effectiveHashtags}` : "";

      const userTimezone = user?.timezone ?? "UTC";
      let scheduledTime;

      if (isImmediate) {
        scheduledTime = Date.now();
      } else {
        const firstEvent = events[0];
        let scheduledForStr = "";
        if (
          firstEvent &&
          typeof firstEvent === "object" &&
          "content" in firstEvent
        ) {
          const content = firstEvent.content;
          if (
            content &&
            typeof content === "object" &&
            !Array.isArray(content) &&
            "scheduledFor" in content
          ) {
            const scheduledFor = content.scheduledFor;
            if (typeof scheduledFor === "string") {
              scheduledForStr = scheduledFor;
            }
          }
        }

        // Only convert timezone if not UTC/Etc/GMT
        if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
          const utcDate = new Date(scheduledForStr);

          // Get timezone offset in minutes between user timezone and UTC
          const userDate = new Date(scheduledForStr).toLocaleString("en-US", {
            timeZone: userTimezone,
          });
          const userOffset =
            (new Date(userDate).getTime() -
              new Date(scheduledForStr).getTime()) /
            60000;

          // Adjust the date by the offset
          utcDate.setMinutes(utcDate.getMinutes() - userOffset);
          scheduledTime = utcDate.getTime();
        } else {
          // Parse date string and ensure it's in UTC
          const dateObj = new Date(scheduledForStr + "Z");
          scheduledTime = dateObj.getTime();
        }
      }

      const scheduledForUnix = Math.floor(scheduledTime / 1000);

      const tagArray = effectiveHashtags
        .split(" ")
        .filter((tag: string) => tag.length > 0)
        .map((tag: string) => ["t", tag.replace("#", "")]);

      const firstEventContent = events[0]?.content;
      const firstCaption =
        firstEventContent &&
        typeof firstEventContent === "object" &&
        "caption" in firstEventContent &&
        typeof firstEventContent.caption === "string"
          ? firstEventContent.caption
          : "";
      const fileUrls = events
        .map((event) => {
          const content = event.content;
          if (
            content &&
            typeof content === "object" &&
            "fileUrl" in content &&
            typeof content.fileUrl === "string"
          ) {
            return content.fileUrl;
          }
          return "";
        })
        .filter((url) => url !== "");

      const eventData = {
        content:
          (firstCaption + addTags || "") +
          (fileUrls.length > 0 ? " " + fileUrls.join(" ") : ""),
        created_at: scheduledForUnix,
        kind: 1,
        tags: tagArray,
      };

      const { signedEvent, nostrEvent } = await nostrAdapter.signEvent(eventData);

      const formData = new FormData();
      formData.append("_action", isImmediate ? "post-media" : "schedule-media");
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      const fileUrlsForForm = events
        .map((event) => {
          const content = event.content;
          if (
            content &&
            typeof content === "object" &&
            "fileUrl" in content &&
            typeof content.fileUrl === "string"
          ) {
            return content.fileUrl;
          }
          return "";
        })
        .filter((url) => url !== "");
      const captionForForm =
        firstEventContent &&
        typeof firstEventContent === "object" &&
        "caption" in firstEventContent &&
        typeof firstEventContent.caption === "string"
          ? firstEventContent.caption
          : "";
      const queueTypeForForm =
        firstEventContent &&
        typeof firstEventContent === "object" &&
        "queueType" in firstEventContent &&
        typeof firstEventContent.queueType === "string"
          ? firstEventContent.queueType
          : "unassigned";

      formData.append("fileUrl", JSON.stringify(fileUrlsForForm));
      formData.append("caption", captionForForm);
      formData.append("scheduledFor", scheduledForUnix.toString());
      formData.append("queueType", queueTypeForForm);

      fetcher.submit(formData, {
        method: "post",
        action: "/dashboard/newpost",
      });
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(
        error,
        {
          component: "NewPostImagesConfirmation",
          action: "handleSignAndSubmit",
        },
        false,
      ); // Don't show toast, let component handle it
    }
  };

  const handleSaveAsDraft = () => {
    const formData = new FormData();
    formData.append("_action", "draft-media");
    const draftFileUrls = events
      .map((event) => {
        const content = event.content;
        if (
          content &&
          typeof content === "object" &&
          "fileUrl" in content &&
          typeof content.fileUrl === "string"
        ) {
          return content.fileUrl;
        }
        return "";
      })
      .filter((url) => url !== "");
    const draftFirstEvent = events[0];
    const draftCaption =
      draftFirstEvent &&
      typeof draftFirstEvent === "object" &&
      "content" in draftFirstEvent &&
      typeof draftFirstEvent.content === "object" &&
      draftFirstEvent.content !== null &&
      "caption" in draftFirstEvent.content &&
      typeof draftFirstEvent.content.caption === "string"
        ? draftFirstEvent.content.caption
        : "";
    const draftQueueType =
      draftFirstEvent &&
      typeof draftFirstEvent === "object" &&
      "content" in draftFirstEvent &&
      typeof draftFirstEvent.content === "object" &&
      draftFirstEvent.content !== null &&
      "queueType" in draftFirstEvent.content &&
      typeof draftFirstEvent.content.queueType === "string"
        ? draftFirstEvent.content.queueType
        : "unassigned";
    formData.append("fileUrl", JSON.stringify(draftFileUrls));
    formData.append("caption", draftCaption);
    formData.append("queueType", draftQueueType);

    fetcher.submit(formData, {
      method: "post",
      action: "/dashboard/newpost",
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6 dark:from-gray-900 dark:to-gray-800">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Confirm Your Post
          </h1>
          <p className="mt-2 text-gray-600 dark:text-gray-400">
            Review your post before publishing or scheduling
          </p>
        </div>

        {/* Post Card */}
        <div className="mx-auto max-w-2xl">
          <div className="group overflow-hidden rounded-xl bg-white shadow-lg transition-all duration-300 hover:shadow-xl dark:bg-gray-800">
            {/* Post Header */}
            <div className="flex items-center justify-between border-b border-gray-200 p-4 dark:border-gray-700">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                Media Post
              </h3>
              <span className="rounded-full bg-blue-100 px-3 py-1 text-xs font-medium text-blue-600 dark:bg-blue-900 dark:text-blue-300">
                {postsCount} {postsCount === 1 ? "File" : "Files"}
              </span>
            </div>

            {/* Media Grid */}
            <div className="p-4">
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4">
                {events.map((event: PreparedEventData, index: number) => {
                  const content = event.content;
                  const fileUrl =
                    content &&
                    typeof content === "object" &&
                    "fileUrl" in content &&
                    typeof content.fileUrl === "string"
                      ? content.fileUrl
                      : "";
                  return (
                    <div
                      key={index}
                      className="relative overflow-hidden rounded-lg"
                    >
                      <MediaThumbnail
                        src={fileUrl}
                        alt={`Preview ${index + 1}`}
                        className="h-32 w-full object-cover transition-transform duration-300 group-hover:scale-105"
                      />
                      <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Content */}
            <div className="space-y-4 p-4">
              {/* Caption */}
              {(() => {
                const firstEvent = events[0];
                const firstContent = firstEvent?.content;
                const caption =
                  firstContent &&
                  typeof firstContent === "object" &&
                  "caption" in firstContent &&
                  typeof firstContent.caption === "string"
                    ? firstContent.caption
                    : "";
                return caption ? (
                  <div>
                    <h4 className="mb-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                      Caption
                    </h4>
                    <div className="max-h-20 overflow-y-auto rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
                      <p className="whitespace-pre-wrap text-sm text-gray-700 dark:text-gray-300">
                        {caption + addTags}
                      </p>
                    </div>
                  </div>
                ) : null;
              })()}

              {/* Tags */}
              {tags ? (
                <div>
                  <h4 className="mb-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                    Tags
                  </h4>
                  <div className="flex flex-wrap gap-1">
                    {tags
                      .split(" ")
                      .filter((tag: string) => tag.length > 0)
                      .map((tag: string, tagIndex: number) => (
                        <span
                          key={tagIndex}
                          className="rounded-full bg-blue-100 px-2 py-1 text-xs font-medium text-blue-600 dark:bg-blue-900 dark:text-blue-300"
                        >
                          {tag.startsWith("#") ? tag : `#${tag}`}
                        </span>
                      ))}
                  </div>
                </div>
              ) : null}

              {/* Schedule time */}
              <div className="rounded-lg border border-gray-200 p-3 text-center dark:border-gray-600">
                <h4 className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500 dark:text-gray-400">
                  Scheduled for
                </h4>
                <p className="text-sm font-semibold text-gray-900 dark:text-white">
                  {events[0]?.content?.scheduledFor
                    ? new Date(events[0].content.scheduledFor).toLocaleDateString(
                        "en-US",
                        {
                          weekday: "short",
                          month: "short",
                          day: "numeric",
                          hour: "2-digit",
                          minute: "2-digit",
                        },
                      )
                    : "Not scheduled"}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center gap-4">
          <button
            onClick={onCancel}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            disabled={isSubmitting}
          >
            ← Back to Edit
          </button>
          <button
            onClick={handleSaveAsDraft}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            disabled={isSubmitting}
          >
            💾 Save as Draft
          </button>
          <button
            onClick={() => void handleSignAndSubmit(true)}
            className="rounded-lg bg-gradient-to-r from-green-500 to-green-600 px-6 py-3 text-sm font-medium text-white shadow-lg transition-all hover:from-green-600 hover:to-green-700 hover:shadow-xl disabled:cursor-not-allowed disabled:from-green-300 disabled:to-green-400"
            disabled={isSubmitting}
          >
            🚀 Post Now
          </button>
          <button
            onClick={() => void handleSignAndSubmit(false)}
            className="rounded-lg bg-gradient-to-r from-blue-500 to-blue-600 px-8 py-3 text-sm font-medium text-white shadow-lg transition-all hover:from-blue-600 hover:to-blue-700 hover:shadow-xl disabled:cursor-not-allowed disabled:from-blue-300 disabled:to-blue-400"
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              <span className="flex items-center gap-2">
                <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24">
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                    fill="none"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  />
                </svg>
                Signing & Scheduling...
              </span>
            ) : (
              <>
                🚀 Schedule {postsCount} {postsCount === 1 ? "Post" : "Posts"}
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { logClientError } from "~/lib/error-handler.client";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import { getSelectedQueueStyle } from "../queueColors";
import type { PreparedEvent } from "../types";

interface PostConfirmationProps {
  preparedEvents: PreparedEvent[];
  postsCount: number;
}

export default function PostConfirmation({
  preparedEvents,
  postsCount,
}: PostConfirmationProps) {
  const fetcher = useFetcher();
  const isSubmitting = fetcher.state !== "idle";

  const handleSignAndSubmit = async () => {
    try {
      const signed = await Promise.all(
        preparedEvents.map(async (eventData: PreparedEvent, index: number) => {
          try {
            const { nostrEvent, signedEvent } = await nostrAdapter.signEvent(
              eventData.events,
            );

            return {
              nostrEvent,
              signedEvent,
              fileUrl: eventData.fileUrl,
              caption: eventData.caption,
              queueType: eventData.queueType,
              isRecyclable: eventData.isRecyclable,
              originalPostId: eventData.originalPostId,
            };
          } catch (eventError) {
            const { handleAsyncError } = await import(
              "~/lib/error-handler.client"
            );
            handleAsyncError(
              eventError,
              {
                component: "PostConfirmation",
                action: "signEvent",
                eventIndex: index,
              },
              false,
            ); // Don't show toast, throw to outer catch
            throw eventError;
          }
        }),
      );

      const finalFormData = new FormData();
      signed.forEach((data) => {
        finalFormData.append("nostrEvent", JSON.stringify(data.nostrEvent));
        finalFormData.append("signedEvents", JSON.stringify(data.signedEvent));
        finalFormData.append("fileUrl", JSON.stringify(data.fileUrl));
        finalFormData.append("caption", JSON.stringify(data.caption));
        finalFormData.append("queueType", data.queueType);
        finalFormData.append(
          "isRecyclable",
          data.isRecyclable ? "true" : "false",
        );
        finalFormData.append("originalPostId", data.originalPostId ?? "");
      });
      finalFormData.append("_action", "sign_and_schedule");

      // Preserve the current URL's search params (including mode=recycle)
      const currentUrl = new URL(window.location.href);
      const actionUrl = `/dashboard/bulkposts${currentUrl.search}`;

      fetcher.submit(finalFormData, {
        method: "post",
        encType: "multipart/form-data",
        action: actionUrl,
      });
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(
        error,
        {
          component: "PostConfirmation",
          action: "handleSignAndSubmit",
        },
        false,
      ); // Don't show toast, let component handle it
    }
  };

  const handleSaveAsDraft = () => {
    const finalFormData = new FormData();
    preparedEvents.forEach((eventData) => {
      finalFormData.append("fileUrl", JSON.stringify(eventData.fileUrl));
      finalFormData.append("caption", JSON.stringify(eventData.caption));
      finalFormData.append("queueType", eventData.queueType);
      finalFormData.append(
        "isRecyclable",
        eventData.isRecyclable ? "true" : "false",
      );
      finalFormData.append("originalPostId", eventData.originalPostId ?? "");
    });
    finalFormData.append("_action", "save_as_draft");

    // Preserve the current URL's search params (including mode=recycle)
    const currentUrl = new URL(window.location.href);
    const actionUrl = `/dashboard/bulkposts${currentUrl.search}`;

    fetcher.submit(finalFormData, {
      method: "post",
      encType: "multipart/form-data",
      action: actionUrl,
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6 dark:from-gray-900 dark:to-gray-800">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Confirm Your Posts
          </h1>
          <p className="mt-2 text-gray-600 dark:text-gray-400">
            Review your {postsCount} posts before scheduling them
          </p>
        </div>

        {/* Posts Grid */}
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {preparedEvents?.map((eventData, index) => {
            // Extract events data with type safety
            const eventsData = eventData.events;
            const eventsKind =
              typeof eventsData === "object" &&
              eventsData !== null &&
              "kind" in eventsData
                ? (eventsData as { kind?: unknown }).kind
                : undefined;
            const isRepost = eventsKind === 6;

            // Debug logging for reposts
            if (isRepost) {
              const eventsTags =
                typeof eventsData === "object" &&
                eventsData !== null &&
                "tags" in eventsData
                  ? (eventsData as { tags?: unknown }).tags
                  : undefined;
              logClientError(
                `Repost ${index + 1} data`,
                {
                  component: "PostConfirmation",
                  action: "renderRepost",
                  index: index + 1,
                  fileUrl: eventData.fileUrl,
                  caption: eventData.caption,
                  kind: eventsKind,
                  tags: eventsTags,
                },
                "info",
              );
            }

            // For reposts, use the original fileUrl directly
            // For regular posts, parse content to extract media URLs
            let mediaUrl = "";
            let caption = "";
            let tags = "";

            if (isRepost) {
              // For reposts, use the fileUrl from the eventData
              mediaUrl = eventData.fileUrl ?? "";
              caption = eventData.caption ?? "";
              // Hide tags for reposts
              tags = "";
            } else {
              // For regular posts, parse content assuming format: "caption mediaUrl1 mediaUrl2 ..."
              const eventsContent =
                typeof eventsData === "object" &&
                eventsData !== null &&
                "content" in eventsData
                  ? (eventsData as { content?: unknown }).content
                  : undefined;
              if (eventsContent && typeof eventsContent === "string") {
                const contentParts = eventsContent.split(" ");
                const mediaUrl_ = contentParts.find(
                  (part) =>
                    part &&
                    part.trim() !== "" &&
                    part !== "null" &&
                    part.startsWith("http"),
                );
                const captionParts = contentParts.filter(
                  (part) =>
                    part &&
                    part.trim() !== "" &&
                    part !== "null" &&
                    !part.startsWith("http"),
                );

                caption = captionParts.join(" ");
                mediaUrl = mediaUrl_ || "";
              } else {
                // Fallback to eventData.caption if content is not available
                caption = eventData.caption ?? "";
                mediaUrl = eventData.fileUrl ?? "";
              }
              const eventsTags =
                typeof eventsData === "object" &&
                eventsData !== null &&
                "tags" in eventsData
                  ? (eventsData as { tags?: unknown }).tags
                  : undefined;
              tags = (Array.isArray(eventsTags) ? eventsTags : [])
                .map((tag) =>
                  Array.isArray(tag) && tag[1] && typeof tag[1] === "string"
                    ? `#${tag[1]}`
                    : "",
                )
                .filter((t) => t !== "")
                .join(" ");
            }

            // Extract eventsTags for use in JSX
            const eventsTagsForDisplay =
              typeof eventsData === "object" &&
              eventsData !== null &&
              "tags" in eventsData
                ? (eventsData as { tags?: unknown }).tags
                : undefined;

            return (
              <div
                key={index}
                className="group overflow-hidden rounded-xl bg-white shadow-lg transition-all duration-300 hover:shadow-xl dark:bg-gray-800"
              >
                {/* Post Header */}
                <div className="flex items-center justify-between border-b border-gray-200 p-4 dark:border-gray-700">
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                    {isRepost ? `Repost ${index + 1}` : `Post ${index + 1}`}
                  </h3>
                  <span
                    className={`rounded-full px-3 py-1 text-xs font-medium ${getSelectedQueueStyle(eventData.queueType, true)}`}
                  >
                    {eventData.queueType}
                  </span>
                </div>

                {/* Content */}
                <div className="space-y-4 p-4">
                  {/* Caption */}
                  {caption ? (
                    <div>
                      <h4 className="mb-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                        Caption
                      </h4>
                      <div className="max-h-20 overflow-y-auto rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
                        <p className="whitespace-pre-wrap text-sm text-gray-700 dark:text-gray-300">
                          {caption}
                        </p>
                      </div>
                    </div>
                  ) : null}

                  {/* Media preview - shown after caption */}
                  {mediaUrl ? (
                    <div>
                      <h4 className="mb-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                        Media
                      </h4>
                      <div className="relative overflow-hidden rounded-lg">
                        <MediaThumbnail
                          src={mediaUrl}
                          alt={`Preview ${index + 1}`}
                          className="h-48 w-full object-cover transition-transform duration-300 group-hover:scale-105"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
                      </div>
                    </div>
                  ) : null}

                  {/* Show placeholder for text-only posts */}
                  {!mediaUrl && !caption ? (
                    <div className="flex h-32 w-full items-center justify-center rounded-lg bg-gray-200 dark:bg-gray-700">
                      <span className="text-gray-500 dark:text-gray-400">
                        {isRepost ? "REPOST" : "TEXT"}
                      </span>
                    </div>
                  ) : null}

                  {/* Tags - Only show hashtag tags (t) for non-reposts */}
                  {tags && !isRepost ? (
                    <div>
                      <h4 className="mb-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                        Tags
                      </h4>
                      <div className="flex flex-wrap gap-1">
                        {(Array.isArray(eventsTagsForDisplay)
                          ? eventsTagsForDisplay
                          : []
                        )
                          .filter((tag) => Array.isArray(tag) && tag[0] === "t") // Only show hashtag tags
                          .map((tag, tagIndex) => {
                            const tagValue =
                              Array.isArray(tag) &&
                              tag[1] &&
                              typeof tag[1] === "string"
                                ? tag[1]
                                : "";
                            return (
                              <span
                                key={tagIndex}
                                className="rounded-full bg-blue-100 px-2 py-1 text-xs font-medium text-blue-600 dark:bg-blue-900 dark:text-blue-300"
                              >
                                #{tagValue}
                              </span>
                            );
                          })}
                      </div>
                    </div>
                  ) : null}

                  {/* Schedule time */}
                  <div className="rounded-lg border border-gray-200 p-3 text-center dark:border-gray-600">
                    <h4 className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Scheduled for
                    </h4>
                    <p className="text-sm font-semibold text-gray-900 dark:text-white">
                      {new Date(
                        (typeof eventsData === "object" &&
                        eventsData !== null &&
                        "created_at" in eventsData &&
                        typeof (eventsData as { created_at?: unknown })
                          .created_at === "number"
                          ? (eventsData as { created_at: number }).created_at
                          : 0) * 1000,
                      ).toLocaleDateString("en-US", {
                        weekday: "short",
                        month: "short",
                        day: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center gap-4">
          <button
            onClick={() => window.history.back()}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            disabled={isSubmitting}
          >
            ← Back to Edit
          </button>
          <button
            onClick={handleSaveAsDraft}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
            disabled={isSubmitting}
          >
            💾 Save as Draft
          </button>
          <button
            onClick={() => void handleSignAndSubmit()}
            className="rounded-lg bg-gradient-to-r from-blue-500 to-blue-600 px-8 py-3 text-sm font-medium text-white shadow-lg transition-all hover:from-blue-600 hover:to-blue-700 hover:shadow-xl disabled:cursor-not-allowed disabled:from-blue-300 disabled:to-blue-400"
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              <span className="flex items-center gap-2">
                <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24">
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                    fill="none"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  />
                </svg>
                Signing & Scheduling...
              </span>
            ) : (
              <>🚀 Sign and Schedule {postsCount} Posts</>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import type { Post } from "@prisma/client";
import { useFetcher, Link } from "@remix-run/react";
import { useState } from "react";

import MediaModal from "~/components/ui/MediaModal";
import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { formatDate, getImageUrls } from "~/lib/helpers";

import { getQueueColor } from "../queueColors";
import type { CombinedContent, PostData } from "../types";
interface PostDetailsModalProps {
  post: Post | PostData | CombinedContent;
  stats?: {
    likes: number;
    replies: number;
    mentions: number;
    reposts: number;
    zaps: number;
    satszapped: number;
  };
  onClose: () => void;
  showStats?: boolean;
  showSignedEvent?: boolean;
  type?: "draft" | "posted" | "scheduled";
  userTimezone?: string;
}

export default function PostDetailsModal({
  post,
  stats,
  onClose,
  showStats = false,
  showSignedEvent = false,
  type = "posted",
  userTimezone,
}: PostDetailsModalProps) {
  const deleteFetcher = useFetcher();
  const [isMediaOpen, setIsMediaOpen] = useState(false);
  const [activeMediaSrc, setActiveMediaSrc] = useState<string | null>(null);

  // Type guard to check if post has queueType property
  const hasQueueType = (
    p: Post | PostData | CombinedContent,
  ): p is PostData | CombinedContent => {
    return "queueType" in p;
  };

  const queueType = hasQueueType(post) ? post.queueType : null;

  const formatScheduledDate = (scheduledFor: string | null | undefined) => {
    if (!scheduledFor) return "Not scheduled";

    // Use the same logic as the table formatDate function
    const timezone = userTimezone ?? "UTC";
    const date = new Date(parseInt(scheduledFor) * 1000);

    return date.toLocaleString("en-US", {
      timeZone: timezone,
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getModalTitle = () => {
    switch (type) {
      case "draft":
        return "Draft Details";
      case "scheduled":
        return "Scheduled Post Details";
      default:
        return "Post Details";
    }
  };

  const getDeleteButtonText = () => {
    switch (type) {
      case "draft":
        return "Delete Draft";
      case "scheduled":
        return "Delete Scheduled Post";
      default:
        return "Delete Post";
    }
  };

  const getStatusBadge = () => {
    const badgeClasses =
      "inline-flex items-center rounded-full px-3 py-1 text-sm font-medium";

    switch (type) {
      case "draft":
        return (
          <span
            className={`${badgeClasses} bg-orange-100 text-orange-900 dark:bg-orange-700/10 dark:text-orange-200`}
          >
            Draft
          </span>
        );
      case "scheduled":
        return (
          <span
            className={`${badgeClasses} bg-blue-100 text-blue-900 dark:bg-blue-700/10 dark:text-blue-200`}
          >
            Scheduled
          </span>
        );
      default:
        return (
          <span
            className={`${badgeClasses} bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-200`}
          >
            Posted
          </span>
        );
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="mx-4 flex max-h-[90vh] w-full max-w-3xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl dark:bg-gray-900">
        <div className="sticky top-0 z-10 border-b border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                {getModalTitle()}
              </h2>
              {getStatusBadge()}
            </div>
            <button
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-full text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600 dark:hover:bg-gray-800 dark:hover:text-gray-300"
            >
              ✕
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-6">
          {post.fileUrl && post.fileUrl.length > 0 ? (
            <div className="mb-6">
              <div className="flex gap-3 overflow-x-auto pb-2">
                {getImageUrls(post.fileUrl).map((url, index) => (
                  <MediaThumbnail
                    key={index}
                    src={url}
                    alt={`Post media ${index + 1}`}
                    className="h-48 w-auto flex-shrink-0 rounded-lg object-cover shadow-sm ring-1 ring-gray-200 dark:ring-gray-700"
                    onClick={() => {
                      setActiveMediaSrc(url);
                      setIsMediaOpen(true);
                    }}
                  />
                ))}
              </div>
            </div>
          ) : null}

          <div className="space-y-6">
            <div className="rounded-lg bg-gray-50 p-4 dark:bg-gray-800/50">
              <h3 className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                Caption
              </h3>
              <p className="leading-relaxed text-gray-900 dark:text-white">
                {post.caption}
              </p>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              {type === "draft" ? (
                <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                  <h3 className="mb-1 text-sm font-medium text-gray-700 dark:text-gray-300">
                    Created
                  </h3>
                  <p className="text-gray-900 dark:text-white">
                    {formatDate(post.createdAt)}
                  </p>
                </div>
              ) : null}

              {type === "scheduled" ? (
                <>
                  {post.scheduledFor ? (
                    <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                      <h3 className="mb-1 text-sm font-medium text-gray-700 dark:text-gray-300">
                        Scheduled For
                      </h3>
                      <p className="text-gray-900 dark:text-white">
                        {formatScheduledDate(post.scheduledFor)}
                      </p>
                    </div>
                  ) : null}

                  {queueType ? (
                    <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                      <h3 className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                        Queue Type
                      </h3>
                      {(() => {
                        const colors = getQueueColor(queueType.name, queueType.color);
                        return (
                          <span
                            className={`inline-flex items-center rounded-full px-3 py-1 text-sm font-medium capitalize ${colors?.bg ?? ""} ${colors?.text ?? ""}`}
                          >
                            {queueType.name}
                          </span>
                        );
                      })()}
                    </div>
                  ) : null}
                </>
              ) : null}

              {type === "posted" ? (
                <>
                  {post.postedAt ? (
                    <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                      <h3 className="mb-1 text-sm font-medium text-gray-700 dark:text-gray-300">
                        Posted At
                      </h3>
                      <p className="text-gray-900 dark:text-white">
                        {formatDate(post.postedAt)}
                      </p>
                    </div>
                  ) : null}

                  {queueType ? (
                    <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                      <h3 className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                        Queue Type
                      </h3>
                      {(() => {
                        const colors = getQueueColor(queueType.name, queueType.color);
                        return (
                          <span
                            className={`inline-flex items-center rounded-full px-3 py-1 text-sm font-medium capitalize ${colors?.bg ?? ""} ${colors?.text ?? ""}`}
                          >
                            {queueType.name}
                          </span>
                        );
                      })()}
                    </div>
                  ) : null}
                </>
              ) : null}

              {type === "draft" && queueType ? (
                <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                  <h3 className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                    Queue Type
                  </h3>
                  {(() => {
                    const colors = getQueueColor(queueType.name, queueType.color);
                    return (
                      <span
                        className={`inline-flex items-center rounded-full px-3 py-1 text-sm font-medium capitalize ${colors?.bg ?? ""} ${colors?.text ?? ""}`}
                      >
                        {queueType.name}
                      </span>
                    );
                  })()}
                </div>
              ) : null}
            </div>

            {post.tags && post.tags.length > 0 && !post.repost ? (
              <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Tags
                </h3>
                <div className="flex flex-wrap gap-2">
                  {post.tags.map((tag) => (
                    <span
                      key={tag}
                      className="rounded-full bg-blue-100 px-3 py-1 text-sm font-medium text-blue-800 dark:bg-blue-900/30 dark:text-blue-200"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>
            ) : null}

            {showStats && stats ? (
              <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Engagement Stats
                </h3>
                <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.likes}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Likes
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.replies}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Replies
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.mentions}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Mentions
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.reposts}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Reposts
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.zaps}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Zaps
                    </p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                      {stats.satszapped}
                    </p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Sats Zapped
                    </p>
                  </div>
                </div>
              </div>
            ) : null}

            {showSignedEvent && post.signedEvent ? (
              <div className="rounded-lg border border-gray-200 p-4 dark:border-gray-700">
                <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Signed Event Data
                </h3>
                <pre className="max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-md bg-gray-100 p-3 text-xs text-gray-800 dark:bg-gray-800 dark:text-gray-200">
                  {JSON.stringify(post.signedEvent, null, 2)}
                </pre>
              </div>
            ) : null}
          </div>
        </div>

        <div className="sticky bottom-0 border-t border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex justify-end gap-3">
            {type === "posted" &&
            post.signedEvent &&
            typeof post.signedEvent === "object" &&
            "id" in post.signedEvent &&
            typeof post.signedEvent.id === "string" ? (
              <Link
                to={`https://primal.net/e/${post.signedEvent.id}`}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 dark:bg-gray-700 dark:hover:bg-gray-600"
              >
                View Note
              </Link>
            ) : null}

            <deleteFetcher.Form
              method="post"
              onClick={(e) => e.stopPropagation()}
            >
              <input type="hidden" name="postId" value={post.id} />
              <input type="hidden" name="_action" value="delete" />
              <button
                type="submit"
                disabled={deleteFetcher.state !== "idle"}
                className="inline-flex items-center rounded-lg border border-red-300 bg-white px-4 py-2 text-sm font-medium text-red-700 transition-colors hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 disabled:opacity-50 dark:border-red-600 dark:bg-gray-800 dark:text-red-400 dark:hover:bg-red-950/50"
              >
                {deleteFetcher.state !== "idle" &&
                deleteFetcher.formData?.get("postId") === post.id
                  ? "Deleting..."
                  : getDeleteButtonText()}
              </button>
            </deleteFetcher.Form>
          </div>
        </div>
      </div>

      {/* Media full-screen modal */}
      <MediaModal
        src={activeMediaSrc ?? ""}
        isOpen={Boolean(isMediaOpen && activeMediaSrc)}
        onClose={() => setIsMediaOpen(false)}
      />
    </div>
  );
}

import { Link } from "@remix-run/react";

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { formatDate, getImageUrls } from "~/lib/helpers";

import { getQueueColor } from "../queueColors";
import type { PostStats } from "../stats.server";
import type { PostData, PostFetcher } from "../types";
// Helper to safely access formData from a fetcher
function getFetcherFormData(
  fetcher: PostFetcher | undefined,
): FormData | null | undefined {
  return (fetcher as { formData?: FormData | null })?.formData;
}

interface PostedPostsTableProps {
  filteredPosts: PostData[];
  selectedPosts: Set<string>;
  stats: Record<string, PostStats>;
  sortConfig: { key: string; direction: string };
  toggleSelectAll: () => void;
  togglePostSelection: (postId: string) => void;
  requestSort: (key: string) => void;
  setSelectedPost: (post: PostData) => void;
  individualRepostFetcher: PostFetcher;
  deleteFetcher: PostFetcher;
  bulkDeleteFetcher: PostFetcher;
}

export default function PostedPostsTable({
  filteredPosts,
  selectedPosts,
  stats,
  sortConfig,
  toggleSelectAll,
  togglePostSelection,
  requestSort,
  setSelectedPost,
  individualRepostFetcher,
  deleteFetcher,
  bulkDeleteFetcher,
}: PostedPostsTableProps) {
  return (
    <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
      <table className="min-w-full whitespace-nowrap align-middle text-sm">
        <thead>
          <tr>
            <th className="bg-gray-100/75 px-3 py-4 text-center font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              <input
                type="checkbox"
                checked={
                  filteredPosts.length > 0
                    ? selectedPosts.size === filteredPosts.length
                    : false
                }
                onChange={toggleSelectAll}
                className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
              />
            </th>
            <th className="bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50">
              Media
            </th>
            <th
              className="cursor-pointer bg-gray-100/75 px-3 py-4 text-left font-semibold text-gray-900 dark:bg-gray-700/25 dark:text-gray-50"
