            {queueTypes.map((queueType) => {
              const queueName =
                typeof queueType === "string" ? queueType : queueType.name;
              const queueColor =
                typeof queueType === "object" ? queueType.color : null;
              const colors = getQueueColor(queueName, queueColor);
              const isSelected = params["queueType"] === queueName;

              const baseClasses =
                "whitespace-nowrap border-b-2 px-1 py-2 text-sm font-medium capitalize";
              const unselectedClasses =
                "border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300";

              if (isSelected && queueColor) {
                // Use inline styles for custom colors
                return (
                  <Link
                    key={queueName}
                    to={`/dashboard/posted/${queueName}?tab=${currentTab}`}
                    prefetch="intent"
                    onClick={() =>
                      setTimeout(() => revalidator.revalidate(), 0)
                    }
                    className={`${baseClasses} border-b-2`}
                    style={{
                      borderBottomColor: queueColor,
                      color: queueColor,
                    }}
                  >
                    {queueName}
                  </Link>
                );
              }

              return (
                <Link
                  key={queueName}
                  to={`/dashboard/posted/${queueName}?tab=${currentTab}`}
                  prefetch="intent"
                  onClick={() => setTimeout(() => revalidator.revalidate(), 0)}
                  className={`${baseClasses} ${
                    isSelected && colors
                      ? `${colors.border.replace("border-", "border-b-")} ${colors.text}`
                      : unselectedClasses
                  }`}
                >
                  {queueName}
                </Link>
              );
            })}
          </nav>
        </div>
      ) : null}
    </>
  );
}

import { Link, useParams, useRevalidator, useSearchParams } from "@remix-run/react";

import { getQueueColor } from "../queueColors";
import type { QueueType } from "../types";
interface QueueSelectionTabsProps {
  currentTab: string;
  queueTypes: Array<QueueType | string>;
  basePath?: string;
}

export default function QueueSelectionTabs({
  currentTab,
  queueTypes,
  basePath = "/dashboard",
}: QueueSelectionTabsProps) {
  const params = useParams();
  const [searchParams] = useSearchParams();
  const revalidator = useRevalidator();

  // Check if we're on a page that uses query parameters (no queueType route param exists)
  // Pages like /dashboard and /dashboard/drafts don't have $queueType route params
  const useQueryParams = !params["queueType"];

  const baseClasses =
    "whitespace-nowrap border-b-2 px-1 py-2 text-sm font-medium capitalize";
  const unselectedClasses =
    "border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300";

  return (
    <div className="mb-6 border-b border-gray-200 dark:border-gray-700">
      <nav className="-mb-px flex space-x-8" aria-label="Queue Types">
        <Link
          to={`${basePath}?tab=${currentTab}`}
          prefetch="intent"
          onClick={() => setTimeout(() => revalidator.revalidate(), 0)}
          className={`whitespace-nowrap border-b-2 px-1 py-2 text-sm font-medium ${
            (!params["queueType"] && !searchParams.get("queueType")) ||
            searchParams.get("queueType") === "all"
              ? "border-blue-500 text-blue-600 dark:text-blue-400"
              : unselectedClasses
          }`}
        >
          All Queues
        </Link>
        {queueTypes.map((queueType) => {
          const queueName =
            typeof queueType === "string" ? queueType : queueType.name;
          const queueColor =
            typeof queueType === "object" ? queueType.color : null;
          const colors = getQueueColor(queueName, queueColor);
          const isSelected =
            params["queueType"] === queueName ||
            searchParams.get("queueType") === queueName;

          // Use query parameters for pages without route params, route parameters for pages with route params
          const queueTypePath = useQueryParams
            ? `${basePath}?tab=${currentTab}&queueType=${queueName}`
            : `${basePath}/scheduled/${queueName}?tab=${currentTab}`;

          if (isSelected && queueColor) {
            // Use inline styles for custom colors
            return (
              <Link
                key={
                  typeof queueType === "object"
                    ? queueType.id || queueName
                    : queueName
                }
                to={queueTypePath}
                prefetch="intent"
                onClick={() => setTimeout(() => revalidator.revalidate(), 0)}
                className={`${baseClasses} border-b-2`}
                style={{
                  borderBottomColor: queueColor,
                  color: queueColor,
                }}
              >
                {queueName}
              </Link>
            );
          }

          return (
            <Link
              key={
                typeof queueType === "object"
                  ? queueType.id || queueName
                  : queueName
              }
              to={queueTypePath}
              prefetch="intent"
              onClick={() => setTimeout(() => revalidator.revalidate(), 0)}
              className={`${baseClasses} ${
                isSelected && colors
                  ? `${colors.border?.replace("border-", "border-b-") || "border-b-blue-500"} ${colors.text ?? "text-blue-600"}`
                  : unselectedClasses
              }`}
            >
              {queueName}
            </Link>
          );
        })}
      </nav>
    </div>
  );
}

import { getDynamicQueueStyle } from "../queueColors";
import type { QueueType } from "../types";
interface QueueSelectorProps {
  queueTypes: Array<string | QueueType>;
  selectedQueue: string;
  onQueueChange: (queue: string) => void;
  disabled?: boolean;
  className?: string;
}

export function QueueSelector({
  queueTypes,
  selectedQueue,
  onQueueChange,
  disabled = false,
  className = "",
}: QueueSelectorProps) {
  const getQueueTypeId = (queueName: string): string => {
    const selectedQueueType = queueTypes.find((qt) =>
      typeof qt === "string" ? qt === queueName : qt.name === queueName,
    );
    return typeof selectedQueueType === "object"
      ? (selectedQueueType.id ?? "")
      : "";
  };

  return (
    <div className={className}>
      <label
        id="queue-type-label"
        htmlFor="queue-type-selector"
        className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
      >
        Queue Type
      </label>
      <div
        id="queue-type-selector"
        className="flex flex-wrap gap-2"
        role="group"
        aria-labelledby="queue-type-label"
      >
        {/* Unassigned option */}
        <button
          type="button"
          onClick={() => onQueueChange("unassigned")}
          disabled={disabled}
          className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(null, selectedQueue === "unassigned")} disabled:cursor-not-allowed disabled:opacity-50`}
        >
          Unassigned
        </button>

        {/* Queue types */}
        {queueTypes
          .filter((queue) => {
            const queueName = typeof queue === "string" ? queue : queue.name;
            const isEnabled =
              typeof queue === "object" ? queue.isEnabled !== false : true;
            // Exclude "Unassigned" queue type since we have a hard-coded unassigned option
            return isEnabled && queueName !== "Unassigned";
          })
          .map((queue) => {
            const queueName = typeof queue === "string" ? queue : queue.name;
            const queueColor = typeof queue === "object" ? queue.color : null;
            return (
              <button
                key={queueName}
                type="button"
                onClick={() => onQueueChange(queueName ?? "")}
                disabled={disabled}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueue === queueName)} disabled:cursor-not-allowed disabled:opacity-50`}
                style={{
                  backgroundColor: queueColor ?? undefined,
                  borderColor: queueColor ?? undefined,
                }}
              >
                {queueName}
              </button>
            );
          })}
      </div>
      <input type="hidden" name="queueType" value={selectedQueue} />
      <input
        type="hidden"
        name="queueTypeId"
        value={getQueueTypeId(selectedQueue)}
      />
    </div>
  );
}

import type { FetcherWithComponents } from "@remix-run/react";
import { Edit, Trash2 } from "lucide-react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import { Card, CardContent } from "~/components/ui/card";

import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "../types";
import type { QueueType } from "../types";
interface QueueTypeCardProps {
  queueType: QueueType & {
    isDefault?: boolean;
    hashTagPreset?: { id: string; name: string } | null;
  };
  onEdit: (queueType: QueueType) => void;
  isDeletingQueueType: boolean;
  deleteFetcher: FetcherWithComponents<{ success?: boolean; error?: string }>;
}

export function QueueTypeCard({
  queueType,
  onEdit,
  isDeletingQueueType,
  deleteFetcher,
}: QueueTypeCardProps) {
  const handleDelete = () => {
    const formData = new FormData();
    formData.set("_action", "delete_queue_type");
    formData.set("id", queueType.id);
    deleteFetcher.submit(formData, { method: "post" });
  };

  const getScheduleDescription = () => {
    if (!queueType.scheduleConfig) return "No schedule configured";
    if (queueType.scheduleType === "INTERVAL") {
      if (
        isIntervalScheduleConfig(queueType.scheduleConfig) &&
        queueType.scheduleConfig.useGlobalInterval
      ) {
        return "Uses global schedule intervals";
      }
      if (isIntervalScheduleConfig(queueType.scheduleConfig)) {
        return `Every ${String(queueType.scheduleConfig.intervalHours ?? 0)} hours`;
      }
      return "Invalid interval configuration";
    } else {
      if (isFixedSlotsScheduleConfig(queueType.scheduleConfig)) {
        return `Fixed slots: ${queueType.scheduleConfig.slots?.join(", ") || "None"}`;
      }
      return "Invalid slots configuration";
    }
  };

  return (
    <Card className="transition-colors hover:bg-accent/50">
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div
              className="h-4 w-4 rounded-full"
              style={{ backgroundColor: queueType.color ?? "#6B7280" }}
            />
            <div className="space-y-1">
              <div className="flex items-center space-x-2">
                <h4 className="font-medium">{queueType.name}</h4>
                {queueType.isDefault ? (
                  <Badge variant="secondary" className="text-xs">
                    Default
                  </Badge>
                ) : null}
                {!queueType.isEnabled ? (
                  <Badge variant="outline" className="text-xs">
                    Disabled
                  </Badge>
                ) : null}
              </div>
              {queueType.description ? (
                <p className="text-sm text-muted-foreground">
                  {queueType.description}
                </p>
              ) : null}
              <p className="text-xs text-muted-foreground">
                {getScheduleDescription()}
              </p>
              {queueType.hashTagPreset ? (
                <div className="flex items-center space-x-1">
                  <Badge variant="outline" className="text-xs">
                    #{queueType.hashTagPreset.name}
                  </Badge>
                </div>
              ) : null}
            </div>
          </div>
          <div className="flex space-x-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => onEdit(queueType)}
            >
              <Edit className="h-4 w-4" />
            </Button>
            {!queueType.isDefault ? (
              <Button
                variant="destructive"
                size="sm"
                onClick={handleDelete}
                disabled={isDeletingQueueType}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            ) : null}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { useFetcher } from "@remix-run/react";
import { useEffect } from "react";
import { toast } from "react-hot-toast";

import { Button } from "~/components/ui/button";
import { Checkbox } from "~/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "~/components/ui/dialog";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { queueTypeClientSchema } from "~/lib/validation";
import { useZodForm, formDataToFormData } from "~/lib/validation/utils.client";

import type { QueueType } from "../types";
import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "../types";

interface QueueTypeDialogQueueType extends QueueType {
  isDefault?: boolean;
  hashTagPreset?: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  } | null;
  hashTagPresetId?: string;
}

interface QueueTypeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  queueType?: QueueTypeDialogQueueType | null;
  hashTagPresets: Array<{
    id: string;
    name: string;
    tags: string;
    description?: string;
  }>;
}

export function QueueTypeDialog({
  open,
  onOpenChange,
  queueType,
  hashTagPresets,
}: QueueTypeDialogProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
  }
  const fetcher = useFetcher<FetcherData>();
  const isEditing = !!queueType;

  // Initialize form with default values
  const getDefaultValues = () => {
    if (queueType) {
      const scheduleConfig = queueType.scheduleConfig;
      return {
        name: queueType.name ?? "",
        description: queueType.description ?? "",
        color: queueType.color ?? "#3B82F6",
        hashTagPresetId: queueType.hashTagPresetId ?? "none",
        scheduleType: (queueType.scheduleType ?? "INTERVAL"),
        isEnabled: queueType.isEnabled ?? false,
        useGlobalInterval:
          scheduleConfig && isIntervalScheduleConfig(scheduleConfig)
            ? scheduleConfig.useGlobalInterval
            : false,
        intervalHours:
          scheduleConfig && isIntervalScheduleConfig(scheduleConfig)
            ? scheduleConfig.intervalHours?.toString() ?? ""
            : "",
        slots:
          scheduleConfig && isFixedSlotsScheduleConfig(scheduleConfig)
            ? scheduleConfig.slots?.join(", ") ?? ""
            : "",
      };
    }
    return {
      name: "",
      description: "",
      color: "#3B82F6",
      hashTagPresetId: "none",
      scheduleType: "INTERVAL" as const,
      isEnabled: false,
      useGlobalInterval: false,
      intervalHours: "",
      slots: "",
    };
  };

  const form = useZodForm(queueTypeClientSchema, {
    defaultValues: getDefaultValues(),
  });

  const isSubmitting =
    fetcher.state === "submitting" || fetcher.state === "loading";
  const scheduleType = form.watch("scheduleType");
  const hashTagPresetId = form.watch("hashTagPresetId");

  useEffect(() => {
    const fetcherData = fetcher.data;
    if (
      fetcherData &&
      typeof fetcherData === "object" &&
      !Array.isArray(fetcherData)
    ) {
      const data = fetcherData as FetcherData;
      if (typeof data.success === "boolean" && data.success) {
        const action = isEditing ? "updated" : "created";
        toast.success(`Queue type ${action} successfully!`);
      }
      if (typeof data.error === "string") {
        toast.error(data.error);
      }
    }
  }, [fetcher.data, isEditing]);

  const onSubmit = form.handleSubmit((data) => {
    // Transform data for FormData submission
    const submitData: Record<string, unknown> = {
      name: data.name,
      description: data.description ?? "",
      color: data.color,
      hashTagPresetId: data.hashTagPresetId === "none" || !data.hashTagPresetId ? "none" : data.hashTagPresetId,
      scheduleType: data.scheduleType,
      ...(data.isEnabled !== undefined ? { isEnabled: data.isEnabled } : {}),
      ...(data.useGlobalInterval !== undefined ? { useGlobalInterval: data.useGlobalInterval } : {}),
      ...(data.intervalHours ? { intervalHours: data.intervalHours } : {}),
      ...(data.slots ? { slots: data.slots } : {}),
    };

    const formData = formDataToFormData(
      submitData,
      isEditing ? "update_queue_type" : "create_queue_type",
    );

    if (isEditing) {
      formData.set("id", queueType.id);
    }

    fetcher.submit(formData, { method: "post" });
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? "Edit Queue Type" : "Create Queue Type"}
          </DialogTitle>
          <DialogDescription>
            {isEditing
              ? "Update the queue type settings below."
              : "Create a new queue type with custom scheduling."}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={(e) => { e.preventDefault(); void onSubmit(e); }} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">Name</Label>
            <Input
              id="name"
              {...form.register("name")}
              placeholder="e.g., Tech News"
            />
            {form.formState.errors.name ? <p className="text-sm text-destructive">
                {form.formState.errors.name.message}
              </p> : null}
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Input
              id="description"
              {...form.register("description")}
              placeholder="Optional description"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="color">Color</Label>
            <Input
              id="color"
              type="color"
              {...form.register("color")}
              className="h-10 w-full"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="hashTagPresetId">Hashtag Preset (optional)</Label>
            <Select
              value={hashTagPresetId ?? "none"}
              onValueChange={(value) => {
                form.setValue("hashTagPresetId", value);
              }}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a hashtag preset" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">No hashtag preset</SelectItem>
                {hashTagPresets.map((preset) => (
                  <SelectItem key={preset.id} value={preset.id}>
                    {preset.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              Posts in this queue will automatically use the selected hashtag
              preset
            </p>
          </div>

          {isEditing ? (
            <div className="flex items-center space-x-2">
              <Checkbox
                id="isEnabled"
                checked={form.watch("isEnabled")}
                onCheckedChange={(checked) => {
                  form.setValue("isEnabled", checked as boolean);
                }}
              />
              <Label htmlFor="isEnabled" className="text-sm font-normal">
                Enabled
              </Label>
            </div>
          ) : null}

          <div className="space-y-2">
            <Label htmlFor="scheduleType">Schedule Type</Label>
            <Select
              value={scheduleType}
              onValueChange={(value) => {
                form.setValue("scheduleType", value as "INTERVAL" | "FIXED_SLOTS");
              }}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="INTERVAL">Interval-based</SelectItem>
                <SelectItem value="FIXED_SLOTS">Fixed time slots</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {scheduleType === "INTERVAL" ? (
            <div className="space-y-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="useGlobalInterval"
                  checked={form.watch("useGlobalInterval")}
                  onCheckedChange={(checked) => {
                    form.setValue("useGlobalInterval", checked as boolean);
                  }}
                />
                <Label
                  htmlFor="useGlobalInterval"
                  className="text-sm font-normal"
                >
                  Use global schedule intervals
                </Label>
              </div>
              <div className="space-y-2">
                <Label htmlFor="intervalHours">Hours between posts</Label>
                <Input
                  id="intervalHours"
                  type="number"
                  min="1"
                  max="168"
                  {...form.register("intervalHours")}
                />
                {form.formState.errors.intervalHours ? <p className="text-sm text-destructive">
                    {form.formState.errors.intervalHours.message}
                  </p> : null}
              </div>
            </div>
          ) : null}

          {scheduleType === "FIXED_SLOTS" ? (
            <div className="space-y-2">
              <Label htmlFor="slots">
                Time slots (HH:MM format, comma separated)
              </Label>
              <Input
                id="slots"
                {...form.register("slots")}
                placeholder="08:00, 12:00, 18:00"
              />
              {form.formState.errors.slots ? <p className="text-sm text-destructive">
                  {form.formState.errors.slots.message}
                </p> : null}
              <p className="text-xs text-muted-foreground">
                Times are in your selected timezone
              </p>
            </div>
          ) : null}

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? (
                <svg
                  className="-ml-1 mr-2 h-4 w-4 animate-spin text-white"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  ></path>
                </svg>
              ) : null}
              {isSubmitting
                ? isEditing
                  ? "Updating..."
                  : "Creating..."
                : isEditing
                  ? "Update"
                  : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useFetcher } from "@remix-run/react";
import { Plus } from "lucide-react";
import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";

import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";

import type { QueueType } from "../types";

import { QueueTypeCard } from "./QueueTypeCard";
import { QueueTypeDialog } from "./QueueTypeDialog";

interface QueueTypeSettings extends QueueType {
  isDefault: boolean;
  hashTagPreset?: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  } | null;
  hashTagPresetId?: string;
}

interface QueueTypesSettingsProps {
  queueTypes: QueueTypeSettings[];
  hashTagPresets: Array<{
    id: string;
    name: string;
    tags: string;
    description?: string;
  }>;
}

export function QueueTypesSettings({
  queueTypes,
  hashTagPresets,
}: QueueTypesSettingsProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
  }
  const createFetcher = useFetcher<FetcherData>();
  const updateFetcher = useFetcher<FetcherData>();
  const deleteFetcher = useFetcher<FetcherData>();

  const [queueTypesState, setQueueTypesState] = useState(queueTypes || []);
  const [showDialog, setShowDialog] = useState(false);
  const [editingQueueType, setEditingQueueType] = useState<QueueType | null>(
    null,
  );

  const _isCreating = createFetcher.state === "submitting";
  const _isUpdating = updateFetcher.state === "submitting";
  const isDeleting = deleteFetcher.state === "submitting";

  useEffect(() => {
    if (queueTypes) {
      setQueueTypesState(queueTypes);
    }
  }, [queueTypes]);

  // Close dialog on successful submission
  useEffect(() => {
    if (createFetcher.data?.success) {
      setShowDialog(false);
      toast.success("Queue type created successfully!");
    }
    if (createFetcher.data?.error) {
      toast.error(createFetcher.data.error);
    }
  }, [createFetcher.data]);

  useEffect(() => {
    if (updateFetcher.data?.success) {
      setEditingQueueType(null);
      toast.success("Queue type updated successfully!");
    }
    if (updateFetcher.data?.error) {
      toast.error(updateFetcher.data.error);
    }
  }, [updateFetcher.data]);

  useEffect(() => {
    if (deleteFetcher.data?.success) {
      toast.success("Queue type deleted successfully!");
    }
    if (deleteFetcher.data?.error) {
      toast.error(deleteFetcher.data.error);
    }
  }, [deleteFetcher.data]);

  const handleCreateNew = () => {
    setEditingQueueType(null);
    setShowDialog(true);
  };

  const handleEdit = (queueType: QueueType) => {
    setEditingQueueType(queueType);
    setShowDialog(true);
  };

  const handleDialogOpenChange = (open: boolean) => {
    if (!open) {
      setEditingQueueType(null);
    }
    setShowDialog(open);
  };

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Queue Types</CardTitle>
              <CardDescription>
                Manage your posting queues with custom scheduling
              </CardDescription>
            </div>
            <Button onClick={handleCreateNew}>
              <Plus className="mr-2 h-4 w-4" />
              Add Queue Type
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {queueTypesState.length === 0 ? (
            <p className="py-8 text-center text-muted-foreground">
              No queue types found. Create your first queue type to get started.
            </p>
          ) : (
            queueTypesState.map((queueType) => (
              <QueueTypeCard
                key={queueType.id}
                queueType={queueType}
                onEdit={handleEdit}
                isDeletingQueueType={isDeleting}
                deleteFetcher={deleteFetcher}
              />
            ))
          )}
        </CardContent>
      </Card>

      <QueueTypeDialog
        open={showDialog}
        onOpenChange={handleDialogOpenChange}
        queueType={editingQueueType}
        hashTagPresets={hashTagPresets}
      />
    </>
  );
}

