/**
 * Queue Type Handlers for Bulk Posts
 *
 * Handles queue type changes for individual and bulk posts
 */

import { logClientError } from "~/lib/error-handler.client";

import type { BulkPostsHandlerDeps } from "../types";
import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "../types";

import { updateDisplayedHashtags } from "./hashtag.handler";

/**
 * Handle queue type change for a single post
 */
export async function handleQueueTypeChange(
  index: number,
  value: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
  >,
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
  } = deps;
  const updatedPosts = [...posts];
  const postToUpdate = updatedPosts[index];
  if (!postToUpdate) return;
  postToUpdate.queueType = value;

  // Find the queue type object to get its ID
  const selectedQueueType = queueTypes.find(
    (qt) => (typeof qt === "string" ? qt : qt.name) === value,
  );
  const queueTypeId =
    typeof selectedQueueType === "object" ? selectedQueueType.id : null;

  // Auto-calculate schedule time if not unassigned
  if (value !== "unassigned" && queueTypeId) {
    try {
      const requestBody = {
        queueTypeId,
        queueTypeName: value, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as {
          scheduledTime?: string;
        };
        const { scheduledTime } = responseData;
        if (scheduledTime) {
          const postToUpdate = updatedPosts[index];
          if (postToUpdate) {
            postToUpdate.scheduledFor = scheduledTime;
          }
        }
      }
    } catch (error) {
      logClientError(
        error instanceof Error ? error : new Error(String(error)),
        {
          component: "bulkposts",
          action: "handleQueueTypeChange",
          queueType: value,
        },
      );
    }
  } else {
    const postToUpdate = updatedPosts[index];
    if (postToUpdate) {
      postToUpdate.scheduledFor = "";
    }
  }

  setPosts(updatedPosts);

  // Update displayed hashtags if this is the predominant queue type
  const queueTypeCounts: Record<string, number> = {};
  updatedPosts.forEach((post) => {
    queueTypeCounts[post.queueType] =
      (queueTypeCounts[post.queueType] ?? 0) + 1;
  });

  const mostUsedQueueType = Object.keys(queueTypeCounts).reduce(
    (a, b) => ((queueTypeCounts[a] ?? 0) > (queueTypeCounts[b] ?? 0) ? a : b),
    "unassigned",
  );

  if (mostUsedQueueType !== value) {
    await updateDisplayedHashtags(
      mostUsedQueueType,
      queueTypes,
      tags,
      setSelectedQueueType,
      setDisplayedHashtags,
    );
  }
}

/**
 * Handle bulk queue update for all posts
 */
export async function handleBulkQueueUpdate(
  queueType: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
    | "firstItemTimeManuallyChanged"
  >,
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
    firstItemTimeManuallyChanged,
  } = deps;

  if (posts.length === 0) return Promise.resolve();

  // Update displayed hashtags
  await updateDisplayedHashtags(
    queueType,
    queueTypes,
    tags,
    setSelectedQueueType,
    setDisplayedHashtags,
  );

  // Get the base schedule time from the API (this is the next available time after last scheduled post)
  let baseTime: string | null = null;
  if (queueType !== "unassigned") {
    // If first item time was manually changed, use it as base
    const firstPost = posts[0];
    if (firstItemTimeManuallyChanged && firstPost?.scheduledFor) {
      baseTime = firstPost.scheduledFor;
    } else {
      // Original behavior - fetch from API
      const selectedQueueType = queueTypes.find(
        (qt) => (typeof qt === "string" ? qt : qt.name) === queueType,
      );
      const queueTypeId =
        typeof selectedQueueType === "object" ? selectedQueueType.id : null;

      const requestBody = {
        queueTypeId,
        queueTypeName: queueType, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as {
          scheduledTime?: string;
        };
        const { scheduledTime } = responseData;
        baseTime = scheduledTime ?? null;
      }
    }
  }

  // Find the queue type configuration for bulk scheduling
  const queueTypeConfig = queueTypes.find((qt) => qt.name === queueType);

  const updatedPosts = posts.map((post, index) => {
    let scheduledFor = post.scheduledFor;

    // Auto-calculate schedule time if not unassigned
    if (queueType !== "unassigned" && baseTime && queueTypeConfig) {
      // Calculate each post's time based on the base time + offsets
      const baseDate = new Date(baseTime);
      let calculatedTime = "";

      if (queueTypeConfig.scheduleType === "INTERVAL") {
        const config = queueTypeConfig.scheduleConfig;
        let intervalHours = 4; // default

        if (config && isIntervalScheduleConfig(config)) {
          if (config.useGlobalInterval) {
            intervalHours = user?.scheduleInterval?.[0] ?? 4;
          } else {
            intervalHours = config.intervalHours ?? 4;
          }
        }

        // Add interval * index to base time
        const newDate = new Date(baseDate);
        newDate.setHours(newDate.getHours() + index * intervalHours);

        // Format back to datetime-local format
        const year = newDate.getFullYear();
        const month = String(newDate.getMonth() + 1).padStart(2, "0");
        const day = String(newDate.getDate()).padStart(2, "0");
        const hours = String(newDate.getHours()).padStart(2, "0");
        const minutes = String(newDate.getMinutes()).padStart(2, "0");

        calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
      } else if (queueTypeConfig.scheduleType === "FIXED_SLOTS") {
        const config = queueTypeConfig.scheduleConfig;
        const slots =
          config && isFixedSlotsScheduleConfig(config) ? config.slots : [];

        if (slots.length > 0) {
          // Sort slots to ensure consistent ordering
          const sortedSlots = slots
            .map((slot) => {
              const parts = slot.split(":");
              const hours = parts[0] ? Number(parts[0]) : 0;
              const minutes = parts[1] ? Number(parts[1]) : 0;
              return {
                slot,
                hours,
                minutes,
                totalMinutes: hours * 60 + minutes,
              };
            })
            .sort((a, b) => a.totalMinutes - b.totalMinutes);

          // Get the current slot index based on the base time
          const baseHours = baseDate.getHours();
          const baseMinutes = baseDate.getMinutes();
          const baseTotalMinutes = baseHours * 60 + baseMinutes;

          let currentSlotIndex = 0;
          for (let i = 0; i < sortedSlots.length; i++) {
            const slot = sortedSlots[i];
            if (slot && slot.totalMinutes >= baseTotalMinutes) {
              currentSlotIndex = i;
              break;
            }
          }

          // Calculate which slot this post should use
          const targetSlotIndex =
            (currentSlotIndex + index) % sortedSlots.length;
          const targetSlot = sortedSlots[targetSlotIndex];
          if (!targetSlot) {
            calculatedTime = post.scheduledFor ?? "";
          } else {
            // Calculate how many days to add
            const daysToAdd = Math.floor(
              (currentSlotIndex + index) / sortedSlots.length,
            );

            // Set the time to the target slot
            const newDate = new Date(baseDate);
            newDate.setHours(targetSlot.hours, targetSlot.minutes, 0, 0);
            newDate.setDate(newDate.getDate() + daysToAdd);

            // Format back to datetime-local format
            const year = newDate.getFullYear();
            const month = String(newDate.getMonth() + 1).padStart(2, "0");
            const day = String(newDate.getDate()).padStart(2, "0");
            const hours = String(newDate.getHours()).padStart(2, "0");
            const minutes = String(newDate.getMinutes()).padStart(2, "0");

            calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
          }
        }
      }

      if (calculatedTime) {
        scheduledFor = calculatedTime;
      }
    } else if (queueType === "unassigned") {
      scheduledFor = "";
    }

    return {
      ...post,
      queueType,
      scheduledFor,
    };
  });

  setPosts(updatedPosts);
}

/**
 * TanStack Query hooks for calendar
 * Provides caching and background refetching for calendar page
 */

import { useFetcher, useLoaderData , useParams } from "@remix-run/react";
import { useQuery } from "@tanstack/react-query";

import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  calendarLoaderDataSchema,
  type CalendarLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";
import { validateUserData } from "~/lib/validation/user-data";

import { combineContent } from "../combined";
import type { PostDTO, LongFormPostDTO } from "../dtos";
import {
  fromPostDTOArray,
  fromLongFormPostDTOArray,
} from "../dtos";
import type {
  PostData,
  LongFormPostData,
  CombinedContent as _CombinedContent,
  QueueType,
  UserData,
} from "../types";
import { convertJsonValueToScheduleConfig } from "../types";


/**
 * Query key factory for calendar
 */
export const calendarKeys = {
  all: ["calendar"] as const,
  lists: () => [...calendarKeys.all, "list"] as const,
  list: (queueType?: string) =>
    [...calendarKeys.lists(), queueType] as const,
};

// CalendarLoaderData is now exported from schemas

/**
 * Hook to fetch calendar data with TanStack Query
 */
export function useCalendarQuery() {
  const params = useParams();
  const queueType = params["queueType"] ?? "all";

  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    calendarLoaderDataSchema,
  );

  return useQuery({
    queryKey: calendarKeys.list(queueType),
    queryFn: async () => {
      const url = `/dashboard/calendar${queueType !== "all" ? `/${queueType}` : ""}`;
      fetcher.load(url);

      return new Promise<CalendarLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                calendarLoaderDataSchema,
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData ?? undefined,
    staleTime: 30 * 1000, // 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false,
  });
}

/**
 * Hook to get processed calendar data from query
 */
export function useCalendarData() {
  const { data, isLoading, error } = useCalendarQuery();

  if (!data) {
    return {
      scheduledPosts: [] as PostData[],
      scheduledLongFormPosts: [] as LongFormPostData[],
      pastPosts: [] as PostData[],
      pastLongFormPosts: [] as LongFormPostData[],
      allContent: [] as Array<{ type: "post" | "longform"; [key: string]: unknown }>,
      user: null as UserData | null,
      queueTypes: [] as QueueType[],
      selectedQueueType: "all",
      isLoading,
      error,
    };
  }

  const typedData = data;
  const scheduledPostsRaw =
    "scheduledPosts" in typedData && Array.isArray(typedData.scheduledPosts)
      ? typedData.scheduledPosts
      : [];
  const scheduledLongFormPostsRaw =
    "scheduledLongFormPosts" in typedData &&
    Array.isArray(typedData.scheduledLongFormPosts)
      ? typedData.scheduledLongFormPosts
      : [];
  const pastPostsRaw =
    "pastPosts" in typedData && Array.isArray(typedData.pastPosts)
      ? typedData.pastPosts
      : [];
  const pastLongFormPostsRaw =
    "pastLongFormPosts" in typedData &&
    Array.isArray(typedData.pastLongFormPosts)
      ? typedData.pastLongFormPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const user: UserData | null = userRaw ? validateUserData(userRaw) : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const selectedQueueTypeRaw =
    "selectedQueueType" in typedData ? typedData.selectedQueueType : "all";

  const scheduledPosts: PostData[] = Array.isArray(scheduledPostsRaw)
    ? fromPostDTOArray(scheduledPostsRaw as PostDTO[])
    : [];
  const scheduledLongFormPosts: LongFormPostData[] = Array.isArray(
    scheduledLongFormPostsRaw,
  )
    ? fromLongFormPostDTOArray(scheduledLongFormPostsRaw as LongFormPostDTO[])
    : [];
  const pastPosts: PostData[] = Array.isArray(pastPostsRaw)
    ? fromPostDTOArray(pastPostsRaw as PostDTO[])
    : [];
  const pastLongFormPosts: LongFormPostData[] = Array.isArray(
    pastLongFormPostsRaw,
  )
    ? fromLongFormPostDTOArray(pastLongFormPostsRaw as LongFormPostDTO[])
    : [];

  // Reconstruct allContent on client from deserialized posts
  const allContent = combineContent(
    [...scheduledPosts, ...pastPosts],
    [...scheduledLongFormPosts, ...pastLongFormPosts],
    "scheduledFor",
    "asc",
  );

  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw
        .map((qt: unknown) => {
          if (qt && typeof qt === "object" && "id" in qt && "name" in qt) {
            const q = qt as {
              id: string;
              name: string;
              color?: string | null;
              scheduleType?: string;
              scheduleConfig?: unknown;
              isEnabled?: boolean;
              userId?: string;
            };
            const queueType: QueueType = {
              id: q.id,
              name: q.name,
              color: q.color,
              description: undefined,
              scheduleType: q.scheduleType as
                | "INTERVAL"
                | "FIXED_SLOTS"
                | undefined,
              scheduleConfig: convertJsonValueToScheduleConfig(q.scheduleConfig),
              isEnabled: q.isEnabled,
              userId: q.userId,
            };
            return queueType;
          }
          return null;
        })
        .filter((qt): qt is QueueType => qt !== null)
    : [];
  const selectedQueueType =
    typeof selectedQueueTypeRaw === "string" ? selectedQueueTypeRaw : "all";

  return {
    scheduledPosts,
    scheduledLongFormPosts,
    pastPosts,
    pastLongFormPosts,
    allContent,
    user,
    queueTypes,
    selectedQueueType,
    isLoading,
    error,
  };
}

