 * Query key factory for dashboard data
 */
export const dashboardKeys = {
  all: ["dashboard"] as const,
  lists: () => [...dashboardKeys.all, "list"] as const,
  list: (queueType?: string, tab?: string) =>
    [...dashboardKeys.lists(), queueType, tab] as const,
};

// DashboardLoaderData is now exported from schemas

/**
 * Hook to fetch dashboard data with TanStack Query
 */
export function useDashboardQuery() {
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";

  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    dashboardLoaderDataSchema,
  );

  return useQuery({
    queryKey: dashboardKeys.list(queueType, currentTab),
    queryFn: async () => {
      const url = `/dashboard${queueType !== "all" ? `/${queueType}` : ""}?tab=${currentTab}`;
      fetcher.load(url);

      return new Promise<DashboardLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                dashboardLoaderDataSchema,
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData ?? undefined,
    staleTime: 30 * 1000, // 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false,
  });
}

/**
 * Hook to get processed dashboard data from query
 */
export function useDashboardData() {
  const { data, isLoading, error } = useDashboardQuery();

  if (!data) {
    return {
      scheduledPosts: [] as PostData[],
      longformPosts: [] as LongFormPostData[],
      allContent: [] as CombinedContent[],
      user: null as UserData | null,
      queueTypes: [] as QueueType[],
      hashTagPresets: [] as HashTagPreset[],
      postStatistics: undefined,
      isLoading,
      error,
    };
  }

  const typedData = data;
  const scheduledPostsRaw =
    "scheduledPosts" in typedData && Array.isArray(typedData.scheduledPosts)
      ? typedData.scheduledPosts
      : [];
  const longformPostsRaw =
    "longformPosts" in typedData && Array.isArray(typedData.longformPosts)
      ? typedData.longformPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const hashTagPresetsRaw =
    "hashTagPresets" in typedData && Array.isArray(typedData.hashTagPresets)
      ? typedData.hashTagPresets
      : [];
  const postStatisticsRaw = "postStatistics" in typedData ? typedData.postStatistics : undefined;

  const scheduledPosts: PostData[] = Array.isArray(scheduledPostsRaw)
    ? fromPostDTOArray(scheduledPostsRaw as PostDTO[])
    : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw)
    ? fromLongFormPostDTOArray(longformPostsRaw as LongFormPostDTO[])
    : [];
  // Reconstruct allContent on client from deserialized scheduledPosts/longformPosts
  const allContent: CombinedContent[] = combineContent(
    scheduledPosts,
    longformPosts,
    "scheduledFor",
    "asc",
  );
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw.map((qt: unknown) => {
        if (
          qt &&
          typeof qt === "object" &&
          qt !== null &&
          "id" in qt &&
          "name" in qt
        ) {
          const q = qt as {
            id?: unknown;
            name?: unknown;
            color?: unknown;
            scheduleType?: unknown;
            scheduleConfig?: unknown;
            isEnabled?: unknown;
            userId?: unknown;
          };
          const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
          const name =
            typeof q.name === "string" ? q.name : String(q.name ?? "");
          const color =
            q.color !== null && q.color !== undefined
              ? typeof q.color === "string"
                ? q.color
                : String(q.color)
              : null;
          const scheduleType =
            typeof q.scheduleType === "string" &&
            (q.scheduleType === "INTERVAL" || q.scheduleType === "FIXED_SLOTS")
              ? q.scheduleType
              : undefined;
          const scheduleConfig = convertJsonValueToScheduleConfig(
            q.scheduleConfig,
          );
          const isEnabled =
            typeof q.isEnabled === "boolean"
              ? q.isEnabled
              : q.isEnabled !== false;
          const userId = typeof q.userId === "string" ? q.userId : "";
          const queueType: QueueType = {
            id,
            name,
            color,
            description: undefined,
            scheduleType,
            scheduleConfig,
            isEnabled,
            userId,
          };
          return queueType;
        }
        return null;
      })
      .filter((qt): qt is QueueType => qt !== null)
    : [];
  // Validate HashTagPreset array with Zod schema
  const hashTagPresets: HashTagPreset[] = validateHashTagPresets(hashTagPresetsRaw);

  return {
    scheduledPosts,
    longformPosts,
    allContent,
    user: userRaw,
    queueTypes,
    hashTagPresets,
    postStatistics: postStatisticsRaw,
    isLoading,
    error,
  };
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useMemo } from "react";

import type { PostData, LongFormPostData } from "../types";
interface UseDashboardStateProps {
  scheduledPosts: PostData[];
  userTimezone?: string | null;
}

/**
 * Custom hook for managing dashboard state and operations
 */
export function useDashboardState({
  scheduledPosts,
  userTimezone,
}: UseDashboardStateProps) {
  const [sortConfig, setSortConfig] = useState({
    key: "scheduledFor",
    direction: "asc" as "asc" | "desc",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [countdowns, setCountdowns] = useState<Record<string, string>>({});
  const [selectedPost, setSelectedPost] = useState<PostData | null>(null);
  const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
  const [selectedMedia, setSelectedMedia] = useState<string | null>(null);
  const [isMediaModalOpen, setIsMediaModalOpen] = useState(false);

  const [selectedLongFormPost, setSelectedLongFormPost] =
    useState<LongFormPostData | null>(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [postToEdit, setPostToEdit] = useState<
    PostData | LongFormPostData | null
  >(null);
  const [postToReschedule, setPostToReschedule] = useState<
    PostData | LongFormPostData | null
  >(null);
  interface FetcherData {
    success?: boolean;
  }
  const bulkDeleteFetcher = useFetcher<FetcherData>();

  // Memoize post IDs to avoid infinite loops when scheduledPosts array reference changes
  const postIds = useMemo(
    () => scheduledPosts.map((post) => post.id).join(","),
    [scheduledPosts],
  );

  // Update countdowns
  useEffect(() => {
    const updateCountdowns = () => {
      const tz = userTimezone ?? "UTC";
      const now = new Date(
        new Date().toLocaleString("en-US", { timeZone: tz }),
      ).getTime();
      const newCountdowns: Record<string, string> = {};

      scheduledPosts.forEach((post) => {
        const scheduledFor = post.scheduledFor;
        const scheduledForValue =
          typeof scheduledFor === "string" || typeof scheduledFor === "number"
            ? scheduledFor
            : "0";
        const utcTime = parseInt(String(scheduledForValue ?? 0)) * 1000;
        const userTime = new Date(utcTime).toLocaleString("en-US", {
          timeZone: tz,
        });
        const scheduledTime = new Date(userTime).getTime();
        const distance = scheduledTime - now;

        if (distance > 0) {
          const days = Math.floor(distance / (1000 * 60 * 60 * 24));
          const hours = Math.floor(
            (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
          );
          const minutes = Math.floor(
            (distance % (1000 * 60 * 60)) / (1000 * 60),
          );
          newCountdowns[post.id] = `${days}d ${hours}h ${minutes}m`;
        } else {
          newCountdowns[post.id] = "Due now";
        }
      });

      setCountdowns((prev) => {
        // Only update if countdowns actually changed to prevent unnecessary re-renders
        const hasChanged =
          Object.keys(newCountdowns).some(
            (id) => prev[id] !== newCountdowns[id],
          ) ||
          Object.keys(prev).length !== Object.keys(newCountdowns).length;

        return hasChanged ? newCountdowns : prev;
      });
    };

    updateCountdowns();
    const timer = setInterval(updateCountdowns, 60000);
    return () => clearInterval(timer);
    // Use postIds instead of scheduledPosts to avoid infinite loops
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependencies are intentionally limited to avoid infinite loops
  }, [postIds, userTimezone]);

  // Clear selected posts after bulk delete
  useEffect(() => {
    const dataRaw = bulkDeleteFetcher.data;
    const data =
      dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
        ? (dataRaw as { success?: unknown })
        : null;
    if (data && typeof data.success === "boolean" && data.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  // Sort posts
  const sortedPosts = [...scheduledPosts].sort((a, b) => {
    if (sortConfig.key === "scheduledFor") {
      const aScheduled = a.scheduledFor;
      const bScheduled = b.scheduledFor;
      const aValue =
        typeof aScheduled === "string" || typeof aScheduled === "number"
          ? aScheduled
          : "0";
      const bValue =
        typeof bScheduled === "string" || typeof bScheduled === "number"
          ? bScheduled
          : "0";
      const dateA = parseInt(String(aValue)) * 1000;
      const dateB = parseInt(String(bValue)) * 1000;
      return sortConfig.direction === "asc" ? dateA - dateB : dateB - dateA;
    }
    // For other keys, access safely
    const key = sortConfig.key as keyof PostData;
    const aValue = a[key] as string | number | undefined;
    const bValue = b[key] as string | number | undefined;
    if (aValue === undefined || bValue === undefined) return 0;
    if (aValue < bValue) return sortConfig.direction === "asc" ? -1 : 1;
    if (aValue > bValue) return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  // Filter posts
  const filteredPosts = sortedPosts.filter((post) =>
    post.caption?.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDelete");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  const handleMediaClick = (mediaSrc: string) => {
    setSelectedMedia(mediaSrc);
    setIsMediaModalOpen(true);
  };

  const handleCloseMediaModal = () => {
    setIsMediaModalOpen(false);
    setSelectedMedia(null);
  };

  const handleEditPost = (post: PostData | LongFormPostData) => {
    setPostToEdit(post);
    setShowEditModal(true);
  };

  const handleReschedulePost = (post: PostData | LongFormPostData) => {
    setPostToReschedule(post);
    setShowRescheduleModal(true);
  };

  const handleCloseEditModal = () => {
    setShowEditModal(false);
    setPostToEdit(null);
  };

  const handleCloseRescheduleModal = () => {
    setShowRescheduleModal(false);
    setPostToReschedule(null);
  };

  const handleModalSuccess = () => {
    window.location.reload();
  };

  return {
    sortConfig,
    searchTerm,
    countdowns,
    selectedPost,
    selectedPosts,
    selectedMedia,
    isMediaModalOpen,
    selectedLongFormPost,
    showEditModal,
    showRescheduleModal,
    postToEdit,
    postToReschedule,
    filteredPosts,
    bulkDeleteFetcher,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    setSelectedLongFormPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleMediaClick,
    handleCloseMediaModal,
    handleEditPost,
    handleReschedulePost,
    handleCloseEditModal,
    handleCloseRescheduleModal,
    handleModalSuccess,
  };
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";

import { useOptionalUser } from "~/lib/remix-utils";
import { draftEditClientSchema } from "~/lib/validation/schemas/posts.client.schemas";
import { useZodForm } from "~/lib/validation/utils.client";

import { signDraftForScheduling } from "../services/draft-sign.server";
import type { UserData, HashTagPreset, PostData } from "../types";

interface Post {
  content?: string | null;
  caption?: string | null;
  queueType?: { name: string } | null;
  hashTagPresetId?: string | null;
  fileUrl?: string[] | null;
}

interface UseDraftEditStateProps {
  post: Post;
  user: UserData;
  hashTagPresets: HashTagPreset[];
}

/**
 * Custom hook for managing draft edit state and operations
 */
export function useDraftEditState({
  post,
  user,
  hashTagPresets,
}: UseDraftEditStateProps) {
  const fetcher = useFetcher();
  const currentUser = useOptionalUser();

  // Initialize form with React Hook Form
  const form = useZodForm(draftEditClientSchema, {
    defaultValues: {
      content: post.content ?? "",
      selectedQueue:
        typeof post.queueType === "object" && post.queueType?.name
          ? post.queueType.name
          : typeof post.queueType === "string"
            ? post.queueType
            : "unassigned",
      scheduledFor: "",
      useHashtagPresets: !!post.hashTagPresetId,
      hashTagPresetId: post.hashTagPresetId ?? null,
    },
  });

  // Watch form values
  const content = form.watch("content") ?? "";
  const selectedQueue = form.watch("selectedQueue") ?? "unassigned";
  const scheduledFor = form.watch("scheduledFor") ?? "";
  const useHashtagPresets = form.watch("useHashtagPresets") ?? false;
  const selectedHashtagPresetId = form.watch("hashTagPresetId") ?? null;

  // Non-form state
  const [caption] = useState(post.caption ?? "");
  const [showResumeModal, setShowResumeModal] = useState(false);
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = fetcher.state !== "idle";

  const handleResumeClick = () => {
    if (!scheduledFor) {
      alert("Please set a schedule time first");
      return;
    }
    setShowResumeModal(true);
  };

  const calculateQueueScheduleTime = useCallback(
    async (queueTypeName: string) => {
      if (queueTypeName === "unassigned") {
        form.setValue("scheduledFor", "");
        return;
      }

      try {
        const response = await fetch("/api/queue-schedule", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            queueTypeName,
            userId: currentUser?.id,
          }),
        });

        if (response.ok) {
          const data = (await response.json()) as { scheduledTime?: string };
          const scheduledTime = data.scheduledTime;
          if (scheduledTime) {
            form.setValue("scheduledFor", scheduledTime);
          }
        }
      } catch (error) {
        console.error("Error calculating schedule time:", error);
      }
    },
    [currentUser?.id, form],
  );

  const handleSignAndResume = async () => {
    try {
      // Convert currentUser (User | null | undefined) to UserData | null
      const currentUserData: UserData | null = currentUser
        ? {
            id: currentUser.id,
            npub: currentUser.npub,
            timezone: currentUser.timezone ?? null,
            scheduleInterval: currentUser.scheduleInterval
              ? currentUser.scheduleInterval
                  .map(Number)
                  .filter((n) => !isNaN(n))
              : undefined,
            userRelays: currentUser.userRelays,
            showHashTagsinPosts: currentUser.showHashTagsinPosts,
            isEnabled: currentUser.isEnabled,
          }
        : null;

      const result = await signDraftForScheduling({
        content,
        caption,
        scheduledFor,
        selectedQueue,
        useHashtagPresets,
        selectedHashtags,
        user,
        currentUser: currentUserData,
        post: post as unknown as PostData,
      });

      const formData = new FormData();
      formData.append("_action", "resume");
      formData.append("content", content);
      formData.append("caption", caption || content);
      formData.append("queueType", selectedQueue);
      formData.append("scheduledFor", result.scheduledForUnix.toString());
      formData.append("signedEvent", JSON.stringify(result.signedEvent));
      formData.append("nostrEvent", JSON.stringify(result.nostrEvent));

      // Add hashtag preset data
      if (useHashtagPresets && selectedHashtagPresetId) {
        formData.append("hashTagPresetId", selectedHashtagPresetId);
        formData.append("useHashtagPresets", "on");
      }

      fetcher.submit(formData, { method: "post" });
      setShowResumeModal(false);
    } catch (error) {
      console.error("Error signing event:", error);
      alert("Error signing the post. Please try again.");
    }
  };

  const handleHashtagPresetSelect = (presetId: string, hashtags: string) => {
    form.setValue("hashTagPresetId", presetId);
    form.setValue("useHashtagPresets", true);
    setSelectedHashtags(hashtags);
  };

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    } else {
      form.setValue("scheduledFor", "");
    }
  }, [selectedQueue, calculateQueueScheduleTime, form]);

  // Initialize hashtag preset data on component mount
  useEffect(() => {
    if (post.hashTagPresetId && hashTagPresets.length > 0) {
      const preset = hashTagPresets.find((p) => p.id === post.hashTagPresetId);
      if (preset) {
        setSelectedHashtags(preset.tags ?? "");
      }
    }
  }, [post.hashTagPresetId, hashTagPresets]);

  // Provide setter wrappers for backward compatibility
  const setContent = (value: string) => form.setValue("content", value);
  const setSelectedQueue = (value: string) => form.setValue("selectedQueue", value);
  const setScheduledFor = (value: string) => form.setValue("scheduledFor", value);
  const setUseHashtagPresets = (value: boolean) => form.setValue("useHashtagPresets", value);

  return {
    content,
    selectedQueue,
    scheduledFor,
    showResumeModal,
    useHashtagPresets,
    selectedHashtagPresetId,
    isSubmitting,
    fetcher,
    form, // Expose form for direct access if needed
    setContent,
    setSelectedQueue,
    setScheduledFor,
    setShowResumeModal,
    setUseHashtagPresets,
    handleResumeClick,
    handleSignAndResume,
    handleHashtagPresetSelect,
  };
}

/**
 * TanStack Query hooks for drafts
 * Provides caching and background refetching for drafts page
 */

import { useFetcher, useLoaderData , useParams } from "@remix-run/react";
import { useQuery } from "@tanstack/react-query";

import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  draftsLoaderDataSchema,
  type DraftsLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";

import { combineContent } from "../combined";
import type { PostDTO, LongFormPostDTO } from "../dtos";
import {
  fromPostDTOArray,
  fromLongFormPostDTOArray,
} from "../dtos";
import type {
  PostData,
  LongFormPostData,
  CombinedContent,
  QueueType,
  UserData,
} from "../types";
import { convertJsonValueToScheduleConfig } from "../types";

/**
 * Query key factory for drafts
 */
export const draftsKeys = {
  all: ["drafts"] as const,
  lists: () => [...draftsKeys.all, "list"] as const,
  list: (queueType?: string) =>
    [...draftsKeys.lists(), queueType] as const,
};

// DraftsLoaderData is now exported from schemas

/**
 * Hook to fetch drafts data with TanStack Query
 */
export function useDraftsQuery() {
  const params = useParams();
  const queueType = params["queueType"] ?? "all";

  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    draftsLoaderDataSchema,
  );

  return useQuery({
    queryKey: draftsKeys.list(queueType),
    queryFn: async () => {
      const url = `/dashboard/drafts${queueType !== "all" ? `/${queueType}` : ""}`;
      fetcher.load(url);

      return new Promise<DraftsLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                draftsLoaderDataSchema,
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData ?? undefined,
    staleTime: 30 * 1000, // 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false,
  });
}

/**
 * Hook to get processed drafts data from query
 */
export function useDraftsData() {
  const { data, isLoading, error } = useDraftsQuery();

  if (!data) {
    return {
      posts: [] as PostData[],
      longformPosts: [] as LongFormPostData[],
      allContent: [] as CombinedContent[],
      user: null as UserData | null,
      queueTypes: [] as QueueType[],
      selectedQueueType: "all",
      isLoading,
      error,
    };
  }

  const typedData = data;
  const postsRaw =
    "posts" in typedData && Array.isArray(typedData.posts) ? typedData.posts : [];
  const longformPostsRaw =
    "longformPosts" in typedData && Array.isArray(typedData.longformPosts)
      ? typedData.longformPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const selectedQueueTypeRaw = "selectedQueueType" in typedData ? typedData.selectedQueueType : "all";

  const posts: PostData[] = Array.isArray(postsRaw)
    ? fromPostDTOArray(postsRaw as PostDTO[])
    : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw)
    ? fromLongFormPostDTOArray(longformPostsRaw as LongFormPostDTO[])
    : [];
  // Reconstruct allContent on client from deserialized posts/longformPosts
  const allContent: CombinedContent[] = combineContent(
    posts,
    longformPosts,
    "createdAt",
    "desc",
  );
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw
        .map((qt: unknown) => {
          if (
            qt &&
            typeof qt === "object" &&
            qt !== null &&
            "id" in qt &&
            "name" in qt
          ) {
            const q = qt as {
              id?: unknown;
              name?: unknown;
              color?: unknown;
              scheduleType?: unknown;
              scheduleConfig?: unknown;
              isEnabled?: unknown;
              userId?: unknown;
            };
            const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
            const name =
              typeof q.name === "string" ? q.name : String(q.name ?? "");
            const color =
              q.color !== null && q.color !== undefined
                ? typeof q.color === "string"
                  ? q.color
                  : String(q.color)
                : null;
            const scheduleType =
              typeof q.scheduleType === "string" &&
              (q.scheduleType === "INTERVAL" || q.scheduleType === "FIXED_SLOTS")
                ? q.scheduleType
                : undefined;
            const scheduleConfig = convertJsonValueToScheduleConfig(
              q.scheduleConfig,
            );
            const isEnabled =
              typeof q.isEnabled === "boolean"
                ? q.isEnabled
                : q.isEnabled !== false;
            const userId = typeof q.userId === "string" ? q.userId : "";
            const queueType: QueueType = {
              id,
              name,
              color,
              description: undefined,
              scheduleType,
              scheduleConfig,
              isEnabled,
              userId,
            };
            return queueType;
          }
          return null;
        })
        .filter((qt): qt is QueueType => qt !== null)
    : [];
  const selectedQueueType = typeof selectedQueueTypeRaw === "string" ? selectedQueueTypeRaw : "all";

  return {
    posts,
    longformPosts,
    allContent,
    user: userRaw,
    queueTypes,
    selectedQueueType,
    isLoading,
    error,
  };
}

import { useState, useEffect, useRef } from "react";
import { toast } from "react-hot-toast";

import {
  convertEditorJSToMarkdown,
  convertMarkdownToEditorJS,
} from "~/features/posts/utils/editorjs-conversion";
import { resizeImage } from "~/features/upload/image-resize";
import { logClientError } from "~/lib/error-handler.client";
import {
  editPostClientSchema,
  editLongformPostClientSchema,
} from "~/lib/validation";
import { useZodForm } from "~/lib/validation/utils.client";

import type {
  PostData,
  LongFormPostData,
  UserData,
  HashTagPreset,
} from "../types";
import type {
  EditorJSInstance as EditorJSInstanceType,
  EditorJSAPI,
} from "../types/editorjs.types";

interface UseEditPostModalProps {
  post: PostData | LongFormPostData;
  user?: UserData;
  hashTagPresets?: HashTagPreset[];
  isLongform: boolean;
}

export function useEditPostModal({
  post,
  user,
  hashTagPresets: _hashTagPresets = [],
  isLongform,
}: UseEditPostModalProps) {
  // Get initial values for form
  const getInitialValues = () => {
    if (isLongform && post && typeof post === "object" && "title" in post) {
      const postTitle = typeof post.title === "string" ? post.title : "";
      const postSummary =
        typeof post.summary === "string" ? post.summary : "";
      const postImage = typeof post.image === "string" ? post.image : "";
      const publishedAt =
        post && typeof post === "object" && "publishedAt" in post
          ? post.publishedAt
          : null;
      const scheduledForStr = publishedAt
        ? new Date(publishedAt).toISOString().slice(0, 16)
        : "";
      const queueType =
        post &&
        typeof post === "object" &&
        "queueType" in post &&
        post.queueType &&
        typeof post.queueType === "object" &&
        "name" in post.queueType &&
        typeof post.queueType.name === "string"
          ? post.queueType.name
          : "";

      const hashTagPresetId =
        post &&
        typeof post === "object" &&
        "hashTagPresetId" in post &&
        typeof post.hashTagPresetId === "string"
          ? post.hashTagPresetId
          : undefined;

      return {
        title: postTitle,
        summary: postSummary,
        content: "",
        image: postImage,
        scheduledFor: scheduledForStr,
        queueType,
        useHashtagPresets: !!hashTagPresetId,
        hashTagPresetId,
        customTags: "",
      };
    } else {
      const postCaption =
        post &&
        typeof post === "object" &&
        "caption" in post &&
        typeof post.caption === "string"
          ? post.caption
          : "";
      const queueTypeId =
        post &&
        typeof post === "object" &&
        "queueType" in post &&
        post.queueType &&
        typeof post.queueType === "object" &&
        "id" in post.queueType &&
        typeof post.queueType.id === "string"
          ? post.queueType.id
          : "";
      const scheduledForValue =
        post && typeof post === "object" && "scheduledFor" in post
          ? (post as { scheduledFor?: unknown }).scheduledFor
          : null;
      const scheduledForStr =
        scheduledForValue && typeof scheduledForValue === "string"
          ? new Date(parseInt(scheduledForValue, 10) * 1000)
              .toISOString()
              .slice(0, 16)
          : "";

      const hashTagPresetId =
        post &&
        typeof post === "object" &&
        "hashTagPresetId" in post &&
        typeof post.hashTagPresetId === "string"
          ? post.hashTagPresetId
          : undefined;

      const existingHashtags =
        post &&
        typeof post === "object" &&
        "hashtags" in post &&
        typeof post.hashtags === "string"
          ? post.hashtags
          : "";

      return {
        caption: postCaption,
        queueType: queueTypeId,
        scheduledFor: scheduledForStr,
        isRecyclable: false,
        useHashtagPresets: !!hashTagPresetId,
        hashTagPresetId,
        manualHashtags: existingHashtags,
      };
    }
  };

  // Initialize form with React Hook Form
  const schema = isLongform
    ? editLongformPostClientSchema
    : editPostClientSchema;
  const form = useZodForm(schema, {
    defaultValues: getInitialValues(),
  });

  // Image/media handling (not part of form schema)
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const [newFiles, setNewFiles] = useState<File[]>([]);
  const [isUploadingImages, setIsUploadingImages] = useState(false);

  // Hashtag preset tags (derived state, not form field)
  const [selectedHashtagPresetTags, setSelectedHashtagPresetTags] =
    useState("");

  // EditorJS state for longform content
  const editorRef = useRef<EditorJSInstanceType | null>(null);
  const editorInitialized = useRef(false);
  const [editorReady, setEditorReady] = useState(false);

  // Load initial content for longform posts
  useEffect(() => {
    if (isLongform && post && typeof post === "object" && "content" in post) {
      const postContent =
        typeof post.content === "string" ? post.content : "";
      if (postContent) {
        form.setValue("content", postContent);
      }
    }
  }, [isLongform, post, form]);

  // Initialize EditorJS for longform posts
  useEffect(() => {
    if (!isLongform) return;

    const loadEditor = async () => {
      if (
        typeof window !== "undefined" &&
        !editorRef.current &&
        !editorInitialized.current
      ) {
        editorInitialized.current = true;

        try {
          const EditorJS = (await import("@editorjs/editorjs")).default;

          const toolsConfig = {
            header: {
              class: (await import("@editorjs/header")).default,
              config: {
                placeholder: "Enter a header",
                levels: [2, 3, 4],
                defaultLevel: 3,
              },
            },
            list: {
              class: (await import("@editorjs/list")).default,
              inlineToolbar: true,
            },
            quote: {
              class: (await import("@editorjs/quote")).default,
              inlineToolbar: true,
              config: {
                quotePlaceholder: "Enter a quote",
                captionPlaceholder: "Quote's author",
              },
            },
            code: {
              class: (await import("@editorjs/code")).default,
              config: {
                placeholder: "Enter code here...",
              },
            },
            inlineCode: {
              class: (await import("@editorjs/inline-code")).default,
            },
            linkTool: {
              class: (await import("@editorjs/link")).default,
              config: {
                endpoint: "/api/link-preview",
              },
            },
            embed: {
              class: (await import("@editorjs/embed")).default,
              config: {
                services: {
                  youtube: true,
                  twitter: true,
                },
              },
            },
            image: {
              class: (await import("@editorjs/image")).default,
              config: {
                buttonContent: "Select Image",
                captionPlaceholder: "",
                withBorder: false,
                withBackground: false,
                stretched: false,
                uploader: {
                  uploadByFile: async (file: File) => {
                    try {
                      const formData = new FormData();
                      formData.append("image", file);

                      const response = await fetch(
                        "/api/upload-editorjs-image",
                        {
                          method: "POST",
                          body: formData,
                        },
                      );

                      if (!response.ok) {
                        throw new Error(`Server error: ${response.status}`);
                      }

                      const resultRaw: unknown = await response.json();
                      const result =
                        resultRaw &&
                        typeof resultRaw === "object" &&
                        !Array.isArray(resultRaw)
                          ? (resultRaw as {
                              success?: unknown;
                              file?: unknown;
                              error?: unknown;
                            })
                          : {};
                      const success =
                        typeof result.success === "number"
                          ? result.success
                          : undefined;
                      const fileResult =
                        result.file &&
                        typeof result.file === "object" &&
                        !Array.isArray(result.file)
                          ? (result.file as { url?: unknown })
                          : undefined;
                      const fileUrl =
                        fileResult && typeof fileResult.url === "string"
                          ? fileResult.url
                          : undefined;
                      const error =
                        typeof result.error === "string"
                          ? result.error
                          : undefined;

                      if (success === 1 && fileUrl) {
                        return {
                          success: 1,
                          file: {
                            url: fileUrl,
                          },
                        };
                      } else {
                        throw new Error(error ?? "Upload failed");
                      }
                    } catch (error: unknown) {
                      const { handleAsyncError } = await import(
                        "~/lib/error-handler.client"
                      );
                      handleAsyncError(
                        error,
                        {
                          component: "EditPostModal",
                          action: "uploadImage",
                        },
                        false,
                      );
                      throw error;
                    }
                  },
                },
              },
            },
          };

          const editorInstance = new EditorJS({
            holder: "longform-editorjs",
            minHeight: 300,
            // @ts-expect-error - EditorJS types don't match exactly but work at runtime
            tools: toolsConfig,
            // @ts-expect-error - EditorJS onChange signature doesn't match types but works at runtime
            // eslint-disable-next-line @typescript-eslint/no-misused-promises -- EditorJS onChange is async but types don't reflect this
            onChange: async (api: EditorJSAPI) => {
              try {
                const outputData = await api.saver.save();
                const markdownContent = convertEditorJSToMarkdown(outputData);
                form.setValue("content", markdownContent);
              } catch (error: unknown) {
                console.error("Editor save error:", error);
              }
            },
          }) as EditorJSInstanceType;

          editorRef.current = editorInstance;
          await editorRef.current.isReady;
          setEditorReady(true);
        } catch (error: unknown) {
          console.error("Error loading EditorJS:", error);
          editorInitialized.current = false;
        }
      }
    };

    void loadEditor();

    return () => {
      if (editorRef.current) {
        try {
          if (editorRef.current.destroy) {
            editorRef.current.destroy();
          }
        } catch (error) {
          logClientError(
            error instanceof Error ? error : new Error(String(error)),
            {
              component: "useEditPostModal",
              action: "cleanup",
              message: "Error during editor cleanup",
            },
            "warning",
          );
        } finally {
          editorRef.current = null;
          editorInitialized.current = false;
          setEditorReady(false);
        }
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependencies are intentionally limited to avoid unnecessary re-renders
  }, [isLongform]);

  // Load initial content into EditorJS for longform posts
  const formContent = form.watch("content");
  useEffect(() => {
    if (!isLongform || !editorReady || !editorRef.current || !formContent) return;

    const loadInitialContent = async () => {
      if (!editorRef.current) return;
      try {
        await editorRef.current.isReady;
        const contentString = typeof formContent === "string" ? formContent : "";
        const editorJSData = convertMarkdownToEditorJS(contentString);
        await editorRef.current.render(editorJSData);
      } catch (error: unknown) {
        console.error("Error loading initial content into EditorJS:", error);
      }
    };

    const timeoutId = setTimeout(() => {
      void loadInitialContent();
    }, 100);
    return () => clearTimeout(timeoutId);
  }, [isLongform, editorReady, formContent]);

  const formatDateTimeForInput = (date: Date) => {
    const userTimezone =
      user &&
      typeof user === "object" &&
      "timezone" in user &&
      typeof user.timezone === "string"
        ? user.timezone
        : "UTC";
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone }),
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files ?? []);
    if (selectedFiles.length === 0) return;

    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        }),
      );
      setNewFiles((prev) => [...prev, ...processedFiles]);
    } catch (error: unknown) {
      console.error("Error processing files:", error);
      toast.error("Error processing files");
    }
  };

  const removeExistingImage = (index: number) => {
    setExistingImages((prev) => prev.filter((_, i) => i !== index));
  };

  const removeNewFile = (index: number) => {
    setNewFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    form.setValue("hashTagPresetId", presetId ?? undefined);
    form.setValue("useHashtagPresets", !!presetId);
    setSelectedHashtagPresetTags(hashtags);
  };

  // Watch form values for easy access
  const caption = isLongform ? "" : (String(form.watch("caption") ?? ""));
  const title = isLongform ? (String(form.watch("title") ?? "")) : "";
  const summary = isLongform ? (String(form.watch("summary") ?? "")) : "";
  const content = isLongform ? (String(form.watch("content") ?? "")) : "";
  const image = isLongform ? (String(form.watch("image") ?? "")) : "";
  const scheduledForStr = form.watch("scheduledFor");
  const scheduledFor = scheduledForStr
    ? new Date(scheduledForStr)
    : null;
  const selectedQueueType = String(form.watch("queueType") ?? "");
  const useHashtagPresets = Boolean(form.watch("useHashtagPresets") ?? false);
  const selectedHashtagPresetId = form.watch("hashTagPresetId") ?? null;
  const manualHashtags = isLongform ? "" : (String(form.watch("manualHashtags") ?? ""));

  // Setter functions for backward compatibility
  const setCaption = (value: string) => {
    if (!isLongform) form.setValue("caption", value);
  };
  const setTitle = (value: string) => {
    if (isLongform) form.setValue("title", value);
  };
  const setSummary = (value: string) => {
    if (isLongform) form.setValue("summary", value);
  };
  const setImage = (value: string) => {
    if (isLongform) form.setValue("image", value);
  };
  const setScheduledFor = (value: Date | null) => {
    form.setValue(
      "scheduledFor",
      value ? value.toISOString().slice(0, 16) : "",
    );
  };
  const setSelectedQueueType = (value: string) => {
    form.setValue("queueType", value);
  };
  const setUseHashtagPresets = (value: boolean) => {
    form.setValue("useHashtagPresets", value);
  };
  const setManualHashtags = (value: string) => {
    if (!isLongform) form.setValue("manualHashtags", value);
  };
  const setContent = (value: string) => {
    if (isLongform) form.setValue("content", value);
  };

  return {
    // Form instance
    form,
    // Form values (for backward compatibility)
    caption,
    title,
    summary,
    content,
    image,
    scheduledFor,
    selectedQueueType,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtagPresetTags,
    manualHashtags,
    // Setter functions (for backward compatibility)
    setCaption,
    setTitle,
    setSummary,
    setImage,
    setScheduledFor,
    setSelectedQueueType,
    setUseHashtagPresets,
    setManualHashtags,
    setContent,
    // Non-form state
    existingImages,
    newFiles,
    isUploadingImages,
    setIsUploadingImages,
    editorRef,
    editorReady,
    // Handlers
    handleFileChange,
    removeExistingImage,
    removeNewFile,
    handleHashtagPresetSelect,
    formatDateTimeForInput,
  };
}

import { useNavigation } from "@remix-run/react";
import { useState } from "react";
interface UseLongFormEditStateProps {
  userTags: string;
  hashtagPresets: Array<{ id: string; tags: string }>;
}

/**
 * Custom hook for managing longform edit state
 */
export function useLongFormEditState({
  userTags,
  hashtagPresets,
}: UseLongFormEditStateProps) {
  const navigation = useNavigation();
  const [displayedHashtags, setDisplayedHashtags] = useState(userTags ?? "");
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewData, setPreviewData] = useState({
    title: "",
    summary: "",
    content: "",
    image: "",
  });

  // Hashtag preset state
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState("");
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = navigation.state === "submitting";

  // Hashtag preset handlers
  const handleHashtagPresetToggle = (enabled: boolean) => {
    setUseHashtagPresets(enabled);
    if (!enabled) {
      // If disabled, clear manual selection and revert to queue/user default
      setSelectedHashtagPresetId("");
      setSelectedHashtags("");
      // Note: displayedHashtags will be updated by queue type change logic
    } else if (selectedHashtags) {
      // If enabled and we have selected hashtags, show them
      setDisplayedHashtags(selectedHashtags);
    }
  };

  const handleHashtagPresetChange = (presetId: string) => {
    setSelectedHashtagPresetId(presetId);
    const preset = hashtagPresets.find((p) => p.id === presetId);
    const tags = preset?.tags ?? "";
    setSelectedHashtags(tags);
    if (useHashtagPresets) {
      setDisplayedHashtags(tags);
    }
  };

  // Function to update displayed hashtags when queue type changes
  const updateDisplayedHashtags = async (queueTypeName: string) => {
    // Don't update if using manual hashtag presets
    if (useHashtagPresets) {
      return;
    }

    if (queueTypeName === "unassigned") {
      setDisplayedHashtags(userTags ?? "");
      return;
    }

    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName: queueTypeName,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { hashtags?: string };
        setDisplayedHashtags((data.hashtags ?? userTags) || "");
      } else {
        setDisplayedHashtags(userTags ?? "");
      }
    } catch (error) {
      console.error("Error fetching effective hashtags:", error);
      setDisplayedHashtags(userTags ?? "");
    }
  };

  const handlePreview = (data: {
    title: string;
    summary: string;
    content: string;
    image: string;
  }) => {
    setPreviewData(data);
    setShowPreviewModal(true);
  };

  return {
    displayedHashtags,
    showPreviewModal,
    setShowPreviewModal,
    previewData,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtags,
    isSubmitting,
    handleHashtagPresetToggle,
    handleHashtagPresetChange,
    updateDisplayedHashtags,
    handlePreview,
  };
}

/**
 * Hook for handling longform post submission logic
 * Extracts the complex submission logic from LongFormPost component
 */

import {
  convertEditorJSToMarkdown,
  generateArticleIdentifier,
} from "~/features/posts/utils/editorjs-conversion";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { EditorJSBlock } from "../types";
import { generateSummaryFromContent } from "../utils/editorjs-content";

interface UseLongFormSubmissionProps {
  title: string;
  summary: string;
  content: string;
  image: string;
  customTags: string;
  selectedQueueType: string;
  scheduledFor: string | null;
  displayedHashtags: string | null;
  useHashtagPresets: boolean;
  selectedHashtags: string;
}

export function useLongFormSubmission({
  title,
  summary,
  content,
  image,
  customTags,
  selectedQueueType,
  scheduledFor,
  displayedHashtags,
  useHashtagPresets,
  selectedHashtags,
}: UseLongFormSubmissionProps) {
  const handleSchedule = async (actionType: "schedule" | "publish") => {
    if (!title.trim() || !content.trim()) {
      return;
    }

    try {
      let markdownContent;
      try {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        markdownContent = convertEditorJSToMarkdown(
          editorData as { blocks: EditorJSBlock[] },
        );
      } catch {
        markdownContent = content;
      }

      const finalSummary = summary || generateSummaryFromContent(content);
      const identifier = generateArticleIdentifier(title);

      let scheduledTimestamp: number | undefined;
      if (actionType === "schedule" && scheduledFor) {
        const scheduledTime = new Date(scheduledFor);
        if (!isNaN(scheduledTime.getTime())) {
          scheduledTimestamp = Math.floor(scheduledTime.getTime() / 1000);
        }
      }

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
      } else {
        // Manual hashtag presets are disabled, use displayed hashtags (queue defaults)
        effectiveHashtags = displayedHashtags ?? "";
      }

      const hashtagsFromQueue = effectiveHashtags
        ? effectiveHashtags
            .split(" ")
            .map((tag) => tag.replace("#", "").trim())
            .filter(Boolean)
        : [];
      const customTagsList = customTags
        ? customTags
            .split(",")
            .map((tag) => tag.trim())
            .filter(Boolean)
        : [];
      // Combine and deduplicate tags (case insensitive)
      const allTags = [...hashtagsFromQueue, ...customTagsList];
      const uniqueTags = allTags.filter(
        (tag, index) =>
          allTags.findIndex((t) => t.toLowerCase() === tag.toLowerCase()) ===
          index,
      );

      const eventData = {
        title,
        content: markdownContent,
        summary: finalSummary,
        image,
        tags: uniqueTags,
        identifier,
        publishedAt:
          actionType === "publish"
            ? Math.floor(Date.now() / 1000)
            : scheduledTimestamp,
      };

      const { nostrEvent, signedEvent } = await nostrAdapter.signLongFormEvent(eventData);

      const form = document.createElement("form");
      form.method = "POST";
      form.style.display = "none";

      const fields: Array<[string, string]> = [
        [
          "_action",
          actionType === "schedule" ? "schedule-longform" : "publish",
        ],
        ["title", title],
        ["content", content],
        ["summary", finalSummary],
        ["image", image],
        ["tags", uniqueTags.join(",")],
        ["queueType", selectedQueueType],
        [
          "scheduledFor",
          scheduledTimestamp ? scheduledTimestamp.toString() : "",
        ],
        ["signedEvent", JSON.stringify(signedEvent)],
        ["nostrEvent", JSON.stringify(nostrEvent)],
      ];

      fields.forEach(([name, value]) => {
        const input = document.createElement("input");
        input.type = "hidden";
        input.name = name;
        input.value = value ?? "";
        form.appendChild(input);
      });

      document.body.appendChild(form);
      form.submit();
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(
        error,
        {
          component: "LongFormPost",
          action: "handleSubmit",
        },
        false,
      ); // Don't show toast, let component handle it
    }
  };

  return { handleSchedule };
}

import { useNavigation } from "@remix-run/react";
import { useState } from "react";
interface UseNewLongFormStateProps {
  userTags: string;
}

/**
 * Custom hook for managing new longform post state
 */
export function useNewLongFormState({ userTags }: UseNewLongFormStateProps) {
  const navigation = useNavigation();
  const [displayedHashtags, setDisplayedHashtags] = useState(userTags ?? "");
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewData, setPreviewData] = useState({
    title: "",
    summary: "",
    content: "",
    image: "",
  });
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState<
    string | null
  >(null);
  const [selectedHashtags, setSelectedHashtags] = useState("");

  const isSubmitting = navigation.state === "submitting";

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtags(hashtags);
    if (useHashtagPresets) {
      setDisplayedHashtags(hashtags);
    }
  };

  // Function to update displayed hashtags when queue type changes
  const updateDisplayedHashtags = async (queueTypeName: string) => {
    if (useHashtagPresets && selectedHashtags) {
      // If manual hashtag presets are enabled, use the selected hashtags
      setDisplayedHashtags(selectedHashtags);
      return;
    }

    if (queueTypeName === "Unassigned") {
      setDisplayedHashtags(userTags ?? "");
      return;
    }

    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName: queueTypeName,
        }),
      });

      if (response.ok) {
        const data = (await response.json()) as { hashtags?: string };
        setDisplayedHashtags((data.hashtags ?? userTags) || "");
      } else {
        setDisplayedHashtags(userTags ?? "");
      }
    } catch (error) {
      console.error("Error fetching effective hashtags:", error);
      setDisplayedHashtags(userTags ?? "");
    }
  };

  // Update displayed hashtags when hashtag preset usage changes
  const handleUseHashtagPresetsChange = (enabled: boolean) => {
    setUseHashtagPresets(enabled);
    if (!enabled) {
      // When disabling manual presets, revert to queue type hashtags
      // This will trigger through the queue type change logic in the component
    } else if (selectedHashtags) {
      setDisplayedHashtags(selectedHashtags);
    }
  };

  const handlePreview = (data: {
    title: string;
    summary: string;
    content: string;
    image: string;
  }) => {
    setPreviewData(data);
    setShowPreviewModal(true);
  };

  return {
    displayedHashtags,
    showPreviewModal,
    setShowPreviewModal,
    previewData,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtags,
    isSubmitting,
    handleHashtagPresetSelect,
    updateDisplayedHashtags,
    handleUseHashtagPresetsChange,
    handlePreview,
  };
}

import { useState, useEffect, useCallback } from "react";

import { useOptionalUser } from "~/lib/remix-utils";

import type { QueueType } from "../types";

interface UsePostSchedulingProps {
  queueTypes: Array<string | QueueType>;
  scheduleIntervals?: number[];
  userTimezone?: string;
  initialQueue?: string;
  onQueueTypeChange?: (queueType: string) => void;
  onTimeError?: (error: string) => void;
}

export function usePostScheduling({
  queueTypes,
  scheduleIntervals = [],
  userTimezone = "UTC",
  initialQueue = "unassigned",
  onQueueTypeChange,
  onTimeError,
}: UsePostSchedulingProps) {
  const user = useOptionalUser();
  const [selectedQueue, setSelectedQueue] = useState(initialQueue);
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");

  const calculateQueueScheduleTime = useCallback(
    async (queueTypeName: string) => {
      if (queueTypeName === "unassigned") {
        setScheduledFor("");
        return;
      }

      // Find the queue type object to get its ID
      const selectedQueueType = queueTypes.find((qt) =>
        typeof qt === "string"
          ? qt === queueTypeName
          : qt.name === queueTypeName,
      );
      const queueTypeId =
        typeof selectedQueueType === "object" ? selectedQueueType.id : null;

      try {
        const response = await fetch("/api/queue-schedule", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            queueTypeId,
            queueTypeName, // Keep for backward compatibility
            userId: user?.id,
          }),
        });

        if (response.ok) {
          const data = (await response.json()) as { scheduledTime?: string };
          const scheduledTime = data.scheduledTime;
          if (scheduledTime) {
            setScheduledFor(scheduledTime);
          }
          setTimeError("");
          if (onTimeError) {
            onTimeError("");
          }
        }
      } catch (error) {
        console.error("Error calculating schedule time:", error);
      }
    },
    [queueTypes, user?.id, onTimeError],
  );

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find((qt) =>
      typeof qt === "string" ? qt === selectedQueue : qt.name === selectedQueue,
    );

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (
      selectedQueueType &&
      typeof selectedQueueType === "object" &&
      selectedQueueType.scheduleType === "FIXED_SLOTS"
    ) {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      void calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const hoursLater = new Date(
      now.getTime() + parseInt(String(intervalHours)) * 60 * 60 * 1000,
    );

    // Format the date in the user's timezone
    const effectiveTimezone = userTimezone || (user?.timezone ?? "UTC");
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: effectiveTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart?.split("/") ?? ["", "", ""];
    const [hours, minutes] = timePart?.split(":") ?? ["", ""];

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    if (!year || !month || !day || !hours || !minutes) {
      return "";
    }
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
    if (onTimeError) {
      onTimeError("");
    }
  };

  // Calculate schedule time when queue changes
  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduledForChange = (value: string) => {
    setScheduledFor(value);
    setTimeError("");
    if (onTimeError) {
      onTimeError("");
    }
  };

  const handleTimeError = (error: string) => {
    setTimeError(error);
    if (onTimeError) {
      onTimeError(error);
    }
  };

  return {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor: handleScheduledForChange,
    timeError,
    setTimeError: handleTimeError,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals: scheduleIntervals || user?.scheduleInterval || [],
  };
}

/**
 * TanStack Query hooks for posted posts
 * Provides caching, background refetching, and optimistic updates
 */

import { useFetcher, useLoaderData , useParams, useSearchParams } from "@remix-run/react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

import type { User as _User } from "~/features/user";
import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  postedPostsLoaderDataSchema,
  type PostedPostsLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";
import { validateUserData } from "~/lib/validation/user-data";
import type { UserData } from "~/lib/validation/user-data";

import { combineContent } from "../combined";
import type { PostDTO, LongFormPostDTO } from "../dtos";
import {
  fromPostDTOArray,
  fromLongFormPostDTOArray,
} from "../dtos";
import type { PostStats } from "../stats.server";
import type {
  PostData,
  LongFormPostData,
  CombinedContent,
  QueueType,
} from "../types";
import { convertJsonValueToScheduleConfig } from "../types";

// PostedPostsLoaderData is now exported from schemas

/**
 * Query key factory for posted posts
 */
export const postedPostsKeys = {
  all: ["posted-posts"] as const,
  lists: () => [...postedPostsKeys.all, "list"] as const,
  list: (queueType?: string, tab?: string, page?: number) =>
    [...postedPostsKeys.lists(), queueType, tab, page] as const,
  detail: (id: string) => [...postedPostsKeys.all, "detail", id] as const,
};

/**
 * Hook to fetch posted posts with TanStack Query
 * Uses Remix loader data as initial data and enables client-side refetching
 */
export function usePostedPostsQuery() {
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";
  const page = parseInt(searchParams.get("page") ?? "1", 10);

  // Import loader dynamically to avoid circular dependency
  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    postedPostsLoaderDataSchema,
  );

  return useQuery({
    queryKey: postedPostsKeys.list(queueType, currentTab, page),
    queryFn: async () => {
      // Use fetcher to refetch data
      const url = `/dashboard/posted${queueType !== "all" ? `/${queueType}` : ""}?tab=${currentTab}&page=${page}`;
      fetcher.load(url);

      // Wait for fetcher to complete
      return new Promise<PostedPostsLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                postedPostsLoaderDataSchema,
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData ?? undefined,
    staleTime: 30 * 1000, // 30 seconds - data is fresh for 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes - keep in cache for 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false, // Don't refetch on mount if data is fresh
  });
}

/**
 * Hook to get processed post data from query
 */
export function usePostedPostsData() {
  const { data, isLoading, error } = usePostedPostsQuery();

  if (!data) {
    return {
      posts: [] as PostData[],
      longformPosts: [] as LongFormPostData[],
      allContent: [] as CombinedContent[],
      isLoading,
      error,
      user: null,
      queueTypes: [] satisfies QueueType[],
      pagination: { total: 0, pages: 0, currentPage: 1, limit: 50 },
      stats: {} satisfies Record<string, PostStats>,
    };
  }

  // Data is already validated by the query hook
  const typedData = data;
  const postsRaw = "posts" in typedData && Array.isArray(typedData.posts) ? typedData.posts : [];
  const longformPostsRaw =
    "longformPosts" in typedData && Array.isArray(typedData.longformPosts)
      ? typedData.longformPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const user: UserData | null = userRaw ? validateUserData(userRaw) : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const paginationRaw = "pagination" in typedData ? typedData.pagination : undefined;
  const statsRaw = "stats" in typedData ? typedData.stats : undefined;

  const posts: PostData[] = Array.isArray(postsRaw)
    ? fromPostDTOArray(postsRaw as PostDTO[])
    : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw)
    ? fromLongFormPostDTOArray(longformPostsRaw as LongFormPostDTO[])
    : [];
  // Reconstruct allContent on client from deserialized posts/longformPosts
  const allContent: CombinedContent[] = combineContent(
    posts,
    longformPosts,
    "postedAt",
    "desc",
  );
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw.map((qt: unknown) => {
        if (typeof qt !== "object" || qt === null) {
          throw new Error("Invalid queue type");
        }
        const q = qt as {
          id?: unknown;
          name?: unknown;
          color?: unknown;
          scheduleType?: unknown;
          scheduleConfig?: unknown;
          isEnabled?: unknown;
          userId?: unknown;
        };
        const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
        const name = typeof q.name === "string" ? q.name : String(q.name ?? "");
        const color =
          q.color !== null && q.color !== undefined
            ? typeof q.color === "string"
              ? q.color
              : String(q.color)
            : null;
        const scheduleType =
          typeof q.scheduleType === "string" &&
          (q.scheduleType === "INTERVAL" || q.scheduleType === "FIXED_SLOTS")
            ? q.scheduleType
            : undefined;
        const scheduleConfig = convertJsonValueToScheduleConfig(
          q.scheduleConfig,
        );
        const isEnabled =
          typeof q.isEnabled === "boolean"
            ? q.isEnabled
            : q.isEnabled !== false;
        const userId = typeof q.userId === "string" ? q.userId : "";
        const queueType: QueueType = {
          id,
          name,
          color,
          description: undefined,
          scheduleType,
          scheduleConfig,
          isEnabled,
          userId,
        };
        return queueType;
      })
    : [];
  const pagination = paginationRaw &&
    typeof paginationRaw === "object" &&
    !Array.isArray(paginationRaw) &&
    "total" in paginationRaw &&
    "pages" in paginationRaw &&
    "currentPage" in paginationRaw &&
    "limit" in paginationRaw
    ? {
        total: typeof paginationRaw.total === "number" ? paginationRaw.total : 0,
        pages: typeof paginationRaw.pages === "number" ? paginationRaw.pages : 0,
        currentPage: typeof paginationRaw.currentPage === "number" ? paginationRaw.currentPage : 1,
        limit: typeof paginationRaw.limit === "number" ? paginationRaw.limit : 50,
      }
    : { total: 0, pages: 0, currentPage: 1, limit: 50 };
  const stats: Record<string, PostStats> =
    statsRaw && typeof statsRaw === "object" && !Array.isArray(statsRaw)
      ? (statsRaw)
      : {};

  return {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes,
    pagination,
    stats,
    isLoading,
    error,
    rawData: typedData,
  };
}

/**
 * Mutation hook for bulk delete with optimistic updates
 */
export function useBulkDeletePostsMutation() {
  const queryClient = useQueryClient();
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";
  const page = parseInt(searchParams.get("page") ?? "1", 10);

  return useMutation({
    mutationFn: async (postIds: string[]) => {
      const formData = new FormData();
      formData.append("_action", "bulk-delete");
      postIds.forEach((id) => {
        formData.append("postIds", id);
      });

      const response = await fetch("/dashboard/posted", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        throw new Error("Failed to delete posts");
      }

      return response.json();
    },
    onMutate: async (postIds) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: postedPostsKeys.list(queueType, currentTab, page),
      });

      // Snapshot previous value
      const previousData = queryClient.getQueryData<PostedPostsLoaderData>(
        postedPostsKeys.list(queueType, currentTab, page),
      );

      // Optimistically update
      if (previousData) {
        queryClient.setQueryData<PostedPostsLoaderData>(
          postedPostsKeys.list(queueType, currentTab, page),
          (old) => {
            if (!old) return old;
            return {
              ...old,
              posts:
                "posts" in old && Array.isArray(old.posts)
                  ? old.posts.filter(
                      (p: unknown) =>
                        p &&
                        typeof p === "object" &&
                        "id" in p &&
                        typeof p.id === "string" &&
                        !postIds.includes(p.id),
                    )
                  : [],
              allContent:
                "allContent" in old && Array.isArray(old.allContent)
                  ? old.allContent.filter(
                      (c: unknown) =>
                        c &&
                        typeof c === "object" &&
                        "id" in c &&
                        typeof c.id === "string" &&
                        !postIds.includes(c.id),
                    )
                  : [],
            };
          },
        );
      }

      return { previousData };
    },
    onError: (err, variables, context) => {
      // Rollback on error
      if (context?.previousData) {
        queryClient.setQueryData(
          postedPostsKeys.list(queueType, currentTab, page),
          context.previousData,
        );
      }
    },
    onSettled: () => {
      // Refetch after mutation
      void queryClient.invalidateQueries({
        queryKey: postedPostsKeys.lists(),
      });
    },
  });
}

/**
 * TanStack Query hooks for recyclable posts
 * Provides caching and background refetching for recyclables page
 */

import { useFetcher, useLoaderData , useParams } from "@remix-run/react";
import { useQuery } from "@tanstack/react-query";

import type { UserWithHashTagPresets as _UserWithHashTagPresets } from "~/features/user";
import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  recyclablesLoaderDataSchema,
  type RecyclablesLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";


import type { PostDTO } from "../dtos";
import { fromPostDTOArray } from "../dtos";
import type { PostStats as _PostStats } from "../stats.server";
import type {
  PostData,
  QueueType,
} from "../types";

// RecyclablesLoaderData is now exported from schemas

/**
 * Query key factory for recyclables
 */
export const recyclablesKeys = {
  all: ["recyclables"] as const,
  lists: () => [...recyclablesKeys.all, "list"] as const,
  list: (queueType?: string, page?: number) =>
    [...recyclablesKeys.lists(), queueType, page] as const,
  detail: (id: string) => [...recyclablesKeys.all, "detail", id] as const,
};

/**
 * Hook to fetch recyclable posts with TanStack Query
 * Uses Remix loader data as initial data and enables client-side refetching
 */
export function useRecyclablesQuery() {
  const params = useParams();
  const queueType = params["queueType"] ?? "all";
  const page = 1; // Recyclables doesn't use pagination in URL currently, but we'll support it

  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    recyclablesLoaderDataSchema,
  );

  return useQuery({
    queryKey: recyclablesKeys.list(queueType, page),
    queryFn: async () => {
      // Use fetcher to refetch data
      const url = `/dashboard/recyclables${queueType !== "all" ? `/${queueType}` : ""}?page=${page}`;
      fetcher.load(url);

      // Wait for fetcher to complete
      return new Promise<RecyclablesLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                recyclablesLoaderDataSchema,
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else {
            setTimeout(checkFetcher, 50);
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData ?? undefined,
    staleTime: 30 * 1000, // 30 seconds
  });
}

/**
 * Processed recyclables data with deserialized DTOs
 */
export function useRecyclablesData() {
  const query = useRecyclablesQuery();
  const rawData = query.data;

  if (!rawData) {
    const emptyPosts: PostData[] = [];
    const emptyStats: Record<
      string,
      {
        likes?: number;
        replies?: number;
        mentions?: number;
        reposts?: number;
        zaps?: number;
        satszapped?: number;
      }
    > = {};
    const emptyQueueTypes: QueueType[] = [];
    return {
      posts: emptyPosts,
      pagination: { total: 0, pages: 0, currentPage: 1, limit: 50 },
      stats: emptyStats,
      user: null,
      queueTypes: emptyQueueTypes,
      selectedQueueType: "all",
      isLoading: query.isLoading,
      rawData: null,
    };
  }

  // Deserialize DTOs (with string dates) back to PostData (with Date objects)
  const posts: PostData[] = Array.isArray(rawData.posts)
    ? fromPostDTOArray(rawData.posts as PostDTO[])
    : [];

  // Type assertions for stats
  const stats: Record<
    string,
    {
      likes?: number;
      replies?: number;
      mentions?: number;
      reposts?: number;
      zaps?: number;
      satszapped?: number;
    }
  > = rawData.stats && typeof rawData.stats === "object" && !Array.isArray(rawData.stats)
    ? rawData.stats
    : {};

  // Type assertion for pagination
  const pagination =
    rawData.pagination &&
    typeof rawData.pagination === "object" &&
    !Array.isArray(rawData.pagination) &&
    "total" in rawData.pagination &&
    "pages" in rawData.pagination &&
    "currentPage" in rawData.pagination &&
    "limit" in rawData.pagination
      ? {
          total: typeof rawData.pagination.total === "number" ? rawData.pagination.total : 0,
          pages: typeof rawData.pagination.pages === "number" ? rawData.pagination.pages : 0,
          currentPage:
            typeof rawData.pagination.currentPage === "number"
              ? rawData.pagination.currentPage
              : 1,
          limit: typeof rawData.pagination.limit === "number" ? rawData.pagination.limit : 50,
        }
      : { total: 0, pages: 0, currentPage: 1, limit: 50 };

  return {
    posts,
    pagination,
    stats,
    user: rawData.user,
    queueTypes: Array.isArray(rawData.queueTypes) ? rawData.queueTypes : [],
    selectedQueueType: rawData.selectedQueueType ?? "all",
    isLoading: query.isLoading,
    rawData,
  };
}

import type { useFetcher , type FetcherWithComponents } from "@remix-run/react";
import { useState, useEffect } from "react";

import { nostrAdapter } from "~/lib/nostr-adapter.client";

