export async function handleDraftsAction(formData: FormData, userId: string) {
  const result = validateFormDataOrRespond(formData, draftsActionSchema);
  if (!result.success) {
    return result.response;
  }

  const { _action } = result.data;

  if (_action === "delete") {
    await deletePost({ id: result.data.postId, userId });
    return { success: true };
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: result.data.postId, userId });
    return { success: true };
  }

  if (_action === "bulkDelete") {
    await Promise.all(
      result.data.postIds.map((id: string) => deletePost({ id, userId })),
    );
    return { success: true };
  }

  if (_action === "bulkDeleteLongForm") {
    await Promise.all(
      result.data.postIds.map((id: string) =>
        deleteLongFormPost({ id, userId }),
      ),
    );
    return { success: true };
  }

  if (_action === "bulkSignAndResume") {
    // TypeScript needs explicit narrowing for discriminated unions
    const bulkData = result.data._action === "bulkSignAndResume" ? result.data : null;
    if (!bulkData) {
      return { error: "Invalid action" };
    }

    await Promise.all(
      bulkData.postIds.map(async (id, index) => {
        // Resolve queue type ID in feature layer (business logic)
        const resolvedQueueTypeId = await resolveQueueTypeId(
          userId,
          bulkData.queueTypeIds[index] ?? null,
          bulkData.queueTypes[index] ?? null,
        );

        return updatePost({
          id,
          userId,
          data: {
            content: bulkData.contents[index],
            caption: bulkData.captions[index],
            queueTypeId: resolvedQueueTypeId,
            scheduledFor: bulkData.scheduledFors[index],
            signedEvent: bulkData.signedEvents[index],
            nostrEvent: bulkData.nostrEvents[index],
            draft: false,
            isScheduled: true,
            isPosted: false,
          },
        });
      }),
    );
    return { success: true };
  }

  return { error: "Invalid action" };
}

/**
 * Effective hashtags service layer
 * Handles effective hashtag calculation for queue types
 */

import { json } from "@remix-run/node";

import { getQueueTypes } from "~/features/user";
import { ValidationError } from "~/lib/errors";
/**
 * Get effective hashtags for a queue type
 * Returns the hashtag preset assigned to the queue type, or empty if none assigned
 */
export async function getEffectiveHashtags(
  userId: string,
  queueTypeName?: string,
  queueTypeId?: string,
) {
  // If explicitly "unassigned", return empty hashtags (valid case)
  if (queueTypeName === "unassigned") {
    return json({ hashtags: "" });
  }

  // If no queue type specified at all, return validation error
  if (!queueTypeName && !queueTypeId) {
    throw new ValidationError("queueTypeName or queueTypeId is required", {
      queueTypeName,
      queueTypeId,
    });
  }

  // Get all queue types for the user
  const queueTypes = await getQueueTypes(userId);

  // Find the specified queue type - prefer ID over name
  let queueType;
  if (queueTypeId) {
    queueType = queueTypes.find((qt) => qt.id === queueTypeId);
  } else {
    queueType = queueTypes.find((qt) => qt.name === queueTypeName);
  }

  if (
    !queueType ||
    !("hashTagPreset" in queueType) ||
    !queueType.hashTagPreset
  ) {
    return json({ hashtags: "" });
  }

  // Return the hashtag preset tags assigned to this queue type
  // Use consistent unwrapped format to match other return statements
  return json({
    hashtags: (queueType.hashTagPreset as { tags: string | null })?.tags ?? "",
  });
}

/**
 * Parse effective hashtags request body
 */
export function parseEffectiveHashtagsRequest(body: unknown): {
  queueTypeName?: string;
  queueTypeId?: string;
} {
  if (typeof body !== "object" || body === null) {
    throw new ValidationError("Request body must be an object", {
      bodyType: typeof body,
    });
  }

  const requestBody = body as { queueTypeName?: string; queueTypeId?: string };

  return {
    queueTypeName: requestBody.queueTypeName,
    queueTypeId: requestBody.queueTypeId,
  };
}

