/**
 * Posted Posts Service
 *
 * Handles posted posts data loading
 */

import type { Prisma } from "@prisma/client";

import { getUserById, getQueueTypes } from "~/features/user";
import {
  validateSignedEvent,
  validateNostrEvent,
} from "~/lib/validation/nostr-events.server";
import { getPublishedLongFormPosts } from "~/models/longformpost.server";
import { getPostedPosts } from "~/models/post.queries.server";

import {
  toPostDTOArray,
  toLongFormPostDTOArray,
  type PostDTO,
  type LongFormPostDTO,
} from "../dtos";
import { getPostStats } from "../stats.server";
import type { PostData, LongFormPostData } from "../types";
import { convertPrismaQueueTypeToQueueType } from "../types";
/**
 * Get posted posts dashboard data
 */
export async function getPostedDashboardData({
  userId,
  params,
  url,
}: {
  userId: string;
  params: { queueType?: string };
  url: URL;
}) {
  const page = parseInt(url.searchParams.get("page") ?? "1");
  const limit = 50;
  const queueType = params.queueType ?? "all";

  const [{ posts, pagination }, allLongformResultRaw, user, queueTypesRaw] =
    await Promise.all([
      getPostedPosts({
        userId,
        page,
        limit,
        queueType,
      }),
      getPublishedLongFormPosts({ userId, page, limit }),
      getUserById(userId),
      getQueueTypes(userId),
    ]);

  const allLongformResult =
    typeof allLongformResultRaw === "object" &&
    allLongformResultRaw !== null &&
    "posts" in allLongformResultRaw &&
    "pagination" in allLongformResultRaw
      ? (allLongformResultRaw as { posts: unknown[]; pagination: unknown })
      : { posts: [], pagination: { total: 0, pages: 0, currentPage: 1 } };
  const queueTypes = Array.isArray(queueTypesRaw) ? queueTypesRaw : [];

  const allLongformPosts = Array.isArray(allLongformResult.posts)
    ? allLongformResult.posts
    : [];
  const longformResult = {
    ...allLongformResult,
    posts:
      queueType === "all"
        ? allLongformPosts
        : allLongformPosts.filter((post: unknown) => {
            if (
              typeof post === "object" &&
              post !== null &&
              "queueType" in post &&
              post.queueType &&
              typeof post.queueType === "object" &&
              "name" in post.queueType &&
              typeof post.queueType.name === "string"
            ) {
              return post.queueType.name === queueType;
            }
            return false;
          }),
  };

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    // Validate Prisma JsonValue with Zod schemas
    const signedEventValue = validateSignedEvent(post.signedEvent);
    const nostrEventValue = validateNostrEvent(post.nostrEvent);
    const result: PostData = {
      ...rest,
      queueType: convertPrismaQueueTypeToQueueType(
        "queueType" in post ? post.queueType : undefined,
      ),
      signedEvent: signedEventValue ?? undefined,
      nostrEvent: nostrEventValue ?? undefined,
    };
    return result;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformResult.posts.map(
    (post: unknown) => {
      const postObj =
        typeof post === "object" && post !== null
          ? (post as Record<string, unknown>)
          : {};
      // Validate Prisma JsonValue with Zod schemas
      const signedEventValue = validateSignedEvent(
        ("signedEvent" in postObj ? postObj["signedEvent"] : undefined) as
          | Prisma.JsonValue
          | null
          | undefined,
      );
      const nostrEventValue = validateNostrEvent(
        ("nostrEvent" in postObj ? postObj["nostrEvent"] : undefined) as
          | Prisma.JsonValue
          | null
          | undefined,
      );
      const queueTypeValue =
        "queueType" in postObj &&
        postObj["queueType"] &&
        typeof postObj["queueType"] === "object" &&
        "id" in postObj["queueType"] &&
        "name" in postObj["queueType"] &&
        typeof (postObj["queueType"] as { id: unknown; name: unknown })["id"] ===
          "string" &&
        typeof (postObj["queueType"] as { id: unknown; name: unknown })["name"] ===
          "string"
          ? (postObj["queueType"] as {
              id: string;
              name: string;
              scheduleConfig?: unknown;
              color?: string | null;
              description?: string | null;
              scheduleType?: string | null;
              isEnabled?: boolean | null;
              userId: string;
              [key: string]: unknown;
            })
          : undefined;
      // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- Type assertion needed for Prisma query result with spread operator
      return {
        ...postObj,
        queueType: convertPrismaQueueTypeToQueueType(
          queueTypeValue as unknown as Parameters<
            typeof convertPrismaQueueTypeToQueueType
          >[0],
        ),
        signedEvent: signedEventValue ?? undefined,
        nostrEvent: nostrEventValue ?? undefined,
      } as LongFormPostData;
    },
  );

  const eventIds = posts
    .map((post) => {
      const signedEvent = post.signedEvent;
      if (
        signedEvent &&
        typeof signedEvent === "object" &&
        "id" in signedEvent &&
        typeof signedEvent["id"] === "string"
      ) {
        return signedEvent["id"];
      }
      return "";
    })
    .filter((id) => id !== "");
  const stats = await getPostStats(eventIds);

  // Serialize Date objects to strings for Remix loader response
  // Note: allContent is removed - reconstruct on client from posts/longformPosts
  const postsDTO: PostDTO[] = toPostDTOArray(postsData);
  const longformPostsDTO: LongFormPostDTO[] = toLongFormPostDTOArray(
    longformPostsData,
  );

  return {
    posts: postsDTO,
    longformPosts: longformPostsDTO,
    longformPagination: longformResult.pagination,
    pagination,
    stats,
    user,
    queueTypes: queueTypes.filter(
      (qt: unknown) =>
        typeof qt === "object" &&
        qt !== null &&
        "isEnabled" in qt &&
        qt.isEnabled !== false,
    ),
    selectedQueueType: queueType,
  };
}

/**
 * Recyclable Posts Service
 *
 * Handles recyclable posts data loading and actions (repost, quote, delete)
 */

import { json } from "@remix-run/node";

import type { UserWithHashTagPresets } from "~/features/user";
import { getUserById, getQueueTypes } from "~/features/user";
import {
  recyclableActionSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import { deletePost } from "~/models/post.commands.server";
import {
  getRecyclablePosts,
  getPostsByIds,
} from "~/models/post.queries.server";

import {
  toPostDTOArray,
  type PostDTO,
} from "../dtos";
import { getPostStats } from "../stats.server";
import type { PostData } from "../types";
import { convertPrismaQueueTypeToQueueType } from "../types";
/**
 * Get recyclable posts dashboard data
 */
export async function getRecyclableDashboardData({
  userId,
  params,
  url,
}: {
  userId: string;
  params: { queueType?: string };
  url: URL;
}) {
  const page = parseInt(url.searchParams.get("page") ?? "1");
  const limit = 50;
  const queueType = params.queueType ?? "all";

  const [{ posts, pagination }, userResult, queueTypesResult] =
    await Promise.all([
      getRecyclablePosts({
        userId,
        page,
        limit,
        queueType,
      }),
      getUserById(userId),
      getQueueTypes(userId),
    ]);

  if (!userResult) {
    throw new Error("User not found");
  }

  const user: UserWithHashTagPresets = userResult;
  const queueTypes = Array.isArray(queueTypesResult) ? queueTypesResult : [];

  // Get event IDs from signedEvent.id
  const eventIds = posts
    .map((post) => {
      const signedEvent = post.signedEvent;
      if (
        signedEvent &&
        typeof signedEvent === "object" &&
        "id" in signedEvent &&
        typeof signedEvent["id"] === "string"
      ) {
        return signedEvent["id"];
      }
      return "";
    })
    .filter((id) => id !== "");

  // Use the extracted stats fetching logic
  const stats = await getPostStats(eventIds);

  // Convert PostWithQueueType[] to PostData[] and serialize to DTOs
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    const signedEventValue: PostData["signedEvent"] =
      post.signedEvent as PostData["signedEvent"];
    const nostrEventValue: PostData["nostrEvent"] =
      post.nostrEvent as PostData["nostrEvent"];
    const result: PostData = {
      ...rest,
      queueType: convertPrismaQueueTypeToQueueType(queueType),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return result;
  });

  const postsDTO: PostDTO[] = toPostDTOArray(postsData);

  return {
    posts: postsDTO,
    pagination,
    stats,
    user,
    queueTypes: queueTypes.filter(
      (qt: unknown) =>
        typeof qt === "object" &&
        qt !== null &&
        "isEnabled" in qt &&
        qt.isEnabled !== false,
    ),
    selectedQueueType: queueType,
  };
}

/**
 * Handle recyclable post actions (delete, repost, quote)
 */
export async function handleRecyclablePostAction(
  formData: FormData,
  userId: string,
) {
  // Validate with Zod
  const result = validateFormDataOrRespond(formData, recyclableActionSchema);
  if (!result.success) {
    return result.response;
  }

  const validatedData = result.data;

  // Handle delete action
  if (validatedData._action === "delete") {
    await deletePost({ id: validatedData.postId, userId });
    return json({ success: true });
  }

  // Handle bulk delete
  if (validatedData._action === "bulkDelete") {
    await Promise.all(
      validatedData.postIds.map((id: string) => deletePost({ id, userId })),
    );
    return json({ success: true });
  }

  // Handle bulk repost
  if (validatedData._action === "bulkRepost") {
    const postsData = await getPostsByIds({ ids: validatedData.postIds, userId });
    return json({ repostData: postsData });
  }

  // Handle bulk scheduled repost
  if (validatedData._action === "bulkScheduledRepost") {
    const postsData = await getPostsByIds({ ids: validatedData.postIds, userId });
    return json({ scheduledRepostData: postsData });
  }

  // Handle bulk quote
  if (validatedData._action === "bulkQuote") {
    const postsData = await getPostsByIds({ ids: validatedData.postIds, userId });

    // Transform posts data into quote post format
    const quotePostsData = postsData.map((post) => {
      const signedEvent = post.signedEvent;
      let eventId = "";
      let eventPubkey = "";

      if (
        signedEvent &&
        typeof signedEvent === "object" &&
        !Array.isArray(signedEvent)
      ) {
        if ("id" in signedEvent && typeof signedEvent["id"] === "string") {
          eventId = signedEvent["id"];
        }
        if ("pubkey" in signedEvent && typeof signedEvent["pubkey"] === "string") {
          eventPubkey = signedEvent["pubkey"];
        }
      }

      const fileUrl = Array.isArray(post.fileUrl)
        ? post.fileUrl
        : typeof post.fileUrl === "string"
          ? [post.fileUrl]
          : [];
      const caption = typeof post.caption === "string" ? post.caption : "";
      const queueTypeName =
        post.queueType &&
        typeof post.queueType === "object" &&
        "name" in post.queueType &&
        typeof post.queueType.name === "string"
          ? post.queueType.name
          : "unassigned";

      return {
        caption: "", // Empty caption - user can add content
        fileUrl: fileUrl.length > 0 ? (fileUrl[0] ?? "") : "",
        queueType: queueTypeName,
        scheduledFor: "",
        originalPostId: post.id,
        originalEventId: eventId,
        originalEventPubkey: eventPubkey,
        isQuotePost: true,
        originalCaption: caption,
      };
    });

    return json({ quotePostData: quotePostsData });
  }

  // Handle single repost
  if (validatedData._action === "repost") {
    try {
      // Type narrowing for repost action
      const repostData = validatedData._action === "repost" ? validatedData : null;
      if (!repostData) {
        return json({ error: "Invalid action" }, { status: 400 });
      }
      // Get the original post data
      const postsData = await getPostsByIds({ ids: [repostData.postId], userId });
      if (!postsData || postsData.length === 0) {
        const { NotFoundError } = await import("~/lib/errors");
        throw new NotFoundError("Post not found", { postId: repostData.postId, userId });
      }

      const originalPost = postsData[0];
      if (!originalPost) {
        return json({ error: "Post not found" }, { status: 404 });
      }
      const originalEvent = originalPost.signedEvent;

      if (
        !originalEvent ||
        typeof originalEvent !== "object" ||
        !("id" in originalEvent) ||
        !("pubkey" in originalEvent)
      ) {
        return json({ error: "Invalid event data" }, { status: 400 });
      }

      const eventId =
        typeof originalEvent["id"] === "string"
          ? originalEvent["id"]
          : String(originalEvent["id"]);
      const eventPubkey =
        typeof originalEvent["pubkey"] === "string"
          ? originalEvent["pubkey"]
          : String(originalEvent["pubkey"]);

      // Create kind 6 repost event structure according to NIP-18
      const kind6EventData = {
        kind: 6,
        content: "", // Empty content as recommended by NIP-18
        tags: [
          // e tag with the id of the note being reposted and relay URL
          ["e", eventId, "wss://relay.primal.net"],
          // p tag with the pubkey of the event being reposted
          ["p", eventPubkey],
        ],
        created_at: Math.floor(Date.now() / 1000),
      };

      // Return the unsigned event data for client-side signing
      return json({
        repostEventData: kind6EventData,
        originalPost: originalPost,
      });
    } catch (error) {
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }

  // Handle single quote
  if (validatedData._action === "quote") {
    try {
      // Type narrowing for quote action
      const quoteData = validatedData._action === "quote" ? validatedData : null;
      if (!quoteData) {
        return json({ error: "Invalid action" }, { status: 400 });
      }
      // Get the original post data
      const postsData = await getPostsByIds({ ids: [quoteData.postId], userId });
      if (!postsData || postsData.length === 0) {
        const { NotFoundError } = await import("~/lib/errors");
        throw new NotFoundError("Post not found", { postId: quoteData.postId, userId });
      }

      const originalPost = postsData[0];
      if (!originalPost) {
        return json({ error: "Post not found" }, { status: 404 });
      }
      const originalEvent = originalPost.signedEvent;

      if (
        !originalEvent ||
        typeof originalEvent !== "object" ||
        !("id" in originalEvent) ||
        !("pubkey" in originalEvent)
      ) {
        return json({ error: "Invalid event data" }, { status: 400 });
      }

      const eventId =
        typeof originalEvent["id"] === "string"
          ? originalEvent["id"]
          : String(originalEvent["id"]);
      const eventPubkey =
        typeof originalEvent["pubkey"] === "string"
          ? originalEvent["pubkey"]
          : String(originalEvent["pubkey"]);

      // Create quote post data for bulk posts page
      const fileUrl =
        "fileUrl" in originalPost
          ? Array.isArray(originalPost.fileUrl)
            ? originalPost.fileUrl[0]
            : typeof originalPost.fileUrl === "string"
              ? originalPost.fileUrl
              : ""
          : "";
      const queueTypeName =
        originalPost.queueType &&
        typeof originalPost.queueType === "object" &&
        "name" in originalPost.queueType &&
        typeof originalPost.queueType.name === "string"
          ? originalPost.queueType.name
          : "unassigned";
      const caption =
        "caption" in originalPost && typeof originalPost.caption === "string"
          ? originalPost.caption
          : "";
      const originalPostId =
        "id" in originalPost && typeof originalPost.id === "string"
          ? originalPost.id
          : "";

      const quotePostData = {
        caption: "", // Empty caption - user can add content
        fileUrl,
        queueType: queueTypeName,
        scheduledFor: "",
        originalPostId: originalPostId,
        originalEventId: eventId,
        originalEventPubkey: eventPubkey,
        isQuotePost: true,
        originalCaption: caption,
      };

      return json({ quotePostData: [quotePostData] });
    } catch (error) {
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

/**
 * Scheduled posts action handlers
 * Centralized action processing for scheduled posts page
 */

import {
  scheduledActionSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import { deleteLongFormPost } from "~/models/longformpost.server";
import { deletePost } from "~/models/post.commands.server";

export async function handleScheduledAction(
  formData: FormData,
  userId: string,
) {
  const result = validateFormDataOrRespond(formData, scheduledActionSchema);
  if (!result.success) {
    return result.response;
  }

  const { _action } = result.data;

  if (_action === "delete") {
    await deletePost({ id: result.data.postId, userId });
    return { success: true };
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: result.data.postId, userId });
    return { success: true };
  }

  if (_action === "bulkDelete") {
    await Promise.all(
      result.data.postIds.map((id: string) => deletePost({ id, userId })),
    );
    return { success: true };
  }

  if (_action === "bulkDeleteLongForm") {
    await Promise.all(
      result.data.postIds.map((id: string) =>
        deleteLongFormPost({ id, userId }),
      ),
    );
    return { success: true };
  }

  if (_action === "bulkDeleteMixed") {
    const promises = result.data.itemData.map((item) => {
      if (item.type === "post") {
        return deletePost({ id: item.id, userId });
      } else {
        return deleteLongFormPost({ id: item.id, userId });
      }
    });
    await Promise.all(promises);
    return { success: true };
  }

  return { error: "Invalid action" };
}

/**
 * Scheduled Posts Service
 *
 * Handles scheduled posts data loading and actions
 */

import { json } from "@remix-run/node";

import {
  getUserById,
  getQueueTypes,
  getUserHashTagPresets,
} from "~/features/user";
import {
  enqueuePostJob as schedulePost,
  cancelPostJob as cancelScheduledPost,
} from "~/infra/queue";
import { logError } from "~/lib/error-logger.server";
import {
  getScheduledLongFormPosts,
  deleteLongFormPost,
  updateLongFormPost,
  getLongFormPost as getLongFormPostModel,
} from "~/models/longformpost.server";
import {
  deletePost,
  reschedulePost,
  updatePost,
} from "~/models/post.commands.server";
import { getScheduledPosts, getPostById } from "~/models/post.queries.server";

import { combineContent } from "../combined.server";
import { convertPrismaQueueTypeToQueueType } from "../types";
import type { PostData, LongFormPostData } from "../types";

/**
 * Get scheduled posts dashboard data
 */
export async function getScheduledDashboardData({
  userId,
  queueType,
}: {
  userId: string;
  queueType: string;
}) {
  const [posts, allLongformPosts, user, queueTypesRaw, hashTagPresetsRaw] =
    await Promise.all([
      getScheduledPosts({ userId, queueType }),
      getScheduledLongFormPosts({ userId }),
      getUserById(userId),
      getQueueTypes(userId),
      getUserHashTagPresets(userId),
    ]);

  const queueTypes = Array.isArray(queueTypesRaw) ? queueTypesRaw : [];
  const hashTagPresets = Array.isArray(hashTagPresetsRaw)
    ? hashTagPresetsRaw
    : [];

  // Filter longform posts by queue type if specific queue is selected
  const longformPosts =
    queueType === "all"
      ? allLongformPosts
      : allLongformPosts.filter((post) => post.queueType?.name === queueType);

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    const signedEventValue: PostData["signedEvent"] =
      post.signedEvent as PostData["signedEvent"];
    const nostrEventValue: PostData["nostrEvent"] =
      post.nostrEvent as PostData["nostrEvent"];
    const postData: PostData = {
      ...rest,
      queueType: convertPrismaQueueTypeToQueueType(queueType),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return postData;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformPosts.map((post) => {
    const signedEventValue: LongFormPostData["signedEvent"] =
      post.signedEvent as LongFormPostData["signedEvent"];
    const nostrEventValue: LongFormPostData["nostrEvent"] =
      post.nostrEvent as LongFormPostData["nostrEvent"];
    const longformPostData: LongFormPostData = {
      ...post,
      queueType: convertPrismaQueueTypeToQueueType(
        "queueType" in post ? post.queueType : undefined,
      ),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return longformPostData;
  });

  // Combine posts and longform posts for the "All" tab
  const allContent = combineContent(
    postsData,
    longformPostsData,
    "scheduledFor",
    "asc",
  );

  return {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes: queueTypes.filter(
      (qt: unknown) =>
        typeof qt === "object" &&
        qt !== null &&
        "isEnabled" in qt &&
        qt.isEnabled !== false,
    ),
    selectedQueueType: queueType,
    hashTagPresets,
  };
}

/**
 * Handle scheduled post actions (delete, reschedule, edit)
 */
export async function handleScheduledPostAction(
  formData: FormData,
  userId: string,
) {
  const postId = formData.get("postId") as string;
  const _action = formData.get("_action");

  if (_action === "delete") {
    await deletePost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "bulkDelete") {
    const postIdsValue = formData.get("postIds");
    const postIdsStr = postIdsValue ? String(postIdsValue) : "[]";
    let postIds: string[] = [];
    try {
      const parsed: unknown = JSON.parse(postIdsStr);
      postIds = Array.isArray(parsed)
        ? parsed.filter((id: unknown): id is string => typeof id === "string")
        : [];
    } catch {
      postIds = [];
    }
    await Promise.all(postIds.map((id: string) => deletePost({ id, userId })));
    return json({ success: true });
  }

  if (_action === "bulkDeleteLongForm") {
    const postIdsValue = formData.get("postIds");
    const postIdsStr = postIdsValue ? String(postIdsValue) : "[]";
    let postIds: string[] = [];
    try {
      const parsed: unknown = JSON.parse(postIdsStr);
      postIds = Array.isArray(parsed)
        ? parsed.filter((id: unknown): id is string => typeof id === "string")
        : [];
    } catch {
      postIds = [];
    }
    await Promise.all(
      postIds.map((id: string) => deleteLongFormPost({ id, userId })),
    );
    return json({ success: true });
  }

  if (_action === "bulkDeleteMixed") {
    const itemDataValue = formData.get("itemData");
    const itemDataStr = itemDataValue ? String(itemDataValue) : "[]";
    let itemData: Array<{ id: string; type: string }> = [];
    try {
      const parsed: unknown = JSON.parse(itemDataStr);
      if (Array.isArray(parsed)) {
        itemData = parsed.filter(
          (item: unknown): item is { id: string; type: string } =>
            typeof item === "object" &&
            item !== null &&
            "id" in item &&
            "type" in item &&
            typeof (item as { id: unknown; type: unknown }).id === "string" &&
            typeof (item as { id: unknown; type: unknown }).type === "string",
        );
      }
    } catch {
      itemData = [];
    }
    const promises = itemData.map((item: { id: string; type: string }) => {
      if (item.type === "post") {
        return deletePost({ id: item.id, userId });
      } else {
        return deleteLongFormPost({ id: item.id, userId });
      }
    });
    await Promise.all(promises);
    return json({ success: true });
  }

  // Reschedule a regular post (with optional re-signed event)
  if (_action === "reschedule") {
    const newTime = formData.get("newTime") as string;
    const overrideQueue = formData.get("overrideQueue") === "true";
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = formData.get("queueTypeId") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getPostById({ id: postId, userId });
    if (!originalPost) {
      return json({ error: "Post not found" }, { status: 404 });
    }

    await cancelScheduledPost(postId);

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updatedPost = await reschedulePost({
      id: postId,
      userId,
      newScheduledFor: newTime,
      overrideQueue,
      queueTypeId,
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    if (parsedSignedEvent && parsedNostrEvent) {
      await schedulePost(postId, userId, parsedSignedEvent, parseInt(newTime));
      return json({ success: true, post: updatedPost, signed: true });
    }

    return json({ success: true, post: updatedPost, needsSigning: true });
  }

  // Reschedule a longform post (with optional re-signed event)
  if (_action === "rescheduleLongform") {
    const newTime = formData.get("newTime") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getLongFormPostModel({ id: postId, userId });
    if (!originalPost) {
      return json({ error: "Longform post not found" }, { status: 404 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updatedPost = await updateLongFormPost({
      id: postId,
      userId,
      publishedAt: new Date(parseInt(newTime) * 1000),
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    return json({
      success: true,
      post: updatedPost,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a regular post's content/media/hashtags and re-sign
  if (_action === "editPost") {
    const caption = (formData.get("caption") ?? "") as string;
    const fileUrl = (formData.get("fileUrl") ?? "") as string;
    const hashtags = (formData.get("hashtags") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = (formData.get("queueTypeId") as string) ?? null;
    const scheduledFor = (formData.get("scheduledFor") as string) ?? null;
    const hashTagPresetId = (formData.get("hashTagPresetId") as string) ?? null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    let parsedFileUrl: string[] = [];
    if (fileUrl) {
      try {
        const parsed: unknown = JSON.parse(fileUrl);
        parsedFileUrl = Array.isArray(parsed)
          ? parsed.filter(
              (item: unknown): item is string => typeof item === "string",
            )
          : [];
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          fileUrl,
          message: "Error parsing fileUrl",
        });
        parsedFileUrl = [];
      }
    }

    const updated = await updatePost({
      id: postId,
      userId,
      data: {
        caption,
        fileUrl: parsedFileUrl,
        tags: hashtags
          ? hashtags
              .toString()
              .split(" ")
              .filter((tag) => tag.trim())
          : [],
        queueTypeId,
        scheduledFor: scheduledFor ? String(Number(scheduledFor)) : undefined,
        signedEvent: parsedSignedEvent ?? undefined,
        nostrEvent: parsedNostrEvent ?? undefined,
        hashTagPresetId,
      },
    });

    if (scheduledFor && parsedSignedEvent) {
      await cancelScheduledPost(postId);
      await schedulePost(
        postId,
        userId,
        parsedSignedEvent,
        Number(scheduledFor),
      );
    }

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a longform post's content and re-sign
  if (_action === "editLongform") {
    const title = (formData.get("title") ?? "") as string;
    const summary = (formData.get("summary") ?? "") as string;
    const content = (formData.get("content") ?? "") as string;
    const image = (formData.get("image") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const scheduledFor = (formData.get("scheduledFor") as string) ?? null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: "Error parsing signed events",
        });
      }
    }

    const updated = await updateLongFormPost({
      id: postId,
      userId,
      title,
      summary,
      content,
      image,
      publishedAt: scheduledFor
        ? new Date(Number(scheduledFor) * 1000)
        : undefined,
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

import { env } from "~/lib/env.server";
import { fetchJsonWithRetry } from "~/lib/fetch.server";

export interface PostStats {
  likes: number;
  replies: number;
  mentions: number;
  reposts: number;
  zaps: number;
  satszapped: number;
}

export async function getPostStats(
  eventIds: string[],
): Promise<Record<string, PostStats>> {
  let stats: Record<string, PostStats> = {};

  if (eventIds.length === 0) {
    return stats;
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    // Fetch stats for each event ID
    const statsPromises = eventIds.map(async (eventId) => {
      // Read directly from process.env to support test environment changes
      const primalUrl =
        process.env["PRIMAL_CACHING_URL"] ?? env.PRIMAL_CACHING_URL;
      if (!primalUrl) {
        throw new Error("PRIMAL_CACHING_URL environment variable is not set");
      }
      const response = await fetchJsonWithRetry<unknown[]>(primalUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          requestType: "thread_view",
          params: {
            event_id: eventId,
          },
        }),
        timeout: 5000, // 5 seconds for cache requests
        maxRetries: 1, // Single retry for stats
      });

      const data: unknown[] = Array.isArray(response) ? response : [];
      // Find the stats event in the response array
      // The stats event has kind 10000100 and contains engagement metrics
      const statsEvent: unknown = data.find((event: unknown) => {
        if (!Array.isArray(event) || event.length < 3 || event[0] !== "EVENT")
          return false;
        const eventDataRaw: unknown = event[2];
        const eventData: unknown = eventDataRaw;
        if (
          !eventData ||
          typeof eventData !== "object" ||
          Array.isArray(eventData)
        )
          return false;
        const eventTyped = eventData as { kind?: unknown; content?: unknown };
        return (
          typeof eventTyped.kind === "number" &&
          eventTyped.kind === 10000100 &&
          eventTyped.content &&
          typeof eventTyped.content === "string" &&
          eventTyped.content.includes(eventId)
        );
      });

      if (
        Array.isArray(statsEvent) &&
        statsEvent[2] &&
        typeof statsEvent[2] === "object" &&
        !Array.isArray(statsEvent[2])
      ) {
        const eventData = statsEvent[2] as {
          kind?: unknown;
          content?: unknown;
        };
        if (eventData.content && typeof eventData.content === "string") {
          let content: {
            likes?: number;
            replies?: number;
            mentions?: number;
            reposts?: number;
            zaps?: number;
            satszapped?: number;
          } = {};
          try {
            const parsed: unknown = JSON.parse(eventData.content ?? "");
            if (
              typeof parsed === "object" &&
              parsed !== null &&
              !Array.isArray(parsed)
            ) {
              const parsedObj = parsed as Record<string, unknown>;
              content = {
                likes:
                  typeof parsedObj["likes"] === "number"
                    ? parsedObj["likes"]
                    : undefined,
                replies:
                  typeof parsedObj["replies"] === "number"
                    ? parsedObj["replies"]
                    : undefined,
                mentions:
                  typeof parsedObj["mentions"] === "number"
                    ? parsedObj["mentions"]
                    : undefined,
                reposts:
                  typeof parsedObj["reposts"] === "number"
                    ? parsedObj["reposts"]
                    : undefined,
                zaps:
                  typeof parsedObj["zaps"] === "number"
                    ? parsedObj["zaps"]
                    : undefined,
                satszapped:
                  typeof parsedObj["satszapped"] === "number"
                    ? parsedObj["satszapped"]
                    : undefined,
              };
            }
          } catch {
            // If parsing fails, use empty content
          }
          return {
            [eventId]: {
              likes: content.likes ?? 0,
              replies: content.replies ?? 0,
              mentions: content.mentions ?? 0,
              reposts: content.reposts ?? 0,
              zaps: content.zaps ?? 0,
              satszapped: content.satszapped ?? 0,
            },
          };
        }
      }

      const statsValue: PostStats = {
        likes: 0,
        replies: 0,
        mentions: 0,
        reposts: 0,
        zaps: 0,
        satszapped: 0,
      };
      const result: Record<string, PostStats> = {
        [eventId]: statsValue,
      };
      return result;
    });

    const statsResults = await Promise.all(statsPromises);
    stats = statsResults.reduce((acc, curr) => ({ ...acc, ...curr }), {});
    clearTimeout(timeoutId);
  } catch (error) {
    console.error("Error fetching stats:", error);
    // Initialize empty stats object with 0 values for each post
    const emptyStats: Record<string, PostStats> = {};
    stats = eventIds.reduce((acc, eventId) => {
      acc[eventId] = {
        likes: 0,
        replies: 0,
        mentions: 0,
        reposts: 0,
        zaps: 0,
        satszapped: 0,
      };
      return acc;
    }, emptyStats);
  }

  return stats;
}

