    pendingChildren: UserAccountInfo[];
  };
  mutedList: MutedList | null;
  filterMuted: boolean;
  hidePostsFromLowTrustUsers: boolean;
}

/**
 * Load all settings data
 */
export async function loadSettingsData(
  userId: string,
): Promise<SettingsLoaderData> {
  // Get subscription and plan name for gating Accounts tab
  const currentSub = await getUserSubscription(userId);
  const planName = currentSub?.Plan?.name ?? null;

  const userRecord = await getUserBasicInfo(userId);
  const myNpub = userRecord?.npub as string;
  const isChild = !!userRecord?.isChild;
  const hasAccountsAccess =
    isChild || planName === "Founder" || planName === "Premium";

  // Load all settings data in parallel
  const [
    timezone,
    relays,
    giveawayBlacklist,
    showHashTagsInPosts,
    scheduleIntervals,
    queueTypes,
    uploadProvider,
    enableMirrorBlossom,
    mirrorUploadUrls,
    hashTagPresets,
    nwcSettings,
    mutedList,
    filterMuted,
    hidePostsFromLowTrustUsers,
  ] = await Promise.all([
    getUserTimezone(userId),
    getUserRelays(userId),
    getGiveawayBlacklist(userId),
    getShowHashTagsInPosts(userId),
    getScheduleInterval(userId),
    getQueueTypes(userId),
    getUserUploadProvider(userId),
    getUserEnableMirrorBlossom(userId),
    getUserMirrorUploadUrls(userId),
    getUserHashTagPresets(userId),
    getUserNWC(userId),
    getUserMutedList(userId),
    getUserFilterMuted(userId),
    getUserHidePostsFromLowTrustUsers(userId),
  ]);

  // Accounts data
  let accounts: SettingsLoaderData["accounts"];
  if (isChild) {
    const parentUser = userRecord?.parentNpub
      ? await getUserByNpubWithProfile(userRecord.parentNpub)
      : null;
    accounts = {
      isChild: true,
      parentNpub: parentUser?.npub ?? null,
      parentUser: parentUser
        ? {
            ...parentUser,
            id: parentUser.npub, // Add required id field
            nostrProfile: parentUser.nostrProfile,
          }
        : null,
      confirmedChildren: [],
      pendingChildren: [],
    };
  } else {
    const parentNpub = myNpub;
    const [confirmedChildren, pendingChildren] = await Promise.all([
      parentNpub
        ? getConfirmedChildrenForParent(parentNpub)
        : Promise.resolve([]),
      parentNpub
        ? getPendingChildrenForParent(parentNpub)
        : Promise.resolve([]),
    ]);
    accounts = {
      isChild: false,
      parentNpub,
      parentUser: null,
      confirmedChildren,
      pendingChildren,
    };
  }

  // Get subscription information
  const [subscription, allPlans, paymentHistory] = await Promise.all([
    getUserSubscription(userId),
    getAllPlans(),
    getUserPaymentHistory(userId),
  ]);

  return {
    timezone,
    relays,
    showHashTagsInPosts,
    giveawayBlacklist,
    scheduleIntervals,
    queueTypes: queueTypes.map((qt) => ({
      id: qt.id,
      name: qt.name,
      color: qt.color,
      description: qt.description,
      scheduleType: qt.scheduleType,
      scheduleConfig:
        qt.scheduleConfig &&
        typeof qt.scheduleConfig === "object" &&
        !Array.isArray(qt.scheduleConfig)
          ? (qt.scheduleConfig as ScheduleConfig)
          : undefined,
      isEnabled: qt.isEnabled,
      userId: qt.userId,
    })),
    uploadProvider,
    enableMirrorBlossom,
    mirrorUploadUrls,
    hashTagPresets: hashTagPresets as unknown as typeof hashTagPresets,
    nwcEnabled: nwcSettings.enabled,
    maskedNwcString: nwcSettings.maskedString ?? null,
    nwcLastUsed: nwcSettings.lastUsed ?? null,
    subscription: subscription
      ? {
          id: subscription.id,
          planId: subscription.planId ?? null,
          status: subscription.status as string,
          startDate: subscription.startDate,
          currentPeriodEnd: subscription.currentPeriodEnd,
          nextPaymentDue: subscription.nextPaymentDue,
          cancelAtPeriodEnd: subscription.cancelAtPeriodEnd,
          plan: subscription.Plan
            ? {
                id: subscription.Plan.id,
                name: subscription.Plan.name,
                price: Number(subscription.Plan.price),
                enableLifetimeAccess: subscription.Plan.enableLifetimeAccess,
              }
            : null,
        }
      : null,
    availablePlans: allPlans.map((plan) => ({
      id: plan.id,
      name: plan.name,
      price: Number(plan.price),
      enableLifetimeAccess: plan.enableLifetimeAccess,
    })),
    paymentHistory: paymentHistory.map((payment) => ({
      id: payment.id,
      amount: payment.amount,
      amountUsd: payment.amountUsd ? Number(payment.amountUsd) : null,
      description: payment.description,
      paidAt: payment.paidAt,
      paymentMethod: payment.paymentMethod,
      paymentHash: payment.paymentHash ?? "",
      planName: payment.Subscription?.Plan?.name ?? undefined,
      planPrice: payment.Subscription?.Plan?.price
        ? Number(payment.Subscription.Plan.price)
        : undefined,
    })),
    isChild,
    hasAccountsAccess,
    accounts,
    mutedList,
    filterMuted,
    hidePostsFromLowTrustUsers,
  };
}

import { useFetcher, useLocation } from "@remix-run/react";
import { useState, useEffect, useRef } from "react";

import { type Asset, type AssetFetcher } from "~/features/assets";
import {
  resizeImageClient,
  uploadFile,
  uploadMultipleFiles,
} from "~/features/upload";

import type { Template, ScheduleData, TemplateFetcher } from "../types";

interface UseTemplatesStateProps {
  searchTerm: string;
}

/**
 * Custom hook for managing templates/assets state and operations
 */
export function useTemplatesState({ searchTerm }: UseTemplatesStateProps) {
  const [selectedTemplate, setSelectedTemplate] = useState<Template | null>(
    null,
  );
  const [activeTab, setActiveTab] = useState<"assets" | "upload">("assets");
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [searchInput, setSearchInput] = useState(searchTerm ?? "");
  const [bulkUploadFiles, setBulkUploadFiles] = useState<File[]>([]);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [uploadProvider, setUploadProvider] = useState<string | null>(null);
  const [singleFileUploading, setSingleFileUploading] = useState(false);
  const [bulkFileUploading, setBulkFileUploading] = useState(false);

  const textAssetFormRef = useRef<HTMLFormElement>(null);
  const imageAssetFormRef = useRef<HTMLFormElement>(null);
  const location = useLocation();

  const deleteFetcher = useFetcher();
  const scheduleFetcher: TemplateFetcher = useFetcher<{
    scheduleData?: ScheduleData[];
  }>();
  const assetFetcher = useFetcher<{
    success?: boolean;
    asset?: Asset;
    assets?: Asset[];
  }>() as AssetFetcher;

  // Fetch upload provider on component mount
  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch("/api/user-upload-provider");
        const dataRaw: unknown = await res.json();
        const data =
          typeof dataRaw === "object" &&
          dataRaw !== null &&
          !Array.isArray(dataRaw)
            ? (dataRaw as { provider?: unknown })
            : {};
        const provider =
          typeof data.provider === "string" ? data.provider : null;
        setUploadProvider(provider);
      } catch (err) {
        console.error("Failed to get upload provider:", err);
      }
    })();
  }, []);

  // Check if we're on a child route (edit page)
  const isOnChildRoute = location.pathname.includes("/edit/");

  // Handle schedule data response
  useEffect(() => {
    const fetcherData = scheduleFetcher.data;
    const scheduleData =
      fetcherData &&
      typeof fetcherData === "object" &&
      fetcherData !== null &&
      "scheduleData" in fetcherData
        ? fetcherData.scheduleData
        : undefined;
    if (scheduleData && Array.isArray(scheduleData)) {
      sessionStorage.setItem("repostData", JSON.stringify(scheduleData));
      window.location.href = "/dashboard/bulkposts?mode=recycle";
    }
  }, [scheduleFetcher.data]);

  // Handle successful asset creation
  useEffect(() => {
    const fetcherData = assetFetcher.data;
    if (
      fetcherData &&
      typeof fetcherData === "object" &&
      fetcherData !== null &&
      "success" in fetcherData &&
      fetcherData.success
    ) {
      if (
        "asset" in fetcherData &&
        fetcherData.asset &&
        typeof fetcherData.asset === "object" &&
        "assetType" in fetcherData.asset
      ) {
        const assetType =
          typeof fetcherData.asset.assetType === "string"
            ? fetcherData.asset.assetType
            : "asset";
        setToastMessage(
          `${assetType.toLowerCase()} asset created successfully!`,
        );
      } else if ("assets" in fetcherData && Array.isArray(fetcherData.assets)) {
        setToastMessage(
          `${fetcherData.assets.length} image assets uploaded successfully!`,
        );
      } else {
        setToastMessage("Asset created successfully!");
      }
      setShowToast(true);

      if (textAssetFormRef.current) {
        textAssetFormRef.current.reset();
      }
      if (imageAssetFormRef.current) {
        imageAssetFormRef.current.reset();
      }

      setBulkUploadFiles([]);
      setTimeout(() => setShowToast(false), 3000);
      window.location.reload();
    }
  }, [assetFetcher.data]);

  // Asset management ha??lers
  const handleAssetSelect = (assetId: string) => {
    setSelectedAssets((prev) =>
      prev.includes(assetId)
        ? prev.filter((id) => id !== assetId)
        : [...prev, assetId],
    );
  };

  const handleSelectAllAssets = (assets: Asset[]) => {
    if (selectedAssets.length === assets.length) {
      setSelectedAssets([]);
    } else {
      setSelectedAssets(assets.map((asset) => asset.id));
    }
  };

  const handleBulkPostAssets = (assets: Asset[]) => {
    if (selectedAssets.length === 0) return;

    const selectedAssetData = assets.filter((asset) =>
      selectedAssets.includes(asset.id),
    );

    const assetData = selectedAssetData.map((asset) => ({
      caption: asset.assetType === "TEXT" ? asset.content : (asset.title ?? ""),
      fileUrl:
        asset.assetType === "IMAGE" || asset.assetType === "VIDEO"
          ? asset.fileUrl
          : null,
      queueType: "unassigned",
      scheduledFor: new Date(Date.now() + 60 * 60 * 1000)
        .toISOString()
        .slice(0, 16),
    }));

    sessionStorage.setItem("repostData", JSON.stringify(assetData));
    window.location.href = "/dashboard/bulkposts?mode=recycle";
  };

  const handleBulkDeleteAssets = () => {
    if (selectedAssets.length === 0) return;

    if (
      !confirm(
        `Are you sure you want to delete ${selectedAssets.length} selected asset${selectedAssets.length > 1 ? "s" : ""}?`,
      )
    ) {
      return;
    }

    const formData = new FormData();
    formData.append("_action", "bulk_delete_assets");
    selectedAssets.forEach((assetId) => {
      formData.append("assetIds", assetId);
    });

    deleteFetcher.submit(formData, { method: "post" });
    setSelectedAssets([]);
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const url = new URL(window.location.href);
    if (searchInput.trim()) {
      url.searchParams.set("search", searchInput.trim());
    } else {
      url.searchParams.delete("search");
    }
    url.searchParams.delete("page");
    window.location.href = url.toString();
  };

  const handlePageChange = (newPage: number) => {
    setSelectedAssets([]);
    const url = new URL(window.location.href);
    if (newPage === 1) {
      url.searchParams.delete("page");
    } else {
      url.searchParams.set("page", newPage.toString());
    }
    window.location.href = url.toString();
  };

  const handleDeleteAsset = (
    e: React.MouseEvent<HTMLButtonElement>,
    _assetId: string,
  ) => {
    if (!confirm("Are you sure you want to dele?? this asset?")) {
      e.preventDefault();
    }
  };

  // Upload handlers
  const handleSingleFileUpload = async (
    e: React.FormEvent,
    form: HTMLFormElement,
  ) => {
    e.preventDefault();
    setSingleFileUploading(true);

    try {
      const formData = new FormData(form);
      const fileInput = form.querySelector(
        'input[type="file"]',
      ) as HTMLInputElement;
      const file = fileInput?.files?.[0];

      if (!file) {
        throw new Error("No file selected");
      }

      const processedFile = file.type.startsWith("image/")
        ? await resizeImageClient(file)
        : file;

      const uploadResult = await uploadFile(processedFile);

      if (!uploadResult.success) {
        throw new Error(uploadResult.error ?? "Upload failed");
      }

      const serverFormData = new FormData();
      serverFormData.append("_action", formData.get("_action") as string);
      serverFormData.append("title", formData.get("title") as string);
      serverFormData.append("tags", formData.get("tags") as string);
      serverFormData.append("uploadResult", JSON.stringify(uploadResult));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Upload error:", error);
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setSingleFileUploading(false);
    }
  };

  const handleBulkFileUpload = async () => {
    if (bulkUploadFiles.length === 0) return;

    setBulkFileUploading(true);

    try {
      const uploadResults = await uploadMultipleFiles(bulkUploadFiles);

      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        throw new Error(`Upload failed: ${errorMessages}`);
      }

      const bulkForm = document.querySelector(
        "form[data-bulk-form]",
      ) as HTMLFormElement;
      if (!bulkForm) throw new Error("Bulk form not found");

      const formData = new FormData(bulkForm);
      const serverFormData = new FormData();
      serverFormData.append("_action", "bulk_create_media_assets");
      serverFormData.append("uploadResults", JSON.stringify(uploadResults));

      const titles = formData.getAll("titles");
      const tags = formData.getAll("tags");
      titles.forEach((title) =>
        serverFormData.append("titles", title as string),
      );
      tags.forEach((tag) => serverFormData.append("tags", tag as string));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Bulk upload error:", error);
      const errorMessage =
        error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Bulk upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setBulkFileUploading(false);
    }
  };

  const handleBulkFileChange = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    if (e.target.files) {
      const selectedFiles = Array.from(e.target.files);

      try {
        const processedFiles = await Promise.all(
          selectedFiles.map(async (file) => {
            if (file.type.startsWith("image/")) {
              return await resizeImageClient(file);
            }
            return file;
          }),
        );
        setBulkUploadFiles(processedFiles);
      } catch (error) {
        console.error("Error processing media files:", error);
        setBulkUploadFiles(selectedFiles);
      }
    }
  };

  return {
    selectedTemplate,
    activeTab,
    selectedAssets,
    searchInput,
    bulkUploadFiles,
    showToast,
    toastMessage,
    uploadProvider,
    singleFileUploading,
    bulkFileUploading,
    textAssetFormRef,
    imageAssetFormRef,
    isOnChildRoute,
    deleteFetcher,
    scheduleFetcher,
    assetFetcher,
    setSelectedTemplate,
    setActiveTab,
    setSearchInput,
    handleAssetSelect,
    handleSelectAllAssets,
    handleBulkPostAssets,
    handleBulkDeleteAssets,
    handleSearch,
    handlePageChange,
    handleDeleteAsset,
    handleSingleFileUpload,
    handleBulkFileUpload,
    handleBulkFileChange,
  };
}

/**
 * Template edit service layer
 * Handles template editing operations
 */

import { json, redirect } from "@remix-run/node";

import { ValidationError } from "~/lib/errors";
import {
  templateEditActionSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import {
  getTemplateById,
  updateTemplate,
  deleteTemplate,
  removePostFromTemplate,
} from "~/models/template.server";

/**
 * Load template data for editing
 */
export async function loadTemplateEditData(templateId: string, userId: string) {
  if (!templateId) {
    throw new ValidationError("Template ID is required");
  }

  const template = await getTemplateById({ id: templateId, userId });

  if (!template) {
    throw new ValidationError("Template not found", { templateId, userId });
  }

  return { template };
}

/**
 * Handle template edit actions
 */
export async function handleTemplateEditAction(
  formData: FormData,
  templateId: string,
  userId: string,
) {
  if (!templateId) {
    throw new ValidationError("Template ID is required");
  }

  const result = validateFormDataOrRespond(formData, templateEditActionSchema);
  if (!result.success) {
    return result.response;
  }

  const { _action } = result.data;

  if (_action === "updateName") {
    const updateData = result.data._action === "updateName" ? result.data : null;
    if (!updateData) {
      return json({ error: "Invalid action" }, { status: 400 });
    }

    await updateTemplate({
      id: templateId,
      userId,
      name: updateData.name,
    });

    return json({ success: true });
  }

  if (_action === "removePost") {
    const removeData = result.data._action === "removePost" ? result.data : null;
    if (!removeData) {
      return json({ error: "Invalid action" }, { status: 400 });
    }

    await removePostFromTemplate({
      templateId,
      postId: removeData.postId,
      userId,
    });

    return json({ success: true });
  }

  if (_action === "delete") {
    await deleteTemplate({
      id: templateId,
      userId,
    });

    return json({ success: true });
  }

  if (_action === "deleteTemplate") {
    await deleteTemplate({ id: templateId, userId });
    return redirect("/dashboard/templates");
  }

  if (_action === "schedule") {
    const template = await getTemplateById({ id: templateId, userId });

    if (!template) {
      return json({ error: "Template not found" }, { status: 404 });
    }

    // Prepare template data for scheduling (similar to repost mode)
    const localDate = new Date();
    localDate.setHours(localDate.getHours() + 1);

    const templateData = template.posts.map((post, index) => {
      const scheduleDate = new Date(localDate);
      scheduleDate.setHours(scheduleDate.getHours() + index);

      return {
        caption: post.caption ?? "",
        fileUrl: post.fileUrl,
        queueType: post.queueTypeId ?? "unassigned",
        scheduledFor: scheduleDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    });

    return json({ scheduleData: templateData });
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

/**
 * Templates action handlers
 * Centralized action processing for templates page
 */

import { AssetType } from "@prisma/client";

import {
  templatesActionSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import { createAsset, deleteAsset } from "~/models/asset.server";
import { deleteTemplate, getTemplates } from "~/models/template.server";

export async function handleTemplatesAction(
  formData: FormData,
  userId: string,
) {
  const result = validateFormDataOrRespond(formData, templatesActionSchema);
  if (!result.success) {
    return result.response;
  }

  const { _action } = result.data;

  if (_action === "delete") {
    const deleteData = result.data._action === "delete" ? result.data : null;
    if (!deleteData) {
      return { error: "Invalid action" };
    }
    await deleteTemplate({ id: deleteData.templateId, userId });
    return { success: true };
  }

  if (_action === "delete_asset") {
    const deleteData = result.data._action === "delete_asset" ? result.data : null;
    if (!deleteData) {
      return { error: "Invalid action" };
    }
    await deleteAsset({ id: deleteData.assetId, userId });
    return { success: true };
  }

  if (_action === "create_text_asset") {
    const textData = result.data._action === "create_text_asset" ? result.data : null;
    if (!textData) {
      return { error: "Invalid action" };
    }
    const asset = await createAsset({
      userId,
      title: textData.title,
      content: textData.content,
      tags: textData.tags,
      assetType: AssetType.TEXT,
    });

    return { success: true, asset };
  }

  if (
    _action === "create_image_asset" ||
    _action === "create_video_asset" ||
    _action === "create_media_asset"
  ) {
    const mediaData =
      result.data._action === "create_image_asset" ||
      result.data._action === "create_video_asset" ||
      result.data._action === "create_media_asset"
        ? result.data
        : null;
    if (!mediaData) {
      return { error: "Invalid action" };
    }

    // These properties are validated by Zod, so they're safe to access
    const fileUrl = mediaData.uploadResult.file.url;
    const mimeType = mediaData.uploadResult.file.mimeType ?? "";

    // Determine asset type based on file URL extension or mime type
    let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO =
      AssetType.IMAGE;
    const lower = fileUrl.toLowerCase();
    const videoExtensions = [
      ".mp4",
      ".webm",
      ".ogg",
      ".mov",
      ".avi",
      ".mkv",
      ".m4v",
    ];

    if (
      mimeType.startsWith("video/") ||
      videoExtensions.some((ext) => lower.includes(ext))
    ) {
      assetType = AssetType.VIDEO;
    }

    const asset = await createAsset({
      userId,
      title: mediaData.title,
      fileUrl,
      tags: mediaData.tags,
      assetType,
    });

    return { success: true, asset };
  }

  if (
    _action === "bulk_create_image_assets" ||
    _action === "bulk_create_media_assets"
  ) {
    const bulkData =
      result.data._action === "bulk_create_image_assets" ||
      result.data._action === "bulk_create_media_assets"
        ? result.data
        : null;
    if (!bulkData) {
      return { error: "Invalid action" };
    }

    // Check for failed uploads
    const failedUploads = bulkData.uploadResults.filter(
      (result) => !result.success,
    );
    if (failedUploads.length > 0) {
      return { error: "Some uploads failed" };
    }

    const assets = await Promise.all(
      bulkData.uploadResults.map(async (uploadResult, index: number) => {
        if (!uploadResult.file?.url) {
          throw new Error("File upload failed");
        }
        // These properties are validated by Zod, so they're safe to access
        const fileUrl = uploadResult.file.url;
        const mimeType = uploadResult.file.mimeType ?? "";

        // Determine asset type based on file URL extension or mime type
        let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO =
          AssetType.IMAGE;
        const lower = fileUrl.toLowerCase();
        const videoExtensions = [
          ".mp4",
          ".webm",
          ".ogg",
          ".mov",
          ".avi",
          ".mkv",
          ".m4v",
        ];

        if (
          mimeType.startsWith("video/") ||
          videoExtensions.some((ext) => lower.includes(ext))
        ) {
          assetType = AssetType.VIDEO;
        }

        const title =
          bulkData.titles[index] ??
          `${assetType === AssetType.VIDEO ? "Video" : "Image"} ${index + 1}`;
        const tagsString = bulkData.tags[index] ?? "";
        const tags = tagsString
          ? tagsString
              .split(",")
              .map((tag) => tag.trim())
              .filter(Boolean)
          : [];

        return createAsset({
          userId,
          title,
          fileUrl,
          tags,
          assetType,
        });
      }),
    );

    return { success: true, assets };
  }

  if (_action === "bulk_delete_assets") {
    const bulkDeleteData =
      result.data._action === "bulk_delete_assets" ? result.data : null;
    if (!bulkDeleteData) {
      return { error: "Invalid action" };
    }

    await Promise.all(
      bulkDeleteData.assetIds.map((assetId) =>
        deleteAsset({ id: assetId, userId }),
      ),
    );

    return { success: true, deletedCount: bulkDeleteData.assetIds.length };
  }

  if (_action === "schedule") {
    const scheduleData =
      result.data._action === "schedule" ? result.data : null;
    if (!scheduleData) {
      return { error: "Invalid action" };
    }
    const templates = await getTemplates({ userId });
    const template = templates.find((t) => t.id === scheduleData.templateId);

    if (!template) {
      return { error: "Template not found" };
    }

    // Prepare template data for scheduling
    const localDate = new Date();
    localDate.setHours(localDate.getHours() + 1);

    const templateData = template.posts.map((post, index) => {
      const scheduleDate = new Date(localDate);
      scheduleDate.setHours(scheduleDate.getHours() + index);

      return {
        caption: post.caption ?? "",
        fileUrl: post.fileUrl,
        queueType: post.queueTypeId ?? "unassigned",
        scheduledFor: scheduleDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    });

    return { scheduleData: templateData };
  }

  return { error: "Invalid action" };
}

import imageCompression from "browser-image-compression";
/**
 * Completely strips all metadata (EXIF, IPTC, XMP) from images and resizes them
 * for better performance and enhanced user privacy.
 *
 * @param file - The original image file to process
 * @param customOptions - Optional configuration overrides
 * @returns A new File object with metadata removed and size optimized
 */
export async function resizeImage(
  file: File,
  customOptions: {
    maxSizeMB?: number;
    maxWidthOrHeight?: number;
    useWebWorker?: boolean;
    fileType?: string;
    preserveExif?: boolean;
    [key: string]: unknown;
  } = {},
) {
  // Default options focused on privacy and optimization
  const options = {
    maxSizeMB: 0.1,
    maxWidthOrHeight: 1200,
    useWebWorker: true,
    fileType: "image/jpeg",
    // Explicitly disable EXIF preservation for privacy
    preserveExif: false,
    // Additional options
    ...customOptions,
  };

  try {
    // Step 1: Compress and resize the image with browser-image-compression
    const compressedFile = await imageCompression(file, options);

    // Step 2: Use canvas to create a completely clean image without metadata
    // This creates a new image data representation, effectively removing all metadata
    const cleanImage = await stripAllMetadata(compressedFile);

    // Step 3: Create a new file with the clean image data
    const baseName = file.name.split(".")[0] ?? file.name;
    return new File([cleanImage], `${baseName}.jpg`, {
      type: "image/jpeg",
      lastModified: new Date().getTime(), // Update last modified time
    });
  } catch (error) {
    console.error("Error processing image:", error);
    throw error;
  }
}

/**
 * Strips all metadata from an image by drawing it to a canvas and re-encoding it.
 * This process removes all embedded metadata (EXIF, IPTC, XMP) for enhanced privacy.
 *
 * @param file - The image file to strip metadata from
 * @returns A Blob containing the image data with all metadata removed
 */
async function stripAllMetadata(file: File): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();

    img.onload = () => {
      try {
        // Create a canvas element
        const canvas = document.createElement("canvas");
        canvas.width = img.width;
        canvas.height = img.height;

        // Draw the image to the canvas - this step strips all metadata
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          throw new Error("Could not get canvas context");
        }

        // Draw with a clean white background first to handle transparency
        ctx.fillStyle = "#FFFFFF";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        // Convert to blob with high quality JPEG (0.92 quality)
        canvas.toBlob(
          (blob) => {
            // Clean up the URL object
            URL.revokeObjectURL(url);

            if (blob) {
              resolve(blob);
            } else {
              reject(new Error("Failed to create image blob"));
            }
          },
          "image/jpeg",
          0.92,
        );
      } catch (error) {
        URL.revokeObjectURL(url);
        reject(error);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Failed to load image"));
    };

    img.src = url;
  });
}

import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import {
  unstable_composeUploadHandlers as composeUploadHandlers,
  unstable_createMemoryUploadHandler as createMemoryUploadHandler,
} from "@remix-run/node";
import { v4 as uuidv4 } from "uuid";

import { env } from "~/lib/env.server";
import { logError } from "~/lib/error-logger.server";

import {
  validateUpload,
  getS3ContentType,
  MAX_FILE_SIZE,
} from "./validation.server";

type UploadStream = AsyncIterable<Uint8Array>;

const uploadStreamToS3 = async (
  stream: UploadStream,
  key: string,
  s3Client: S3Client,
  filename: string,
  contentType?: string,
): Promise<string> => {
  // Convert stream to buffer (required for MIME type detection)
  const chunks: Buffer[] = [];
  for await (const chunk of stream) {
    chunks.push(
      Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk),
    );
  }
  const buffer = Buffer.concat(chunks);

  // Validate upload (MIME type and size)
  const validation = await validateUpload(buffer, filename, contentType);
  if (!validation.valid) {
    throw new Error(validation.error ?? "Upload validation failed");
  }

  // Get normalized content type
  const s3ContentType = getS3ContentType(validation.detectedMimeType!);

  const params = {
    Bucket: env.STORAGE_BUCKET!,
    Key: key,
    Body: buffer,
    ContentType: s3ContentType,
    // Server-side encryption
    ServerSideEncryption: "AES256" as const,
    // Explicit ACL - private by default
    ACL: "private" as const,
  };

  try {
    const command = new PutObjectCommand(params);
    await s3Client.send(command);
    // Construct the URL manually since v3 doesn't return Location
    return `https://${String(env.STORAGE_BUCKET ?? "")}.s3.${String(env.STORAGE_REGION ?? "")}.amazonaws.com/${key}`;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      key,
      bucket: env.STORAGE_BUCKET,
      message: "S3 upload error",
    });
    throw error;
  }
};

export function createUploadHandler(userId: string) {
  return composeUploadHandlers(
    async ({ name: _name, filename, contentType, data }) => {
      // Skip if no filename is provided
      if (!filename) {
        return;
      }

      try {
        const ext = filename.split(".").pop()?.toLowerCase() ?? "";
        const uniqueFilename = `${uuidv4()}.${ext}`;
        const key = `clients/${userId}/${uniqueFilename}`;

        const s3Client = createS3Client();

        return await uploadStreamToS3(
          data,
          key,
          s3Client,
          filename,
          contentType,
        );
      } catch (error) {
        logError(error instanceof Error ? error : new Error(String(error)), {
          userId,
          filename,
          message: "Upload handler error",
        });
        throw error;
      }
    },
    createMemoryUploadHandler({
      maxPartSize: MAX_FILE_SIZE, // Use same limit as validation
    }),
  );
}

// Upload a buffer directly to S3 (useful for processed files)
export async function uploadBufferToS3(
  buffer: Buffer,
  userId: string,
  filename?: string,
  customKey?: string,
  contentType?: string,
): Promise<string> {
  // Generate filename if not provided
  let finalFilename: string;
  if (filename) {
    const ext = filename.split(".").pop()?.toLowerCase() ?? "jpg";
    finalFilename = `${Date.now()}-${Math.random().toString(36).substring(2)}.${ext}`;
  } else {
    finalFilename = `${Date.now()}-${Math.random().toString(36).substring(2)}.jpg`;
  }

  // Validate upload (MIME type and size)
  const validation = await validateUpload(buffer, finalFilename, contentType);
  if (!validation.valid) {
    throw new Error(validation.error ?? "Upload validation failed");
  }

  // Use custom key or generate default one
  const key = customKey ?? `clients/${userId}/${finalFilename}`;

  try {
    const s3Client = createS3Client();

    // Get normalized content type
    const s3ContentType = getS3ContentType(validation.detectedMimeType!);

    const command = new PutObjectCommand({
      Bucket: env.STORAGE_BUCKET!,
      Key: key,
      Body: buffer,
      ContentType: s3ContentType,
      // Server-side encryption
      ServerSideEncryption: "AES256",
      // Explicit ACL - private by default
      ACL: "private",
    });

    await s3Client.send(command);

    // Return the full URL
    const bucket = env.STORAGE_BUCKET ?? "";
    const region = env.STORAGE_REGION ?? "";
    return `https://${bucket}.s3.${region}.amazonaws.com/${key}`;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      userId,
      filename: finalFilename,
      key,
      message: "S3 buffer upload error",
    });
    throw error;
  }
}

// Create S3 client with credentials
export function createS3Client() {
  return new S3Client({
    region: env.STORAGE_REGION!,
    credentials: {
      accessKeyId: env.STORAGE_ACCESS_KEY!,
      secretAccessKey: env.STORAGE_SECRET!,
    },
  });
}

// Specialized function for EditorJS image uploads
export async function uploadEditorJSImage(
  buffer: Buffer,
  userId: string,
  filename: string,
): Promise<string> {
  try {
    // Validate upload (MIME type and size)
    const validation = await validateUpload(buffer, filename);
    if (!validation.valid) {
      throw new Error(validation.error ?? "Upload validation failed");
    }

    // Generate a unique filename with timestamp and random string
    const ext = filename.split(".").pop()?.toLowerCase() ?? "jpg";
    const uniqueFilename = `editorjs-${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${ext}`;
    const key = `clients/${userId}/editorjs/${uniqueFilename}`;

    const s3Client = createS3Client();

    // Get normalized content type
    const s3ContentType = getS3ContentType(validation.detectedMimeType!);

    const command = new PutObjectCommand({
      Bucket: env.STORAGE_BUCKET!,
      Key: key,
      Body: buffer,
      ContentType: s3ContentType,
      // Server-side encryption
      ServerSideEncryption: "AES256",
      // Explicit ACL - private by default
      ACL: "private",
      // Add cache control for better performance
      CacheControl: "public, max-age=31536000",
    });

    await s3Client.send(command);

    // Return the full URL
    const bucket = env.STORAGE_BUCKET ?? "";
    const region = env.STORAGE_REGION ?? "";
    return `https://${bucket}.s3.${region}.amazonaws.com/${key}`;
  } catch (error) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      userId,
      filename,
      message: "EditorJS S3 upload error",
    });
    throw new Error(
      `Failed to upload image: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
}

// Type declaration for window.nostr is in app/types/window.d.ts

interface UploadResult {
  success: boolean;
  file?: {
    url: string;
    size: number;
    name: string;
    extension: string;
    sha256?: string;
    mimeType?: string;
    provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  };
  error?: string;
}

/**
 * Upload a file using the user's preferred upload provider (S3 or Blossom)
 * This function handles client-side uploads and server-side processing
 */
export async function uploadFile(file: File): Promise<UploadResult> {
  try {
    // First, check what upload provider the user prefers
    // Use utility function that can work outside React components
    const { getUploadProvider } = await import("~/lib/query");
    const data = await getUploadProvider();
    const uploadProvider = data.provider;
    const enableMirrorBlossom = data.enableMirrorBlossom;
    const mirrorUploadUrls = data.mirrorUploadUrls;

    if (
      uploadProvider === "BLOSSOM_PRIMAL" ||
      uploadProvider === "BLOSSOM_BLOSSTR" ||
      uploadProvider === "BLOSSOM"
    ) {
      return await uploadFileToBlossom(
        file,
        uploadProvider,
        enableMirrorBlossom,
        mirrorUploadUrls,
      );
    } else {
      return await uploadFileToS3(file);
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import(
      "~/lib/error-handler.client"
    );
    handleAsyncError(
      error,
      {
        component: "upload.client",
        action: "uploadFile",
      },
      false,
    ); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Upload failed",
    };
  }
}

/**
 * Upload file to S3 via server-side processing
 */
async function uploadFileToS3(file: File): Promise<UploadResult> {
  const formData = new FormData();
  formData.append("file", file);

  const response = await fetch("/api/upload", {
    method: "POST",
    body: formData,
  });

  const result = (await response.json()) as {
    success?: boolean;
    fileUrl?: string;
    error?: string;
  };

  if (result.success && result.fileUrl) {
    return {
      success: true,
      file: {
        url: result.fileUrl,
        size: file.size,
        name: file.name,
        extension: file.name.split(".").pop() ?? "",
        provider: "S3" as const,
      },
    };
  } else {
    return {
      success: false,
      error: result.error ?? "S3 upload failed",
    };
  }
}

/**
 * Upload file to Blossom via client-side processing
 */
async function uploadFileToBlossom(
  file: File,
  provider = "BLOSSOM_PRIMAL",
  enableMirrorBlossom = false,
  mirrorUploadUrls: string[] = [],
): Promise<UploadResult> {
  try {
    // Check if NOSTR is available
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not available. Please install a NOSTR browser extension like Alby, Amber, or nos2x.",
      );
    }

    // Dynamic import to avoid SSR issues
    const { BlossomUploader } = await import("@nostrify/nostrify/uploaders");

    // Determine primary server based on provider
    let primaryServerUrl;
    if (provider === "BLOSSOM_BLOSSTR") {
      primaryServerUrl = "https://blosstr.com";
    } else {
      // Default to Primal for BLOSSOM_PRIMAL or legacy BLOSSOM
      primaryServerUrl = "https://blossom.primal.net";
    }

    // Build servers array starting with primary server
    const servers = [primaryServerUrl];

    // Add mirror URLs if enabled and available
    if (
      enableMirrorBlossom &&
      Array.isArray(mirrorUploadUrls) &&
      mirrorUploadUrls.length > 0
    ) {
      servers.push(...mirrorUploadUrls);
    }

    // Create uploader with NOSTR signer and all servers
    const uploader = new BlossomUploader({
      servers: servers,
      signer: window.nostr,
    });

    // Upload the file
    const tags = await uploader.upload(file);

    // Validate that we got the expected tag format
    if (!Array.isArray(tags)) {
      throw new Error(
        "BlossomUploader returned invalid format - expected array of tags",
      );
    }

    // Send the result to server for processing
    const response = await fetch("/api/upload-blossom", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        tags,
        fileName: file.name,
      }),
    });

    const result = (await response.json()) as {
      success?: boolean;
      file?: { url: string };
      error?: string;
    };

    if (result.success && result.file) {
      return {
        success: true,
        file: {
          url: result.file.url,
          size: file.size,
          name: file.name,
          extension: file.name.split(".").pop() ?? "",
          provider: "BLOSSOM_PRIMAL" as const,
        },
      };
    } else {
      return {
        success: false,
        error: result.error ?? "Blossom upload failed",
      };
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import(
      "~/lib/error-handler.client"
    );
    handleAsyncError(
      error,
      {
        component: "upload.client",
        action: "uploadFileToBlossom",
        provider,
      },
      false,
    ); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Blossom upload failed",
    };
  }
}

/**
 * Upload multiple files
 */
export async function uploadMultipleFiles(
  files: File[],
): Promise<UploadResult[]> {
  const uploadPromises = files.map((file) => uploadFile(file));
  return Promise.all(uploadPromises);
}

/**
 * Upload file for EditorJS image tool compatibility
 * This specifically uses the EditorJS endpoint which handles image processing
 */
export async function uploadEditorJSImage(
  file: File,
): Promise<{ success: number; file?: { url: string } }> {
  try {
    const formData = new FormData();
    formData.append("image", file);

    const response = await fetch("/api/upload-editorjs-image", {
      method: "POST",
      body: formData,
    });

    const result = (await response.json()) as {
      success?: number;
      file?: { url: string };
      error?: { message?: string };
    };

    if (result.success === 1 && result.file) {
      return {
        success: 1,
        file: {
          url: result.file.url,
        },
      };
    } else {
      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        new Error(result.error?.message ?? "EditorJS upload failed"),
        {
          component: "upload.client",
          action: "uploadEditorJSImage",
        },
        "warning",
      );
      return {
        success: 0,
        // EditorJS expects no error property in success response
      };
    }
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(
      error,
      {
        component: "upload.client",
        action: "uploadEditorJSImage",
      },
      false,
    ); // Don't show toast, return error code instead
    return {
      success: 0,
    };
  }
}

import { useNavigate } from "@remix-run/react";
import { useState, useCallback } from "react";
import { toast } from "react-hot-toast";
interface UploadProvider {
  provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  isUsingBlossom: boolean;
  enableMirrorBlossom?: boolean;
  mirrorUploadUrls?: string[];
}

interface SubmitOptions {
  method: string;
  encType?: string;
  action?: string;
}

export function useBlossomAwareUpload() {
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [response, setResponse] = useState<Record<string, unknown> | null>(
    null,
  );
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const checkUploadProvider = async (): Promise<UploadProvider> => {
    try {
      const response = await fetch("/api/user-upload-provider");
      if (!response.ok) throw new Error("Failed to check provider");
      const data = (await response.json()) as {
        provider?: string;
        enableMirrorBlossom?: boolean;
        mirrorUploadUrls?: string[];
      };

      const {
        provider,
        enableMirrorBlossom = false,
        mirrorUploadUrls = [],
      } = data;

      // Handle legacy BLOSSOM value as BLOSSOM_PRIMAL
      if (provider === "BLOSSOM" || provider === "BLOSSOM_PRIMAL") {
        return {
          provider: "BLOSSOM_PRIMAL",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      if (provider === "BLOSSOM_BLOSSTR") {
        return {
          provider: "BLOSSOM_BLOSSTR",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    } catch (error) {
      console.error("Failed to check upload provider:", error);
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    }
  };

  const createBlossomAuthHeaders = async (
    provider: "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
  ) => {
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not found. Please install Alby, Amber, or another NOSTR extension to upload to Blossom.",
      );
    }

    let _uploadUrl: string;
    if (provider === "BLOSSOM_PRIMAL") {
      _uploadUrl = "https://blossom.primal.net/upload";
    } else if (provider === "BLOSSOM_BLOSSTR") {
      _uploadUrl = "https://blosstr.com/upload";
    } else {
      throw new Error("Invalid blossom provider");
    }

    // Note: Authentication should be handled by the upload service directly
    throw new Error(
      "Blossom auth not implemented in useBlossomAwareUpload. Use upload.client.ts instead.",
    );
  };

  const submitForm = useCallback(
    async (formData: FormData, options: SubmitOptions) => {
      setIsUploading(true);
      setUploadProgress(10);
      setError(null);

      try {
        // Check upload provider
        const providerInfo = await checkUploadProvider();
        setUploadProgress(20);

        let headers: Record<string, string> = {};

        // If using any Blossom provider, create auth headers and show progress
        if (providerInfo.isUsingBlossom) {
          setUploadProgress(30);
          const providerName =
            providerInfo.provider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr";

          // Log mirror configuration if enabled
          if (
            providerInfo.enableMirrorBlossom &&
            providerInfo.mirrorUploadUrls?.length
          ) {
            // Mirror configuration is active
          }

          toast.loading(
            `Signing upload request with NOSTR extension for ${providerName}...`,
            {
              id: "blossom-auth",
            },
          );
          try {
            headers = await createBlossomAuthHeaders(
              providerInfo.provider as "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
            );
            toast.success("Upload authorized!", { id: "blossom-auth" });
            setUploadProgress(60);
          } catch (authError: unknown) {
            const errorMessage =
              authError instanceof Error
                ? authError.message
                : String(authError);
            toast.error("Failed to authorize upload: " + errorMessage, {
              id: "blossom-auth",
            });
            throw authError;
          }
        }

        setUploadProgress(70);

        // Get the action URL (default to current page)
        const actionUrl = options.action ?? window.location.pathname;

        // Make the request with custom headers for Blossom Primal
        const fetchResponse = await fetch(actionUrl, {
          method: options.method,
          body: formData,
          headers: {
            ...headers,
            // Don't set Content-Type for FormData, let the browser set it
          },
        });

        setUploadProgress(90);

        if (!fetchResponse.ok) {
          let errorData: { error?: string };
          try {
            errorData = (await fetchResponse.json()) as { error?: string };
          } catch {
            // If response is not JSON, try to get text
            const errorText = await fetchResponse
              .text()
              .catch(() => `HTTP ${fetchResponse.status}`);
            errorData = {
              error: errorText.includes("<!DOCTYPE")
                ? `HTTP ${fetchResponse.status}`
                : errorText,
            };
          }
          throw new Error(errorData.error ?? "Upload failed");
        }

        let result;
        const responseText = await fetchResponse.text();

        try {
          // Try to parse as JSON first
          result = JSON.parse(responseText) as Record<string, unknown>;
        } catch (_parseError: unknown) {
          // If response is HTML (redirect or error page), handle gracefully
          if (
            responseText.includes("<!DOCTYPE") ||
            responseText.includes("<html")
          ) {
            if (
              responseText.includes("success") ||
              responseText.includes("uploaded") ||
              fetchResponse.status === 200
            ) {
              result = {
                success: true,
                redirect: true,
                message:
                  "Upload completed, but received HTML response instead of JSON",
              };
            } else {
              result = {
                success: false,
                error: "Server returned HTML instead of expected JSON response",
              };
            }
          } else {
            const parseError = _parseError as Error;
            throw new Error(
              "Invalid response format: " +
                (parseError?.message ?? "Unknown error") +
                ". Response: " +
                responseText.substring(0, 100),
            );
          }
        }

        setResponse(result);
        setUploadProgress(100);

        // Handle successful response
        if (result["success"] !== false) {
          // Check if this was a redirect response
          if (fetchResponse.redirected || result["redirect"]) {
            const redirectUrl = result["redirect"] ?? fetchResponse.url;
            navigate(redirectUrl);
          }
        }

        return result;
      } catch (error: unknown) {
        const { handleAsyncError } = await import("~/lib/error-handler.client");
        const errorMessage =
          error instanceof Error ? error.message : "Upload failed";
        handleAsyncError(error, {
          component: "useBlossomAwareUpload",
          action: "submitForm",
        });
        setError(errorMessage);
        throw error;
      } finally {
        setTimeout(() => {
          setIsUploading(false);
          setUploadProgress(0);
        }, 1000);
      }
    },
    [navigate],
  );

  return {
    submitForm,
    isUploading,
    uploadProgress,
    response,
    error,
  };
}

/**
 * Upload validation utilities
 *
 * Provides MIME type validation and file size checking for secure uploads
 */

// Dynamic import for file-type since it's ESM-only and we're bundling as CommonJS
interface FileTypeResult {
  mime: string;
  ext: string;
}

let fileTypeFromBuffer: (buffer: Uint8Array | ArrayBuffer) => Promise<FileTypeResult | undefined>;

async function getFileTypeFromBuffer() {
  if (!fileTypeFromBuffer) {
    const fileType = await import("file-type");
    fileTypeFromBuffer = fileType.fileTypeFromBuffer;
  }
  return fileTypeFromBuffer;
}

/**
 * Allowed MIME types for uploads
 */
export const ALLOWED_MIME_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
  "image/webp",
  "image/gif",
  // Add video if needed in the future:
  // "video/mp4",
] as const;

/**
 * Maximum file size in bytes (10MB)
 */
export const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

/**
 * Upload validation result
 */
export interface UploadValidationResult {
  valid: boolean;
  error?: string;
  detectedMimeType?: string;
}

/**
 * Validates file buffer against MIME type and size
 *
 * @param buffer - The file buffer to validate
 * @param filename - Original filename (for logging)
 * @param contentType - Content-Type header if provided (for comparison)
 * @returns Validation result with detected MIME type
 */
export async function validateUpload(
  buffer: Buffer,
  filename: string,
  contentType?: string,
): Promise<UploadValidationResult> {
  // Check size first (fastest check)
  if (buffer.length > MAX_FILE_SIZE) {
    return {
      valid: false,
      error: `File size exceeds ${MAX_FILE_SIZE / 1024 / 1024}MB limit`,
    };
  }

  // Detect actual MIME type from buffer (magic number detection)
  let fileType;
  try {
    const fileTypeFn = await getFileTypeFromBuffer();
    fileType = await fileTypeFn(buffer);
  } catch (_error) {
    return {
      valid: false,
      error: "Could not detect file type",
    };
  }

  if (!fileType?.mime) {
    return {
      valid: false,
      error: "Could not detect file type from file content",
    };
  }

  const detectedMimeType = fileType.mime;

  // Validate against allowlist
  if (!ALLOWED_MIME_TYPES.includes(detectedMimeType as (typeof ALLOWED_MIME_TYPES)[number])) {
    return {
      valid: false,
      error: `File type ${detectedMimeType} is not allowed. Allowed types: ${ALLOWED_MIME_TYPES.join(", ")}`,
      detectedMimeType,
    };
  }

  // If contentType was provided, verify it matches detected type
  // This prevents MIME type spoofing
  if (contentType) {
    // Normalize content type (remove charset, etc.)
    const contentTypeParts = contentType.split(";");
    const normalizedContentType = contentTypeParts[0]?.trim().toLowerCase() ?? "";
    const normalizedDetected = detectedMimeType.toLowerCase();

    if (normalizedContentType !== normalizedDetected) {
      return {
        valid: false,
        error: `Content-Type mismatch: expected ${detectedMimeType}, got ${contentType}`,
        detectedMimeType,
      };
    }
  }

  return {
    valid: true,
    detectedMimeType,
  };
}

/**
 * Gets the appropriate S3 ContentType from detected MIME type
 * Normalizes common variations (e.g., jpg -> jpeg)
 */
export function getS3ContentType(detectedMimeType: string): string {
  // Normalize common variations
  if (detectedMimeType === "image/jpg") {
    return "image/jpeg";
  }
  return detectedMimeType;
}

import { Link, useFetcher } from "@remix-run/react";
