interface UserWithProfile {
  npub: string;
  nostrProfile?: ProfileData | null;
  [key: string]: unknown;
}

interface ChildAccount {
  npub: string;
  name?: string;
  displayName?: string;
  picture?: string;
}

function displayLabel(user: UserWithProfile | null | undefined): string {
  try {
    let p: ProfileData | null | undefined;
    if (typeof user?.nostrProfile === "string") {
      const parsed: unknown = JSON.parse(user.nostrProfile);
      p =
        parsed && typeof parsed === "object" && !Array.isArray(parsed)
          ? (parsed as ProfileData)
          : null;
    } else {
      p = user?.nostrProfile;
    }
    const name =
      p && typeof p === "object" && "name" in p && typeof p.name === "string"
        ? p.name
        : undefined;
    const displayName =
      p &&
      typeof p === "object" &&
      "display_name" in p &&
      typeof p.display_name === "string"
        ? p.display_name
        : undefined;
    return name ?? displayName ?? formatNpubShort(user?.npub);
  } catch {
    return formatNpubShort(user?.npub);
  }
}

function displayPicture(
  user: UserWithProfile | null | undefined,
): string | undefined {
  try {
    let p: ProfileData | null | undefined;
    if (typeof user?.nostrProfile === "string") {
      const parsed: unknown = JSON.parse(user.nostrProfile);
      p =
        parsed && typeof parsed === "object" && !Array.isArray(parsed)
          ? (parsed as ProfileData)
          : null;
    } else {
      p = user?.nostrProfile;
    }
    const picture =
      p &&
      typeof p === "object" &&
      "picture" in p &&
      typeof p.picture === "string"
        ? p.picture
        : undefined;
    return picture ?? undefined;
  } catch {
    return undefined;
  }
}

function formatNpubShort(hexOrNpub?: string): string {
  if (!hexOrNpub) return "";
  const np = hexOrNpub.startsWith("npub")
    ? hexOrNpub
    : (nostrAdapter.encodeNpub(hexOrNpub) ?? hexOrNpub);
  if (!np) return "";
  if (np.length <= 20) return np; // already short
  return `${np.slice(0, 8)}...${np.slice(-8)}`;
}

export default function AccountSwitchMenu() {
  const user = useOptionalUser() as UserWithProfile | null | undefined;
  const subscription = useSubscription();
  const fetcher = useFetcher<{ children: ChildAccount[] }>();
  const [open, setOpen] = React.useState(false);
  const [children, setChildren] = React.useState<ChildAccount[]>([]);

  // Safely handle potentially undefined subscription values
  const planId =
    (subscription?.currentSubscription?.planId ?? "")
      .toString()
      .toLowerCase() ?? "";
  const planName =
    (subscription?.currentSubscription?.Plan?.name ?? "")
      .toString()
      .toLowerCase() ?? "";
  const isChild = !!user?.["isChild"];
  const parentNpub = user?.["parentNpub"] as string | undefined;
  const hasAccountsAccess =
    !isChild &&
    (planId === "premium" || planName === "premium" || planName === "founder");

  React.useEffect(() => {
    if (
      open &&
      hasAccountsAccess &&
      fetcher.state === "idle" &&
      !fetcher.data
    ) {
      fetcher.load("/api/children");
    }
  }, [open, hasAccountsAccess, fetcher.state, fetcher]);

  React.useEffect(() => {
    if (fetcher.data?.children) setChildren(fetcher.data.children);
  }, [fetcher.data]);

  // Hide trigger if not parent with access and not a child with parent link
  if (!hasAccountsAccess && !(isChild && parentNpub)) return null;

  const onSwitch = async (childNpub: string) => {
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: () => {
          void (async () => {
            if (window.nostr) {
              const contentSign = `Switch account ${Math.random().toString(36).slice(2, 12)}`;
              const event: NostrEvent = {
                kind: 27235,
                created_at: Math.floor(Date.now() / 1000),
                tags: [],
                content: contentSign,
              };
              const signedEvent = await window.nostr.signEvent(event);
              if (signedEvent.pubkey !== childNpub) {
                // Silent no-op on mismatch
                return;
              }
              const formData = new FormData();
              formData.append("pubkey", signedEvent.pubkey);
              formData.append("signature", signedEvent.sig);
              formData.append("event", JSON.stringify(signedEvent));
              formData.append("contentSign", contentSign);
              formData.append("redirectTo", "/dashboard");
              fetcher.submit(formData, {
                method: "post",
                action: "/nostr-auth",
              });
            }
          })();
        },
      });
      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {
      const { handleErrorSafely } = require("~/lib/error-handler.client") as {
        handleErrorSafely: (
          error: unknown,
          context: { component: string; action: string },
        ) => void;
      };
      handleErrorSafely(e, {
        component: "AccountSwitchMenu",
        action: "onSwitchAccount",
      });
    }
  };

  const onSwitchParent = async () => {
    if (!parentNpub) return;
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: () => {
          void (async () => {
            if (window.nostr) {
              const contentSign = `Switch parent ${Math.random().toString(36).slice(2, 12)}`;
              const event: NostrEvent = {
                kind: 27235,
                created_at: Math.floor(Date.now() / 1000),
                tags: [],
                content: contentSign,
              };
              const signedEvent = await window.nostr.signEvent(event);
              if (signedEvent.pubkey !== parentNpub) {
                // Silent no-op on mismatch
                return;
              }
              const formData = new FormData();
              formData.append("pubkey", signedEvent.pubkey);
              formData.append("signature", signedEvent.sig);
              formData.append("event", JSON.stringify(signedEvent));
              formData.append("contentSign", contentSign);
              formData.append("redirectTo", "/dashboard");
              fetcher.submit(formData, {
                method: "post",
                action: "/nostr-auth",
              });
            }
          })();
        },
      });
      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {
      const { handleErrorSafely } = require("~/lib/error-handler.client") as {
        handleErrorSafely: (
          error: unknown,
          context: { component: string; action: string },
        ) => void;
      };
      handleErrorSafely(e, {
        component: "AccountSwitchMenu",
        action: "onSwitchParent",
      });
    }
  };

  const currentAvatar = displayPicture(user);
  const currentLabel = displayLabel(user);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <RefreshCw className="h-4 w-4" />
          <span className="hidden sm:inline">Accounts</span>
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Switch account</DialogTitle>
          <DialogDescription>
            Choose an account to switch to or manage your linked accounts.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          <div className="flex items-center gap-3 rounded-md border p-3">
            <Avatar className="h-8 w-8">
              {currentAvatar ? (
                <AvatarImage src={currentAvatar} alt={currentLabel} />
              ) : (
                <AvatarFallback>{currentLabel?.[0] ?? "U"}</AvatarFallback>
              )}
            </Avatar>
            <div className="min-w-0">
              <div className="truncate font-medium">{currentLabel}</div>
              <div className="truncate text-xs text-muted-foreground">
                {formatNpubShort(user?.npub)}
              </div>
              <div className="text-xs text-muted-foreground">
                Currently signed in
              </div>
            </div>
          </div>

          {hasAccountsAccess ? (
            <div>
              <div className="mb-2 text-sm font-medium">Child accounts</div>
              <div className="divide-y rounded-md border">
                {children.length === 0 ? (
                  <div className="p-3 text-sm text-muted-foreground">
                    No child accounts linked
                  </div>
                ) : (
                  children.map((c) => {
                    const label =
                      c.name ??
                      c.displayName ??
                      `${c.npub.slice(0, 8)}...${c.npub.slice(-8)}`;
                    return (
                      <div
                        key={c.npub}
                        className="flex items-center justify-between p-3"
                      >
                        <div className="flex min-w-0 items-center gap-3">
                          <Avatar className="h-7 w-7">
                            {c.picture ? (
                              <AvatarImage src={c.picture} alt={label} />
                            ) : (
                              <AvatarFallback>C</AvatarFallback>
                            )}
                          </Avatar>
                          <div className="min-w-0">
                            <div className="truncate font-medium">{label}</div>
                            <div className="truncate text-xs text-muted-foreground">
                              {formatNpubShort(c.npub)}
                            </div>
                          </div>
                        </div>
                        <Button
                          size="sm"
                          onClick={() => {
                            void onSwitch(c.npub);
                          }}
                          disabled={fetcher.state !== "idle"}
                        >
                          {fetcher.state !== "idle" ? "Switching..." : "Switch"}
                        </Button>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          ) : null}

          {isChild && parentNpub ? (
            <div className="rounded-md border p-3">
              <div className="mb-2 text-sm font-medium">Managed by account</div>
              <div className="flex items-center justify-between">
                <div className="min-w-0">
                  <div className="truncate text-sm">
                    {formatNpubShort(parentNpub)}
                  </div>
                </div>
                <Button
                  size="sm"
                  onClick={() => {
                    void onSwitchParent();
                  }}
                  disabled={fetcher.state !== "idle"}
                >
                  {fetcher.state !== "idle"
                    ? "Switching..."
                    : "Switch to parent"}
                </Button>
              </div>
            </div>
          ) : null}

          <div className="flex justify-between">
            <Link
              to="/dashboard/settings?tab=accounts"
              className="text-sm underline underline-offset-2"
            >
              Manage accounts
            </Link>
            <Button variant="outline" size="sm" onClick={() => setOpen(false)}>
              Close
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useFetcher, useRevalidator } from "@remix-run/react";
import * as React from "react";

import { Avatar, AvatarImage } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import { Card } from "~/components/ui/card";
import { Input } from "~/components/ui/input";
import type { ProfileData } from "~/features/nostr/types";
interface AccountInfo {
  npub: string;
  nostrProfile?: ProfileData | null;
}

interface SearchResult {
  id: string;
  npub: string;
  profileName?: string;
  profileDisplayName?: string;
  profilePicture?: string;
  isChild?: boolean;
  parentNpub?: string | null;
  pendingParentRequests?: string[];
}

function extractProfileBits(nostrProfile: ProfileData | null | undefined) {
  if (!nostrProfile)
    return {
      name: undefined,
      display_name: undefined,
      picture: undefined,
    } as const;
  try {
    if (typeof nostrProfile === "string") {
      const p = JSON.parse(nostrProfile) as {
        name?: string;
        display_name?: string;
        picture?: string;
      };
      return {
        name: p.name,
        display_name: p.display_name,
        picture: p.picture,
      } as const;
    }
    if (typeof nostrProfile === "object") {
      const p = nostrProfile;
      return {
        name: p.name,
        display_name: p.display_name,
        picture: p.picture,
      } as const;
    }
  } catch {
    // Ignore parsing errors, return defaults
  }
  return {
    name: undefined,
    display_name: undefined,
    picture: undefined,
  } as const;
}

export function AccountsSettings({
  parentNpub,
  confirmedChildren,
  pendingChildren,
  isChild = false,
  parentUser,
}: {
  parentNpub?: string;
  confirmedChildren?: AccountInfo[];
  pendingChildren?: AccountInfo[];
  isChild?: boolean;
  parentUser?: AccountInfo | null;
}) {
  const fetcher = useFetcher<{ results?: SearchResult[]; error?: string }>();
  const [q, setQ] = React.useState("");
  const revalidator = useRevalidator();

  // Prevent duplicate submissions due to re-renders by remembering last query
  const lastSubmittedRef = React.useRef("");

  React.useEffect(() => {
    const value = q.trim();
    if (!value) {
      lastSubmittedRef.current = "";
      return;
    }
    if (lastSubmittedRef.current === value) return;

    const i = setTimeout(() => {
      lastSubmittedRef.current = value;
      fetcher.submit(
        { _action: "search_accounts", q: value },
        { method: "post" },
      );
    }, 300);

    return () => clearTimeout(i);
  }, [q, fetcher]);

  const onRequestChild = (childNpub: string) => {
    const np = (childNpub ?? "").trim();
    fetcher.submit(
      { _action: "request_child", childNpub: np },
      { method: "post", action: "/dashboard/settings" },
    );
  };

  // Submission state feedback
  const submittingAction =
    (fetcher.formData?.get("_action") as string) ?? undefined;
  const submittingChildNpub =
    (fetcher.formData?.get("childNpub") as string) ?? undefined;
  const isUnlinking =
    submittingAction === "unlink_parent" && fetcher.state !== "idle";

  React.useEffect(() => {
    if (
      (submittingAction === "unlink_parent" ||
        submittingAction === "unlink_child" ||
        submittingAction === "cancel_child_request") &&
      fetcher.state === "idle" &&
      (fetcher.data as { success?: boolean } | undefined)?.success
    ) {
      revalidator.revalidate();
    }
  }, [fetcher.state, fetcher.data, submittingAction, revalidator]);

  const _renderAccountRow = (
    npub: string,
    nostrProfile?: ProfileData | null,
  ) => {
    const bits = extractProfileBits(nostrProfile);
    return (
      <div
        key={npub}
        className="flex items-center justify-between border-b py-2 last:border-0"
      >
        <div className="flex min-w-0 items-center gap-3">
          <Avatar className="h-8 w-8">
            {bits.picture ? (
              <AvatarImage
                src={bits.picture}
                alt={bits.name ?? bits.display_name ?? npub}
              />
            ) : null}
          </Avatar>
          <div className="min-w-0">
            <div className="truncate font-medium">
              {bits.name ?? bits.display_name ?? npub}
            </div>
            <div className="truncate text-xs text-muted-foreground">{npub}</div>
          </div>
        </div>
      </div>
    );
  };

  const results = fetcher.data?.results ?? [];

  if (isChild) {
    const bits = extractProfileBits(parentUser?.nostrProfile);
    const parentName =
      bits.name ?? bits.display_name ?? parentUser?.npub ?? "Parent";
    return (
      <Card className="p-4">
        <div className="mb-4">
          <h2 className="text-xl font-semibold">Accounts</h2>
          <p className="text-sm text-muted-foreground">
            This account is managed by a parent account.
          </p>
        </div>

        <div className="mb-6 flex items-center justify-between rounded-md border bg-muted/30 p-4">
          <div className="flex min-w-0 items-center gap-3">
            <Avatar className="h-10 w-10">
              {bits.picture ? (
                <AvatarImage src={bits.picture} alt={parentName} />
              ) : null}
            </Avatar>
            <div className="min-w-0">
              <div className="truncate font-medium">
                Managed by {parentName}
              </div>
              {parentUser?.npub ? (
                <div className="truncate text-xs text-muted-foreground">
                  {parentUser.npub}
                </div>
              ) : null}
            </div>
          </div>
          <Button
            size="sm"
            variant="destructive"
            disabled={isUnlinking}
            onClick={() =>
              fetcher.submit(
                { _action: "unlink_parent" },
                { method: "post", action: "/dashboard/settings" },
              )
            }
          >
            {isUnlinking ? "Unlinking..." : "Unlink from Parent"}
          </Button>
        </div>

        <p className="text-sm text-muted-foreground">
          As a child account, you cannot search for or link child accounts.
        </p>
      </Card>
    );
  }

  return (
    <Card className="p-4">
      <div className="mb-4">
        <h2 className="text-xl font-semibold">Accounts</h2>
        <p className="text-sm text-muted-foreground">
          Search Nostr users by profile name and request to add them as child
          accounts.
        </p>
      </div>

      <div className="mb-6">
        <label
          htmlFor="accounts-search"
          className="mb-2 block text-sm font-medium"
        >
          Search users
        </label>
        <Input
          id="accounts-search"
          placeholder="Search by name or npub..."
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      {q.trim() ? (
        <div className="mb-8">
          <h3 className="mb-2 text-sm font-medium">Search results</h3>
          <div className="divide-y rounded-md border">
            {results.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">
                No results
              </div>
            ) : (
              results.map((r) => {
                const isSubmittingThis =
                  submittingAction === "request_child" &&
                  submittingChildNpub === r.npub &&
                  fetcher.state !== "idle";
                const disabled =
                  isSubmittingThis ||
                  r.npub === parentNpub ||
                  (r.pendingParentRequests ?? []).includes(parentNpub ?? "") ||
                  r.parentNpub === parentNpub ||
                  r.isChild === true;
                const label = isSubmittingThis
                  ? "Requesting..."
                  : r.npub === parentNpub
                    ? "This is you"
                    : (r.pendingParentRequests ?? []).includes(parentNpub ?? "")
                      ? "Requested"
                      : r.parentNpub
                        ? "Has a parent"
                        : r.isChild
                          ? "Is a child"
                          : "Request";

                return (
                  <div
                    key={r.id}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {r.profilePicture ? (
                          <AvatarImage
                            src={r.profilePicture}
                            alt={
                              r.profileName ?? r.profileDisplayName ?? r.npub
                            }
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {r.profileName ?? r.profileDisplayName ?? r.npub}
                        </div>
                        <div className="truncate text-xs text-muted-foreground">
                          {r.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant={disabled ? "secondary" : "default"}
                      disabled={disabled}
                      onClick={() => onRequestChild(r.npub)}
                    >
                      {label}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
          {fetcher.data?.error ? (
            <p className="mt-2 text-sm text-red-600">{fetcher.data.error}</p>
          ) : null}
        </div>
      ) : null}

      <div className="grid gap-6 md:grid-cols-2">
        <div>
          <h3 className="mb-2 text-sm font-medium">Confirmed children</h3>
          <div className="divide-y rounded-md border">
            {confirmedChildren?.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">
                No confirmed children
              </div>
            ) : (
              (confirmedChildren ?? []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const removingThis =
                  submittingAction === "unlink_child" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div
                    key={u.npub}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage
                            src={bits.picture}
                            alt={bits.name ?? bits.display_name ?? u.npub}
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {bits.name ?? bits.display_name ?? u.npub}
                        </div>
                        <div className="truncate text-xs text-muted-foreground">
                          {u.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="destructive"
                      disabled={removingThis}
                      onClick={() =>
                        fetcher.submit(
                          { _action: "unlink_child", childNpub: u.npub },
                          { method: "post", action: "/dashboard/settings" },
                        )
                      }
                    >
                      {removingThis ? "Removing..." : "Remove"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
        <div>
          <h3 className="mb-2 text-sm font-medium">Pending requests</h3>
          <div className="divide-y rounded-md border">
            {pendingChildren?.length === 0 ? (
              <div className="p-3 text-sm text-muted-foreground">
                No pending requests
              </div>
            ) : (
              (pendingChildren ?? []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const cancelingThis =
                  submittingAction === "cancel_child_request" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div
                    key={u.npub}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage
                            src={bits.picture}
                            alt={bits.name ?? bits.display_name ?? u.npub}
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {bits.name ?? bits.display_name ?? u.npub}
                        </div>
                        <div className="truncate text-xs text-muted-foreground">
                          {u.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="secondary"
                      disabled={cancelingThis}
                      onClick={() =>
                        fetcher.submit(
                          {
                            _action: "cancel_child_request",
                            childNpub: u.npub,
                          },
                          { method: "post", action: "/dashboard/settings" },
                        )
                      }
                    >
                      {cancelingThis ? "Canceling..." : "Cancel"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

