/**
 * Error Logging Service
 *
 * Centralized error logging with different log levels and structured output
 */

import { recordErrorMetric } from "./error-metrics.server";
import type { AppError } from "./errors";
import { sanitizeError, sanitizeObject } from "./secrets-sanitizer.server";
import { captureException } from "./sentry.server";
export type LogLevel = "error" | "warn" | "info" | "debug";

export interface LogContext {
  userId?: string;
  requestId?: string;
  path?: string;
  method?: string;
  userAgent?: string;
  ip?: string;
  includeStack?: boolean;
  [key: string]: unknown;
}

/**
 * Structured error log entry
 */
interface ErrorLogEntry {
  timestamp: string;
  level: LogLevel;
  error: {
    name: string;
    message: string;
    code: string;
    statusCode: number;
    isOperational: boolean;
    stack?: string;
    context?: Record<string, unknown>;
  };
  request?: {
    method?: string;
    path?: string;
    userAgent?: string;
    ip?: string;
  };
  user?: {
    id?: string;
  };
  environment: string;
}

/**
 * Log an error with structured output
 * Automatically sanitizes sensitive data (NWC strings, secrets, etc.)
 */
export function logError(
  error: AppError | Error,
  context: LogContext = {},
): void {
  const logEntry: ErrorLogEntry = {
    timestamp: new Date().toISOString(),
    level: "error",
    error: {
      name: error.name,
      message: error.message,
      code: isAppError(error) ? error.code : "UNKNOWN_ERROR",
      statusCode: isAppError(error) ? error.statusCode : 500,
      isOperational: isAppError(error) ? error.isOperational : false,
      ...(context.includeStack && error.stack && { stack: error.stack }),
      ...(isAppError(error) && error.context && { context: error.context }),
    },
    ...(context.method && {
      request: {
        method: context.method,
        path: context.path,
        userAgent: context.userAgent,
        ip: context.ip,
      },
    }),
    ...(context.userId && {
      user: {
        id: context.userId,
      },
    }),
    environment: process.env.NODE_ENV ?? "development",
  };

  // Sanitize log entry to prevent secrets from appearing in logs
  const sanitizedError = sanitizeError(error);
  const sanitizedLogEntry = sanitizeObject({
    ...logEntry,
    error: {
      ...logEntry.error,
      message: sanitizedError.message,
      stack: sanitizedError.stack,
    },
  });

  // In production, you might want to send to an external service
  // For now, we'll use structured console logging
  if (process.env.NODE_ENV === "production") {
    // In production, log as JSON for log aggregation services
    console.error(JSON.stringify(sanitizedLogEntry));
  } else {
    // In development, use more readable format
    console.error("\n❌ Error:", {
      message: sanitizedError.message,
      code: logEntry.error.code,
      statusCode: logEntry.error.statusCode,
      path: logEntry.request?.path,
      method: logEntry.request?.method,
      userId: logEntry.user?.id,
      ...(context.includeStack &&
        sanitizedError.stack && { stack: sanitizedError.stack }),
    });
  }

  // Record error in metrics
  if (isAppError(error)) {
    recordErrorMetric(error);
  }

  // Send to Sentry if configured
  captureException(sanitizedError, {
    tags: {
      code: isAppError(error) ? error.code : "UNKNOWN_ERROR",
      statusCode: String(logEntry.error.statusCode),
      isOperational: String(logEntry.error.isOperational),
    },
    extra: {
      ...sanitizedLogEntry,
      // Include sanitized context
      context: sanitizedLogEntry.request ?? sanitizedLogEntry.user ?? {},
    },
    user: context.userId ? { id: context.userId } : undefined,
    level: logEntry.error.isOperational ? "warning" : "error",
  });
}

/**
 * Log a warning
 */
export function logWarning(message: string, context: LogContext = {}): void {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: "warn" as LogLevel,
    message,
    ...context,
    environment: process.env.NODE_ENV ?? "development",
  };

  if (process.env.NODE_ENV === "production") {
    console.warn(JSON.stringify(logEntry));
  } else {
    console.warn("⚠️  Warning:", message, context);
  }
}

/**
 * Log info
 */
export function logInfo(message: string, context: LogContext = {}): void {
  const logEntry = {
    timestamp: new Date().toISOString(),
    level: "info" as LogLevel,
    message,
    ...context,
    environment: process.env.NODE_ENV ?? "development",
  };

  if (process.env.NODE_ENV === "production") {
    console.info(JSON.stringify(logEntry));
  } else {
    console.info("ℹ️  Info:", message, context);
  }
}

/**
 * Type guard for AppError
 */
function isAppError(error: AppError | Error): error is AppError {
  return "code" in error && "statusCode" in error;
}

/**
 * Centralized Error Handling System
 *
 * This module provides a comprehensive error handling system with:
 * - Custom error classes for different error types
 * - Structured error responses
 * - Error logging
 * - Type-safe error handling
 */

/**
 * Base error class for all application errors
 */
export class AppError extends Error {
  public readonly statusCode: number;
  public readonly code: string;
  public readonly isOperational: boolean;
  public readonly context?: Record<string, unknown>;
  public readonly timestamp: string;

  constructor(
    message: string,
    statusCode = 500,
    code = "INTERNAL_ERROR",
    isOperational = true,
    context?: Record<string, unknown>,
  ) {
    super(message);
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;
    this.context = context;
    this.timestamp = new Date().toISOString();

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      statusCode: this.statusCode,
      timestamp: this.timestamp,
      ...(this.context && { context: this.context }),
    };
  }
}

/**
 * Validation errors (400)
 */
export class ValidationError extends AppError {
  constructor(message: string, context?: Record<string, unknown>) {
    super(message, 400, "VALIDATION_ERROR", true, context);
  }
}

/**
 * Authentication errors (401)
 */
export class AuthenticationError extends AppError {
  constructor(
    message = "Authentication required",
    context?: Record<string, unknown>,
  ) {
    super(message, 401, "AUTHENTICATION_ERROR", true, context);
  }
}

/**
 * Authorization errors (403)
 */
export class AuthorizationError extends AppError {
  constructor(
    message = "Insufficient permissions",
    context?: Record<string, unknown>,
  ) {
    super(message, 403, "AUTHORIZATION_ERROR", true, context);
  }
}

/**
 * Not found errors (404)
 */
export class NotFoundError extends AppError {
  constructor(
    message = "Resource not found",
    context?: Record<string, unknown>,
  ) {
    super(message, 404, "NOT_FOUND_ERROR", true, context);
  }
}

/**
 * Conflict errors (409)
 */
export class ConflictError extends AppError {
  constructor(
    message = "Resource conflict",
    context?: Record<string, unknown>,
  ) {
    super(message, 409, "CONFLICT_ERROR", true, context);
  }
}

/**
 * Rate limit errors (429)
 */
export class RateLimitError extends AppError {
  constructor(
    message = "Rate limit exceeded",
    context?: Record<string, unknown>,
  ) {
    super(message, 429, "RATE_LIMIT_ERROR", true, context);
  }
}

/**
 * External service errors (502, 503, 504)
 */
export class ExternalServiceError extends AppError {
  constructor(
    message: string,
    statusCode = 502,
    context?: Record<string, unknown>,
  ) {
    super(message, statusCode, "EXTERNAL_SERVICE_ERROR", true, context);
  }
}

/**
 * Database errors (500)
 */
export class DatabaseError extends AppError {
  constructor(
    message = "Database operation failed",
    context?: Record<string, unknown>,
  ) {
    super(message, 500, "DATABASE_ERROR", true, context);
  }
}

/**
 * Type guard to check if error is an AppError
 */
export function isAppError(error: unknown): error is AppError {
  return (
    error instanceof AppError ||
    (typeof error === "object" &&
      error !== null &&
      "statusCode" in error &&
      "code" in error)
  );
}

/**
 * Type guard to check if error is an Error
 */
export function isError(error: unknown): error is Error {
  return error instanceof Error;
}

/**
 * Normalize any error to an AppError
 */
export function normalizeError(error: unknown): AppError {
  if (isAppError(error)) {
    return error;
  }

  if (isError(error)) {
    const message = error.message.trim();

    // Check for common Prisma errors
    if (message.includes("Unique constraint")) {
      return new ConflictError(
        "A record with this information already exists",
        { originalError: error.message },
      );
    }

    if (message.includes("Record to update not found")) {
      return new NotFoundError(
        "The record you're trying to update doesn't exist",
        {
          originalError: error.message,
        },
      );
    }

    // Check for authentication errors
    if (
      message.toLowerCase().includes("authentication required") ||
      message.toLowerCase().includes("authentication error") ||
      message.toLowerCase().includes("not authenticated")
    ) {
      return new AuthenticationError(message, {
        originalError: error.message,
      });
    }

    // Check for authorization/subscription errors
    if (
      message.toLowerCase().includes("subscription required") ||
      message.toLowerCase().includes("subscription error")
    ) {
      return new AuthorizationError(message, {
        originalError: error.message,
      });
    }

    // Check for feature access errors
    if (
      message.toLowerCase().includes("feature access denied") ||
      message.toLowerCase().includes("feature not available")
    ) {
      return new AuthorizationError(message, {
        originalError: error.message,
      });
    }

    // Check for database errors
    if (
      message.toLowerCase().includes("database error") ||
      message.toLowerCase().includes("database connection failed") ||
      message.toLowerCase().includes("database operation failed")
    ) {
      return new DatabaseError(message, {
        originalError: error.message,
      });
    }

    // Generic error - use default message if empty
    const errorMessage =
      message && message !== "" ? message : "An unexpected error occurred";
    return new AppError(errorMessage, 500, "INTERNAL_ERROR", false, {
      originalError: error.message,
    });
  }

  // Unknown error type
  return new AppError(
    "An unexpected error occurred",
    500,
    "UNKNOWN_ERROR",
    false,
    { originalError: String(error) },
  );
}

/**
 * Get user-friendly error message
 */
export function getUserFriendlyMessage(error: AppError): string {
  // Always return the actual message in test/development mode
  const isTestOrDev =
    process.env.NODE_ENV === "test" || process.env.NODE_ENV === "development";

  if (isTestOrDev) {
    return error.message;
  }

  // Don't expose internal errors to users in production
  if (!error.isOperational && process.env.NODE_ENV === "production") {
    return "An unexpected error occurred. Please try again later.";
  }

  return error.message;
}

/**
 * Error codes enum for type safety
 */
export const ErrorCodes = {
  VALIDATION_ERROR: "VALIDATION_ERROR",
  AUTHENTICATION_ERROR: "AUTHENTICATION_ERROR",
  AUTHORIZATION_ERROR: "AUTHORIZATION_ERROR",
  NOT_FOUND_ERROR: "NOT_FOUND_ERROR",
  CONFLICT_ERROR: "CONFLICT_ERROR",
  RATE_LIMIT_ERROR: "RATE_LIMIT_ERROR",
  EXTERNAL_SERVICE_ERROR: "EXTERNAL_SERVICE_ERROR",
  DATABASE_ERROR: "DATABASE_ERROR",
  INTERNAL_ERROR: "INTERNAL_ERROR",
  UNKNOWN_ERROR: "UNKNOWN_ERROR",
};

export type ErrorCode = (typeof ErrorCodes)[keyof typeof ErrorCodes];

/**
 * Hardened fetch wrapper with timeouts, retries, and structured error handling
 *
 * This module provides a robust fetch wrapper that:
 * - Enforces timeouts on all requests
 * - Implements retry logic with exponential backoff
 * - Provides typed error responses
 * - Includes correlation IDs for request tracking
 * - Handles common failure modes (network errors, timeouts, rate limits)
 *
 * Usage:
 *   import { fetchWithRetry } from "~/lib/fetch.server";
 *   const response = await fetchWithRetry(url, options);
 */

import { v4 as uuidv4 } from "uuid";

import { logError } from "~/lib/error-logger.server";

/**
 * Structured error types for fetch operations
 */
export class FetchError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
    public readonly statusText?: string,
    public readonly correlationId?: string,
    public readonly retries?: number,
  ) {
    super(message);
    this.name = "FetchError";
  }
}

export class FetchTimeoutError extends FetchError {
  constructor(
    message: string,
    public readonly timeout: number,
    correlationId?: string,
  ) {
    super(message, undefined, undefined, correlationId);
    this.name = "FetchTimeoutError";
  }
}

export class FetchNetworkError extends FetchError {
  constructor(
    message: string,
    public readonly originalError: unknown,
    correlationId?: string,
  ) {
    super(message, undefined, undefined, correlationId);
    this.name = "FetchNetworkError";
  }
}

export class FetchRateLimitError extends FetchError {
  constructor(
    message: string,
    public readonly retryAfter?: number,
    correlationId?: string,
  ) {
    super(message, 429, "Too Many Requests", correlationId);
    this.name = "FetchRateLimitError";
  }
}

/**
 * Options for fetchWithRetry
 */
export interface FetchRetryOptions extends RequestInit {
  /**
   * Timeout in milliseconds (default: 10000)
   */
  timeout?: number;

  /**
   * Maximum number of retries (default: 2)
   */
  maxRetries?: number;

  /**
   * Base delay for exponential backoff in milliseconds (default: 1000)
   */
  retryDelay?: number;

  /**
   * Custom correlation ID (auto-generated if not provided)
   */
  correlationId?: string;

  /**
   * Whether to retry on 5xx errors (default: true)
   */
  retryOn5xx?: boolean;

  /**
   * Whether to retry on network errors (default: true)
   */
  retryOnNetworkError?: boolean;

  /**
   * Custom function to determine if a response should be retried
   */
  shouldRetry?: (response: Response, attempt: number) => boolean;
}

/**
 * Default fetch options
 */
const DEFAULT_OPTIONS: Required<
  Pick<
    FetchRetryOptions,
    | "timeout"
    | "maxRetries"
    | "retryDelay"
    | "retryOn5xx"
    | "retryOnNetworkError"
  >
> = {
  timeout: 10000, // 10 seconds
  maxRetries: 2,
  retryDelay: 1000, // 1 second base delay
  retryOn5xx: true,
  retryOnNetworkError: true,
};

/**
 * Creates an AbortController that aborts after the specified timeout
 */
function createTimeoutController(timeout: number): AbortController {
  const controller = new AbortController();
  setTimeout(() => {
    controller.abort();
  }, timeout);

  // Note: The timeout will fire and abort the request if it takes too long
  // If the request completes before timeout, the abort signal will be ignored
  return controller;
}

/**
 * Calculates exponential backoff delay with jitter
 */
function calculateBackoffDelay(attempt: number, baseDelay: number): number {
  const exponentialDelay = baseDelay * Math.pow(2, attempt);
  // Add jitter (±25%) to prevent thundering herd
  const jitter = exponentialDelay * 0.25 * (Math.random() * 2 - 1);
  return Math.min(exponentialDelay + jitter, 30000); // Cap at 30 seconds
}

/**
 * Determines if a response should be retried
 */
function shouldRetryResponse(
  response: Response,
  attempt: number,
  maxRetries: number,
  retryOn5xx: boolean,
  customShouldRetry?: (response: Response, attempt: number) => boolean,
): boolean {
  if (attempt >= maxRetries) {
    return false;
  }

  // Use custom retry logic if provided
  if (customShouldRetry) {
    return customShouldRetry(response, attempt);
  }

  // Retry on 5xx errors if enabled
  if (retryOn5xx && response.status >= 500 && response.status < 600) {
    return true;
  }

  // Retry on 429 (rate limit) with exponential backoff
  if (response.status === 429) {
    return true;
  }

  // Don't retry on client errors (4xx except 429)
  if (response.status >= 400 && response.status < 500) {
    return false;
  }

  // Don't retry on success
  if (response.status >= 200 && response.status < 300) {
    return false;
  }

  return false;
}

/**
 * Hardened fetch with timeout, retries, and structured error handling
 *
 * @param url - The URL to fetch
 * @param options - Fetch options including retry configuration
 * @returns Promise resolving to Response
 * @throws FetchError, FetchTimeoutError, FetchNetworkError, or FetchRateLimitError
 */
export async function fetchWithRetry(
  url: string | URL,
  options: FetchRetryOptions = {},
): Promise<Response> {
  const {
    timeout = DEFAULT_OPTIONS.timeout,
    maxRetries = DEFAULT_OPTIONS.maxRetries,
    retryDelay = DEFAULT_OPTIONS.retryDelay,
    retryOn5xx = DEFAULT_OPTIONS.retryOn5xx,
    retryOnNetworkError = DEFAULT_OPTIONS.retryOnNetworkError,
    correlationId = uuidv4(),
    shouldRetry: customShouldRetry,
    ...fetchOptions
  } = options;

  let lastError: Error | undefined;
  let lastResponse: Response | undefined;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      // Create timeout controller for this attempt
      const timeoutController = createTimeoutController(timeout);

      // Merge abort signals if both are provided
      const abortController = new AbortController();
      if (fetchOptions.signal) {
        // If original signal aborts, abort our controller
        fetchOptions.signal.addEventListener("abort", () => {
          abortController.abort();
        });
      }
      timeoutController.signal.addEventListener("abort", () => {
        abortController.abort();
      });

      // Make the fetch request
      const response = await fetch(url, {
        ...fetchOptions,
        signal: abortController.signal,
        headers: {
          ...fetchOptions.headers,
          "X-Correlation-Id": correlationId,
        },
      });

      // Check if we should retry
      if (
        shouldRetryResponse(
          response,
          attempt,
          maxRetries,
          retryOn5xx,
          customShouldRetry,
        )
      ) {
        lastResponse = response;

        // Handle rate limiting
        if (response.status === 429) {
          const retryAfter = response.headers.get("Retry-After");
          const retryAfterSeconds = retryAfter
            ? parseInt(retryAfter, 10)
            : undefined;

          if (attempt < maxRetries) {
            const delay = retryAfterSeconds
              ? retryAfterSeconds * 1000
              : calculateBackoffDelay(attempt, retryDelay);

            logError(
              new FetchRateLimitError(
                `Rate limited (429) on attempt ${attempt + 1}/${maxRetries + 1}`,
                retryAfterSeconds,
                correlationId,
              ),
              {
                url: String(url),
                attempt: attempt + 1,
                maxRetries: maxRetries + 1,
                delay,
                correlationId,
              },
            );

            await new Promise((resolve) => setTimeout(resolve, delay));
            continue;
          } else {
            throw new FetchRateLimitError(
              `Rate limited after ${maxRetries + 1} attempts`,
              retryAfterSeconds,
              correlationId,
            );
          }
        }

        // Retry on 5xx errors
        if (response.status >= 500 && response.status < 600) {
          if (attempt < maxRetries) {
            const delay = calculateBackoffDelay(attempt, retryDelay);

            logError(
              new FetchError(
                `Server error (${response.status}) on attempt ${attempt + 1}/${maxRetries + 1}`,
                response.status,
                response.statusText,
                correlationId,
                attempt + 1,
              ),
              {
                url: String(url),
                attempt: attempt + 1,
                maxRetries: maxRetries + 1,
                delay,
                correlationId,
              },
            );

            await new Promise((resolve) => setTimeout(resolve, delay));
            continue;
          }
        }
      }

      // Success or non-retryable error
      return response;
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Handle AbortError (timeout)
      if (error instanceof Error && error.name === "AbortError") {
        if (attempt < maxRetries && retryOnNetworkError) {
          const delay = calculateBackoffDelay(attempt, retryDelay);

          logError(
            new FetchTimeoutError(
              `Request timeout after ${timeout}ms on attempt ${attempt + 1}/${maxRetries + 1}`,
              timeout,
              correlationId,
            ),
            {
              url: String(url),
              attempt: attempt + 1,
              maxRetries: maxRetries + 1,
              delay,
              correlationId,
            },
          );

          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        } else {
          throw new FetchTimeoutError(
            `Request timeout after ${timeout}ms (${maxRetries + 1} attempts)`,
            timeout,
            correlationId,
          );
        }
      }

      // Handle network errors
      if (
        error instanceof TypeError ||
        (error instanceof Error &&
          (error.message.includes("fetch") ||
            error.message.includes("network") ||
            error.message.includes("ECONNREFUSED") ||
            error.message.includes("ENOTFOUND")))
      ) {
        if (attempt < maxRetries && retryOnNetworkError) {
          const delay = calculateBackoffDelay(attempt, retryDelay);

          logError(
            new FetchNetworkError(
              `Network error on attempt ${attempt + 1}/${maxRetries + 1}: ${error.message}`,
              error,
              correlationId,
            ),
            {
              url: String(url),
              attempt: attempt + 1,
              maxRetries: maxRetries + 1,
              delay,
              correlationId,
            },
          );

          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        } else {
          throw new FetchNetworkError(
            `Network error after ${maxRetries + 1} attempts: ${error.message}`,
            error,
            correlationId,
          );
        }
      }

      // Re-throw unknown errors
      throw error;
    }
  }

  // If we get here, we've exhausted retries
  if (lastResponse) {
    throw new FetchError(
      `Request failed after ${maxRetries + 1} attempts with status ${lastResponse.status}`,
      lastResponse.status,
      lastResponse.statusText,
      correlationId,
      maxRetries + 1,
    );
  }

  if (lastError) {
    throw new FetchNetworkError(
      `Request failed after ${maxRetries + 1} attempts: ${lastError.message}`,
      lastError,
      correlationId,
    );
  }

  throw new FetchError(
    `Request failed after ${maxRetries + 1} attempts`,
    undefined,
    undefined,
    correlationId,
    maxRetries + 1,
  );
}

/**
 * Convenience wrapper for JSON requests with retry
 */
export async function fetchJsonWithRetry<T = unknown>(
  url: string | URL,
  options: FetchRetryOptions = {},
): Promise<T> {
  const response = await fetchWithRetry(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

  if (!response.ok) {
    throw new FetchError(
      `JSON request failed with status ${response.status}`,
      response.status,
      response.statusText,
      options.correlationId,
    );
  }

  return response.json() as Promise<T>;
}

import { nip19 } from "nostr-tools";
export const getTimeRemaining = (
  scheduledDate: string | Date,
  currentTime: Date = new Date(),
): string => {
  const scheduleUTC = new Date(scheduledDate);
  const currentUTC = new Date(currentTime);

  const total = scheduleUTC.getTime() - currentUTC.getTime();
  const seconds = Math.floor((total / 1000) % 60);
  const minutes = Math.floor((total / 1000 / 60) % 60);
  const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
  const days = Math.floor(total / (1000 * 60 * 60 * 24));

  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${minutes}m`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
};

export function convertToHex(key: string): string | null {
  try {
    const { data } = nip19.decode(key);
    return typeof data === "string" ? data : null;
  } catch (error) {
    console.error("Error decoding npub:", error);
    return null;
  }
}

export const formatDate = (date: string | Date): string => {
  return new Date(date).toLocaleString("en-US", {
    month: "2-digit",
    day: "2-digit",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
};

export const getImageUrls = (fileUrl: string[]): string[] => {
  if (!fileUrl || fileUrl.length === 0) return [];

  // Handle case where fileUrl is an array of JSON strings
  if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
    try {
      return JSON.parse(fileUrl[0]) as string[];
    } catch (e) {
      console.error("Error parsing fileUrl:", e);
      return [];
    }
  }

  // Handle direct URLs
  return fileUrl;
};

/**
 * Determines if a URL points to a video file based on its extension
 * @param url - The URL to check
 * @returns true if the URL appears to be a video file
 */
export const isVideoFile = (url: string): boolean => {
  if (!url || typeof url !== "string") return false;

  const lowerUrl = url.toLowerCase();
  const videoExtensions = [
    ".mp4",
    ".mov",
    ".webm",
    ".ogg",
    ".avi",
    ".mkv",
    ".m4v",
    ".3gp",
    ".flv",
    ".wmv",
  ];

  // Check if URL ends with a video extension (after removing query params and fragments)
  const urlWithoutQuery = lowerUrl.split("?")[0]?.split("#")[0];
  if (!urlWithoutQuery) return false;
  return videoExtensions.some((ext) => urlWithoutQuery.endsWith(ext));
};

import { marked } from "marked";
import sanitizeHtml from "sanitize-html";

/**
 * Allowed HTML tags for markdown content
 */
const ALLOWED_TAGS = [
  "p",
  "br",
  "strong",
  "em",
  "b",
  "i",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "ul",
  "ol",
  "li",
  "blockquote",
  "pre",
  "code",
  "a",
  "img",
];

/**
 * Allowed attributes per tag
 */
const ALLOWED_ATTRIBUTES: sanitizeHtml.IOptions["allowedAttributes"] = {
  a: ["href", "title", "target", "rel"],
  img: ["src", "alt", "title", "loading"],
  code: ["class"],
};

/**
 * Sanitizes markdown content by parsing it to HTML and then sanitizing the HTML
 * Uses sanitize-html library for robust XSS protection
 *
 * @param markdown - The markdown string to sanitize
 * @returns Sanitized HTML string
 */
export function sanitizeMarkdown(markdown: string): string {
  if (!markdown || typeof markdown !== "string") {
    return "";
  }

  try {
    // Parse markdown to HTML using marked
    const htmlResult = marked(markdown, {
      gfm: true,
      breaks: false,
      pedantic: false,
      smartLists: true,
      smartypants: false,
    });
    const html =
      typeof htmlResult === "string" ? htmlResult : String(htmlResult ?? "");

    // Preserve code blocks before sanitization
    // sanitize-html will escape code block content, which we want to preserve as-is
    const codeBlockPlaceholders: Array<{ placeholder: string; content: string }> =
      [];
    let placeholderIndex = 0;

    // Extract code blocks and replace with placeholders
    // Use a unique placeholder that won't be modified by sanitize-html
    const htmlWithPlaceholders = html.replace(
      /<pre><code(?: class="language-([^"]*)")?>([\s\S]*?)<\/code><\/pre>/gi,
      (match, lang, code) => {
        const placeholder = `__CODE_BLOCK_PLACEHOLDER_${placeholderIndex}__`;
        const codeStr = typeof code === "string" ? code : String(code ?? "");
        const langStr = typeof lang === "string" ? lang : String(lang ?? "");

        // Sanitize language class name
        const sanitizedLang = langStr.replace(/[^a-zA-Z0-9-_]/g, "");

        // Preserve the code block content (it's already HTML-escaped by marked)
        // We'll restore it after sanitization
        codeBlockPlaceholders.push({
          placeholder,
          content: sanitizedLang
            ? `<pre><code class="language-${sanitizedLang}">${codeStr}</code></pre>`
            : `<pre><code>${codeStr}</code></pre>`,
        });
        placeholderIndex++;
        return placeholder;
      },
    );

    // Sanitize HTML using sanitize-html library
    const sanitized = sanitizeHtml(htmlWithPlaceholders, {
      allowedTags: ALLOWED_TAGS,
      allowedAttributes: ALLOWED_ATTRIBUTES,
      allowedSchemes: ["http", "https"],
      allowedSchemesByTag: {
        img: ["http", "https", "data"], // Allow data URIs for images if needed
      },
      allowedSchemesAppliedToAttributes: ["href", "src"],
      // Ensure links open in new tab with security attributes
      transformTags: {
        a: (tagName, attribs) => {
          return {
            tagName: "a",
            attribs: {
              ...attribs,
              target: "_blank",
              rel: "noopener noreferrer",
            },
          };
        },
        img: (tagName, attribs) => {
          return {
            tagName: "img",
            attribs: {
              ...attribs,
              loading: "lazy",
            },
          };
        },
      },
    });

    // Restore code blocks (placeholders should remain unchanged by sanitize-html)
    let finalHtml = sanitized;
    codeBlockPlaceholders.forEach(({ placeholder, content }) => {
      finalHtml = finalHtml.replace(placeholder, content);
    });

    return finalHtml;
  } catch (error) {
    console.error("Error sanitizing markdown:", error);
    return "";
  }
}

export function extractPlainText(markdown: string): string {
  if (!markdown || typeof markdown !== "string") {
    return "";
  }

  return markdown
    .replace(/#+\s*/g, "")
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/\*(.*?)\*/g, "$1")
    .replace(/~~(.*?)~~/g, "$1")
    .replace(/`(.*?)`/g, "$1")
    .replace(/\[(.*?)\]\(.*?\)/g, "$1")
    .replace(/!\[(.*?)\]\(.*?\)/g, "$1")
    .replace(/>\s*/g, "")
    .replace(/^\s*[-*+]\s+/gm, "")
    .replace(/^\s*\d+\.\s+/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

export function generateSummary(content: string, maxLength = 280): string {
  const plainText = extractPlainText(content);
  if (plainText.length <= maxLength) {
    return plainText;
  }

  const truncated = plainText.substring(0, maxLength);
  const lastSpace = truncated.lastIndexOf(" ");

  if (lastSpace > maxLength * 0.8) {
    return truncated.substring(0, lastSpace) + "...";
  }

  return truncated + "...";
}

/**
 * Canonical Nostr Adapter (Client-side)
 *
 * This module provides a unified interface for client-side Nostr operations.
 * It wraps window.nostr (NIP-07) and nostr-tools for consistent event signing.
 *
 * Usage:
 *   import { nostrAdapter } from "~/lib/nostr-adapter.client";
 *   const result = await nostrAdapter.signEvent(eventData);
 */

import { nip19 } from "nostr-tools";

import type {
  NostrEvent,
  SignedEvent,
  SignEventResult,
  NostrEventData,
  LongFormEventData,
} from "~/features/nostr/types";

/**
 * Canonical Nostr adapter for client-side operations
 */
export const nostrAdapter = {
  /**
   * Encode hex public key to npub (bech32)
   */
  encodeNpub(hex: string): string | null {
    try {
      return nip19.npubEncode(hex);
    } catch {
      return null;
    }
  },

  /**
   * Decode npub (bech32) to hex public key
   */
  decodeNpub(npub: string): string | null {
    try {
      if (!npub.startsWith("npub")) {
        return npub; // Already hex
      }
      const { data } = nip19.decode(npub);
      return typeof data === "string" ? data : null;
    } catch {
      return null;
    }
  },

  /**
   * Sign an event using NIP-07 (window.nostr)
   * This is the canonical way to sign events client-side
   */
  async signEvent(eventData: NostrEventData): Promise<SignEventResult> {
    try {
      // Add retry logic to handle extension loading
      let retries = 0;
      const maxRetries = 5;

      while (retries < maxRetries) {
        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        if (window.nostr) {
          const nostrEvent: NostrEvent = {
            content: eventData.content,
            created_at: eventData.created_at,
            kind: eventData.kind ?? 1,
            tags: eventData.tags ?? [],
          };

          // @ts-ignore - window.nostr is injected by browser extensions at runtime
          const signResult = await window.nostr.signEvent(nostrEvent);

          // Handle different return types from different extensions
          const signedEvent: SignedEvent = {
            id: signResult?.id ?? "unknown",
            pubkey: signResult?.pubkey ?? "unknown",
            created_at: nostrEvent.created_at,
            kind: nostrEvent.kind,
            tags: nostrEvent.tags,
            content: nostrEvent.content,
            sig:
              typeof signResult === "string"
                ? signResult
                : (signResult?.sig ?? "unknown"),
          };

          return { nostrEvent, signedEvent };
        }

        retries++;
        await new Promise((resolve) => setTimeout(resolve, 500));
      }

      throw new Error(
        "Nostr extension not found after retries. Please install a Nostr extension."
      );
    } catch (error) {
      // Only log on client side
      if (typeof window !== "undefined") {
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { logClientError } = await import("~/lib/error-handler.client");
        logClientError(
          error instanceof Error ? error : new Error(String(error)),
          {
            component: "nostr-adapter",
            action: "signEvent",
          },
          "error"
        );
      }
      throw error;
    }
  },

  /**
   * Sign a long-form event (NIP-23) using NIP-07
   */
  async signLongFormEvent(
    eventData: LongFormEventData
  ): Promise<SignEventResult> {
    try {
      // Add retry logic to handle extension loading
      let retries = 0;
      const maxRetries = 5;

      while (retries < maxRetries) {
        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        if (window.nostr) {
          // Build NIP-23 tags
          const eventTags: string[][] = [];

          if (eventData.title) {
            eventTags.push(["title", eventData.title]);
          }
          eventTags.push(["r", "wss://relay.primal.net/"]);
          eventTags.push(["client", "SmartFlow"]);
          if (eventData.summary) {
            eventTags.push(["summary", eventData.summary]);
          }
          if (eventData.image) {
            eventTags.push(["image", eventData.image]);
          }
          if (eventData.identifier) {
            eventTags.push(["d", eventData.identifier]);
          }
          if (eventData.publishedAt) {
            eventTags.push(["published_at", eventData.publishedAt.toString()]);
          }
          if (eventData.tags && eventData.tags.length > 0) {
            eventData.tags.forEach((tag) => {
              if (tag.trim()) {
                eventTags.push(["t", tag.trim().toLowerCase()]);
              }
            });
          }

          const nostrEvent: NostrEvent = {
            content: eventData.content,
            created_at: Math.floor(Date.now() / 1000),
            kind: 30023, // NIP-23 long-form content
            tags: eventTags,
          };

          // @ts-ignore - window.nostr is injected by browser extensions at runtime
          const signResult = await window.nostr.signEvent(nostrEvent);

          // Handle different return types from different extensions
          const signedEvent: SignedEvent = {
            id: signResult?.id ?? "unknown",
            pubkey: signResult?.pubkey ?? "unknown",
            created_at: nostrEvent.created_at,
            kind: nostrEvent.kind,
            tags: nostrEvent.tags,
            content: nostrEvent.content,
            sig:
              typeof signResult === "string"
                ? signResult
                : (signResult?.sig ?? "unknown"),
          };

          return { nostrEvent, signedEvent };
        }

        retries++;
        await new Promise((resolve) => setTimeout(resolve, 500));
      }

      throw new Error(
        "Nostr extension not found after retries. Please install a Nostr extension."
      );
    } catch (error) {
      // Only log on client side
      if (typeof window !== "undefined") {
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { logClientError } = await import("~/lib/error-handler.client");
        logClientError(
          error instanceof Error ? error : new Error(String(error)),
          {
            component: "nostr-adapter",
            action: "signLongFormEvent",
          },
          "error"
        );
      }
      throw error;
    }
  },
};

/**
 * Re-export types for convenience
 */
export type {
  NostrEvent,
  SignedEvent,
  SignEventResult,
} from "~/features/nostr/types";

import { nip04, finalizeEvent, nip19 } from "nostr-tools";

import { logWarning, logError } from "~/lib/error-logger.server";

import { convertToHex } from "./nostr-conversion";
import { relaysArray } from "./relays";

interface SendNostrDirectMessageResult {
  success: boolean;
  event?: unknown;
  status?: number;
  error?: string;
}

export async function sendNostrDirectMessage(
  receiverPubkey: string,
  content: string,
): Promise<SendNostrDirectMessageResult | false> {
  try {
    if (!content) {
      return Promise.resolve(false);
    }
    const nsecEnv = process.env["NOSTR_NSEC"];
    if (!nsecEnv) {
      return Promise.resolve({
        success: false,
        error: "NOSTR_NSEC is not set.",
      });
    }
    const nsecHex: string | null = convertToHex(nsecEnv);

    if (!nsecHex) {
      return {
        success: false,
        error: "NOSTR_NSEC could not be converted to hex.",
      };
    }

    // Convert hex string to Uint8Array for finalizeEvent
    let privateKeyBytes: Uint8Array;
    try {
      if (nsecEnv.startsWith("nsec")) {
        const decoded = nip19.decode(nsecEnv);
        if (decoded.type === "nsec") {
          privateKeyBytes = decoded.data;
        } else {
          throw new Error("Invalid nsec format");
        }
      } else {
        // Assume hex string
        privateKeyBytes = new Uint8Array(
          nsecHex.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? [],
        );
      }
    } catch {
      // Fallback: treat as hex string
      privateKeyBytes = new Uint8Array(
        nsecHex.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? [],
      );
    }

    // Ensure receiver pubkey is hex. Convert if an npub/bech32 is provided.
    let receiverHex: string = receiverPubkey;
    try {
      if (
        typeof receiverPubkey === "string" &&
        receiverPubkey.startsWith("npub")
      ) {
        const converted = convertToHex(receiverPubkey);
        if (converted) receiverHex = converted;
      }
    } catch (e) {
      logWarning(
        "Failed to convert receiver pubkey to hex; using original value",
        {
          receiverPubkey,
          error: e instanceof Error ? e.message : String(e),
        },
      );
    }

    // Encrypt the content
    const encryptedContent: string = nip04.encrypt(
      nsecHex,
      receiverHex,
      content,
    );

    // Create event template
    const eventTemplate = {
      kind: 4, // NIP-04 encrypted direct message
      created_at: Math.floor(Date.now() / 1000),
      tags: [
        ["p", receiverHex], // Recipient's pubkey
      ],
      content: encryptedContent,
    };

    // Sign the event
    const signedEvent = finalizeEvent(eventTemplate, privateKeyBytes);

    // Send the event to the publisher
    const publisherUrl = process.env["NOSTR_PUBLISHER_URL"];
    if (!publisherUrl) {
      return {
        success: false,
        error: "NOSTR_PUBLISHER_URL is not set.",
        event: signedEvent,
      };
    }

    const response = await fetch(publisherUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        relays: relaysArray,
        event: signedEvent,
      }),
    });

    if (!response.ok) {
      let errorText = "";
      try {
        errorText = await response.text();
      } catch (_err) {
        // ignore
      }
      return {
        success: false,
        status: response.status,
        error: errorText,
        event: signedEvent,
      };
    }

    return { success: true, event: signedEvent };
  } catch (error: unknown) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      receiverPubkey,
      message: "Error sending Nostr direct message",
    });
    const errorMessage = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      error: errorMessage,
    };
  }
}

import { WebSocket } from "ws";

type CacheParams = Record<string, unknown>;
type CacheResponse = unknown[];

/**
 * Gets Primal cache endpoints from environment variable or uses defaults
 * Supports comma-separated list of WebSocket URLs
 */
function getCacheEndpoints(): string[] {
  const envUrl = process.env["PRIMAL_CACHING_URL"];

  if (envUrl) {
    // Support comma-separated list of endpoints
    const endpoints = envUrl
      .split(",")
      .map((url) => url.trim())
      .filter(Boolean);
    if (endpoints.length > 0) {
      return endpoints;
    }
  }

  // Default fallback endpoints (public Primal cache servers only)
  return ["wss://cache1.primal.net/v1", "wss://cache2.primal.net/v1"];
}

async function tryConnectToCache(
  endpoint: string,
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  return new Promise((resolve, reject) => {
    let resolved = false;
    const ws = new WebSocket(endpoint) as unknown as WebSocket & {
      onopen: (() => void) | null;
      onmessage: ((event: { data: { toString(): string } }) => void) | null;
      onerror: ((ev: Event) => void) | null;
      onclose: (() => void) | null;
    };
    const requestId = Math.random().toString(36).substring(2, 12);
    const responses: unknown[] = [];

    ws.onopen = () => {
      switch (requestType) {
        case "net_stats":
          ws.send(JSON.stringify(["REQ", requestId, { cache: ["net_stats"] }]));
          break;
        case "feed":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["feed", { pubkey: params["pubkey"] }] },
            ]),
          );
          break;
        case "thread_view": {
          const threadViewMsg = JSON.stringify([
            "REQ",
            requestId,
            { cache: ["thread_view", { event_id: params["event_id"] }] },
          ]);
          ws.send(threadViewMsg);
          break;
        }
        case "user_infos":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["user_infos", { pubkeys: params["pubkeys"] }] },
            ]),
          );
          break;
        case "events":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["events", { event_ids: params["event_ids"] }] },
            ]),
          );
          break;
        case "user_profile":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              { cache: ["user_profile", { pubkey: params["pubkey"] }] },
            ]),
          );
          break;
        // ---- Added request types below ----

        // Get reposts (kind: 6)
        case "reposts":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params["event_id"],
                    kind: 6,
                    limit: params["limit"] ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get likes/reactions (kind: 7)
        case "likes":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params["event_id"],
                    kind: 7,
                    limit: params["limit"] ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get replies (kind: 1)
        case "replies":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params["event_id"],
                    kind: 1,
                    limit: params["limit"] ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // Get zaps (kind: 9735)
        case "zaps":
          ws.send(
            JSON.stringify([
              "REQ",
              requestId,
              {
                cache: [
                  "event_actions",
                  {
                    event_id: params["event_id"],
                    kind: 9735,
                    limit: params["limit"] ?? 100,
                  },
                ],
              },
            ]),
          );
          break;

        // ---- End of added request types ----
        default:
          ws.close();
          reject(new Error("Invalid request type"));
          return;
      }
    };

    ws.onmessage = (event: { data: { toString(): string } }) => {
      const data = JSON.parse(event.data.toString()) as unknown;
      const dataArray = Array.isArray(data) ? data : [];
      responses.push(dataArray);

      if (dataArray[0] === "EOSE") {
        ws.send(JSON.stringify(["CLOSE", requestId]));
        ws.close();
        if (!resolved) {
          resolved = true;
          resolve(responses);
        }
      }
    };

    ws.onerror = (ev: Event) => {
      const error =
        ev instanceof ErrorEvent && ev.error instanceof Error
          ? ev.error
          : new Error("WebSocket error");
      console.error(`[WS] WebSocket error on ${endpoint}:`, error);
      ws.close();
      if (!resolved) {
        resolved = true;
        reject(error);
      }
    };

    ws.onclose = () => {
      // If ws closed before resolved, must reject if not already handled
      if (!resolved) {
        resolved = true;
        resolve(responses);
      }
    };

    // timeout in case hangs forever
    setTimeout(() => {
      if (!resolved) {
        resolved = true;
        try {
          ws.close();
        } catch {
          // Ignore errors when closing WebSocket during timeout
        }
        resolve(responses);
      }
    }, 6000);
  });
}

/**
 * Attempts each Primal cache endpoint, returning the first successful non-empty response.
 * Uses PRIMAL_CACHING_URL from environment (comma-separated for multiple endpoints),
 * or falls back to default endpoints if not configured.
 */
export async function connectToPrimalCache(
  requestType: string,
  params: CacheParams,
): Promise<CacheResponse> {
  const endpoints = getCacheEndpoints();

  for (const endpoint of endpoints) {
    try {
      const responses = await tryConnectToCache(endpoint, requestType, params);

      // A "good" response: has at least one element that's not ["EOSE"]
      const nonEose = responses?.filter(
        (res): res is unknown[] => Array.isArray(res) && res[0] !== "EOSE",
      );

      if (nonEose && nonEose.length > 0) {
        return responses;
      }
      // else, try next endpoint
    } catch (err) {
      console.error(`[Cache] ${endpoint} failed with error:`, err);
      // try next endpoint
      continue;
    }
  }
  // All endpoints failed or gave empty responses
  console.error("[Cache] All endpoints failed or gave empty responses");
  throw new Error("All Primal cache endpoints failed or gave empty responses.");
}

import { PrismaClient } from "@prisma/client";

import { env } from "./env.server";
import { recordQueryMetrics } from "./query-metrics.server";
import { singleton } from "./singleton.server";
// Hard-code a unique key, so we can look up the client when this module gets re-imported
const prisma = singleton("prisma", getPrismaClient);

function getPrismaClient() {
  // Use validated env object to ensure DATABASE_URL is set and valid
  const DATABASE_URL = env.DATABASE_URL;

  const databaseUrl = new URL(DATABASE_URL);

  const isLocalHost = databaseUrl.hostname === "localhost";

  const PRIMARY_REGION = isLocalHost ? null : env.PRIMARY_REGION;
  const FLY_REGION = isLocalHost ? null : env.FLY_REGION;

  const isReadReplicaRegion = !PRIMARY_REGION || PRIMARY_REGION === FLY_REGION;

  if (!isLocalHost) {
    if (databaseUrl.host.endsWith(".internal")) {
      databaseUrl.host = `${String(FLY_REGION ?? "")}.${databaseUrl.host}`;
    }

    if (!isReadReplicaRegion) {
      // 5433 is the read-replica port
      databaseUrl.port = "5433";
    }
  }

  // NOTE: during development if you change anything in this function, remember
  // that this only runs once per server restart and won't automatically be
  // re-run per request like everything else is. So if you need to change
  // something in this file, you'll need to manually restart the server.
  const baseClient = new PrismaClient({
    datasources: {
      db: {
        url: databaseUrl.toString(),
      },
    },
    // Enable query logging in development for performance monitoring
    log:
      env.NODE_ENV === "development"
        ? ["query", "info", "warn", "error"]
        : ["error"],
  });

  // Add query performance monitoring middleware using $extends (Prisma 5+)
  const client = baseClient.$extends({
    query: {
      $allModels: {
        async $allOperations({ model, operation, args, query }) {
          const before = Date.now();
          let error: Error | undefined;

          try {
            const result = await query(args);
            const after = Date.now();
            const duration = after - before;

            // Record metrics
            recordQueryMetrics(model ?? "unknown", operation, duration, true);

            // Log slow queries (over 100ms)
            if (duration > 100) {
              console.warn(
                `⚠️ Slow query detected: ${model}.${operation} took ${duration}ms`,
                {
                  model,
                  operation,
                  duration,
                  args,
                },
              );
            }

            return result;
          } catch (err) {
            error = err instanceof Error ? err : new Error(String(err));
            const after = Date.now();
            const duration = after - before;

            // Record error metrics
            recordQueryMetrics(
              model ?? "unknown",
              operation,
              duration,
              false,
              error,
            );

            // Log query errors

            console.error(
              `❌ Query error: ${model}.${operation} failed after ${duration}ms`,
              {
                model,
                operation,
                error: error.message,
                duration,
              },
            );

            throw err;
          }
        },
      },
    },
  });

  // connect eagerly
  void client.$connect();

  return client;
}

export { prisma };

/**
 * Query Performance Metrics
 *
 * Provides Prometheus metrics for database query performance monitoring.
 * Metrics are automatically registered with the default Prometheus registry
 * and will be exposed via the /metrics endpoint.
 */

import * as promClient from "prom-client";

import { singleton } from "./singleton.server";
/**
 * Get or create a metric, handling hot-reloads gracefully
 */
function getOrCreateMetric<T extends promClient.Metric>(
  name: string,
  factory: () => T,
): T {
  return singleton(`prom_metric_${name}`, () => {
    // Check if metric already exists in registry
    const registry = promClient.register;
    try {
      const existingMetric = registry.getSingleMetric(name);
      if (existingMetric) {
        return existingMetric as T;
      }
    } catch {
      // Metric doesn't exist, continue to create it
    }

    try {
      return factory();
    } catch (error) {
      // If metric already exists (e.g., from hot reload), try to get it
      if (
        error instanceof Error &&
        error.message.includes("has already been registered")
      ) {
        const existingMetric = registry.getSingleMetric(name);
        if (existingMetric) {
          return existingMetric as T;
        }
      }
      throw error;
    }
  });
}

/**
 * Query duration histogram
 * Tracks how long queries take, broken down by model and action
 *
 * Example PromQL queries:
 * - Average query time: rate(prisma_query_duration_ms_sum[5m]) / rate(prisma_query_duration_ms_count[5m])
 * - P95 query time: histogram_quantile(0.95, rate(prisma_query_duration_ms_bucket[5m]))
 * - Slow queries: rate(prisma_slow_query_total[5m])
 */
export const queryDurationHistogram = getOrCreateMetric(
  "prisma_query_duration_ms",
  () =>
    new promClient.Histogram({
      name: "prisma_query_duration_ms",
      help: "Duration of Prisma queries in milliseconds",
      labelNames: ["model", "action", "status"],
      buckets: [10, 50, 100, 200, 500, 1000, 2000, 5000],
      // Register with default registry (used by express-prometheus-middleware)
    }),
);

/**
 * Query counter
 * Tracks total number of queries by model and action
 */
export const queryCounter = getOrCreateMetric(
  "prisma_query_total",
  () =>
    new promClient.Counter({
      name: "prisma_query_total",
      help: "Total number of Prisma queries",
      labelNames: ["model", "action", "status"],
    }),
);

/**
 * Slow query counter
 * Tracks queries that exceed the slow query threshold (100ms)
 */
export const slowQueryCounter = getOrCreateMetric(
  "prisma_slow_query_total",
  () =>
    new promClient.Counter({
      name: "prisma_slow_query_total",
      help: "Total number of slow Prisma queries (>100ms)",
      labelNames: ["model", "action"],
    }),
);

/**
 * Query error counter
 * Tracks failed queries
 */
export const queryErrorCounter = getOrCreateMetric(
  "prisma_query_errors_total",
  () =>
    new promClient.Counter({
      name: "prisma_query_errors_total",
      help: "Total number of Prisma query errors",
      labelNames: ["model", "action", "error_type"],
    }),
);

/**
 * Record query metrics
 */
export function recordQueryMetrics(
  model: string,
  action: string,
  duration: number,
  success = true,
  error?: Error,
): void {
  const status = success ? "success" : "error";

  // Record duration
  queryDurationHistogram.observe(
    {
      model,
      action,
      status,
    },
    duration,
  );

  // Increment query counter
  queryCounter.inc({
    model,
    action,
    status,
  });

  // Record slow queries
  if (duration > 100) {
    slowQueryCounter.inc({
      model,
      action,
    });
  }

  // Record errors
  if (!success && error) {
    const errorType = error.constructor.name ?? "UnknownError";
    queryErrorCounter.inc({
      model,
      action,
      error_type: errorType,
    });
  }
}

/**
 * TanStack Query client configuration
 * Provides a singleton QueryClient instance for the application
 */

import { QueryClient } from "@tanstack/react-query";

/**
 * Default query client configuration
 * Optimized for Remix SSR and client-side data fetching
 */
export function createQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: {
        // Stale time: data is considered fresh for 5 minutes
        staleTime: 1000 * 60 * 5,
        // Cache time: data stays in cache for 10 minutes after it becomes unused
        gcTime: 1000 * 60 * 10,
        // Retry failed requests 1 time
        retry: 1,
        // Refetch on window focus in development, but not in production
        refetchOnWindowFocus: process.env.NODE_ENV === "development",
        // Don't refetch on mount if data is fresh
        refetchOnMount: false,
        // Don't refetch on reconnect if data is fresh
        refetchOnReconnect: false,
      },
      mutations: {
        // Retry failed mutations 1 time
        retry: 1,
      },
    },
  });
}

/**
 * Singleton QueryClient instance
 * Created once and reused across the application
 */
let browserQueryClient: QueryClient | undefined;

export function getQueryClient() {
  if (typeof window === "undefined") {
    // Server: always make a new query client
    return createQueryClient();
  } else {
    // Browser: use singleton pattern to keep the same query client
    browserQueryClient ??= createQueryClient();
    return browserQueryClient;
  }
}

/**
 * Rate Limiting Middleware
 *
 * Provides rate limiting functionality to protect against abuse, DDoS attacks, and API exhaustion.
 * Uses both in-memory (express-rate-limit) and Redis-based (rate-limiter-flexible) rate limiting.
 */

import type { Request, Response, NextFunction } from "express";
import rateLimit from "express-rate-limit";
import { RateLimiterRedis } from "rate-limiter-flexible";

import { redis } from "~/infra/queue/queue-client.server";

/**
 * Check if we're in a test environment
 * Rate limiting should be disabled or relaxed in test environments
 * This is checked at request time, not module load time, to support dynamic env vars
 */
function isTestEnvironment(): boolean {
  // Check environment variables at request time
  const nodeEnv = process.env["NODE_ENV"];
  const cypress = process.env["CYPRESS"];
  const e2eTest = process.env["E2E_TEST"];
  const disableRateLimit = process.env["DISABLE_RATE_LIMIT"];

  return (
    nodeEnv === "test" ||
    cypress === "true" ||
    e2eTest === "true" ||
    disableRateLimit === "true"
  );
}

/**
 * General API rate limiter
 * Limits: 100 requests per 15 minutes per IP
 * Disabled in test environments
 */
export const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: isTestEnvironment() ? 10000 : 100, // Very high limit in tests, normal in production
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: "Too many requests, please try again later.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many requests, please try again later.",
      retryAfter: Math.ceil(
        (req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) /
          1000,
      ),
    });
  },
  skip: (_req: Request) => isTestEnvironment(), // Skip rate limiting entirely in test environments
});

/**
 * Strict rate limiter for sensitive endpoints
 * Limits: 10 requests per 15 minutes per IP
 * Disabled in test environments
 */
export const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: isTestEnvironment() ? 10000 : 10, // Very high limit in tests, normal in production
  standardHeaders: true,
  legacyHeaders: false,
  message: "Rate limit exceeded for this endpoint.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Rate limit exceeded for this endpoint. Please try again later.",
      retryAfter: Math.ceil(
        (req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) /
          1000,
      ),
    });
  },
  skip: (_req: Request) => isTestEnvironment(), // Skip rate limiting entirely in test environments
});

/**
 * Very strict rate limiter for authentication endpoints
 * Limits: 5 requests per 15 minutes per IP
 * Disabled in test environments
 */
export const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: isTestEnvironment() ? 10000 : 5, // Very high limit in tests, normal in production
  standardHeaders: true,
  legacyHeaders: false,
  message: "Too many authentication attempts, please try again later.",
  handler: (req: Request, res: Response) => {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many authentication attempts, please try again later.",
      retryAfter: Math.ceil(
        (req.rateLimit?.resetTime ?? Date.now() + 15 * 60 * 1000 - Date.now()) /
          1000,
      ),
    });
  },
  skip: (_req: Request) => isTestEnvironment(), // Skip rate limiting entirely in test environments
});

/**
 * Check if Redis is available for rate limiting
 */
function isRedisAvailable(): boolean {
  return !!process.env["REDIS_URL"] && redis.status === "ready";
}

/**
 * Per-user rate limiting middleware
 * Uses Redis for distributed rate limiting across multiple server instances
 *
 * @param points - Number of requests allowed
 * @param duration - Time window in seconds
 */
export function createUserRateLimiter(points = 100, duration = 60) {
  return async (req: Request, res: Response, next: NextFunction) => {
    // Get user ID from request (set by auth middleware)
    const userId = req.user?.id;

    if (!userId) {
      // No user ID, skip rate limiting (will be handled by IP-based limiter)
      next(); return;
    }

    if (!isRedisAvailable()) {
      // Redis not available, skip Redis-based rate limiting
      next(); return;
    }

    try {
      // Create a per-user limiter with custom points/duration
      const userLimiter = new RateLimiterRedis({
        storeClient: redis,
        keyPrefix: `rl:user`,
        points,
        duration,
        blockDuration: duration,
      });

      await userLimiter.consume(userId);
      next();
    } catch (error: unknown) {
      // Rate limit exceeded
      // rate-limiter-flexible throws errors with msBeforeNext property
      const rateLimitError = error as { msBeforeNext?: number };
      const retryAfter = rateLimitError.msBeforeNext
        ? Math.ceil(rateLimitError.msBeforeNext / 1000)
        : duration;

      res.status(429).json({
        error: "Rate limit exceeded",
        message: "Too many requests, please try again later.",
        retryAfter,
      });
    }
  };
}

/**
 * Per-IP rate limiting using Redis (for distributed systems)
 * Falls back to in-memory limiter if Redis is not available
 */
export function createIPRateLimiter(points = 100, duration = 60) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!isRedisAvailable()) {
      // Redis not available, skip Redis-based rate limiting
      // Will be handled by express-rate-limit middleware
      next(); return;
    }

    const ip = req.ip ?? req.socket.remoteAddress ?? "unknown";

    try {
      const ipLimiter = new RateLimiterRedis({
        storeClient: redis,
        keyPrefix: `rl:ip`,
        points,
        duration,
        blockDuration: duration,
      });

      await ipLimiter.consume(ip);
      next();
    } catch (error: unknown) {
      // Rate limit exceeded
      // rate-limiter-flexible throws errors with msBeforeNext property
      const rateLimitError = error as { msBeforeNext?: number };
      const retryAfter = rateLimitError.msBeforeNext
        ? Math.ceil(rateLimitError.msBeforeNext / 1000)
        : duration;

      res.status(429).json({
        error: "Rate limit exceeded",
        message: "Too many requests from this IP, please try again later.",
        retryAfter,
      });
    }
  };
}

/**
 * Helper to get rate limit info for a user
 * Useful for displaying rate limit status to users
 */
export async function getRateLimitInfo(userId: string): Promise<{
  remaining: number;
  resetTime: number;
} | null> {
  if (!isRedisAvailable()) {
    return Promise.resolve(null);
  }

  try {
    const userLimiter = new RateLimiterRedis({
      storeClient: redis,
      keyPrefix: `rl:user`,
      points: 100,
      duration: 60,
    });

    const info = await userLimiter.get(userId);

    if (!info) {
      return Promise.resolve({
        remaining: 100, // Default points
        resetTime: Date.now() + 60 * 1000, // Default duration
      });
    }

    return Promise.resolve({
      remaining: info.remainingPoints,
      resetTime: Date.now() + info.msBeforeNext,
    });
  } catch (error) {
    console.error("Error getting rate limit info:", error);
    return Promise.resolve(null);
  }
}

/**
 * Secrets Sanitization Utility
 *
 * Prevents sensitive data (NWC strings, secrets, etc.) from appearing in logs or error messages
 */

/**
 * Patterns that indicate sensitive data
 */
const SENSITIVE_PATTERNS = [
  /nostr\+walletconnect:\/\/[^\s"']+/gi, // NWC connection strings
  /nsec1[a-z0-9]+/gi, // Nostr secret keys
  /encryptedNwc/gi, // Encrypted NWC field names
  /SESSION_SECRET/gi,
  /DATABASE_URL/gi,
  /REDIS_URL/gi,
  /STORAGE_(ACCESS_KEY|SECRET)/gi,
  /NOSTR_NSEC/gi,
  /OWNER_NWC/gi,
];

/**
 * Replace sensitive data with [REDACTED]
 */
export function sanitizeString(input: string): string {
  let sanitized = input;

  for (const pattern of SENSITIVE_PATTERNS) {
    sanitized = sanitized.replace(pattern, "[REDACTED]");
  }

  return sanitized;
}

/**
 * Sanitize an object recursively, removing or masking sensitive fields
 */
export function sanitizeObject<T>(obj: T): T {
  if (obj === null || obj === undefined) {
    return obj;
  }

  if (typeof obj === "string") {
    return sanitizeString(obj) as T;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => sanitizeObject(item)) as T;
  }

  if (typeof obj === "object") {
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      const lowerKey = key.toLowerCase();

      // Check if key indicates sensitive data
      if (
        lowerKey.includes("nwc") ||
        lowerKey.includes("secret") ||
        lowerKey.includes("password") ||
        lowerKey.includes("token") ||
        lowerKey.includes("key") ||
        lowerKey.includes("encrypted")
      ) {
        sanitized[key] = "[REDACTED]";
      } else {
        sanitized[key] = sanitizeObject(value);
      }
    }
    return sanitized as T;
  }

  return obj;
}

/**
 * Sanitize error message and stack trace
 */
export function sanitizeError(error: Error | unknown): {
  message: string;
  stack?: string;
  name: string;
} {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: sanitizeString(error.message),
      stack: error.stack ? sanitizeString(error.stack) : undefined,
    };
  }

  return {
    name: "Error",
    message: sanitizeString(String(error)),
  };
}

/**
 * Safe console.error that sanitizes sensitive data
 */
export function safeConsoleError(message: string, ...args: unknown[]): void {
  const sanitizedMessage = sanitizeString(message);
  const sanitizedArgs = args.map((arg) => {
    if (typeof arg === "string") {
      return sanitizeString(arg);
    }
    if (typeof arg === "object" && arg !== null) {
      return sanitizeObject(arg);
    }
    return arg;
  });

  console.error(sanitizedMessage, ...sanitizedArgs);
}

/**
 * Safe console.log that sanitizes sensitive data
 */
export function safeConsoleLog(message: string, ...args: unknown[]): void {
  const sanitizedMessage = sanitizeString(message);
  const sanitizedArgs = args.map((arg) => {
    if (typeof arg === "string") {
      return sanitizeString(arg);
    }
    if (typeof arg === "object" && arg !== null) {
      return sanitizeObject(arg);
    }
    return arg;
  });

  console.log(sanitizedMessage, ...sanitizedArgs);
}

/**
 * Security utilities for CSRF protection and request validation
 *
 * This module provides utilities for validating request origins and protecting
 * against CSRF attacks.
 */

import { env } from "./env.server";

/**
 * CSRF validation error
 */
export class CSRFValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CSRFValidationError";
  }
}

/**
 * Validates Origin header for CSRF protection
 *
 * @param request - The incoming request
 * @throws {CSRFValidationError} If origin validation fails
 */
export function validateOrigin(request: Request): void {
  const origin = request.headers.get("Origin");
  const referer = request.headers.get("Referer");

  // Allow same-origin requests (no Origin header)
  // This handles same-origin form submissions and navigation
  if (!origin && !referer) {
    return; // Same-origin request, allow it
  }

  // Get allowed origins from env
  const allowedOrigins: string[] = [];

  // Add APP_URL if set
  if (env.APP_URL) {
    try {
      const appUrl = new URL(env.APP_URL);
      allowedOrigins.push(appUrl.origin);
    } catch (_error) {
      console.warn("Invalid APP_URL in environment:", env.APP_URL);
    }
  }

  // Add ALLOWED_ORIGINS if set (comma-separated)
  if (env.ALLOWED_ORIGINS) {
    const origins = env.ALLOWED_ORIGINS.split(",").map((o) => o.trim());
    for (const originStr of origins) {
      try {
        const originUrl = new URL(originStr);
        allowedOrigins.push(originUrl.origin);
      } catch (_error) {
        console.warn("Invalid origin in ALLOWED_ORIGINS:", originStr);
      }
    }
  }

  // If no allowed origins configured, default to same-origin only
  // In development, allow localhost origins
  const isDevelopment = env.NODE_ENV === "development";
  if (allowedOrigins.length === 0 && !isDevelopment) {
    // In production without configuration, only allow same-origin
    // This is strict but safe
    if (origin || referer) {
      throw new CSRFValidationError(
        "CSRF protection enabled but no allowed origins configured"
      );
    }
    return;
  }

  // In development, add localhost origins
  if (isDevelopment) {
    allowedOrigins.push("http://localhost:3000");
    allowedOrigins.push("http://127.0.0.1:3000");
  }

  // Validate Origin if present (preferred header)
  if (origin) {
    try {
      const originUrl = new URL(origin);
      const isValid = allowedOrigins.some((allowed) => {
        try {
          const allowedUrl = new URL(allowed);
          return originUrl.origin === allowedUrl.origin;
        } catch {
          return false;
        }
      });

      if (!isValid) {
        throw new CSRFValidationError(
          `Invalid origin: ${origin}. Allowed origins: ${allowedOrigins.join(", ")}`
        );
      }
      return; // Origin is valid
    } catch (error) {
      if (error instanceof CSRFValidationError) {
        throw error;
      }
      throw new CSRFValidationError(`Invalid origin header format: ${origin}`);
    }
  }

  // Fallback to Referer if Origin not present (some browsers don't send Origin for same-origin)
  if (!origin && referer) {
    try {
      const refererUrl = new URL(referer);
      const isValid = allowedOrigins.some((allowed) => {
        try {
          const allowedUrl = new URL(allowed);
          return refererUrl.origin === allowedUrl.origin;
        } catch {
          return false;
        }
      });

      if (!isValid) {
        throw new CSRFValidationError(
          `Invalid referer: ${referer}. Allowed origins: ${allowedOrigins.join(", ")}`
        );
      }
      return; // Referer is valid
    } catch (error) {
      if (error instanceof CSRFValidationError) {
        throw error;
      }
      throw new CSRFValidationError(`Invalid referer header format: ${referer}`);
    }
  }
}

/**
 * Checks if a request method is state-changing
 */
export function isStateChangingMethod(method: string): boolean {
  return ["POST", "PUT", "PATCH", "DELETE"].includes(method.toUpperCase());
}

/**
 * Sentry Server-side Initialization
 *
 * Initializes Sentry for server-side error tracking
 * Only initializes if SENTRY_DSN is configured
 */

let sentryInitialized = false;

/**
 * Initialize Sentry for server-side error tracking
 * Should be called early in the application lifecycle (e.g., in entry.server.tsx)
 */
export function initSentry(): void {
  // Only initialize if DSN is provided and not already initialized
  if (sentryInitialized || !process.env["SENTRY_DSN"]) {
    return;
  }

  try {
    // Dynamic import to avoid bundling Sentry in production if not configured

    const Sentry = require("@sentry/remix") as {
      init: (options: {
        dsn?: string;
        environment?: string;
        tracesSampleRate?: number;
        profilesSampleRate?: number;
        beforeSend?: (event: unknown, hint: unknown) => unknown;
        integrations?: unknown[];
      }) => void;
      captureException: (error: Error, options?: unknown) => void;
      captureMessage: (message: string, level?: string) => void;
      setUser: (user: { id?: string; email?: string }) => void;
    };

    Sentry.init({
      dsn: process.env["SENTRY_DSN"],
      environment: process.env["NODE_ENV"] ?? "development",
      // Adjust traces sample rate based on environment
      tracesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,
      // Enable profiling in production (optional)
      profilesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,
      // Filter out health checks and other noise
      beforeSend(event: unknown, _hint: unknown) {
        // Don't send events for health checks
        const sentryEvent = event as { request?: { url?: string } };
        if (sentryEvent.request?.url?.includes("/health")) {
          return null;
        }
        return event;
      },
      // Configure integrations
      integrations: [
        // Add any custom integrations here
      ],
    });

    sentryInitialized = true;
  } catch (error) {
    // Fail silently if Sentry can't be initialized
    // This allows the app to continue working even if Sentry is misconfigured
    console.error("Failed to initialize Sentry:", error);
  }
}

/**
 * Check if Sentry is initialized
 */
export function isSentryInitialized(): boolean {
  return sentryInitialized;
}

/**
 * Capture an exception in Sentry
 * Safe to call even if Sentry is not initialized
 */
export function captureException(
  error: Error,
  context?: {
    tags?: Record<string, string>;
    extra?: Record<string, unknown>;
    user?: { id?: string; email?: string };
    level?: "fatal" | "error" | "warning" | "info" | "debug";
  },
): void {
  if (!sentryInitialized || !process.env["SENTRY_DSN"]) {
    return;
  }

  try {
    const Sentry = require("@sentry/remix") as {
      captureException: (error: Error, options?: unknown) => void;
    };

    Sentry.captureException(error, {
      tags: context?.tags,
      extra: context?.extra,
      user: context?.user,
      level: context?.level ?? "error",
    });
  } catch (err) {
    // Fail silently - don't break the app if Sentry fails
    console.error("Failed to capture exception in Sentry:", err);
  }
}

/**
 * Capture a message in Sentry
 * Useful for tracking important events
 */
export function captureMessage(
  message: string,
  level: "fatal" | "error" | "warning" | "info" | "debug" = "info",
  context?: {
    tags?: Record<string, string>;
    extra?: Record<string, unknown>;
  },
): void {
  if (!sentryInitialized || !process.env["SENTRY_DSN"]) {
    return;
  }

  try {
    const Sentry = require("@sentry/remix") as {
      captureMessage: (message: string, options?: unknown) => void;
    };

    Sentry.captureMessage(message, {
      level,
      tags: context?.tags,
      extra: context?.extra,
    });
  } catch (err) {
    // Fail silently - don't break the app if Sentry fails
    console.error("Failed to capture message in Sentry:", err);
  }
}

/**
 * Set user context for Sentry
 */
export function setUser(user: {
  id?: string;
  email?: string;
  username?: string;
}): void {
  if (!sentryInitialized || !process.env["SENTRY_DSN"]) {
    return;
  }

  try {
    const Sentry = require("@sentry/remix") as {
      setUser: (user: {
        id?: string;
        email?: string;
        username?: string;
      }) => void;
    };
    Sentry.setUser(user);
  } catch (err) {
    // Fail silently
    console.error("Failed to set user in Sentry:", err);
  }
}

/**
 * Clear user context
 */
export function clearUser(): void {
  if (!sentryInitialized || !process.env["SENTRY_DSN"]) {
    return;
  }

  try {
    const Sentry = require("@sentry/remix") as {
      setUser: (user: null) => void;
    };
    Sentry.setUser(null);
  } catch (err) {
    // Fail silently
    console.error("Failed to clear user in Sentry:", err);
  }
}

// Borrowed & modified from https://github.com/jenseng/abuse-the-platform/blob/main/app/utils/singleton.ts
// Thanks @jenseng!

export const singleton = <Value>(
  name: string,
  valueFactory: () => Value,
): Value => {
  const g = global as unknown as { __singletons: Record<string, unknown> };
  if (!g.__singletons) {
    g.__singletons = {};
  }
  if (!g.__singletons[name]) {
    g.__singletons[name] = valueFactory();
  }
  return g.__singletons[name] as Value;
};

/**
 * Type guards for CombinedContent.originalData
 * Provides safe type narrowing for CombinedContent.originalData field
 */

import type {
  PostData,
  LongFormPostData,
  CombinedContent,
} from "~/features/posts/types";

/**
 * Type guard to check if CombinedContent.originalData is PostData
 */
export function isPostData(
  originalData: CombinedContent["originalData"]
): originalData is PostData {
  if (!originalData || typeof originalData !== "object") {
    return false;
  }

  // PostData has specific fields that distinguish it from LongFormPostData
  // PostData doesn't have 'title' or 'summary' fields
  // LongFormPostData has 'title' and 'summary' fields
  return !("title" in originalData) && !("summary" in originalData);
}

/**
 * Type guard to check if CombinedContent.originalData is LongFormPostData
 */
export function isLongFormPostData(
  originalData: CombinedContent["originalData"]
): originalData is LongFormPostData {
  if (!originalData || typeof originalData !== "object") {
    return false;
  }

  // LongFormPostData has 'title' or 'summary' fields
  return "title" in originalData || "summary" in originalData;
}

/**
 * Safely extract PostData from CombinedContent
 * Returns null if originalData is not PostData
 */
export function extractPostData(content: CombinedContent): PostData | null {
  return isPostData(content.originalData) ? content.originalData : null;
}

/**
 * Safely extract LongFormPostData from CombinedContent
 * Returns null if originalData is not LongFormPostData
 */
export function extractLongFormPostData(
  content: CombinedContent
): LongFormPostData | null {
  return isLongFormPostData(content.originalData) ? content.originalData : null;
}

