/**
 * Validation utilities for HashTagPreset from loader responses
 * Replaces unsafe type casts with runtime validation
 */

import { z } from "zod";

import type { HashTagPreset } from "~/features/posts/types";
import { logError } from "~/lib/error-logger.server";

import { hashTagPresetSchema } from "./schemas/loader-responses.schemas";

/**
 * Safely validate and convert unknown array to HashTagPreset[]
 * Returns empty array if validation fails (logs error but doesn't throw)
 * Normalizes createdAt/updatedAt from string | Date to Date | undefined
 */
export function validateHashTagPresets(
  value: unknown,
): HashTagPreset[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const validated: HashTagPreset[] = [];

  for (const item of value) {
    try {
      const parsed = hashTagPresetSchema.parse(item);
      // Normalize createdAt/updatedAt from string | Date to Date | undefined
      validated.push({
        id: parsed.id,
        name: parsed.name,
        tags: parsed.tags,
        description: parsed.description ?? undefined,
        userId: parsed.userId,
        createdAt: parsed.createdAt instanceof Date 
          ? parsed.createdAt 
          : typeof parsed.createdAt === "string" 
            ? new Date(parsed.createdAt) 
            : undefined,
        updatedAt: parsed.updatedAt instanceof Date 
          ? parsed.updatedAt 
          : typeof parsed.updatedAt === "string" 
            ? new Date(parsed.updatedAt) 
            : undefined,
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        logError(error, {
          message: "Invalid HashTagPreset structure in array",
          context: { issues: error.issues, item: JSON.stringify(item) },
        });
      }
      // Skip invalid items, continue with valid ones
    }
  }

  return validated;
}

/**
 * Conversion utilities for PostData to component-specific formats
 * Handles type conversions between PostData and component Post interfaces
 */

import type { PostData } from "~/features/posts/types";

/**
 * Post format expected by ScheduledPostsTable component
 */
export interface ScheduledPostTablePost {
  id: string;
  caption?: string | null;
  scheduledFor: string; // Unix timestamp as string
  fileUrl?: string[] | null;
  queueType?: { name: string; color?: string | null } | null;
  repost?: boolean;
  isQuotedPost?: boolean;
  isPostSigned?: boolean;
}

/**
 * Convert PostData[] to ScheduledPostTablePost[]
 * Converts Date scheduledFor to unix timestamp string
 */
export function convertPostDataToScheduledTablePost(
  post: PostData,
): ScheduledPostTablePost {
  // Convert scheduledFor Date to unix timestamp string
  // PostData.scheduledFor can be Date | string | null | undefined
  let scheduledForString = "";
  if (post.scheduledFor) {
    const scheduledFor = post.scheduledFor as Date | string | null | undefined;
    if (scheduledFor instanceof Date) {
      scheduledForString = Math.floor(scheduledFor.getTime() / 1000).toString();
    } else if (typeof scheduledFor === "string") {
      scheduledForString = scheduledFor;
    } else if (typeof scheduledFor === "number") {
      scheduledForString = Math.floor(scheduledFor / 1000).toString();
    }
  }

  return {
    id: post.id,
    caption: post.caption ?? null,
    scheduledFor: scheduledForString,
    fileUrl: post.fileUrl ?? null,
    queueType: post.queueType
      ? {
          name: post.queueType.name,
          color: post.queueType.color ?? null,
        }
      : null,
    repost: post.repost ?? false,
    isQuotedPost: post.isQuotedPost ?? false,
    isPostSigned: post.signedEvent ? true : false,
  };
}

/**
 * Convert PostData[] array to ScheduledPostTablePost[] array
 */
export function convertPostDataArrayToScheduledTablePosts(
  posts: PostData[],
): ScheduledPostTablePost[] {
  return posts.map((post) => convertPostDataToScheduledTablePost(post));
}

/**
 * Type-safe property accessors for PostData
 * Provides safe access to PostData properties for sorting and filtering
 */

import type { PostData } from "~/features/posts/types";

/**
 * Safely get a property value from PostData for sorting
 * Returns undefined if property doesn't exist or is not sortable
 */
export function getPostDataProperty(
  post: PostData,
  key: string,
): string | number | Date | undefined {
  // Handle known PostData properties
  switch (key) {
    case "id":
      return post.id;
    case "caption":
      return post.caption ?? undefined;
      case "scheduledFor":
        if (post.scheduledFor) {
          const scheduledFor = post.scheduledFor as Date | string | null | undefined;
          if (scheduledFor instanceof Date) {
            return scheduledFor;
          }
          if (typeof scheduledFor === "string") {
            return new Date(scheduledFor);
          }
        }
        return undefined;
    case "postedAt":
      return post.postedAt instanceof Date
        ? post.postedAt
        : typeof post.postedAt === "string"
          ? new Date(post.postedAt)
          : undefined;
    case "createdAt":
      return post.createdAt instanceof Date
        ? post.createdAt
        : typeof post.createdAt === "string"
          ? new Date(post.createdAt)
          : undefined;
    case "updatedAt":
      return post.updatedAt instanceof Date
        ? post.updatedAt
        : typeof post.updatedAt === "string"
          ? new Date(post.updatedAt)
          : undefined;
    default: {
      // For other properties, try safe access
      const value = (post as unknown as Record<string, unknown>)[key];
      if (typeof value === "string" || typeof value === "number" || (value && typeof value === "object" && value instanceof Date)) {
        return value;
      }
      return undefined;
    }
  }
}

/**
 * Compare two PostData objects by a property key
 * Returns comparison result for sorting
 */
export function comparePostDataByProperty(
  a: PostData,
  b: PostData,
  key: string,
  direction: "asc" | "desc",
): number {
  const aValue = getPostDataProperty(a, key);
  const bValue = getPostDataProperty(b, key);

  if (aValue === undefined && bValue === undefined) return 0;
  if (aValue === undefined) return direction === "asc" ? -1 : 1;
  if (bValue === undefined) return direction === "asc" ? 1 : -1;

  // Handle Date comparisons
  if (aValue instanceof Date && bValue instanceof Date) {
    return direction === "asc"
      ? aValue.getTime() - bValue.getTime()
      : bValue.getTime() - aValue.getTime();
  }

  // Handle string/number comparisons
  if (aValue < bValue) return direction === "asc" ? -1 : 1;
  if (aValue > bValue) return direction === "asc" ? 1 : -1;
  return 0;
}

