        typeof (preset as { id: unknown; name: unknown; tags: unknown })
          .tags === "string",
    )
    .map((preset: {
      id: string;
      name: string;
      tags: string;
      description?: unknown;
      createdAt?: unknown;
      updatedAt?: unknown;
      userId?: unknown;
    }) => ({
      id: preset.id,
      name: preset.name,
      tags: preset.tags,
      description:
        preset.description === null
          ? null
          : typeof preset.description === "string"
            ? preset.description
