#!/usr/bin/env node

/**
 * Script to auto-fix ESLint errors
 *
 * This script:
 * 1. Runs ESLint with --fix to auto-fix what it can
 * 2. Applies custom fixes for patterns ESLint might miss
 * 3. Reports remaining errors
 */

const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const PROJECT_ROOT = path.resolve(__dirname, "..");

// Colors for console output
const colors = {
  reset: "\x1b[0m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  red: "\x1b[31m",
  blue: "\x1b[34m",
  cyan: "\x1b[36m",
};

function log(message, color = "reset") {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

/**
 * Recursively find all TypeScript files
 */
function findTsFiles(dir, fileList = []) {
  const files = fs.readdirSync(dir);

  files.forEach((file) => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    // Skip node_modules, build, and other ignored directories
    if (stat.isDirectory()) {
      if (
        file === "node_modules" ||
        file === "build" ||
        file === ".git" ||
        file === "public" ||
        file === "postgres-data" ||
        file === "redis-data" ||
        file.startsWith(".")
      ) {
        return;
      }
      findTsFiles(filePath, fileList);
    } else if (stat.isFile() && /\.(ts|tsx)$/.test(file)) {
      fileList.push(filePath);
    }
  });

  return fileList;
}

/**
 * Run ESLint with --fix flag
 */
function runEslintFix() {
  log("\n🔧 Running ESLint auto-fix...", "cyan");
  try {
    execSync("pnpm lint -- --fix", {
      cwd: PROJECT_ROOT,
      stdio: "inherit",
    });
    log("✅ ESLint auto-fix completed", "green");
    return true;
  } catch (error) {
    log(
      "⚠️  ESLint auto-fix completed with some errors (this is expected)",
      "yellow",
    );
    return false;
  }
}

/**
 * Fix nullish coalescing: Replace || with ?? in safe contexts
 */
function fixNullishCoalescing(content) {
  let modified = false;
  let fixes = 0;

  // More conservative approach: only fix obvious cases
  // Pattern: variable || defaultValue where variable is optional
  const lines = content.split("\n");
  const newLines = lines.map((line) => {
    // Skip if line contains comments or complex expressions
    if (line.includes("//") || line.includes("/*")) {
      return line;
    }

    // Fix: (something?.prop || fallback) -> (something?.prop ?? fallback)
    if (line.includes("?.") && line.includes("||")) {
      const newLine = line.replace(
        /(\w+(?:\?\.\w+)+)\s*\|\|\s*([\w'"[\]{}()]+)/g,
        (match, left, right) => {
          // Only if right is a simple value
          if (
            /^[\w'"[\]{}()]+$/.test(right) &&
            !right.includes("(") &&
            !right.includes("[")
          ) {
            modified = true;
            fixes++;
            return `${left} ?? ${right}`;
          }
          return match;
        },
      );
      return newLine;
    }

    // Fix: (variable || defaultValue) where variable could be null/undefined
    // Only for simple cases like: (user?.name || "Unknown")
    if (line.match(/\([^)]+\?\.[^)]+\)\s*\|\|/)) {
      const newLine = line.replace(
        /\(([^)]+)\?\.[^)]+\)\s*\|\|\s*([\w'"[\]{}]+)/g,
        (match, prefix, right) => {
          if (/^[\w'"[\]{}]+$/.test(right)) {
            modified = true;
            fixes++;
            return `(${prefix}?.${match.split("?.")[1].split(")")[0]}) ?? ${right}`;
          }
          return match;
        },
      );
      if (newLine !== line) return newLine;
    }

    return line;
  });

  if (modified) {
    return { content: newLines.join("\n"), fixes };
  }
  return { content, fixes: 0 };
}

/**
 * Fix import order (basic grouping)
 * NOTE: Disabled - ESLint's --fix handles this better
 */
function fixImportOrder_DISABLED(content) {
  const lines = content.split("\n");
  let importStart = -1;
  let importEnd = -1;
  let inImports = false;

  // Find import block
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.startsWith("import ")) {
      if (!inImports) {
        inImports = true;
        importStart = i;
      }
      importEnd = i;
    } else if (inImports && line === "" && i > importEnd + 1) {
      break;
    } else if (inImports && line !== "" && !line.startsWith("import ")) {
      importEnd = i - 1;
      break;
    }
  }

  if (importStart < 0 || importEnd < importStart) {
    return { content, modified: false };
  }

  const importLines = lines.slice(importStart, importEnd + 1);
  const externalImports = [];
  const internalImports = [];
  const relativeImports = [];
  const typeImports = [];
  const sideEffectImports = [];

  importLines.forEach((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith("import type ")) {
      typeImports.push(line);
    } else if (
      (trimmed.startsWith("import ") && trimmed.includes("from '~/")) ||
      trimmed.includes('from "~/')
    ) {
      internalImports.push(line);
    } else if (
      trimmed.startsWith("import ") &&
      (trimmed.includes("from './") || trimmed.includes('from "../'))
    ) {
      relativeImports.push(line);
    } else if (trimmed.startsWith("import ") && !trimmed.includes(" from ")) {
      sideEffectImports.push(line);
    } else if (trimmed.startsWith("import ")) {
      externalImports.push(line);
    }
  });

  // Sort each group
  externalImports.sort();
  internalImports.sort();
  relativeImports.sort();
  typeImports.sort();
  sideEffectImports.sort();

  // Reconstruct with proper spacing
  const newImportLines = [];
  if (externalImports.length > 0) {
    newImportLines.push(...externalImports);
  }
  if (
    externalImports.length > 0 &&
    (internalImports.length > 0 ||
      relativeImports.length > 0 ||
      typeImports.length > 0)
  ) {
    newImportLines.push("");
  }
  if (internalImports.length > 0) {
    newImportLines.push(...internalImports);
  }
  if (
    internalImports.length > 0 &&
    (relativeImports.length > 0 || typeImports.length > 0)
  ) {
    newImportLines.push("");
  }
  if (relativeImports.length > 0) {
    newImportLines.push(...relativeImports);
  }
  if (relativeImports.length > 0 && typeImports.length > 0) {
    newImportLines.push("");
  }
  if (typeImports.length > 0) {
    newImportLines.push(...typeImports);
  }
  if (sideEffectImports.length > 0) {
    if (newImportLines.length > 0) newImportLines.push("");
    newImportLines.push(...sideEffectImports);
  }

  // Check if anything changed
  const originalBlock = importLines.join("\n");
  const newBlock = newImportLines.join("\n");
  if (originalBlock === newBlock) {
    return { content, modified: false };
  }

  const newContent = [
    ...lines.slice(0, importStart),
    ...newImportLines,
    ...lines.slice(importEnd + 1),
  ].join("\n");

  return { content: newContent, modified: true };
}

/**
 * Remove async from functions without await
 */
function removeUnnecessaryAsync(content) {
  let modified = false;
  let fixes = 0;

  // Pattern: export async function name(): Promise<T> { ... } without await
  const asyncFuncRegex =
    /export\s+async\s+function\s+(\w+)\s*\([^)]*\)\s*:\s*Promise<[^>]+>\s*\{([^}]*)\}/gs;

  content = content.replace(asyncFuncRegex, (match, funcName, body) => {
    // Check if body contains await, Promise methods, or async operations
    if (
      !body.includes("await") &&
      !body.includes("Promise.") &&
      !body.includes("async") &&
      !body.includes("then(") &&
      !body.includes("catch(")
    ) {
      modified = true;
      fixes++;
      return match.replace(/\basync\s+/, "");
    }
    return match;
  });

  return { content, modified, fixes };
}

/**
 * Apply custom fixes to a file
 */
function applyCustomFixes(filePath) {
  try {
    let content = fs.readFileSync(filePath, "utf8");
    let totalFixes = 0;
    let modified = false;

    // Fix 1: Nullish coalescing
    const nullishResult = fixNullishCoalescing(content);
    if (nullishResult.fixes > 0) {
      content = nullishResult.content;
      totalFixes += nullishResult.fixes;
      modified = true;
    }

    // Note: Import order is handled by ESLint's --fix, so we skip custom import order fixes
    // to avoid conflicts with ESLint's more sophisticated rules

    // Fix 2: Remove unnecessary async
    // DISABLED: This function has a bug - it only checks the first brace level
    // and incorrectly removes async from functions that use await in nested blocks
    // const asyncResult = removeUnnecessaryAsync(content);
    // if (asyncResult.modified) {
    //   content = asyncResult.content;
    //   totalFixes += asyncResult.fixes;
    //   modified = true;
    // }

    if (modified) {
      fs.writeFileSync(filePath, content, "utf8");
      return { fixed: true, fixes: totalFixes };
    }

    return { fixed: false, fixes: 0 };
  } catch (error) {
    log(
      `  ⚠️  Error processing ${path.relative(PROJECT_ROOT, filePath)}: ${error.message}`,
      "yellow",
    );
    return { fixed: false, fixes: 0, error: error.message };
  }
}

/**
 * Apply custom fixes to all files
 */
function applyCustomFixesToAll() {
  log("\n🔧 Applying custom fixes...", "cyan");

  const targetDirs = [
    path.join(PROJECT_ROOT, "app"),
    path.join(PROJECT_ROOT, "tests"),
    path.join(PROJECT_ROOT, "cypress"),
  ];

  let filesFixed = 0;
  let totalFixes = 0;

  targetDirs.forEach((dir) => {
    if (!fs.existsSync(dir)) return;

    const files = findTsFiles(dir);
    files.forEach((filePath) => {
      const result = applyCustomFixes(filePath);
      if (result.fixed) {
        filesFixed++;
        totalFixes += result.fixes;
      }
    });
  });

  if (filesFixed > 0) {
    log(
      `✅ Custom fixes applied to ${filesFixed} files (${totalFixes} total fixes)`,
      "green",
    );
  } else {
    log("ℹ️  No custom fixes needed", "blue");
  }

  return filesFixed;
}

/**
 * Count remaining errors
 */
function countRemainingErrors() {
  log("\n📊 Counting remaining errors...", "cyan");
  try {
    const output = execSync("pnpm lint 2>&1", {
      cwd: PROJECT_ROOT,
      encoding: "utf8",
    });

    const errorMatches = output.match(/\d+:\d+\s+error/g);
    const warningMatches = output.match(/\d+:\d+\s+warning/g);

    const errorCount = errorMatches ? errorMatches.length : 0;
    const warningCount = warningMatches ? warningMatches.length : 0;

    log(`\n📈 Results:`, "cyan");
    log(`   Errors: ${errorCount}`, errorCount > 0 ? "red" : "green");
    log(`   Warnings: ${warningCount}`, warningCount > 0 ? "yellow" : "green");

    return { errors: errorCount, warnings: warningCount };
  } catch (error) {
    // ESLint returns non-zero exit code when there are errors
    const output = error.stdout || error.message || "";
    const errorMatches = output.match(/\d+:\d+\s+error/g);
    const warningMatches = output.match(/\d+:\d+\s+warning/g);

    const errorCount = errorMatches ? errorMatches.length : 0;
    const warningCount = warningMatches ? warningMatches.length : 0;

    log(`\n📈 Results:`, "cyan");
    log(`   Errors: ${errorCount}`, errorCount > 0 ? "red" : "green");
    log(`   Warnings: ${warningCount}`, warningCount > 0 ? "yellow" : "green");

    return { errors: errorCount, warnings: warningCount };
  }
}

/**
 * Main execution
 */
function main() {
  log("🚀 Starting ESLint auto-fix script...", "blue");
  log("=".repeat(60), "cyan");

  // Step 1: Run ESLint auto-fix
  runEslintFix();

  // Step 2: Apply custom fixes
  applyCustomFixesToAll();

  // Step 3: Count remaining errors
  const counts = countRemainingErrors();

  log("\n" + "=".repeat(60), "cyan");
  if (counts.errors === 0) {
    log("🎉 All errors fixed!", "green");
  } else {
    log(
      `⚠️  ${counts.errors} errors remaining (these may require manual fixes)`,
      "yellow",
    );
    log('💡 Run "pnpm lint" to see details', "blue");
  }

  process.exit(counts.errors > 0 ? 1 : 0);
}

// Run if executed directly
if (require.main === module) {
  main();
}

module.exports = { main, countRemainingErrors, applyCustomFixesToAll };

import { webcrypto as nodeWebcrypto } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import url from "node:url";

import { createRequestHandler } from "@remix-run/express";
import type { ServerBuild } from "@remix-run/node";
import { broadcastDevReady, installGlobals } from "@remix-run/node";
import compression from "compression";
import { config } from "dotenv";
import type { RequestHandler } from "express";
import express from "express";
import helmet from "helmet";
import * as ipaddr from "ipaddr.js";
import morgan from "morgan";
import * as promClient from "prom-client";
import sourceMapSupport from "source-map-support";

// Load environment variables from .env file (if it exists)
// This must happen before any imports that use environment variables
config({ path: path.resolve(process.cwd(), ".env") });

import { env } from "./app/lib/env.server";
import {
  apiLimiter,
  strictLimiter,
  authLimiter,
} from "./app/lib/rate-limit.server";

// Only install in production or when explicitly enabled to avoid missing map file errors in dev
if (env.NODE_ENV === "production" || env.ENABLE_SOURCE_MAPS === "true") {
  try {
    (
      sourceMapSupport as {
        install: (options: {
          handleUncaughtExceptions: boolean;
          environment: string;
        }) => void;
      }
    ).install({
      handleUncaughtExceptions: false,
      environment: "node",
    });
  } catch (error) {
    // If source map support fails to install, log but don't crash
    console.warn("[Source Maps] Failed to install source map support:", error);
  }
}
installGlobals();

// Ensure Web Crypto API exists for server-side code that expects browser crypto
interface GlobalWithCrypto {
  crypto?: Crypto;
}
const globalWithCrypto = globalThis as unknown as GlobalWithCrypto;
if (!globalWithCrypto.crypto?.getRandomValues) {
  globalWithCrypto.crypto = nodeWebcrypto as Crypto;
}

void run();

async function run() {
  const BUILD_PATH = path.resolve("build/index.js");
  const VERSION_PATH = path.resolve("build/version.txt");

  const initialBuild = await reimportServer();
  const remixHandler =
    env.NODE_ENV === "development"
      ? await createDevRequestHandler(initialBuild)
      : createRequestHandler({
          build: initialBuild,
          mode: initialBuild.mode,
        });

  const app = express();
  const metricsApp = express();

  // Trust proxy for accurate IP extraction (needed for Fly.io and other proxies)
  metricsApp.set("trust proxy", true);

  // Import query metrics to register them
  await import("./app/lib/query-metrics.server");

  // Collect default metrics (CPU, memory, process info, etc.)
  promClient.collectDefaultMetrics();

  // Expose Prometheus metrics endpoint with security protection
  metricsApp.get("/metrics", (req, res) => {
    void (async () => {
      // Validate token if provided
      const token =
        req.query["token"]?.toString() ??
        req.headers.authorization?.replace("Bearer ", "");

      if (env.METRICS_TOKEN) {
        if (!token || token !== env.METRICS_TOKEN) {
          res.status(401).json({ error: "Unauthorized" });
          return;
        }
      }

      // Validate IP if allowlist provided
      if (env.METRICS_ALLOWED_IPS) {
        // Get client IP (handles proxies)
        const clientIp =
          (req.headers["x-forwarded-for"] as string | undefined)?.split(",")[0]?.trim() ??
          (req.headers["x-real-ip"] as string | undefined) ??
          req.socket.remoteAddress ??
          req.ip ??
          "";

        if (!clientIp) {
          res.status(403).json({
            error: "Forbidden",
            message: "Unable to determine client IP address",
          });
          return;
        }

        const allowedIps = env.METRICS_ALLOWED_IPS.split(",").map((ip) =>
          ip.trim(),
        );

        // Use ipaddr.js for proper CIDR matching (supports IPv4 and IPv6)
        let isAllowed = false;

        try {
          const clientAddr = ipaddr.process(clientIp);

          isAllowed = allowedIps.some((allowedIp) => {
            try {
              // Exact match
              if (clientIp === allowedIp) {
                return true;
              }

              // CIDR match (e.g., "10.0.0.0/8" or "2001:db8::/32")
              if (allowedIp.includes("/")) {
                const [prefix, maskStr] = allowedIp.split("/");
                if (!maskStr) {
                  return false;
                }
                const mask = parseInt(maskStr, 10);

                if (isNaN(mask) || mask < 0 || !prefix) {
                  return false;
                }

                try {
                  const prefixAddr = ipaddr.process(prefix);

                  // Both must be same type (IPv4 or IPv6)
                  if (clientAddr.kind() !== prefixAddr.kind()) {
                    return false;
                  }

                  // Check if client IP is within the CIDR range
                  if (clientAddr.kind() === "ipv4") {
                    const subnet = prefixAddr as ipaddr.IPv4;
                    const range = ipaddr.IPv4.subnetMaskFromPrefixLength(mask);
                    const clientIPv4 = clientAddr as ipaddr.IPv4;
                    // @ts-expect-error - ipaddr.js types may be incomplete, but match works correctly
                    return clientIPv4.match(subnet, range);
                  } else {
                    // IPv6
                    const subnet = prefixAddr as ipaddr.IPv6;
                    const range = ipaddr.IPv6.subnetMaskFromPrefixLength(mask);
                    const clientIPv6 = clientAddr as ipaddr.IPv6;
                    // @ts-expect-error - ipaddr.js types may be incomplete, but match works correctly
                    return clientIPv6.match(subnet, range);
                  }
                } catch {
                  // Invalid CIDR format
                  return false;
                }
              }

              // Try parsing as single IP for exact match
              const allowedAddr = ipaddr.process(allowedIp);
              return clientAddr.toString() === allowedAddr.toString();
            } catch {
              // Invalid IP format in allowlist - skip this entry
              return false;
            }
          });
        } catch (error) {
          // Invalid client IP format
          console.warn("Invalid client IP format:", clientIp, error);
          isAllowed = false;
        }

        if (!isAllowed) {
          res.status(403).json({
            error: "Forbidden",
            message: "IP address not allowed",
          });
          return;
        }
      }

      // If neither token nor IP allowlist is configured, allow in development only
      if (
        !env.METRICS_TOKEN &&
        !env.METRICS_ALLOWED_IPS &&
        env.NODE_ENV === "production"
      ) {
        console.warn(
          "⚠️  Metrics endpoint is unprotected in production. Set METRICS_TOKEN or METRICS_ALLOWED_IPS.",
        );
        // Still allow access but log warning
      }

      // Return metrics
      res.set("Content-Type", promClient.register.contentType);
      const metrics = await promClient.register.metrics();
      res.end(metrics);
    })();
  });

  app.use((req, res, next) => {
    // helpful headers:
    res.set("x-fly-region", env.FLY_REGION ?? "unknown");
    res.set("Strict-Transport-Security", `max-age=${60 * 60 * 24 * 365 * 100}`);

    // /clean-urls/ -> /clean-urls
    if (req.path.endsWith("/") && req.path.length > 1) {
      const query = req.url.slice(req.path.length);
      const safepath = req.path.slice(0, -1).replace(/\/+/g, "/");
      res.redirect(301, safepath + query);
      return;
    }
    next();
  });

  // if we're not in the primary region, then we need to make sure all
  // non-GET/HEAD/OPTIONS requests hit the primary region rather than read-only
  // Postgres DBs.
  // learn more: https://fly.io/docs/getting-started/multi-region-databases/#replay-the-request
  app.all("*", function getReplayResponse(req, res, next) {
    const { method, path: pathname } = req;
    const PRIMARY_REGION = env.PRIMARY_REGION;
    const FLY_REGION = env.FLY_REGION;

    const isMethodReplayable = !["GET", "OPTIONS", "HEAD"].includes(method);
    const isReadOnlyRegion =
      FLY_REGION && PRIMARY_REGION && FLY_REGION !== PRIMARY_REGION;

    const shouldReplay = isMethodReplayable && isReadOnlyRegion;

    if (!shouldReplay) return next();

    const logInfo = {
      pathname,
      method,
      PRIMARY_REGION,
      FLY_REGION,
    };
    console.info(`Replaying:`, logInfo);
    res.set("fly-replay", `region=${PRIMARY_REGION}`);
    return res.sendStatus(409);
  });

  app.use(compression());

  // http://expressjs.com/en/advanced/best-practice-security.html#at-a-minimum-disable-x-powered-by-header
  app.disable("x-powered-by");

  // Security headers with Helmet
  // Configure CSP to work with Remix (which uses inline scripts/styles)
  // In production, we remove 'unsafe-eval' for better security
  const isDevelopment = env.NODE_ENV === "development";
  const scriptSrc = [
    "'self'",
    "'unsafe-inline'", // Required for Remix
    ...(isDevelopment ? ["'unsafe-eval'"] : []), // Only in development
  ];

  app.use(
    helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc,
          styleSrc: [
            "'self'",
            "'unsafe-inline'", // Required for Remix
          ],
          imgSrc: ["'self'", "data:", "https:", "blob:"],
          connectSrc: [
            "'self'",
            "wss:", // WebSocket connections for Nostr
            "https:", // External API calls
            ...(isDevelopment ? ["ws://localhost:3001"] : []), // Remix dev server WebSocket
          ],
          workerSrc: [
            "'self'",
            "blob:", // Required for Sentry workers
          ],
          fontSrc: ["'self'", "data:"],
          objectSrc: ["'none'"],
          mediaSrc: ["'self'"],
          frameSrc: ["'none'"],
          baseUri: ["'self'"],
          formAction: ["'self'"],
          upgradeInsecureRequests: !isDevelopment ? [] : null,
        },
      },
      hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true,
      },
      frameguard: {
        action: "deny",
      },
      noSniff: true,
      xssFilter: true,
      referrerPolicy: {
        policy: "strict-origin-when-cross-origin",
      },
      // @ts-expect-error - permissionsPolicy may not be in helmet types but is valid
      permissionsPolicy: {
        features: {
          geolocation: ["'none'"],
          microphone: ["'none'"],
          camera: ["'none'"],
        },
      },
    }),
  );

  // Additional custom security headers
  app.use((req, res, next) => {
    // X-Content-Type-Options: Prevent MIME type sniffing
    res.setHeader("X-Content-Type-Options", "nosniff");

    // X-Frame-Options: Prevent clickjacking (redundant with helmet frameguard, but explicit)
    res.setHeader("X-Frame-Options", "DENY");

    // X-XSS-Protection: Enable XSS filter (legacy browsers)
    res.setHeader("X-XSS-Protection", "1; mode=block");

    // Referrer-Policy: Control referrer information (redundant with helmet, but explicit)
    res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");

    // Permissions-Policy: Control browser features (redundant with helmet, but explicit)
    res.setHeader(
      "Permissions-Policy",
      "geolocation=(), microphone=(), camera=()",
    );

    next();
  });

  // Remix fingerprints its assets so we can cache forever.
  app.use(
    "/build",
    express.static("public/build", { immutable: true, maxAge: "1y" }),
  );

  // Everything else (like favicon.ico) is cached for an hour. You may want to be
  // more aggressive with this caching.
  app.use(express.static("public", { maxAge: "1h" }));

  app.use(morgan("tiny"));

  // Rate limiting
  // Apply general API rate limiting to all API routes
  app.use("/api/", apiLimiter);

  // Stricter limits for sensitive endpoints
  app.use("/api/publish", strictLimiter);
  app.use("/api/upload", strictLimiter);
  app.use("/api/upload-blossom", strictLimiter);
  app.use("/api/upload-editorjs-image", strictLimiter);

  // Very strict limits for authentication endpoints
  app.use("/api/payment-status", strictLimiter);

  // Auth endpoints get the strictest limits
  app.use("/login", authLimiter);
  app.use("/nostr-auth", authLimiter);

  app.all("*", remixHandler);

  const port = parseInt(env.PORT ?? "3000", 10);
  app.listen(port, () => {
    console.log(`✅ app ready: http://localhost:${port}`);

    if (env.NODE_ENV === "development") {
      void broadcastDevReady(initialBuild);
    }
  });

  const metricsPort = parseInt(env.METRICS_PORT ?? "3010", 10);

  metricsApp.listen(metricsPort, () => {
    console.log(`✅ metrics ready: http://localhost:${metricsPort}/metrics`);
  });

  async function reimportServer(): Promise<ServerBuild> {
    // cjs: manually remove the server build from the require cache
    Object.keys(require.cache).forEach((key) => {
      if (key.startsWith(BUILD_PATH)) {
        delete require.cache[key];
      }
    });

    const stat = fs.statSync(BUILD_PATH);

    // convert build path to URL for Windows compatibility with dynamic `import`
    const BUILD_URL = url.pathToFileURL(BUILD_PATH).href;

    // use a timestamp query parameter to bust the import cache
    return import(BUILD_URL + "?t=" + stat.mtimeMs);
  }

  async function createDevRequestHandler(
    initialBuild: ServerBuild,
  ): Promise<RequestHandler> {
    let build = initialBuild;
    async function handleServerUpdate() {
      // 1. re-import the server build
      build = await reimportServer();
      // 2. tell Remix that this app server is now up-to-date and ready
      void broadcastDevReady(build);
    }
    const chokidar = await import("chokidar");
    chokidar
      .watch(VERSION_PATH, { ignoreInitial: true })
      .on("add", () => {
        void handleServerUpdate();
      })
      .on("change", () => {
        void handleServerUpdate();
      });

    // wrap request handler to make sure its recreated with the latest build for every request
    return (req, res, next) => {
      try {
        const handler = createRequestHandler({
          build,
          mode: "development",
        });
        void handler(req, res, next);
      } catch (error) {
        next(error);
      }
    };
  }
}

/**
 * Test Database Utilities
 *
 * Provides utilities for setting up and managing test databases
 * with transaction-based isolation for test safety
 */

import { execSync } from "child_process";

import type { Prisma } from "@prisma/client";
import { PrismaClient } from "@prisma/client";

let testPrisma: PrismaClient | null = null;
let transactionClient: PrismaClient | null = null;

/**
 * Get or create test Prisma client
 * Uses separate test database URL if available
 */
export function getTestPrisma(): PrismaClient {
  if (testPrisma) {
    return testPrisma;
  }

  const testDatabaseUrl =
    process.env["TEST_DATABASE_URL"] ?? process.env["DATABASE_URL"];

  if (!testDatabaseUrl) {
    throw new Error(
      "TEST_DATABASE_URL or DATABASE_URL must be set for database tests",
    );
  }

  testPrisma = new PrismaClient({
    datasources: {
      db: {
        url: testDatabaseUrl,
      },
    },
    log: process.env["DEBUG"] ? ["query", "error", "warn"] : ["error"],
  });

  return testPrisma;
}

/**
 * Create a transaction client for test isolation
 * Each test runs in its own transaction that gets rolled back
 */
export async function createTransactionClient(): Promise<PrismaClient> {
  const prisma = getTestPrisma();

  // Start a transaction
  await prisma.$transaction(
    async (tx) => {
      // Return a client that uses this transaction
      return tx as unknown as PrismaClient;
    },
    {
      timeout: 10000,
    },
  );

  // For Prisma, we'll use a different approach - wrap operations in transactions
  return prisma;
}

/**
 * Run a test function within a transaction
 * The transaction is rolled back after the test, ensuring test isolation
 */
export async function withTransaction<T>(
  testFn: (prisma: PrismaClient) => Promise<T>,
): Promise<T> {
  const prisma = getTestPrisma();

  return await prisma.$transaction(
    async (tx) => {
      // Cast transaction client to PrismaClient for type compatibility
      const txClient = tx as unknown as PrismaClient;
      return await testFn(txClient);
    },
    {
      timeout: 30000,
      isolationLevel: "ReadCommitted",
    },
  );
}

/**
 * Setup test database
 * Syncs schema and seeds test data
 * Uses `db push` for test databases as it doesn't require migrations
 */
export function setupTestDatabase(): Promise<void> {
  const testDatabaseUrl =
    process.env["TEST_DATABASE_URL"] ?? process.env["DATABASE_URL"];

  if (!testDatabaseUrl) {
    throw new Error("TEST_DATABASE_URL or DATABASE_URL must be set");
  }

  try {
    // Use db push for test databases - it syncs schema without requiring migrations
    // This works even if the database already has schema
    // db push is safer than migrate deploy for test databases as it doesn't require
    // migration history or baseline setup
    execSync("npx prisma db push --skip-generate", {
      env: { ...process.env, DATABASE_URL: testDatabaseUrl },
      stdio: "inherit",
    });
    return Promise.resolve();
  } catch (error) {
    console.error("Failed to sync database schema:", error);
    // If db push fails, it might be due to breaking schema changes
    // In that case, use a fresh test database or manually resolve conflicts
    throw error;
  }
}

/**
 * Teardown test database
 * Cleans up test data (optional - transactions handle most cleanup)
 */
export async function teardownTestDatabase(): Promise<void> {
  if (testPrisma) {
    await testPrisma.$disconnect();
    testPrisma = null;
  }

  if (transactionClient) {
    await transactionClient.$disconnect();
    transactionClient = null;
  }
}

/**
 * Reset test database
 * Drops all data and re-runs migrations
 * WARNING: Destructive operation - only use in test environments
 */
export async function resetTestDatabase(): Promise<void> {
  const prisma = getTestPrisma();

  // Get all model names from Prisma schema
  const modelNames = [
    "User",
    "Post",
    "LongFormPost",
    "QueueType",
    "HashTagPreset",
    "Template",
    "Asset",
    "Payment",
    "Plan",
    "Subscription",
  ];

  // Delete in reverse order of dependencies
  for (const modelName of modelNames.reverse()) {
    try {
      const modelKey = modelName.toLowerCase() as keyof PrismaClient;
      const model = prisma[modelKey] as
        | { deleteMany: (args: {}) => Promise<unknown> }
        | undefined;
      if (model && typeof model.deleteMany === "function") {
        await model.deleteMany({});
      }
    } catch (error) {
      // Ignore errors for models that don't exist or have dependencies
      console.warn(`Could not delete ${modelName}:`, error);
    }
  }
}

/**
 * Seed test database with fixtures
 */
interface TestFixtures {
  users?: Array<{ id?: string; [key: string]: unknown }>;
  queueTypes?: Array<{ id?: string; [key: string]: unknown }>;
  hashTagPresets?: Array<{ id?: string; [key: string]: unknown }>;
  posts?: Array<{ id?: string; [key: string]: unknown }>;
  longFormPosts?: Array<{ id?: string; [key: string]: unknown }>;
  payments?: Array<{ id?: string; [key: string]: unknown }>;
  plans?: Array<{ id?: string; [key: string]: unknown }>;
  [key: string]: unknown;
}

export async function seedTestDatabase(fixtures?: TestFixtures): Promise<void> {
  const prisma = getTestPrisma();

  if (fixtures) {
    // Use provided fixtures
    await applyFixtures(prisma, fixtures);
  } else {
    // Use default seed
    try {
      execSync("npm run db:seed", {
        env: {
          ...process.env,
          DATABASE_URL:
            process.env["TEST_DATABASE_URL"] ?? process.env["DATABASE_URL"],
        },
        stdio: "inherit",
      });
    } catch {
      console.warn("Failed to run seed, continuing without seed data");
    }
  }
}

/**
 * Apply fixtures to database
 * Uses upsert to handle existing records (idempotent)
 */
async function applyFixtures(
  prisma: PrismaClient,
  // Dynamic import() type annotation needed for conditional type
  // eslint-disable-next-line @typescript-eslint/consistent-type-imports -- Dynamic import requires value import
  fixtures: TestFixtures | import("./fixtures").TestFixtures,
): Promise<void> {
  // Apply fixtures in dependency order
  if (fixtures.users && Array.isArray(fixtures.users)) {
    for (const user of fixtures.users) {
      // Use upsert to handle existing records
      const userId =
        user &&
        typeof user === "object" &&
        "id" in user &&
        typeof user.id === "string"
          ? user.id
          : undefined;
      if (userId) {
        await prisma.user.upsert({
          where: { id: userId },
          update: user as unknown as Prisma.UserUpdateInput,
          create: user as unknown as Prisma.UserCreateInput,
        });
      } else {
        await prisma.user.create({
          data: user as unknown as Prisma.UserCreateInput,
        });
      }
    }
  }

  if (fixtures.queueTypes && Array.isArray(fixtures.queueTypes)) {
    for (const queueType of fixtures.queueTypes) {
      const queueTypeId =
        queueType &&
        typeof queueType === "object" &&
        "id" in queueType &&
        typeof queueType.id === "string"
          ? queueType.id
          : undefined;
